/// Turn a value read out of a `.mat` file into a Qu value.
///
/// The shape choices follow what MATLAB means rather than what it stores:
///
///   - a 1x1 array is a number, not a one-element vector, because that is
///     what `config.Fs` is;
///   - a vector (1xN or Nx1) is a `Vec`, dropping the orientation MATLAB
///     tracks and Qu does not;
///   - anything else keeps both dimensions as a `Mat`. MATLAB stores
///     column-major and so does `Matrix`, so the data carries over as-is;
///   - N-dimensional arrays past 2-D are flattened to a plain vector,
///     since Qu has no N-D array type -- the dimensions would be silently
///     lost either way, and a vector at least keeps every value.
fn mat_to_value(v: &matfile::MatValue) -> Value {
    use matfile::MatValue as M;
    fn shape(dims: &[usize], data: Vec<f64>) -> Value {
        match dims {
            [1, 1] => Value::Num(data.first().copied().unwrap_or(f64::NAN)),
            [1, _] | [_, 1] => Value::Vec(Arc::new(data)),
            // Checked, not the panicking form: a dimension header that
            // disagrees with the payload means a corrupt file, and that
            // should surface as an odd value rather than an abort.
            [r, c] => Matrix::from_col_major_checked(*r, *c, data.clone())
                .map(|m| Value::Mat(Arc::new(m)))
                .unwrap_or_else(|_| Value::Vec(Arc::new(data))),
            _ => Value::Vec(Arc::new(data)),
        }
    }
    match v {
        M::Numeric { dims, data } => shape(dims, data.clone()),
        M::Complex { dims, re, im } => {
            let z: Vec<Complex64> = re
                .iter()
                .zip(im.iter())
                .map(|(&a, &b)| Complex64::new(a, b))
                .collect();
            match dims.as_slice() {
                [1, 1] => z.first().copied().map(Value::Complex).unwrap_or(Value::Nothing),
                _ => Value::CVec(Arc::new(z)),
            }
        }
        M::Str(t) => Value::Str(t.clone()),
        M::Struct(fields) => Value::Record(Arc::new(
            fields.iter().map(|(k, fv)| (k.clone(), mat_to_value(fv))).collect(),
        )),
        M::Cell { items, .. } => {
            Value::List(Arc::new(items.iter().map(mat_to_value).collect()))
        }
        // A field this reader cannot decode reads as text saying so,
        // rather than vanishing: a script that touches it then fails with
        // something legible instead of a missing-field error.
        M::Unsupported(kind) => Value::Str(format!("<unsupported .mat {kind}>")),
    }
}

