fn reduce_axis(f: &str, m: &Matrix, axis: usize, extra: Option<&Value>, style: &[(String, Value)]) -> R<Value> {
    let idx_err = |se: qu_core::matrix::ShapeError| EvalError {
        msg: se.to_string(),
    };
    // `quantile`/`argquantile` are the only two names here that take a
    // second positional argument (`q`) alongside the matrix -- read once,
    // outside the per-group closure, so a bad `q` is one error rather than
    // one per column.
    let q = || -> R<f64> {
        match extra.and_then(|v| v.as_num().ok()) {
            Some(v) => Ok(v),
            None => e(format!("{f}: needs a quantile argument (0..1) alongside `axis=`")),
        }
    };
    // `on_invalid=` belongs to the ten reductions it was added for.
    // `prod`/`argmedian`/`argquantile` reach this function too (they are
    // also in `AXIS_HONOURING`) but are out of scope here -- so this must
    // not even LOOK at `style` for them: looking marks `on_invalid` as
    // "read" (see `style_entry`) and would let e.g. `prod(M, axis=0,
    // on_invalid="ignore")` through silently accepted and silently
    // ignored, the exact failure `on_invalid=` exists to prevent
    // elsewhere. Read once, outside the per-group loop, and replayed with
    // `apply_on_invalid_mode` per row/column below -- so "ignore" drops
    // NaN/Inf WITHIN each row/column independently, rather than across the
    // whole matrix.
    let on_invalid = if matches!(
        f,
        "sum" | "mean" | "std" | "var" | "median" | "quantile" | "max" | "min" | "argmax" | "argmin"
    ) {
        Some(parse_on_invalid(f, style)?)
    } else {
        None
    };
    let mode = on_invalid.unwrap_or(OnInvalid::Propagate);
    // gather the vectors being reduced: axis 0 -> each column; axis 1 -> each row
    let groups: Vec<Vec<f64>> = match axis {
        0 => (0..m.cols())
            .map(|c| m.col_vec(c).map_err(idx_err))
            .collect::<R<Vec<_>>>()?,
        1 => (0..m.rows())
            .map(|r| m.row_vec(r).map_err(idx_err))
            .collect::<R<Vec<_>>>()?,
        other => return e(format!("axis must be 0 or 1, got {other}")),
    };
    let out: Vec<f64> = groups
        .iter()
        .map(|g| -> R<f64> {
            Ok(match f {
            "sum" => apply_on_invalid_mode(f, g, mode)?.iter().sum(),
            "prod" => g.iter().product(),
            "mean" => {
                let g = apply_on_invalid_mode(f, g, mode)?;
                g.iter().sum::<f64>() / g.len().max(1) as f64
            }
            // `var` and `median` were reachable from the dispatch arm's
            // list and absent from this one, which is the pairing that
            // makes the `_ => NAN` below dangerous: a name added there and
            // forgotten here returns a vector of NaNs rather than an error.
            // `var` is `std` squared here for the same reason the chapter
            // states that invariant -- one definition, not two.
            "std" => std_dev(&apply_on_invalid_mode(f, g, mode)?),
            "var" => variance(&apply_on_invalid_mode(f, g, mode)?),
            "median" => median_of(&apply_on_invalid_mode(f, g, mode)?)?,
            // Found by Ahmed asking "check argmedian / argquantile" after
            // the first pass: `quantile`/`argquantile`/`argmedian` were
            // outside the original five and had the identical gap --
            // fourth occurrence of the same mechanism. `quantile` reuses
            // `quantile_of` so a per-axis quantile can never define "0.5
            // of a column" differently from what `quantile(x, 0.5)` means
            // for a plain vector.
            "quantile" => quantile_of(&apply_on_invalid_mode(f, g, mode)?, q()?)?,
            "argmedian" => arg_order_statistic(g, 0.5, true)? as f64,
            "argquantile" => arg_order_statistic(g, q()?, false)? as f64,
            "max" => apply_on_invalid_mode(f, g, mode)?
                .iter()
                .copied()
                .fold(f64::NEG_INFINITY, f64::max),
            "min" => apply_on_invalid_mode(f, g, mode)?
                .iter()
                .copied()
                .fold(f64::INFINITY, f64::min),
            // Index of the extremum WITHIN the row or column, which is
            // what "argmax along an axis" means everywhere else --
            // `on_invalid="ignore"` must still land on a position in the
            // ORIGINAL row/column, not a filtered one, same reasoning as
            // `arg_extremum_on_invalid`'s flat-array version. `propagate`
            // (the default) is untouched from before this feature existed,
            // including its pre-existing quirk: unlike the flat
            // `arg_extremum`, this inline per-axis scan does NOT skip a
            // leading NaN, so a NaN at the start of a row/column can pin
            // the result to index 0 -- that is "exactly today's behavior",
            // which is what `propagate` promises to preserve.
            "argmax" | "argmin" => {
                let better = |a: f64, b: f64| if f == "argmax" { a > b } else { a < b };
                match mode {
                    OnInvalid::Ignore => {
                        let mut best: Option<usize> = None;
                        for (i, v) in g.iter().enumerate() {
                            if !v.is_finite() {
                                continue;
                            }
                            best = match best {
                                Some(b) if !better(*v, g[b]) => Some(b),
                                _ => Some(i),
                            };
                        }
                        match best {
                            Some(b) => b as f64,
                            None => {
                                return e(format!(
                                    "{f}: every element in this row/column is NaN or Inf -- \
                                     nothing left after on_invalid=\"ignore\""
                                ))
                            }
                        }
                    }
                    OnInvalid::Error => {
                        check_no_invalid(f, g)?;
                        let mut best = 0usize;
                        for (i, v) in g.iter().enumerate() {
                            if better(*v, g[best]) {
                                best = i;
                            }
                        }
                        best as f64
                    }
                    OnInvalid::Propagate => {
                        let mut best = 0usize;
                        for (i, v) in g.iter().enumerate() {
                            if better(*v, g[best]) {
                                best = i;
                            }
                        }
                        best as f64
                    }
                }
            }
            // Was `_ => f64::NAN`. A caller that reached here with a name
            // this function does not reduce got a vector of NaNs and no
            // signal -- the same silent-plausible-answer shape as the
            // `axis=` bug itself, one function down. Refusing means the
            // two lists can only disagree loudly.
            other => {
                return e(format!(
                    "`{other}` has no per-axis rule -- it reached `reduce_axis` from the \
                     dispatch list without being taught how to reduce one row or column. \
                     Add it here, or take it out of that list."
                ))
            }
            })
        })
        .collect::<R<Vec<f64>>>()?;
    Ok(Value::Vec(Arc::new(out)))
}

/// Map a value to a real result with a complex rule for complex inputs and a
/// real rule for real inputs (`abs`, `angle`, `real`, `imag`).
/// The complex payload of a value that carries a FREQUENCY AXIS alongside
/// complex data: `transfer_function`'s `kind="frf"` handle (field `h`) and
/// measured `impedance`'s `kind="impedance"` handle (field `z`).
///
/// `toolkit-signal.md` §11 asks for `Z.real()`/`Z.magnitude()`/`Z.phase()`/
/// `Z.nyquist()` to work on the result directly. Method-call sugar rewrites
/// each of those to `real(Z)`/`nyquist(Z)`/... (see `eval_call`), so rather
/// than teach every one of those builtins about a model kind, the two
/// complex-promotion paths they all funnel through -- `as_complex_flat`
/// and `complex_map_to_real` -- unwrap through this single function.
///
/// Deliberately narrow: only these two kinds, only when the field really
/// holds a `CVec`. Every other `Value::Model` keeps erroring exactly as
/// before, so this cannot quietly make an unrelated model arithmetic.
fn frequency_carrier_complex(v: &Value) -> Option<Vec<Complex64>> {
    let Value::Model(m) = v else { return None };
    let field = match m.kind.as_str() {
        "frf" => "h",
        "impedance" => "z",
        _ => return None,
    };
    match m.field(field) {
        Some(Value::CVec(xs)) => Some(xs.as_ref().clone()),
        _ => None,
    }
}

/// The sample rate of a TWO-recording measurement (`transfer_function`,
/// measured `impedance`). Either recording may carry it, an explicit
/// positional `fs` still cross-checks against it, and two carried rates
/// that DISAGREE are an error rather than a silent pick -- the same
/// contract `resolve_fs` enforces for one signal, extended to the pair,
/// because two recordings at different rates are not two views of one
/// measurement no matter how plausible the arithmetic looks afterwards.
fn resolve_fs_pair(f: &str, a: &Value, b: &Value, explicit: Option<f64>) -> R<f64> {
    let carried = |v: &Value| match v {
        Value::Signal(_, fs, _) => Some(*fs),
        Value::Spectrum(_, fs, _, _) => Some(*fs),
        _ => None,
    };
    if let (Some(ra), Some(rb)) = (carried(a), carried(b)) {
        if (ra - rb).abs() > 1e-9 * ra.abs().max(1.0) {
            return e(format!(
                "{f}: the two recordings carry different sample rates ({ra} Hz and {rb} Hz) -- \
                 they cannot be two views of the same measurement. Resample one of them first."
            ));
        }
    }
    let src = if carried(a).is_some() { a } else { b };
    resolve_fs(f, src, explicit, None)
}

/// The Welch-framed FRF estimate shared by `transfer_function` and the
/// measured branch of `impedance`: parse the common `method=`/`nperseg=`/
/// `noverlap=`/`window=` keywords, run the estimator, and hand back
/// `(H, coherence, freq, method, nperseg)`.
///
/// `x` is the INPUT and `y` the OUTPUT -- for impedance that is current and
/// voltage respectively, which is the opposite of `impedance`'s own
/// `(voltage, current)` argument order; see that arm for why.
///
/// The frequency axis is `k * fs / nperseg`, which is exactly
/// `Value::Spectrum`'s own `k * Fs / N` with `N = nperseg` -- §11 asks the
/// impedance result to "conform to the same frequency-axis convention
/// rather than invent its own", and this is that convention, evaluated for
/// a Welch-framed estimate rather than a whole-record transform.
#[allow(clippy::type_complexity)]
fn estimate_frf(
    f: &str,
    xs: &[f64],
    ys: &[f64],
    fs: f64,
    style: &[(String, Value)],
) -> R<(Vec<Complex64>, Vec<f64>, Vec<f64>, String, usize)> {
    let method = style_str(style, "method").unwrap_or_else(|| "h1".to_string());
    let estimator = match method.to_ascii_lowercase().as_str() {
        "h1" => numeric::transforms::TfEstimator::H1,
        "h2" => numeric::transforms::TfEstimator::H2,
        "hv" => numeric::transforms::TfEstimator::Hv,
        other => {
            return e(format!(
                "{f}: method must be \"h1\", \"h2\" or \"hv\", not {other:?} -- \
                 h1 assumes the noise is on the output, h2 that it is on the input, \
                 and hv is the geometric-mean compromise between the two"
            ))
        }
    };
    let shorter = xs.len().min(ys.len());
    let nperseg = style_num_checked(style, "nperseg", shorter.min(256) as f64, f)? as usize;
    if nperseg == 0 || nperseg > shorter {
        return e(format!(
            "{f}: nperseg ({nperseg}) must be between 1 and the shorter recording's length ({shorter})"
        ));
    }
    let noverlap = style_num_checked(style, "noverlap", (nperseg / 2) as f64, f)? as usize;
    if noverlap >= nperseg {
        return e(format!(
            "{f}: noverlap ({noverlap}) must be less than nperseg ({nperseg})"
        ));
    }
    let window_name = style_str(style, "window").unwrap_or_else(|| "hann".to_string());
    let window = periodic_analysis_window(f, &window_name, nperseg, style)?;
    let (h, coh) =
        numeric::transforms::transfer_function(xs, ys, fs, nperseg, noverlap, &window, estimator)
            .map_err(|ne| EvalError { msg: format!("{f}: {ne}") })?;
    let freq: Vec<f64> = (0..h.len()).map(|k| k as f64 * fs / nperseg as f64).collect();
    Ok((h, coh, freq, method.to_ascii_lowercase(), nperseg))
}

fn complex_map_to_real(
    v: &Value,
    cf: impl Fn(Complex64) -> f64,
    rf: impl Fn(f64) -> f64 + Sync + Send,
) -> R<Value> {
    // `Z.real()`/`H.phase()` -- the frequency-carrying handles read as
    // their own complex data (see `frequency_carrier_complex`).
    if let Some(xs) = frequency_carrier_complex(v) {
        return Ok(Value::Vec(Arc::new(xs.iter().map(|c| cf(*c)).collect())));
    }
    match v {
        Value::Complex(c) => Ok(Value::Num(cf(*c))),
        Value::CVec(xs) => Ok(Value::Vec(Arc::new(xs.iter().map(|c| cf(*c)).collect()))),
        // `rfft`/`fft` on a `Signal` return `Spectrum`, not `CVec` (that's
        // what a plain `Vec` input gets) -- found via the DSP course's own
        // `abs(rfft(a_chirp_signal))`, which errored "cannot apply the
        // operation to spectrum" even though `abs(rfft(a_plain_vector))`
        // already worked. Same real-valued-magnitude result either way;
        // Spectrum's own Fs/N/norm metadata does not carry over, matching
        // CVec's own abs() above (its result is a plain Vec too).
        Value::Spectrum(xs, ..) => Ok(Value::Vec(Arc::new(xs.iter().map(|c| cf(*c)).collect()))),
        Value::CMat(m) => {
            let (r, c) = m.shape();
            let data: Vec<f64> = m.as_slice().iter().map(|&z| cf(z)).collect();
            Ok(mat_value(Matrix::from_col_major(r, c, data)))
        }
        Value::Num(_) | Value::Bool(_) | Value::Vec(_) | Value::Mat(_) | Value::Signal(..) => {
            map1(v.clone(), rf)
        }
        other => e(format!(
            "cannot apply the operation to {}",
            other.type_name()
        )),
    }
}

/// `(rows, cols)` of any value; a vector is treated as a column `(k, 1)`.
/// The shape of `v`, or `None` when it has no meaningful one.
///
/// Split out from `shape_of` so a caller can tell "genuinely zero" from
/// "no answer". `shape()` itself keeps reporting `[0, 0]` for the latter,
/// exactly as before -- but `nrow`/`ncol` refuse instead, because
/// `nrow(sin)` answering `0` is the silent-wrong-answer shape this engine
/// works hard to avoid everywhere else.
fn shape_of_checked(v: &Value) -> Option<(usize, usize)> {
    let s = shape_of(v);
    if s == (0, 0) && !has_genuinely_zero_shape(v) {
        return None;
    }
    Some(s)
}

/// Whether `(0, 0)` is a real answer for this value rather than the
/// fallback. An empty collection genuinely has no rows.
fn has_genuinely_zero_shape(v: &Value) -> bool {
    match v {
        Value::Vec(xs) => xs.is_empty(),
        Value::CVec(xs) => xs.is_empty(),
        Value::List(xs) => xs.is_empty(),
        Value::Str(s) => s.is_empty(),
        Value::Mat(_) | Value::CMat(_) | Value::Table(_) | Value::Num(_) | Value::Bool(_) => true,
        Value::Quantity(inner, _) => has_genuinely_zero_shape(inner),
        _ => false,
    }
}

fn shape_of(v: &Value) -> (usize, usize) {
    match v {
        Value::Mat(m) => m.shape(),
        Value::CMat(m) => m.shape(),
        Value::Vec(xs) => (xs.len(), 1),
        Value::CVec(xs) => (xs.len(), 1),
        Value::Spectrum(xs, ..) => (xs.len(), 1),
        // A circuit is a model, not an array -- it has no shape of its own.
        Value::Circuit(_) => (1, 1),
        Value::Signal(xs, _, _) => (xs.len(), 1),
        Value::Num(_) | Value::Bool(_) | Value::Complex(_) => (1, 1),
        // A report handle is one thing, so (1, 1) -- NOT (0, 0).
        //
        // It cannot report its element count from here: the handle holds
        // indices and the document lives on the interpreter, which this
        // free function cannot reach. That leaves a choice, and (0, 0) is
        // the wrong half of it. `Value::Image` fell through to a (0, 0)
        // default and the result read as "empty image" rather than
        // "nobody taught this function about images" -- it cost two
        // sessions a wrong diagnosis each, because a plausible answer is
        // more expensive than an obviously broken one. A handle is
        // scalar-like; say that.
        Value::Report(_) => (1, 1),
        // `rows(df)`/`cols(df)` (and `size`/`shape`/`sizeof`) — § ergonomic
        // API layer, 2026-08-31: `rows`/`cols` are the free-function
        // aliases for `nrow`/`ncol` on a table, so this must return exactly
        // `(t.nrows(), t.ncols())`, the same values the dedicated
        // `"nrow"`/`"ncol"` match arms compute. Previously `Value::Table`
        // fell through to the `_ => (0, 0)` default below (a latent bug:
        // `shape(df)` silently returned `[0, 0]`), which nothing tested —
        // adding this arm is purely additive for every other type.
        Value::Table(t) => (t.nrows(), t.ncols()),
        // A tagged container has the shape of what it wraps -- the tag
        // says what the numbers mean, not how many there are.
        Value::Quantity(inner, _) => shape_of(inner),
        // `Value::Image` was the same latent bug as `Value::Table` directly
        // above, one type over: it fell through to `_ => (0, 0)`, so
        // `size(image_new(8, 8))` reported `[0, 0]` for a perfectly good
        // 8x8 image. Reported as a broken save/load round trip; it is
        // neither -- `print img` says `image(8x8 rgb)`, so the image is
        // populated and only the accessor was blind to it.
        //
        // (width, height), by Ahmed's ruling of 2026-09-09, and NOT the
        // rows-then-columns order every other type here uses.
        //
        // That inconsistency is deliberate and was chosen with the cost
        // stated: an image is the one value whose own constructors are
        // width-first -- `image_new(width, height)`, `resize(img, width,
        // height)`, `crop(img, x0, y0, width, height)` -- so returning
        // rows-first made the language contradict itself inside a single
        // type. `image_new(640, 480)` answered `[480, 640]`.
        //
        // Filling this arm the other way was reasonable and it decided a
        // language question inside a bugfix, which is how conventions get
        // set by whoever happens to touch the code. Put to Ahmed instead;
        // he held width-first, twice, the second time knowing this arm and
        // its test already shipped the opposite.
        //
        // If you are here to make images match matrices, the constructors
        // are what must move, and that is a migration, not an arm swap.
        Value::Image(img) => (img.width, img.height),

        // Anything with a length is that many rows of one column, matching
        // `value_len` term for term. The two disagreeing is exactly how the
        // original defect showed itself -- `shape(df)` said [4, 2] while
        // `len(df)` said 0 -- so they are written to be read side by side.
        Value::List(items) => (items.len(), 1),
        Value::Record(fields) => (fields.len(), 1),
        Value::Dict(pairs) => (pairs.len(), 1),
        Value::Str(s) => (s.chars().count(), 1),
        Value::Mask(m) => (m.len(), 1),
        Value::Fifo(f) => (f.lock().unwrap().len(), 1),
        Value::LinkedList(l) => (l.lock().unwrap().len(), 1),
        Value::Graph(g) => (g.lock().unwrap().node_count(), 1),
        Value::Queue(q) => (q.lock().unwrap().len(), 1),

        // No shape, and saying so is the answer rather than a fall-through.
        //
        // Not a catch-all, deliberately: this is the seventh instance of one
        // defect in this file -- `shape_of`'s own Table arm and `value_len`'s
        // Str arm both carry comments recording an earlier one, then
        // `value_unchanged` lost Worker, then its handle kinds, then `Func`
        // and `Table`, then `value_len` lost four more. Every one of those
        // was fixed by adding the missing arm and leaving the catch-all in
        // place for the next. Listing the shapeless kinds means the compiler
        // stops the next variant at the point it is declared.
        //
        // `Tensor` sits here under protest: it has a real shape and
        // reports none. Giving it one is an improvement and a decision
        // about what `shape` means for it -- flagged on the board, not
        // settled here.
        //
        // `Image` USED to sit here for the same reason, and this comment
        // outlived that by claiming otherwise. It cost two sessions real
        // time in one night: one quoted the old wording as proof the
        // deferral was still open, another read it and concluded the fix
        // was missing from master. Both readings were reasonable, because
        // the source said so. A stale comment is worse than a stale
        // artefact -- nothing rebuilds it, and the compiler will not
        // contradict it.
        Value::Artist(_)
        | Value::Channel(_)
        | Value::DoubleBuffer(_)
        | Value::EnumType(_)
        | Value::EnumVal(_)
        | Value::File(_)
        | Value::Func(_)
        | Value::Layer(_)
        | Value::Lazy(_)
        | Value::Mmap(_)
        | Value::Model(_)
        | Value::Module(_)
        | Value::Mutex(_)
        | Value::Nothing
        | Value::Pool(_)
        | Value::Process(_)
        | Value::Semaphore(_)
        | Value::Serial(_)
        | Value::TcpConn(_)
        | Value::TcpListener(_)
        | Value::Tensor(_)
        | Value::Timer(_)
        | Value::Unit(_, _)
        | Value::UrlStream(_)
        | Value::Worker(_) => (0, 0),
    }
}

/// Build a constant-filled value from `zeros`/`ones` arguments. `(n)` and the
/// degenerate `(k,1)`/`(1,k)` forms give a vector; a genuine `(r,c)` gives a
/// matrix.
/// Resolves the (rows, cols) shape for `zeros`/`ones`/`randn`/`rand`,
/// accepting either the two-scalar MATLAB form (`zeros(r, c)`) or a single
/// shape-vector argument (`zeros(size(x))`, `randn(size(x))` — the standard
/// "make something the same shape as x" idiom). `size(x)`/`shape(x)` always
/// returns a 2-element `[rows, cols]` `Value::Vec`, and plain `Value::as_num`
/// deliberately can't unwrap a multi-element vector — so before this helper,
/// passing a shape vector straight to `.as_num().unwrap_or(...)` silently
/// fell back to the 1x1 default instead of matching `x`'s actual shape.
fn shape_args(args: &[Value]) -> (usize, Option<usize>) {
    mark_all_args_read();
    if let [Value::Vec(v)] = args {
        let r = v.first().copied().unwrap_or(0.0) as usize;
        let c = v.get(1).copied().map(|c| c as usize);
        return (r, c);
    }
    let r = args.first().and_then(|v| v.as_num().ok()).unwrap_or(0.0) as usize;
    let c = args.get(1).and_then(|v| v.as_num().ok()).map(|c| c as usize);
    (r, c)
}

/// Expand a real-input FFT's non-negative-frequency half (`rfft_real`'s
/// `n/2+1` bins) into the full length-`n` spectrum `fft_complex` would
/// have produced from the same real signal, via the Hermitian symmetry
/// every real signal's spectrum has: `X[n-k] = conj(X[k])`. See
/// `eval_fft`'s own doc comment for why this exists rather than always
/// running the full complex transform.
///
/// `mirror != k` guards the one self-conjugate case (`n` even, `k = n/2`,
/// the Nyquist bin): `n - k == k` there, and that slot is already correct
/// from the copy above, so re-deriving it as its own conjugate would only
/// risk a floating-point-noise imaginary part on a value that should read
/// as exactly real.
fn mirror_half_spectrum(half: &[Complex64], n: usize) -> Vec<Complex64> {
    let mut full = vec![Complex64::real(0.0); n];
    let take = half.len().min(n);
    full[..take].copy_from_slice(&half[..take]);
    for (k, &h) in half.iter().enumerate().skip(1) {
        let mirror = n - k;
        if mirror != k {
            full[mirror] = h.conj();
        }
    }
    full
}

fn make_filled(args: &[Value], value: f64) -> Value {
    mark_all_args_read();
    let (r, c_opt) = shape_args(args);
    match c_opt {
        // One argument is the vector constructor and stays a vector.
        None => Value::Vec(Arc::new(vec![value; r])),
        // Two ARGUMENTS are a shape, and a shape with a 1 in it is still a
        // shape. This used to collapse `zeros(n, 1)` and `zeros(1, n)` to
        // the same plain vector, so a caller who asked for a column got
        // whatever orientation the next operation assumed -- and
        // `hstack(ones(n, 1), A)` refused, saying its 1xn block did not
        // match A's n rows. A row and a column are different matrices and
        // the caller said which one they wanted.
        //
        // A single argument that happens to be a `[rows, cols]` shape
        // VECTOR is the `zeros(size(x))` idiom, which means "the same
        // shape as x" and has always given a plain vector for a vector x.
        // That stays as it was: the caller passed a shape they did not
        // write, so they cannot have meant a particular orientation.
        Some(c) if args.len() >= 2 => Value::Mat(Arc::new(Matrix::filled(r, c, value))),
        Some(c) => {
            if r <= 1 {
                Value::Vec(Arc::new(vec![value; c]))
            } else if c <= 1 {
                Value::Vec(Arc::new(vec![value; r]))
            } else {
                Value::Mat(Arc::new(Matrix::filled(r, c, value)))
            }
        }
    }
}

fn reduce_cmp(name: &str, args: &[Value], style: &[(String, Value)], f: fn(f64, f64) -> f64) -> R<Value> {
    mark_all_args_read();
    let xs = apply_on_invalid(name, to_cow(arg0(args)?)?, style)?;
    if xs.is_empty() {
        return e("reduction of empty vector");
    }
    Ok(Value::Num(xs.iter().copied().reduce(f).unwrap()))
}

/// The index of the first element for which `better(candidate, current)`
/// holds strictly — `argmin`/`argmax`'s shared scan, `better = f64::lt`/
/// `f64::gt` respectively so the first occurrence wins ties, matching
/// `min`/`max`'s own left-to-right `reduce`.
///
/// NaN entries are skipped when picking the running best, not merely left
/// unable to displace it: `better`/`f64::lt`/`f64::gt` are false in *both*
/// directions against a NaN, so a naive "start at index 0" scan gets stuck
/// forever once a NaN becomes the running best — a leading NaN silently
/// pinned `argmin`/`argmax` to index 0 regardless of where the real
/// extremum was, breaking the `x[argmin(x)] == min(x)` invariant that
/// `min`/`max` themselves already uphold (`f64::min`/`f64::max` follow
/// IEEE `minNum`/`maxNum`, which ignore a NaN operand unless every value
/// is NaN). Only a NaN-free run of comparisons falls back to returning
/// index 0 (matching `f64::min`/`f64::max`'s own all-NaN answer of NaN).
fn arg_extremum(xs: &[f64], better: fn(&f64, &f64) -> bool) -> R<usize> {
    if xs.is_empty() {
        return e("reduction of empty vector");
    }
    let mut best: Option<usize> = None;
    for (i, x) in xs.iter().enumerate() {
        if x.is_nan() {
            continue;
        }
        best = match best {
            Some(b) if !better(x, &xs[b]) => Some(b),
            _ => Some(i),
        };
    }
    Ok(best.unwrap_or(0))
}

// ── `on_invalid=` (§ reduction NaN/Inf handling) ────────────────────────
//
// R's `na.rm=` for `mean`/`min`/`max`/`sum`/`std`/`var`/`median`/
// `quantile`/`argmin`/`argmax` -- the one place a NaN or Inf can corrupt a
// result without the language ever saying so, which is exactly the
// "silence is the worst failure" problem `style_entry`'s unread-keyword
// check and a shape mismatch already refuse elsewhere, just for invalid
// DATA instead of a bad call.
//
// Every one of the ten reductions funnels its input through
// `apply_on_invalid`/`arg_extremum_on_invalid` below (or, on a `Mat` under
// `axis=`, through the equivalent handling inside `reduce_axis`) rather
// than each reimplementing the three modes -- one place to get the
// "ignore" n-adjustment and the "error" message right, not ten.
#[derive(Clone, Copy, PartialEq, Eq)]
enum OnInvalid {
    /// `on_invalid="propagate"` — the default, and exactly the behavior
    /// every one of these ten reductions had before this keyword existed:
    /// a NaN/Inf in the input flows through untouched, whatever that
    /// reduction's own arithmetic (or, for `argmin`/`argmax`, its existing
    /// NaN-skipping scan) then does with it.
    Propagate,
    /// `on_invalid="ignore"` — every NaN and Inf element is dropped before
    /// the reduction runs (R's `na.rm=TRUE`, extended to Inf too). For
    /// `mean`/`std`/`var` this also shrinks the effective `n`: each of
    /// them measures the length of the already-filtered slice it is
    /// handed, not the original input.
    Ignore,
    /// `on_invalid="error"` — any NaN or Inf anywhere in the input raises,
    /// naming what was found and at what index, rather than silently
    /// returning a NaN/Inf result.
    Error,
}

/// Reads `on_invalid=` for one of the ten reductions above (default
/// `"propagate"`). Goes through `style_str`, so a call that supplies it is
/// marked "read" even when the value is invalid -- an unrecognized value
/// is this function's own error, not an "unknown keyword" one.
fn parse_on_invalid(f: &str, style: &[(String, Value)]) -> R<OnInvalid> {
    match style_str(style, "on_invalid").as_deref() {
        None | Some("propagate") => Ok(OnInvalid::Propagate),
        Some("ignore") => Ok(OnInvalid::Ignore),
        Some("error") => Ok(OnInvalid::Error),
        Some(other) => e(format!(
            "{f}: on_invalid=\"{other}\" is not recognized -- use \"propagate\" (default, \
             NaN/Inf flows through untouched), \"ignore\" (drop NaN/Inf before reducing), or \
             \"error\" (raise if any NaN/Inf is present)"
        )),
    }
}

/// The first NaN or Inf in `xs`, by index -- `on_invalid="error"`'s check.
fn first_invalid(xs: &[f64]) -> Option<(usize, &'static str)> {
    xs.iter().enumerate().find_map(|(i, x)| {
        if x.is_nan() {
            Some((i, "NaN"))
        } else if x.is_infinite() {
            Some((i, "Inf"))
        } else {
            None
        }
    })
}

/// The `Complex` counterpart of `first_invalid`, for `sum`'s `CVec` path --
/// a NaN/Inf in either the real or the imaginary part counts.
fn first_invalid_complex(xs: &[Complex64]) -> Option<(usize, &'static str)> {
    xs.iter().enumerate().find_map(|(i, c)| {
        if c.re.is_nan() || c.im.is_nan() {
            Some((i, "NaN"))
        } else if c.re.is_infinite() || c.im.is_infinite() {
            Some((i, "Inf"))
        } else {
            None
        }
    })
}

fn check_no_invalid(f: &str, xs: &[f64]) -> R<()> {
    match first_invalid(xs) {
        None => Ok(()),
        Some((i, kind)) => e(format!(
            "{f}: input contains {kind} at index {i} -- pass on_invalid=\"ignore\" to skip \
             invalid values, or on_invalid=\"propagate\" to allow them through"
        )),
    }
}

/// Applies an already-decided `OnInvalid` mode to `xs` -- the per-group
/// version `reduce_axis` uses (so a mode read once from `style` outside the
/// per-row/column loop can be replayed inside it without re-reading
/// `style` -- and re-marking `on_invalid` "read" -- once per row/column).
fn apply_on_invalid_mode<'a>(f: &str, xs: &'a [f64], mode: OnInvalid) -> R<Cow<'a, [f64]>> {
    match mode {
        OnInvalid::Propagate => Ok(Cow::Borrowed(xs)),
        OnInvalid::Error => {
            check_no_invalid(f, xs)?;
            Ok(Cow::Borrowed(xs))
        }
        OnInvalid::Ignore => Ok(Cow::Owned(xs.iter().copied().filter(|v| v.is_finite()).collect())),
    }
}

/// Applies `on_invalid=` (read from `style`) ahead of an ordinary
/// (non-axis, non-index-returning) reduction over `xs`: `"propagate"`
/// passes it through unchanged, `"error"` checks it and passes it through,
/// `"ignore"` drops every non-finite entry. `mean`/`std`/`var` end up
/// dividing by the count of the REMAINING valid elements under
/// `"ignore"` for free, because each of them measures `xs.len()` on
/// whatever this returns, after filtering, not the original input.
fn apply_on_invalid<'a>(f: &str, xs: Cow<'a, [f64]>, style: &[(String, Value)]) -> R<Cow<'a, [f64]>> {
    let mode = parse_on_invalid(f, style)?;
    match mode {
        OnInvalid::Propagate => Ok(xs),
        OnInvalid::Error => {
            check_no_invalid(f, &xs)?;
            Ok(xs)
        }
        OnInvalid::Ignore => Ok(Cow::Owned(xs.iter().copied().filter(|v| v.is_finite()).collect())),
    }
}

/// `argmin`/`argmax` under `on_invalid=`. Unlike `apply_on_invalid`, this
/// cannot simply filter `xs` first and hand the result to `arg_extremum`:
/// the returned index must refer to the position in the ORIGINAL array, so
/// a caller can use it to index back into their own data, even once
/// `"ignore"` has skipped some entries.
fn arg_extremum_on_invalid(
    f: &str,
    xs: &[f64],
    better: fn(&f64, &f64) -> bool,
    style: &[(String, Value)],
) -> R<usize> {
    if xs.is_empty() {
        return e("reduction of empty vector");
    }
    match parse_on_invalid(f, style)? {
        OnInvalid::Propagate => arg_extremum(xs, better),
        OnInvalid::Error => {
            check_no_invalid(f, xs)?;
            arg_extremum(xs, better)
        }
        OnInvalid::Ignore => {
            let mut best: Option<usize> = None;
            for (i, x) in xs.iter().enumerate() {
                if !x.is_finite() {
                    continue;
                }
                best = match best {
                    Some(b) if !better(x, &xs[b]) => Some(b),
                    _ => Some(i),
                };
            }
            best.ok_or_else(|| EvalError {
                msg: format!(
                    "{f}: every element is NaN or Inf -- nothing left after \
                     on_invalid=\"ignore\""
                ),
            })
        }
    }
}

/// The permutation that would sort `xs` ascending — `median`/`quantile`'s
/// `arg`-returning siblings need the original index a sorted position came
/// from, not just the sorted value itself.
///
/// Uses `f64::total_cmp`, not `partial_cmp().unwrap_or(Equal)`: the latter
/// treats a NaN as "equal" to every other element it's compared against,
/// which is not a valid (transitive) total order and silently corrupts the
/// sort of the surrounding *non-NaN* elements too, not just wherever the
/// NaN itself ends up — confirmed with `sort([5, 3, nan, 1, 4, 2])`, which
/// returned `[3, 5, NaN, 1, 2, 4]` (genuinely unsorted) before this fix.
/// `total_cmp` is IEEE 754's own `totalOrder` predicate: a real, transitive
/// ordering over every `f64` bit pattern, so every sort-based consumer
/// (`sort`/`unique`/`argsort` themselves, plus `median_of`/`quantile_of`
/// below) now at least produces a genuinely sorted sequence with any NaNs
/// pushed to one consistent end, rather than scrambling unrelated values.
fn argsort(xs: &[f64]) -> Vec<usize> {
    let mut idx: Vec<usize> = (0..xs.len()).collect();
    idx.sort_by(|&a, &b| xs[a].total_cmp(&xs[b]));
    idx
}

/// Schroeder's phase formula (1-indexed tone number `k` of `count` total):
/// `phi_k = -k(k-1)*pi/count`. A well-known deterministic choice that keeps
/// a multisine's crest factor low without iterative optimization —
/// `multisine`'s default when the caller doesn't supply `phases`.
fn schroeder_phases(count: usize) -> Vec<f64> {
    (0..count)
        .map(|k| {
            let kk = (k + 1) as f64;
            -kk * (kk - 1.0) * std::f64::consts::PI / count as f64
        })
        .collect()
}

/// A linear or logarithmic frequency sweep from `f0` to `f1` over `n`
/// samples at rate `fs`, reaching `f1` exactly at the last sample
/// (duration `T = (n-1)/fs`) — MATLAB's own `chirp` convention. Uses the
/// exact analytic phase integral of the instantaneous frequency in each
/// case (not a naive per-sample frequency-then-numerically-integrate
/// approximation, which would accumulate phase error over a long sweep):
/// linear `f(t) = f0 + (f1-f0)*t/T` integrates to
/// `phase(t) = 2*pi*(f0*t + (f1-f0)*t^2/(2T))`; logarithmic
/// `f(t) = f0*(f1/f0)^(t/T)` integrates to
/// `phase(t) = 2*pi*f0*T/ln(f1/f0) * ((f1/f0)^(t/T) - 1)`.
fn chirp_wave(f0: f64, f1: f64, fs: f64, n: usize, logarithmic: bool) -> R<Vec<f64>> {
    if n < 2 {
        return e("chirp: n must be at least 2 (a sweep needs a start and an end sample)");
    }
    if fs <= 0.0 {
        return e("chirp: fs must be positive");
    }
    let duration = (n - 1) as f64 / fs;
    if logarithmic {
        if f0 <= 0.0 || f1 <= 0.0 {
            return e("chirp: method=\"logarithmic\" needs f0 and f1 both positive");
        }
        if (f1 - f0).abs() < 1e-15 {
            return e("chirp: method=\"logarithmic\" needs f0 != f1");
        }
        let k = (f1 / f0).ln();
        Ok((0..n)
            .map(|i| {
                let t = i as f64 / fs;
                let phase = std::f64::consts::TAU * f0 * duration / k * ((k * t / duration).exp() - 1.0);
                phase.sin()
            })
            .collect())
    } else {
        let rate = (f1 - f0) / duration;
        Ok((0..n)
            .map(|i| {
                let t = i as f64 / fs;
                let phase = std::f64::consts::TAU * (f0 * t + 0.5 * rate * t * t);
                phase.sin()
            })
            .collect())
    }
}

/// Natural-sampling PWM: `+1` where `modulator[i]` exceeds a carrier wave
/// (`[-1, 1]`) at `carrier_freq`, else `-1`. `triangle` selects a symmetric
/// triangle carrier (the standard choice — natural sampling against a
/// triangle produces a pulse width that's a linear, undistorted function
/// of the modulator's own value, unlike a sawtooth carrier, which
/// introduces harmonic distortion) versus a rising sawtooth.
fn pwm_wave(modulator: &[f64], carrier_freq: f64, fs: f64, triangle: bool) -> R<Vec<f64>> {
    if carrier_freq <= 0.0 || fs <= 0.0 {
        return e("pwm: carrier_freq and fs must be positive");
    }
    let period = fs / carrier_freq;
    Ok(modulator
        .iter()
        .enumerate()
        .map(|(i, &m)| {
            let phase_frac = (i as f64 % period) / period; // 0..1
            let carrier = if triangle {
                if phase_frac < 0.5 { -1.0 + 4.0 * phase_frac } else { 3.0 - 4.0 * phase_frac }
            } else {
                -1.0 + 2.0 * phase_frac
            };
            if m > carrier { 1.0 } else { -1.0 }
        })
        .collect())
}

/// Shared body for `hann`/`hamming`/`blackman`: a symmetric (denominator
/// `n-1`) raised-cosine window, `a0 - a1*cos(2*pi*i/(n-1)) + a2*cos(4*pi*i/
/// (n-1))`. `hann`/`hamming` pass `a2=0.0`, collapsing the second cosine
/// term away. `n=1` returns `[1.0]` (no window to shape, and it sidesteps
/// the `n-1` divide-by-zero); `n=0` returns an empty vector.
fn raised_cosine_window(n: usize, a0: f64, a1: f64, a2: f64) -> Vec<f64> {
    if n == 0 {
        return vec![];
    }
    if n == 1 {
        return vec![1.0];
    }
    let denom = (n - 1) as f64;
    (0..n)
        .map(|i| {
            let phase = std::f64::consts::TAU * i as f64 / denom;
            a0 - a1 * phase.cos() + a2 * (2.0 * phase).cos()
        })
        .collect()
}

/// Kaiser window: `w[i] = I0(beta*sqrt(1-((2i/(n-1))-1)^2)) / I0(beta)`,
/// same symmetric (`n-1`) convention as the raised-cosine windows above.
/// `n=1` returns `[1.0]` (matching `raised_cosine_window`'s own
/// divide-by-zero guard).
fn kaiser_window(n: usize, beta: f64) -> Vec<f64> {
    if n == 0 {
        return vec![];
    }
    if n == 1 {
        return vec![1.0];
    }
    let denom = (n - 1) as f64;
    let i0_beta = numeric::special::bessel_i0(beta);
    (0..n)
        .map(|i| {
            let r = (2.0 * i as f64 / denom) - 1.0;
            let arg = beta * (1.0 - r * r).max(0.0).sqrt();
            numeric::special::bessel_i0(arg) / i0_beta
        })
        .collect()
}

/// Builds a length-`n` *periodic* (`sym=False`) analysis window for
/// `welch`/`periodogram`'s own segmentation — the convention spectral-
/// analysis tools want (a periodic window tiles cleanly under overlap-add;
/// see `qu_core::transforms::stft`'s own hardcoded periodic Hann), as
/// opposed to the `hann`/`hamming`/`blackman`/`kaiser` builtins above,
/// which are deliberately *symmetric* (`n-1` denominator, MATLAB's/SciPy's
/// `sym=True` default — the right choice for FIR filter design, which is
/// what `fir1` already uses them for). Rather than a second, separately-
/// maintained set of periodic trigonometric formulas, this reuses
/// `raised_cosine_window`/`kaiser_window`'s exact symmetric math via
/// SciPy's own `sym=False` construction: build the symmetric window one
/// sample longer (`n+1`) and drop the last sample — algebraically identical
/// to the periodic formula (`raised_cosine_window(n+1, ...)`'s denominator
/// is `n`, so its first `n` samples are exactly `a0 - a1*cos(2*pi*i/n) +
/// ...`, matching `qu_core::transforms::hann_window`'s own periodic
/// definition bin-for-bin).
/// `who` is the calling builtin's own name, so the error message names the
/// function the user actually typed. It used to be the hardcoded string
/// `"welch/periodogram"`, which was already only two of the four callers
/// and is now two of six -- a message that names a function the caller did
/// not call sends them to read the wrong documentation.
///
/// `"rectangular"`/`"boxcar"`/`"none"` is an all-ones window: no taper at
/// all. Previously this was an error, which left a caller who wanted the
/// un-tapered transform with no spelling for it (SciPy accepts `"boxcar"`
/// for exactly this). It matters most for `spectrum` below, where it is
/// the setting that makes the result agree bin-for-bin with a plain
/// `rfft(sig, scaling=)` -- i.e. the check that the windowing plumbing
/// does not quietly alter a spectrum nobody asked to have tapered.
fn periodic_analysis_window(
    who: &str,
    name: &str,
    n: usize,
    style: &[(String, Value)],
) -> R<Vec<f64>> {
    if n == 0 {
        return Ok(Vec::new());
    }
    if name == "rectangular" || name == "boxcar" || name == "none" {
        return Ok(vec![1.0; n]);
    }
    if n == 1 {
        return Ok(vec![1.0]);
    }
    let symmetric = match name {
        "hann" | "hanning" => raised_cosine_window(n + 1, 0.5, 0.5, 0.0),
        "hamming" => raised_cosine_window(n + 1, 0.54, 0.46, 0.0),
        "blackman" => raised_cosine_window(n + 1, 0.42, 0.5, 0.08),
        "kaiser" => {
            let beta = style_num(style, "beta").ok_or_else(|| EvalError {
                msg: format!("{who}: window=\"kaiser\" needs a beta= argument"),
            })?;
            kaiser_window(n + 1, beta)
        }
        other => {
            return e(format!(
                "{who}: unknown window `{other}`, expected \"hann\", \"hamming\", \
                 \"blackman\", \"kaiser\", or \"rectangular\""
            ))
        }
    };
    Ok(symmetric[..n].to_vec())
}

/// First-order (error-feedback) 1-bit sigma-delta modulator: quantize each
/// sample to `sign`, but feed the quantization error (`input - output`)
/// forward into the next sample via a running integrator — the standard
/// noise-shaping construction that pushes quantization error to higher
/// frequencies instead of spreading it evenly across the band the way a
/// plain `sign(x)` does.
fn sigma_delta_1bit(xs: &[f64]) -> Vec<f64> {
    let mut integrator = 0.0;
    xs.iter()
        .map(|&x| {
            integrator += x;
            let y = if integrator >= 0.0 { 1.0 } else { -1.0 };
            integrator -= y;
            y
        })
        .collect()
}

fn median_of(xs: &[f64]) -> R<f64> {
    if xs.is_empty() {
        return e("median: empty input");
    }
    let mut sorted = xs.to_vec();
    sorted.sort_by(f64::total_cmp);
    let n = sorted.len();
    Ok(if n % 2 == 1 {
        sorted[n / 2]
    } else {
        (sorted[n / 2 - 1] + sorted[n / 2]) / 2.0
    })
}

/// Linear-interpolation quantile (NumPy's default method): `q` maps to the
/// fractional rank `q*(n-1)`, interpolating between the two order
/// statistics it falls between.
fn quantile_of(xs: &[f64], q: f64) -> R<f64> {
    if xs.is_empty() {
        return e("quantile: empty input");
    }
    if !(0.0..=1.0).contains(&q) {
        return e("quantile: q must be between 0 and 1");
    }
    let mut sorted = xs.to_vec();
    sorted.sort_by(f64::total_cmp);
    let n = sorted.len();
    if n == 1 {
        return Ok(sorted[0]);
    }
    let pos = q * (n - 1) as f64;
    let lo = pos.floor() as usize;
    let hi = pos.ceil() as usize;
    let frac = pos - lo as f64;
    Ok(sorted[lo] * (1.0 - frac) + sorted[hi] * frac)
}

/// The original index of the element at order-statistic position `q`
/// (`0`=min, `1`=max, `0.5`=median, ...) — `argmedian`/`argquantile`'s
/// shared implementation. `round_to_lower` selects the lower of two
/// candidate ranks on an exact tie (used for `argmedian` on an even-length
/// `xs`, where the true median falls exactly between two elements and
/// there is no single "right" index); `argquantile` rounds to the nearest
/// rank instead.
fn arg_order_statistic(xs: &[f64], q: f64, round_to_lower: bool) -> R<usize> {
    if xs.is_empty() {
        return e("empty input");
    }
    if !(0.0..=1.0).contains(&q) {
        return e("q must be between 0 and 1");
    }
    let order = argsort(xs);
    let n = order.len();
    let pos = q * (n - 1) as f64;
    let rank = if round_to_lower {
        pos.floor() as usize
    } else {
        pos.round() as usize
    }
    .min(n - 1);
    Ok(order[rank])
}

/// Sample variance (N-1, unbiased) — `std_dev`'s square, factored out so
/// `var(x)` and `std(x)` can't silently drift to different conventions.
fn variance(xs: &[f64]) -> f64 {
    if xs.len() < 2 {
        return 0.0;
    }
    let m = xs.iter().sum::<f64>() / xs.len() as f64;
    xs.iter().map(|x| (x - m) * (x - m)).sum::<f64>() / (xs.len() as f64 - 1.0)
}

fn std_dev(xs: &[f64]) -> f64 {
    variance(xs).sqrt()
}

// ---- train/test data splitting (§ ML data-prep, 2026-08-24) ----
//
// Shared by `train_test_split`/`sequential_split`/`stratified_split`/
// `train_val_test_split` below. All four return a `Value::Model` handle
// (kind `"split"`/`"split3"`) with named `X_*`/`y_*` fields rather than
// anything positional: Qu has no tuple-unpacking assignment (see
// `BACKLOG.md`'s `argmin`/`argmax` write-up, "every 'returns two things'
// builtin ... returns a `Value::Model` with named fields"), and `emd`/
// `vmd`'s decomposition results already establish the same "just a bag of
// named values, no `fit`/`predict`" use of `ModelHandle` for a builtin
// that isn't a real fitted estimator — the precedent this follows.

/// Full Fisher–Yates shuffle of `0..n`, seeded — the same partial-shuffle
/// construction `kmeans_fit`'s random centroid init already uses (see
/// that function's own doc comment), just run to completion here since
/// every row needs a place in the permutation, not just `k` of them.
fn shuffled_row_order(rng: &mut Rng, n: usize) -> Vec<usize> {
    let mut order: Vec<usize> = (0..n).collect();
    for i in 0..n.saturating_sub(1) {
        let j = i + (rng.next_u64() as usize) % (n - i);
        order.swap(i, j);
    }
    order
}

/// Row count of anything shaped like a feature matrix: a plain `Vec` is a
/// single-column `(n,1)` matrix (matching `Value::to_matrix`'s own
/// promotion rule), a `Mat` is itself, and anything else goes through
/// `to_matrix` for a consistent error message.
fn value_row_count(v: &Value) -> R<usize> {
    match v {
        Value::Vec(xs) => Ok(xs.len()),
        Value::Mat(m) => Ok(m.rows()),
        other => other.to_matrix().map(|m| m.rows()).map_err(|msg| EvalError { msg }),
    }
}

/// Gathers `indices` (in the given order) out of an `X`-shaped value,
/// preserving whether it was a plain `Vec` (single feature column) or a
/// `Mat` — so `train_test_split(x_vec, y)` hands back plain vectors, not a
/// forced-2D matrix, while `train_test_split(X_mat, y)` keeps working the
/// same way `ols_model`/`ridge_model` already expect their `X` argument.
fn select_rows_value(v: &Value, indices: &[usize]) -> R<Value> {
    match v {
        Value::Vec(xs) => Ok(Value::Vec(Arc::new(indices.iter().map(|&i| xs[i]).collect()))),
        Value::Mat(m) => {
            let selected: Vec<Vec<f64>> = indices
                .iter()
                .map(|&i| m.row_vec(i).map_err(|se| EvalError { msg: se.to_string() }))
                .collect::<R<_>>()?;
            Ok(mat_value(Matrix::from_rows(&selected).map_err(|se| EvalError { msg: se.to_string() })?))
        }
        other => {
            let m = other.to_matrix().map_err(|msg| EvalError { msg })?;
            select_rows_value(&Value::Mat(Arc::new(m)), indices)
        }
    }
}

/// Validates `test_size` and turns it into an integer row count via
/// round-to-nearest — the same convention used inside `stratified_split`
/// per-class so the whole-dataset and per-class row counts round the same
/// way. `test_size` must be a fraction strictly between 0 and 1: an
/// empty train or test partition means the split isn't doing its job.
fn test_row_count(caller: &str, n: usize, test_size: f64) -> R<usize> {
    if !(test_size > 0.0 && test_size < 1.0) {
        return e(format!("{caller}: test_size must be strictly between 0 and 1, got {test_size}"));
    }
    if n < 2 {
        return e(format!("{caller}: need at least 2 rows to split, got {n}"));
    }
    let n_test = (n as f64 * test_size).round() as usize;
    Ok(n_test.clamp(1, n - 1))
}

/// Builds the two-way `X_train`/`X_test`/`y_train`/`y_test` handle from a
/// row permutation (`order`) plus how many of its trailing entries are the
/// test partition — `train_test_split`'s random case, `sequential_split`'s
/// identity-order case, and `stratified_split`'s per-class-then-
/// concatenated case all reduce to this one call.
fn make_split_model(x_val: &Value, y: &[f64], order: &[usize], n_test: usize) -> R<Value> {
    let n_train = order.len() - n_test;
    let (train_idx, test_idx) = order.split_at(n_train);
    let x_train = select_rows_value(x_val, train_idx)?;
    let x_test = select_rows_value(x_val, test_idx)?;
    let y_train: Vec<f64> = train_idx.iter().map(|&i| y[i]).collect();
    let y_test: Vec<f64> = test_idx.iter().map(|&i| y[i]).collect();
    Ok(Value::Model(Arc::new(ModelHandle::new(
        "split",
        vec![
            ("X_train".to_string(), x_train),
            ("X_test".to_string(), x_test),
            ("y_train".to_string(), Value::Vec(Arc::new(y_train))),
            ("y_test".to_string(), Value::Vec(Arc::new(y_test))),
        ],
    ))))
}

/// Most frequent value, grouped by exact bit pattern (so `0.1+0.2` and
/// `0.3` are correctly treated as distinct, unlike a tolerance-based
/// grouping would need to define). Ties broken by the smallest value.
fn mode_of(xs: &[f64]) -> f64 {
    let mut counts: HashMap<u64, (f64, usize)> = HashMap::new();
    for &x in xs {
        let entry = counts.entry(x.to_bits()).or_insert((x, 0));
        entry.1 += 1;
    }
    counts
        .values()
        .copied()
        .fold(None, |best: Option<(f64, usize)>, (v, c)| match best {
            Some((bv, bc)) if bc > c || (bc == c && bv <= v) => Some((bv, bc)),
            _ => Some((v, c)),
        })
        .map(|(v, _)| v)
        .unwrap_or(f64::NAN)
}

/// Population third/fourth standardized moment, shared by `skewness_of`/
/// `kurtosis_of` — both need the same mean-and-`m2` setup, just a
/// different power in the numerator.
fn standardized_moment(xs: &[f64], power: i32) -> R<f64> {
    if xs.len() < 2 {
        return e("needs at least 2 points");
    }
    let n = xs.len() as f64;
    let m = xs.iter().sum::<f64>() / n;
    let m2 = xs.iter().map(|x| (x - m).powi(2)).sum::<f64>() / n;
    if m2 == 0.0 {
        return e("moment is undefined for a constant vector (zero variance)");
    }
    let mk = xs.iter().map(|x| (x - m).powi(power)).sum::<f64>() / n;
    Ok(mk / m2.powf(power as f64 / 2.0))
}

fn skewness_of(xs: &[f64]) -> R<f64> {
    standardized_moment(xs, 3)
}

fn kurtosis_of(xs: &[f64]) -> R<f64> {
    standardized_moment(xs, 4)
}

fn linspace(a: f64, b: f64, n: usize) -> Vec<f64> {
    if n == 0 {
        return vec![];
    }
    if n == 1 {
        return vec![a];
    }
    let step = (b - a) / (n as f64 - 1.0);
    (0..n).map(|i| a + step * i as f64).collect()
}

/// Local mean and variance of `x` in a `window`-wide neighborhood around
/// each sample, shrinking at the edges rather than padding — the same
/// edge convention the `rolling_*` family already uses, and for the same
/// reason: a padded (clamped-repeat) window has no real variance of its
/// own, which would bias `remove_noise`'s Wiener estimate toward treating
/// the edges as pure noise.
fn local_mean_var(x: &[f64], window: usize) -> (Vec<f64>, Vec<f64>) {
    let n = x.len();
    let half = window / 2;
    let mut means = vec![0.0; n];
    let mut vars = vec![0.0; n];
    for i in 0..n {
        let lo = i.saturating_sub(half);
        let hi = (i + half + 1).min(n);
        let w = &x[lo..hi];
        let m = w.iter().sum::<f64>() / w.len() as f64;
        let v = w.iter().map(|v| (v - m).powi(2)).sum::<f64>() / w.len() as f64;
        means[i] = m;
        vars[i] = v;
    }
    (means, vars)
}

fn map1(v: Value, g: impl Fn(f64) -> f64 + Sync + Send) -> R<Value> {
    match v {
        Value::Num(x) => Ok(Value::Num(g(x))),
        Value::Bool(b) => Ok(Value::Num(g(if b { 1.0 } else { 0.0 }))),
        Value::Vec(xs) => Ok(Value::Vec(Arc::new(xs.iter().copied().map(g).collect()))),
        Value::Mat(m) => Ok(Value::Mat(Arc::new({
            let _dp = dprof::region(dprof::p::MAP1_KERNEL);
            m.map(g)
        }))),
        // elemental math on a signal keeps its Fs (Â§41.2): `sin(x)`, `-x`,
        // `sqrt(x)`, â€¦ are all still sampled at the same rate as `x`.
        //
        // It keeps the SAMPLING contract -- rate, time origin, markers,
        // regions, metadata -- because none of those are touched by a
        // per-sample function: sample `i` still happened when it happened.
        // It DROPS the calibration record, because `g` is an arbitrary
        // function and `physical = slope*raw + offset` is a precise numeric
        // claim that an unknown `g` almost certainly falsifies. `spl`
        // refusing after `sqrt(s)` is the correct outcome; answering from a
        // slope that no longer describes the samples is not.
        //
        // See `SigMeta::axis_only` for the one rule: the time axis survives
        // a per-sample function, the unit and calibration do not.
        Value::Signal(xs, fs, m) => Ok(Value::Signal(
            Arc::new(xs.iter().copied().map(g).collect()),
            fs,
            Arc::new(m.axis_only()),
        )),
        // Mirrors `as_num`'s own `Family`/`Temp` split: a linear-family
        // quantity unwraps silently into a plain `Value::Num` here too
        // (`sqrt(5 kHz)`, ...), same rationale as `as_num`.
        Value::Unit(n, UnitTag::Dim(..)) => Ok(Value::Num(g(n))),
        other => e(format!(
            "cannot apply a numeric operation to {}",
            other.type_name()
        )),
    }
}

/// `map1` for the functions that have a complex branch.
///
/// `exp`, `log` and `sqrt` are defined on the whole complex plane, and Qu
/// could not evaluate any of them there -- not even `exp(1i * pi)`. A
/// language with complex numbers, complex vectors, complex matrices and an
/// FFT, in which Euler's formula does not evaluate, cannot express a
/// phasor or a design matrix of tones; every port of an impedance or
/// transfer-function script hit it immediately.
///
/// Real input still takes the real function, so `sqrt(-1)` stays NaN
/// rather than silently becoming `i`: promoting reals to complex on
/// underflow of the domain would change the meaning of existing scripts.
fn map1_complex(
    v: Value,
    g: impl Fn(f64) -> f64 + Sync + Send,
    h: impl Fn(Complex64) -> Complex64,
) -> R<Value> {
    match v {
        Value::Complex(z) => Ok(Value::Complex(h(z))),
        Value::CVec(zs) => Ok(Value::CVec(Arc::new(zs.iter().copied().map(h).collect()))),
        Value::CMat(m) => {
            let (r, c) = m.shape();
            let data: Vec<Complex64> = m.as_slice().iter().copied().map(h).collect();
            Ok(cmat_value(CMatrix::from_col_major(r, c, data)))
        }
        other => map1(other, g),
    }
}

/// `map1_complex` for functions that have a real pole (`coth`/`csch` at
/// `x=0` and every `x=i*k*pi` in the complex plane; `atanh` at `x=+-1`).
///
/// `sqrt`/`log`'s existing convention is to hand back `NaN`/`-inf` at a
/// domain edge rather than erroring (see `map1_complex`'s own doc comment).
/// A pole is a narrower case than a domain edge -- the function is
/// undefined at that exact point, not merely complex-valued -- and Ahmed's
/// instruction for this batch was explicit: error there, don't silently
/// hand back `inf`/`NaN`. So this checks every element against `is_pole`
/// first and fails the whole call if any one of them hits it, before
/// `map1_complex` ever runs.
fn map1_complex_checked(
    v: Value,
    is_real_pole: impl Fn(f64) -> bool + Sync + Send,
    is_complex_pole: impl Fn(Complex64) -> bool + Sync + Send,
    pole_msg: impl Fn() -> String,
    g: impl Fn(f64) -> f64 + Sync + Send,
    h: impl Fn(Complex64) -> Complex64,
) -> R<Value> {
    let hit_real = match &v {
        Value::Num(x) => is_real_pole(*x),
        Value::Bool(_) => false,
        Value::Vec(xs) => xs.iter().any(|&x| is_real_pole(x)),
        Value::Mat(m) => m.as_slice().iter().any(|&x| is_real_pole(x)),
        Value::Signal(xs, _, _) => xs.iter().any(|&x| is_real_pole(x)),
        Value::Unit(n, UnitTag::Dim(_, _)) => is_real_pole(*n),
        _ => false,
    };
    let hit_complex = match &v {
        Value::Complex(z) => is_complex_pole(*z),
        Value::CVec(zs) => zs.iter().any(|&z| is_complex_pole(z)),
        Value::CMat(m) => m.as_slice().iter().any(|&z| is_complex_pole(z)),
        _ => false,
    };
    if hit_real || hit_complex {
        return e(pole_msg());
    }
    map1_complex(v, g, h)
}

/// Complex hyperbolic sine/cosine, by Euler's `sinh z = (e^z - e^-z)/2`,
/// `cosh z = (e^z + e^-z)/2`. Not a `Complex64` method (that type has none
/// of the three hyperbolics on `master` as of this batch -- `tanh`'s own
/// complex support is still on the unmerged `claude/complex-tanh` branch)
/// -- kept local to this crate rather than reaching into `qu-core` for a
/// two-line identity that `coth`/`sech`/`csch` are the only callers of.
fn complex_sinh(z: Complex64) -> Complex64 {
    z.exp().sub(z.scale(-1.0).exp()).scale(0.5)
}

fn complex_cosh(z: Complex64) -> Complex64 {
    z.exp().add(z.scale(-1.0).exp()).scale(0.5)
}

/// `map1` with a pole check first, for the real-only special functions
/// (`gamma`/`lgamma`, poles at every non-positive integer). No complex
/// branch: complex gamma is a real generalization this batch's brief did
/// not ask for, and getting its branch cuts right is its own project, not
/// a two-line addition alongside the real one.
fn map1_checked(
    v: Value,
    is_pole: impl Fn(f64) -> bool + Sync + Send,
    pole_msg: impl Fn(f64) -> String,
    g: impl Fn(f64) -> f64 + Sync + Send,
) -> R<Value> {
    let bad = match &v {
        Value::Num(x) => is_pole(*x).then_some(*x),
        Value::Vec(xs) => xs.iter().copied().find(|&x| is_pole(x)),
        Value::Mat(m) => m.as_slice().iter().copied().find(|&x| is_pole(x)),
        Value::Signal(xs, _, _) => xs.iter().copied().find(|&x| is_pole(x)),
        Value::Unit(n, UnitTag::Dim(_, _)) => is_pole(*n).then_some(*n),
        _ => None,
    };
    if let Some(x) = bad {
        return e(pole_msg(x));
    }
    map1(v, g)
}

fn map2(a: Value, b: Value, g: impl Fn(f64, f64) -> f64 + Sync + Send) -> R<Value> {
    match (a, b) {
        (Value::Vec(xs), Value::Vec(ys)) => {
            if xs.len() != ys.len() {
                return e(format!(
                    "vector length mismatch: {} vs {} (broadcasting of unequal vectors is an error)",
                    xs.len(),
                    ys.len()
                ));
            }
            Ok(Value::Vec(Arc::new(
                xs.iter().zip(ys.iter()).map(|(x, y)| g(*x, *y)).collect(),
            )))
        }
        (Value::Vec(xs), b) => {
            let y = b.as_num().map_err(|m| EvalError { msg: m })?;
            Ok(Value::Vec(Arc::new(xs.iter().copied().map(|x| g(x, y)).collect())))
        }
        (a, Value::Vec(ys)) => {
            let x = a.as_num().map_err(|m| EvalError { msg: m })?;
            Ok(Value::Vec(Arc::new(ys.iter().copied().map(|y| g(x, y)).collect())))
        }
        (a, b) => {
            let x = a.as_num().map_err(|m| EvalError { msg: m })?;
            let y = b.as_num().map_err(|m| EvalError { msg: m })?;
            Ok(Value::Num(g(x, y)))
        }
    }
}

/// Matrix-boundary arithmetic (Â§13/Â§14). `*` is matrix multiplication with
/// scalar expansion; `.*`, `+`, `-`, `/`, `./`, `^`, `mod` broadcast elementwise.
/// Reals are promoted to matrices (`Vec` â†’ column, scalar â†’ `1x1`).
/// Signal-aware arithmetic (Â§41.2): a `Signal` behaves like its underlying
/// vector for elementwise ops (`as_flat` unwraps it, same as a plain `Vec`),
/// and the result keeps the `Signal` wrapper -- propagating `Fs` exactly as
/// shape propagates for arrays. Combining two signals with different sample
/// rates is a contract error, never a silent guess at which one wins
/// (matching this codebase's existing shape-mismatch precedent).
fn signal_binop(op: &str, a: Value, b: Value) -> R<Value> {
    let fs = match (&a, &b) {
        (Value::Signal(_, fa, _), Value::Signal(_, fb, _)) => {
            if (fa - fb).abs() > 1e-9 {
                return e(format!(
                    "cannot combine signals with different sample rates (Fs={fa} vs Fs={fb})"
                ));
            }
            *fa
        }
        (Value::Signal(_, fa, _), _) => *fa,
        (_, Value::Signal(_, fb, _)) => *fb,
        _ => unreachable!("signal_binop called without a Signal operand"),
    };
    let xa = a.as_flat().map_err(|m| EvalError { msg: m })?;
    let xb = b.as_flat().map_err(|m| EvalError { msg: m })?;
    let g: fn(f64, f64) -> f64 = match op {
        "+" => |x, y| x + y,
        "-" => |x, y| x - y,
        "*" | ".*" => |x, y| x * y,
        "/" | "./" => |x, y| x / y,
        "^" | "**" | ".^" => |x, y| x.powf(y),
        "mod" => |x, y| x.rem_euclid(y),
        "==" | "!=" | "<" | ">" | "<=" | ">=" => {
            // comparisons produce a Mask, not a Signal.
            return compare(op, Value::Vec(Arc::new(xa)), Value::Vec(Arc::new(xb)));
        }
        _ => return e(format!("operator `{op}` is not supported on signals")),
    };
    let out: Vec<f64> = match (xa.len(), xb.len()) {
        (m, n) if m == n => xa.iter().zip(xb.iter()).map(|(&x, &y)| g(x, y)).collect(),
        (1, n) => (0..n).map(|i| g(xa[0], xb[i])).collect(),
        (m, 1) => (0..m).map(|i| g(xa[i], xb[0])).collect(),
        (m, n) => return e(format!("signal length mismatch: {m} vs {n}")),
    };
    Ok(Value::Signal(out.into(), fs, SigMeta::none()))
}

/// Elementwise matrix-boundary op: consumes both operands via `into_matrix`
/// (skips a full clone when a temporary's `Arc` isn't shared — see its doc
/// comment) rather than `to_matrix`, which always clones. A plain function,
/// not a closure capturing `a`/`b`: each `matrix_binop` match arm below
/// needs to move `a`/`b` independently (some call this, some don't, some
/// pattern-match on them first), which a shared capturing closure can't do.
/// Either a borrow of a `Value::Mat`'s existing buffer or a freshly built
/// one. Exists ONLY for the `QU_EW_BORROW=1` intervention experiment
/// described on `matrix_ew`.
enum EwOperand<'a> {
    Borrowed(&'a Matrix),
    Owned(Matrix),
}

impl std::ops::Deref for EwOperand<'_> {
    type Target = Matrix;
    fn deref(&self) -> &Matrix {
        match self {
            EwOperand::Borrowed(m) => m,
            EwOperand::Owned(m) => m,
        }
    }
}

/// `QU_EW_BORROW=1` — an INTERVENTION, not a proposed fix.
///
/// `orient_vec_for_broadcast` returns an owned `Matrix`, and for a
/// `Value::Mat` that means `Arc::try_unwrap(...).unwrap_or_else(clone)`:
/// a full deep copy whenever the `Arc` is still held by a live variable,
/// which is exactly what `A .* B` on two named variables does. But
/// `Matrix::broadcast` only ever takes `&Matrix`. So the copy buys
/// nothing, and switching it off is the cleanest way to test whether the
/// profiler's `orient` bucket is causally responsible for the time it is
/// charged: if it is, turning this on must remove that bucket AND the
/// matching slice of wall time together.
fn ew_borrow_enabled() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| std::env::var_os("QU_EW_BORROW").is_some())
}

fn matrix_ew(a: Value, b: Value, f: fn(f64, f64) -> f64) -> R<Value> {
    let _dp = dprof::region(dprof::p::EW_OTHER);
    let (b_rows, b_cols) = shape_of(&b);
    let (a_rows, a_cols) = shape_of(&a);
    if ew_borrow_enabled() {
        // Same two probes in the same two places, so the A/B comparison
        // is like-for-like: only the copy is gone.
        let am = {
            let _dp = dprof::region(dprof::p::EW_ORIENT_L);
            match &a {
                Value::Mat(m) => EwOperand::Borrowed(m.as_ref()),
                other => EwOperand::Owned(
                    orient_vec_for_broadcast(other.clone(), b_rows, b_cols)
                        .map_err(|m| EvalError { msg: m })?,
                ),
            }
        };
        let bm = {
            let _dp = dprof::region(dprof::p::EW_ORIENT_R);
            match &b {
                Value::Mat(m) => EwOperand::Borrowed(m.as_ref()),
                other => EwOperand::Owned(
                    orient_vec_for_broadcast(other.clone(), a_rows, a_cols)
                        .map_err(|m| EvalError { msg: m })?,
                ),
            }
        };
        let out = {
            let _dp = dprof::region(dprof::p::EW_KERNEL);
            am.broadcast(&bm, f)
        }
        .map_err(|se| EvalError { msg: se.to_string() })?;
        let _dp_wrap = dprof::region(dprof::p::EW_WRAP);
        return Ok(mat_value(out));
    }
    let am = {
        let _dp = dprof::region(dprof::p::EW_ORIENT_L);
        orient_vec_for_broadcast(a, b_rows, b_cols)
    }
    .map_err(|m| EvalError { msg: m })?;
    let bm = {
        let _dp = dprof::region(dprof::p::EW_ORIENT_R);
        orient_vec_for_broadcast(b, a_rows, a_cols)
    }
    .map_err(|m| EvalError { msg: m })?;
    let out = {
        let _dp = dprof::region(dprof::p::EW_KERNEL);
        am.broadcast(&bm, f)
    }
    .map_err(|se| EvalError {
        msg: se.to_string(),
    })?;
    let _dp_wrap = dprof::region(dprof::p::EW_WRAP);
    Ok(mat_value(out))
}

/// Promotes `v` to a `Matrix` for *elementwise broadcasting* specifically
/// (`matrix_ew`'s own callers: `+`/`-`/`.*`/`./`/`.^`/`mod` at the matrix
/// boundary) — not for matmul, which keeps `to_matrix`'s ordinary
/// column-default untouched (see `outer_product_row_times_column_needs_
/// explicit_orientation`, a deliberately load-bearing test for that
/// convention). Found via the autodiff benchmark (2026-08-24): a bare
/// `Value::Vec` always defaulting to a column silently broke the single
/// most common real use of "matrix plus vector" — `X*W + b`, adding a
/// per-output-channel bias row — either erroring outright (bias length
/// isn't the row count) or, worse, broadcasting against the *wrong* axis
/// when the bias length happened to equal `X*W`'s row count too. So here
/// specifically: a `Vec` whose length matches `other`'s column count (and
/// not, ambiguously, *also* its row count) orients as a row instead;
/// everywhere else — length matches rows, an ambiguous square match, or
/// `v` isn't a bare `Vec` at all — keeps the unchanged column default, so
/// this never touches a case that worked before.
fn orient_vec_for_broadcast(v: Value, other_rows: usize, other_cols: usize) -> Result<Matrix, String> {
    if let Value::Vec(xs) = &v {
        let len = xs.len();
        if len == other_cols && len != other_rows {
            return Matrix::from_rows(&[xs.as_ref().clone()]).map_err(|se| se.to_string());
        }
    }
    v.into_matrix()
}

/// `where(cond, a, b)` -- elementwise select, NumPy's three-argument form.
///
/// `a` and `b` may each be a scalar or an array; a scalar is used for every
/// position, which is how a masked-out region is written
/// (`where(valid, value, nan)`). Shape follows `cond`, so the result of
/// masking a grid is still that grid.
fn where_select(cond: &Value, a: &Value, b: &Value) -> R<Value> {
    // Truthiness is "not zero and not NaN", so a comparison result
    // (1.0/0.0), a `Mask`, and a hand-built 0/1 array all behave the same.
    fn truth(v: f64) -> bool {
        v != 0.0 && !v.is_nan()
    }
    let pick = |flags: &[f64], av: &[f64], bv: &[f64]| -> R<Vec<f64>> {
        let n = flags.len();
        let get = |src: &[f64], i: usize| -> R<f64> {
            match src.len() {
                1 => Ok(src[0]),
                l if l == n => Ok(src[i]),
                l => e(format!(
                    "where(cond, a, b): the condition has {n} elements but a branch has {l}"
                )),
            }
        };
        (0..n)
            .map(|i| {
                if truth(flags[i]) {
                    get(av, i)
                } else {
                    get(bv, i)
                }
            })
            .collect()
    };
    let flat = |v: &Value| -> R<Vec<f64>> {
        match v {
            Value::Num(n) => Ok(vec![*n]),
            Value::Bool(t) => Ok(vec![*t as i32 as f64]),
            Value::Mask(m) => Ok(m.iter().map(|&t| t as i32 as f64).collect()),
            Value::Mat(m) => Ok(m.as_slice().to_vec()),
            other => to_vec(other),
        }
    };
    let (fc, fa, fb) = (flat(cond)?, flat(a)?, flat(b)?);
    let out = pick(&fc, &fa, &fb)?;
    // Give the result the condition's own shape back.
    Ok(match cond {
        Value::Mat(m) => Matrix::from_col_major_checked(m.rows(), m.cols(), out)
            .map(|r| Value::Mat(Arc::new(r)))
            .unwrap_or_else(|_| Value::Vec(Arc::new(Vec::new()))),
        Value::Num(_) | Value::Bool(_) => Value::Num(out[0]),
        _ => Value::Vec(Arc::new(out)),
    })
}

fn matrix_binop(op: &str, a: Value, b: Value) -> R<Value> {
    match op {
        "*" => {
            // scalar expansion keeps the other operand's kind
            if let Value::Num(k) = a {
                return scale_value(b, k);
            }
            if let Value::Num(k) = b {
                return scale_value(a, k);
            }
            let am = a.into_matrix().map_err(|m| EvalError { msg: m })?;
            let bm = b.into_matrix().map_err(|m| EvalError { msg: m })?;
            let out = am.matmul(&bm).map_err(|se| EvalError {
                msg: se.to_string(),
            })?;
            Ok(mat_value(out))
        }
        "+" => matrix_ew(a, b, |x, y| x + y),
        "-" => matrix_ew(a, b, |x, y| x - y),
        ".*" => matrix_ew(a, b, |x, y| x * y),
        "/" | "./" => matrix_ew(a, b, |x, y| x / y),
        // `^`/`**` at a matrix boundary is matrix power (matching `*` = matmul):
        // `M^-1` is the inverse, `M^n` is repeated matmul. `.^` stays elementwise,
        // matching the `.* ./` family.
        "^" | "**" => {
            let m = a.into_matrix().map_err(|msg| EvalError { msg })?;
            let k = b.as_num().map_err(|msg| EvalError { msg })?;
            matrix_pow(&m, k)
        }
        ".^" => matrix_ew(a, b, |x, y| x.powf(y)),
        "mod" => matrix_ew(a, b, |x, y| x.rem_euclid(y)),
        // `A \ b` (MATLAB left-division): solves `A*x = b` for `x`. Reuses
        // the same min-norm least-squares solve `polyfit`/`scatterfit` build
        // on (`pinv(A) * b` under the hood) — exact for a square non-singular
        // `A`, least-squares-best for an overdetermined (tall) one.
        "\\" => {
            let am = a.into_matrix().map_err(|msg| EvalError { msg })?;
            let bm = b.into_matrix().map_err(|msg| EvalError { msg })?;
            let solution = numeric::linalg::least_squares(&am, &bm, None)
                .map_err(|le| EvalError { msg: le.to_string() })?;
            Ok(mat_value(solution))
        }
        ".\\" => matrix_ew(a, b, |x, y| y / x),
        // Elementwise comparison, broadcasting like the arithmetic
        // operators above and yielding 1.0/0.0 rather than a `Mask`.
        //
        // A `Mask` is a flat `Vec<bool>`, which would throw the shape away
        // -- and the shape is the whole point on a matrix: `arg > 0` over a
        // 400x400 grid is a mask *of that grid*, and the only useful things
        // to do with it (`where(cond, a, b)`, multiplying it in) need the
        // rows and columns back. 1.0/0.0 also matches what MATLAB's own
        // comparison returns for a matrix.
        "==" => matrix_ew(a, b, |x, y| (x == y) as i32 as f64),
        "!=" => matrix_ew(a, b, |x, y| (x != y) as i32 as f64),
        "<" => matrix_ew(a, b, |x, y| (x < y) as i32 as f64),
        ">" => matrix_ew(a, b, |x, y| (x > y) as i32 as f64),
        "<=" => matrix_ew(a, b, |x, y| (x <= y) as i32 as f64),
        ">=" => matrix_ew(a, b, |x, y| (x >= y) as i32 as f64),
        _ => e(format!("operator `{op}` is not supported on matrices")),
    }
}

/// Matrix power `M^k` (Â§13: `^` behaves like `*`, a matrix-boundary operator).
/// `k == -1` is the inverse; non-negative integers are repeated `matmul`;
/// other negative integers are `inv(M)` raised to `|k|`. Non-integer exponents
/// are rejected with a pointer to `.^` (elementwise power).
fn matrix_pow(m: &Matrix, k: f64) -> R<Value> {
    if k.fract() != 0.0 {
        return e(format!(
            "non-integer matrix power `^{k}` is not defined; use `.^` for elementwise power"
        ));
    }
    let (r, c) = m.shape();
    if k == 0.0 {
        if r != c {
            return e(format!("`M^0` needs a square matrix, got {r}x{c}"));
        }
        return Ok(mat_value(Matrix::eye(r)));
    }
    if k == 1.0 {
        return Ok(mat_value(m.clone()));
    }
    if k == -1.0 {
        return matrix_inverse(m);
    }
    let n = k.abs() as usize;
    if r != c {
        return e(format!("`M^{k}` needs a square matrix, got {r}x{c}"));
    }
    let base = if k < 0.0 {
        match matrix_inverse(m)? {
            Value::Mat(im) => (*im).clone(),
            Value::Num(x) => Matrix::from_col_major(1, 1, vec![x]),
            _ => unreachable!("matrix_inverse returns Mat or Num"),
        }
    } else {
        m.clone()
    };
    let mut out = base.clone();
    for _ in 1..n {
        out = out.matmul(&base).map_err(|se| EvalError { msg: se.to_string() })?;
    }
    Ok(mat_value(out))
}

/// Converts a `Value::Mat`-backed `Matrix` into the `image::Affine3`
/// `imwarp`'s Rust-level core (`Image::warp`) actually consumes. Accepts
/// either a full 3x3 (the standard homogeneous-coordinate form every
/// `affine_*` builder above returns) or a 2x3 (the common shorthand that
/// omits the always-`[0,0,1]` bottom row) -- the 2x3 case is padded with
/// that row rather than rejected, so a caller who built just the 2x3 "linear
/// part + translation" doesn't have to bolt the trivial row on by hand.
fn matrix_to_affine3(m: &Matrix) -> R<Affine3> {
    let (r, c) = m.shape();
    let g = |i: usize, j: usize| -> R<f64> { m.get(i, j).map_err(|se| EvalError { msg: se.to_string() }) };
    match (r, c) {
        (3, 3) => Ok(Affine3([
            [g(0, 0)?, g(0, 1)?, g(0, 2)?],
            [g(1, 0)?, g(1, 1)?, g(1, 2)?],
            [g(2, 0)?, g(2, 1)?, g(2, 2)?],
        ])),
        (2, 3) => Ok(Affine3([
            [g(0, 0)?, g(0, 1)?, g(0, 2)?],
            [g(1, 0)?, g(1, 1)?, g(1, 2)?],
            [0.0, 0.0, 1.0],
        ])),
        _ => e(format!("imwarp: transform matrix must be 3x3 (or 2x3), got {r}x{c}")),
    }
}

/// Shared plumbing for `imwarp`/`imtranslate`/`imscale`: reads the common
/// `method=`/`bbox=`/`fill=` style args (each wrapper picks its own
/// `loose_default` for `bbox` when the caller doesn't override it -- see
/// each builtin's own doc comment for why) and calls `Image::warp`. `fill`
/// is a single scalar in this pixel format's raw 0-255 byte scale (the same
/// scale `imerode`/binary-mask thresholds already use, NOT `imadjust`'s
/// normalized `[0,1]`), applied identically to all 3 channels -- per this
/// feature's spec, a full per-channel fill triple is out of scope for this
/// pass.
fn do_imwarp(img: &Image, affine: &Affine3, style: &[(String, Value)], loose_default: bool) -> R<Image> {
    let method = style_str(style, "method").unwrap_or_else(|| "bilinear".to_string());
    let bbox = style_str(style, "bbox").unwrap_or_else(|| if loose_default { "loose" } else { "crop" }.to_string());
    let loose = match bbox.as_str() {
        "loose" => true,
        "crop" => false,
        other => return e(format!("imwarp: unknown bbox `{other}` — use \"loose\" or \"crop\"")),
    };
    let fill_v = style_num(style, "fill").unwrap_or(0.0).round().clamp(0.0, 255.0) as u8;
    img.warp(affine, &method, loose, (fill_v, fill_v, fill_v)).map_err(|msg| EvalError { msg })
}

/// `M^-1` / `inv(M)`: the matrix inverse, computed via the shared SVD-backed
/// pseudo-inverse. Requires a square, full-rank matrix -- singular or
/// non-square inputs get a clear error pointing at `pinv` instead of a
/// silently wrong (or `Inf`-filled) answer.
fn matrix_inverse(m: &Matrix) -> R<Value> {
    let (r, c) = m.shape();
    if r != c {
        return e(format!(
            "matrix must be square to invert (got {r}x{c}); use pinv(M) for the pseudoinverse"
        ));
    }
    let result = numeric::linalg::pseudo_inverse(m, None).map_err(|le| EvalError {
        msg: le.to_string(),
    })?;
    if result.rank < r {
        return e(format!(
            "matrix is singular (rank {} of {r}); use pinv(M) for the pseudoinverse",
            result.rank
        ));
    }
    Ok(mat_value(result.matrix))
}

/// Least-squares polynomial fit: solves the Vandermonde system `V c = y`
/// (`V[i][k] = x[i]^(degree-k)`) via the same pseudoinverse solver as `pinv`.
/// Returns coefficients highest-degree-first (numpy/MATLAB convention).
fn polyfit(x: &[f64], y: &[f64], degree: usize) -> R<Vec<f64>> {
    if x.len() != y.len() {
        return e(format!(
            "polyfit: x and y must have the same length ({} vs {})",
            x.len(),
            y.len()
        ));
    }
    if x.is_empty() {
        return e("polyfit: x and y are empty");
    }
    let cols = degree + 1;
    if cols > x.len() {
        return e(format!(
            "polyfit: degree {degree} needs at least {cols} points, got {}",
            x.len()
        ));
    }
    let rows: Vec<Vec<f64>> = x
        .iter()
        .map(|&xi| (0..cols).rev().map(|p| xi.powi(p as i32)).collect())
        .collect();
    let vander = Matrix::from_rows(&rows).map_err(|se| EvalError { msg: se.to_string() })?;
    let observed = Matrix::from_rows(&y.iter().map(|&v| vec![v]).collect::<Vec<_>>())
        .map_err(|se| EvalError { msg: se.to_string() })?;
    let solution = numeric::linalg::least_squares(&vander, &observed, None)
        .map_err(|le| EvalError { msg: le.to_string() })?;
    Ok(solution.as_slice().to_vec())
}

/// Evaluates a `polyfit`-style (highest-degree-first) polynomial via
/// Horner's method.
fn polyval(coeffs: &[f64], x: f64) -> f64 {
    coeffs.iter().fold(0.0, |acc, &c| acc * x + c)
}

/// Validates that `m` is row-stochastic (every row non-negative and
/// summing to ~1, within a `1e-6` tolerance — loose enough for a script to
/// type `[0.7, 0.3]` by hand without a rounding false-alarm, tight enough
/// to actually catch a mistake). Square-ness is checked separately by each
/// call site that needs it (a transition matrix must be square; an HMM's
/// `(n,m)` emission matrix deliberately isn't). Shared by `markov_chain`'s
/// own transition matrix and `hmm`'s transition/emission matrices.
fn check_row_stochastic(m: &Matrix, ctx: &str) -> R<()> {
    let (r, c) = m.shape();
    if ctx == "markov_chain" && r != c {
        return e(format!("markov_chain: transition matrix must be square, got {r}x{c}"));
    }
    if ctx == "hmm: transition matrix" && r != c {
        return e(format!("hmm: transition matrix must be square, got {r}x{c}"));
    }
    for i in 0..r {
        let mut sum = 0.0;
        for j in 0..c {
            let v = m.get(i, j).unwrap_or(0.0);
            if v < -1e-9 {
                return e(format!("{ctx}: row {i} has a negative entry ({v}) — not a valid probability row"));
            }
            sum += v;
        }
        if (sum - 1.0).abs() > 1e-6 {
            return e(format!("{ctx}: row {i} sums to {sum}, not 1 — not row-stochastic"));
        }
    }
    Ok(())
}

/// `markov_chain.simulate(n_steps, [seed=])`'s implementation: a length-
/// `n_steps+1` sequence of state indices starting at `chain.initial_state`.
/// Each step samples the next state from the current row of
/// `chain.transition` via inverse-CDF (draw `u ~ Uniform[0,1)`, walk the
/// row's cumulative sum, take the first state where the cumulative sum
/// exceeds `u`) — the standard way to sample a discrete distribution from a
/// single uniform draw.
fn markov_simulate(m: &ModelHandle, n_steps: usize, seed: u64) -> R<Value> {
    let p = match m.field("transition") {
        Some(Value::Mat(mm)) => mm.clone(),
        _ => return e("markov_chain model is missing its transition field"),
    };
    let n = p.rows();
    let mut state = m.field("initial_state").and_then(|v| v.as_num().ok()).unwrap_or(0.0) as usize;
    let mut rng = Rng::new(seed);
    let mut path = Vec::with_capacity(n_steps + 1);
    path.push(state as f64);
    for _ in 0..n_steps {
        let u = rng.uniform();
        let mut cum = 0.0;
        let mut next_state = n - 1;
        for j in 0..n {
            cum += p.get(state, j).unwrap_or(0.0);
            if u < cum {
                next_state = j;
                break;
            }
        }
        state = next_state;
        path.push(state as f64);
    }
    Ok(Value::Vec(Arc::new(path)))
}

/// `markov_chain.stationary()`'s implementation: the fixed point `v = v*P`
/// via power iteration from a uniform start (`v <- v*P`, renormalize,
/// repeat until the L1 change drops below `1e-12` or `MAX_ITERS` is hit).
/// Deliberately not an eigenvector extraction — see the `"stationary"`
/// builtin arm's own doc comment for why `eig` doesn't apply here. Converges
/// for any irreducible aperiodic chain (the standard textbook precondition
/// for a unique stationary distribution); a reducible/periodic chain may
/// oscillate or converge to a start-dependent answer, same caveat every
/// power-iteration stationary-distribution method carries.
fn markov_stationary(m: &ModelHandle) -> R<Value> {
    let p = match m.field("transition") {
        Some(Value::Mat(mm)) => mm.clone(),
        _ => return e("markov_chain model is missing its transition field"),
    };
    let n = p.rows();
    let mut v = vec![1.0 / n as f64; n];
    const MAX_ITERS: usize = 10_000;
    for _ in 0..MAX_ITERS {
        let mut next = vec![0.0; n];
        for i in 0..n {
            if v[i] == 0.0 {
                continue;
            }
            for j in 0..n {
                next[j] += v[i] * p.get(i, j).unwrap_or(0.0);
            }
        }
        let sum: f64 = next.iter().sum();
        if sum > 0.0 {
            for x in next.iter_mut() {
                *x /= sum;
            }
        }
        let diff: f64 = v.iter().zip(&next).map(|(a, b)| (a - b).abs()).sum();
        v = next;
        if diff < 1e-12 {
            break;
        }
    }
    Ok(Value::Vec(Arc::new(v)))
}

/// Reads an `hmm` model's three fields back out as plain `(transition,
/// emission, initial)` — shared setup for `hmm_forward`/`hmm_viterbi`.
fn hmm_fields(m: &ModelHandle) -> R<(Arc<Matrix>, Arc<Matrix>, Vec<f64>)> {
    let trans = match m.field("transition") {
        Some(Value::Mat(mm)) => mm.clone(),
        _ => return e("hmm model is missing its transition field"),
    };
    let emission = match m.field("emission") {
        Some(Value::Mat(mm)) => mm.clone(),
        _ => return e("hmm model is missing its emission field"),
    };
    let initial = to_vec(m.field("initial").expect("hmm model always has initial"))?;
    Ok((trans, emission, initial))
}

/// The HMM forward algorithm (Rabiner 1989, §III.A): `alpha[i]` is
/// maintained in place across time steps rather than kept as a full `(T,n)`
/// history (Viterbi below needs the full history for backtracking; forward
/// only ever needs the previous time step). `alpha_0[i] = initial[i] *
/// emission[i][obs[0]]`; `alpha_t[j] = emission[j][obs[t]] * sum_i
/// alpha_{t-1}[i] * transition[i][j]`. The answer is `sum_i alpha_{T-1}[i]`
/// — the total probability of `obs`, marginalized over every hidden-state
/// path. Verified against the textbook 2-state "Healthy/Fever" HMM (see
/// `hmm_forward_matches_hand_computed_likelihood_on_the_healthy_fever_example`).
/// log-sum-exp: `ln(sum(exp(xs)))` computed without ever exponentiating the
/// raw (possibly hugely negative) terms directly -- shifts by the max term
/// first so the largest `exp()` argument is always `0.0`.
fn log_sum_exp(xs: &[f64]) -> f64 {
    let max_term = xs.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    if max_term == f64::NEG_INFINITY {
        return f64::NEG_INFINITY;
    }
    let sum: f64 = xs.iter().map(|&x| (x - max_term).exp()).sum();
    max_term + sum.ln()
}

/// Forward algorithm, computed in log-space throughout (not linear
/// probability space): a raw linear accumulation (`alpha[i] * trans[i][j]`)
/// underflows to exactly `0.0` once the cumulative probability drops below
/// `f64::MIN_POSITIVE`'s subnormal floor (roughly 745 nats of cumulative
/// log-likelihood, i.e. a few hundred observations for a typical model) --
/// verified this was a real, silent bug via a direct comparison against a
/// known-correct log-space Python/numpy reference on an 8000-step sequence
/// (2026-09-01). Log-space keeps every intermediate value finite and exact
/// regardless of sequence length; only the final returned linear
/// probability can still legitimately underflow to `0.0` for a very long
/// sequence -- that is the mathematically correct nearest-representable
/// answer at that point (the true probability really is unrepresentably
/// small in `f64`), not a bug, so it is left as a `Value::Num` return.
fn hmm_forward(m: &ModelHandle, obs: &[usize]) -> R<Value> {
    let (trans, emission, initial) = hmm_fields(m)?;
    let n = trans.rows();
    if obs.is_empty() {
        return e("forward: observation sequence must not be empty");
    }
    for &o in obs {
        if o >= emission.cols() {
            return e(format!("forward: observation symbol {o} is out of range (0..{})", emission.cols() - 1));
        }
    }
    let mut log_alpha: Vec<f64> = (0..n)
        .map(|i| initial[i].ln() + emission.get(i, obs[0]).unwrap_or(0.0).ln())
        .collect();
    for &o in &obs[1..] {
        let mut next = vec![0.0; n];
        for j in 0..n {
            let terms: Vec<f64> = (0..n).map(|i| log_alpha[i] + trans.get(i, j).unwrap_or(0.0).ln()).collect();
            next[j] = log_sum_exp(&terms) + emission.get(j, o).unwrap_or(0.0).ln();
        }
        log_alpha = next;
    }
    Ok(Value::Num(log_sum_exp(&log_alpha).exp()))
}

/// Viterbi decoding (Rabiner 1989, §III.B): `delta[t][i]` is the highest
/// LOG-probability (not linear probability — see `hmm_forward`'s doc
/// comment for why: a raw linear `delta[t-1][i] * trans[i][j]` accumulation
/// underflows to exactly `0.0` after a few hundred observations, and once
/// every candidate ties at `0.0`, `Iterator::max_by`'s documented "last
/// element wins on a tie" behavior means the decoded path silently gets
/// stuck on the highest-index state forever after — a real, confirmed bug,
/// not a hypothetical one: reproduced directly on an 8000-step synthetic
/// sequence against a known-correct log-space reference, divergence
/// starting almost exactly at the predicted ~300-step double-underflow
/// point). Log-space sidesteps this entirely: sums of logs never
/// underflow regardless of sequence length, and no `exp()` is needed at
/// any point in the decision-making (only comparisons), so there is no
/// remaining underflow risk at all, unlike `hmm_forward`'s necessarily
/// linear final return. `psi[t][i]` remembers which state at `t-1`
/// achieved that maximum (the backpointer walked in reverse to recover the
/// full path once `t` reaches the end). Verified against the same
/// textbook "Healthy/Fever" example as `hmm_forward` (see
/// `hmm_viterbi_recovers_the_textbook_healthy_fever_path`), including its
/// well-known `[Healthy, Healthy, Fever]` / `0.01512` answer, AND against
/// the 8000-step regression case.
fn hmm_viterbi(m: &ModelHandle, obs: &[usize]) -> R<Value> {
    let (trans, emission, initial) = hmm_fields(m)?;
    let n = trans.rows();
    if obs.is_empty() {
        return e("viterbi: observation sequence must not be empty");
    }
    for &o in obs {
        if o >= emission.cols() {
            return e(format!("viterbi: observation symbol {o} is out of range (0..{})", emission.cols() - 1));
        }
    }
    let t_len = obs.len();
    let mut delta = vec![vec![f64::NEG_INFINITY; n]; t_len];
    let mut psi = vec![vec![0usize; n]; t_len];
    for i in 0..n {
        delta[0][i] = initial[i].ln() + emission.get(i, obs[0]).unwrap_or(0.0).ln();
    }
    for t in 1..t_len {
        for j in 0..n {
            let (best_i, best_val) = (0..n)
                .map(|i| (i, delta[t - 1][i] + trans.get(i, j).unwrap_or(0.0).ln()))
                .max_by(|a, b| a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal))
                .expect("n >= 1: hmm always has at least one state");
            delta[t][j] = best_val + emission.get(j, obs[t]).unwrap_or(0.0).ln();
            psi[t][j] = best_i;
        }
    }
    let (last_state, _) = (0..n)
        .map(|i| (i, delta[t_len - 1][i]))
        .max_by(|a, b| a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal))
        .expect("n >= 1: hmm always has at least one state");
    let mut path = vec![0usize; t_len];
    path[t_len - 1] = last_state;
    for t in (1..t_len).rev() {
        path[t - 1] = psi[t][path[t]];
    }
    Ok(Value::Vec(Arc::new(path.into_iter().map(|s| s as f64).collect())))
}

/// `naive_bayes_model(X, y)`'s fit step: per class (the sorted distinct
/// values of `y`), per feature, the sample mean and variance (population
/// variance — divides by the class count, not `count - 1`; the small,
/// synthetic-dataset scale this targets makes the distinction negligible
/// and it keeps the formula the simplest correct one). A variance is
/// floored at `1e-9` (matching scikit-learn's own `var_smoothing` idea) so
/// a degenerate, exactly-constant feature within a class doesn't produce a
/// division by zero / `-inf` log-density at predict time. Returns
/// `(classes, (k,d) means, (k,d) variances, length-k priors)`.
fn naive_bayes_fit(x: &Matrix, y: &[f64]) -> R<(Vec<f64>, Matrix, Matrix, Vec<f64>)> {
    let (n, d) = x.shape();
    if n == 0 {
        return e("naive_bayes_model: X has no rows");
    }
    let mut classes: Vec<f64> = y.to_vec();
    classes.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    classes.dedup_by(|a, b| (*a - *b).abs() < 1e-12);
    let k = classes.len();
    let rows: Vec<Vec<f64>> = (0..n).map(|r| matrix_row(x, r)).collect();
    let mut means = vec![vec![0.0; d]; k];
    let mut variances = vec![vec![0.0; d]; k];
    let mut priors = vec![0.0; k];
    for (ci, &c) in classes.iter().enumerate() {
        let idxs: Vec<usize> = (0..n).filter(|&i| (y[i] - c).abs() < 1e-12).collect();
        let count = idxs.len();
        if count == 0 {
            continue;
        }
        priors[ci] = count as f64 / n as f64;
        for j in 0..d {
            let vals: Vec<f64> = idxs.iter().map(|&i| rows[i][j]).collect();
            let mean = vals.iter().sum::<f64>() / count as f64;
            let var = vals.iter().map(|v| (v - mean) * (v - mean)).sum::<f64>() / count as f64;
            means[ci][j] = mean;
            variances[ci][j] = var.max(1e-9);
        }
    }
    Ok((
        classes,
        Matrix::from_rows(&means).map_err(|se| EvalError { msg: se.to_string() })?,
        Matrix::from_rows(&variances).map_err(|se| EvalError { msg: se.to_string() })?,
        priors,
    ))
}

/// `voronoi(points)`'s implementation, on `spade`'s Delaunay triangulation
/// (see this crate's `Cargo.toml` for the crate choice). For each input
/// point (in input order), walks its dual Voronoi face's boundary edges
/// (`VoronoiFace::adjacent_edges`, clockwise) and collects the FINITE
/// vertex positions only (`VoronoiVertex::Inner`'s circumcenter — see
/// `spade::handles::VoronoiVertex`'s own doc comment); an `Outer` (infinite-
/// ray) vertex contributes nothing to the polygon but flips that cell's
/// `bounded` flag to `0`. This is deliberately NOT a closed polygon for an
/// unbounded cell (there is no finite point to close it with) — a script
/// reading `.cells[i]` gets exactly the real, finite vertices `spade`
/// computed, nothing synthesized. Returns a model with `points` (the input,
/// echoed back), `cells` (a `List` of per-point `(m_i, 2)` vertex-coordinate
/// matrices), and `bounded` (a `0`/`1` flag per point).
fn voronoi_diagram(points: &Matrix) -> R<Value> {
    use spade::{DelaunayTriangulation, Point2, Triangulation};
    let n = points.rows();
    if n < 2 {
        return e("voronoi: need at least 2 points");
    }
    let mut triangulation: DelaunayTriangulation<Point2<f64>> = DelaunayTriangulation::new();
    let mut handles = Vec::with_capacity(n);
    for r in 0..n {
        let x = points.get(r, 0).unwrap_or(0.0);
        let y = points.get(r, 1).unwrap_or(0.0);
        if !x.is_finite() || !y.is_finite() {
            return e(format!("voronoi: point {r} is not finite ({x}, {y})"));
        }
        let h = triangulation
            .insert(Point2::new(x, y))
            .map_err(|ie| EvalError { msg: format!("voronoi: could not insert point {r}: {ie:?}") })?;
        handles.push(h);
    }
    let mut cells = Vec::with_capacity(n);
    let mut bounded = Vec::with_capacity(n);
    for &h in &handles {
        let vh = triangulation.vertex(h);
        let face = vh.as_voronoi_face();
        let mut verts: Vec<Vec<f64>> = Vec::new();
        let mut is_bounded = true;
        for edge in face.adjacent_edges() {
            match edge.from().position() {
                Some(p) => verts.push(vec![p.x, p.y]),
                None => is_bounded = false,
            }
        }
        let cell_mat = if verts.is_empty() {
            Matrix::zeros(0, 2)
        } else {
            Matrix::from_rows(&verts).map_err(|se| EvalError { msg: se.to_string() })?
        };
        cells.push(Value::Mat(Arc::new(cell_mat)));
        bounded.push(if is_bounded { 1.0 } else { 0.0 });
    }
    let fields = vec![
        ("points".to_string(), Value::Mat(Arc::new(points.clone()))),
        ("cells".to_string(), Value::List(Arc::new(cells))),
        ("bounded".to_string(), Value::Vec(Arc::new(bounded))),
    ];
    Ok(Value::Model(Arc::new(ModelHandle::new("voronoi", fields))))
}

/// Lloyd's algorithm (`kmeans`/`kmeans_centers`) — random (not k-means++)
/// initial centroids for a simple, fully deterministic-under-`seed` first
/// cut. Runs to convergence (no assignment changes) or `MAX_ITERS`,
/// whichever comes first. Returns `(label per row, (k, d) centroid matrix)`;
/// a centroid that loses every point keeps its previous position rather
/// than becoming NaN (a real risk with random init on small/clustered
/// data), so a run never silently produces garbage centroids.
fn kmeans_fit(x: &Matrix, k: usize, seed: u64) -> R<(Vec<usize>, Matrix)> {
    const MAX_ITERS: usize = 100;
    let (n, d) = x.shape();
    if k == 0 || k > n {
        return e(format!("kmeans: k={k} must be between 1 and the number of rows ({n})"));
    }
    let rows: Vec<Vec<f64>> = (0..n).map(|r| (0..d).map(|c| x.get(r, c).unwrap_or(0.0)).collect()).collect();

    // random initial centroids: k distinct row indices, sampled without
    // replacement via a partial Fisher-Yates shuffle.
    let mut rng = Rng::new(seed);
    let mut order: Vec<usize> = (0..n).collect();
    for i in 0..k {
        let j = i + (rng.next_u64() as usize) % (n - i);
        order.swap(i, j);
    }
    let mut centers: Vec<Vec<f64>> = order[..k].iter().map(|&i| rows[i].clone()).collect();

    let dist2 = |a: &[f64], b: &[f64]| -> f64 { a.iter().zip(b).map(|(u, v)| (u - v) * (u - v)).sum() };
    let mut labels = vec![0usize; n];
    for _ in 0..MAX_ITERS {
        let mut changed = false;
        for (i, row) in rows.iter().enumerate() {
            let (best, _) = centers
                .iter()
                .enumerate()
                .map(|(c, center)| (c, dist2(row, center)))
                .min_by(|a, b| a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal))
                .unwrap();
            if labels[i] != best {
                labels[i] = best;
                changed = true;
            }
        }
        if !changed {
            break;
        }
        let mut sums = vec![vec![0.0; d]; k];
        let mut counts = vec![0usize; k];
        for (i, row) in rows.iter().enumerate() {
            counts[labels[i]] += 1;
            for c in 0..d {
                sums[labels[i]][c] += row[c];
            }
        }
        for c in 0..k {
            if counts[c] > 0 {
                for col in 0..d {
                    centers[c][col] = sums[c][col] / counts[c] as f64;
                }
            }
            // else: no points assigned this round — keep the previous
            // centroid rather than dividing by zero into NaN.
        }
    }
    let center_matrix = Matrix::from_rows(&centers).map_err(|se| EvalError { msg: se.to_string() })?;
    Ok((labels, center_matrix))
}

/// The standard median of a slice: sorts a scratch copy, then the middle
/// element (odd length) or the average of the two middle elements (even
/// length) — the same convention the `median` builtin itself uses.
/// `kmedians_fit`'s coordinate-wise center-update rule.
fn median_of_mut(vals: &mut [f64]) -> f64 {
    vals.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    let n = vals.len();
    if n % 2 == 1 {
        vals[n / 2]
    } else {
        (vals[n / 2 - 1] + vals[n / 2]) / 2.0
    }
}

/// The row index of `centers` nearest `row` under L1 (Manhattan) distance —
/// `kmedians_fit`'s own assignment rule, and `kmedians` model's `.predict`
/// use it identically. The L2 sibling is `nearest_center`, below.
fn nearest_center_l1(row: &[f64], centers: &Matrix) -> usize {
    let (k, d) = centers.shape();
    (0..k)
        .map(|c| {
            let dist: f64 = (0..d).map(|j| (row[j] - centers.get(c, j).unwrap_or(0.0)).abs()).sum();
            (c, dist)
        })
        .min_by(|a, b| a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal))
        .map(|(c, _)| c)
        .unwrap_or(0)
}

/// k-medians: identical assign/update/repeat-to-convergence loop shape to
/// `kmeans_fit` right above (same random-restart seeding, same "empty
/// cluster keeps its previous center" guard), but with both pieces that
/// actually make this k-medians instead of a relabeled k-means swapped
/// out: cluster assignment uses L1 (Manhattan) distance instead of squared
/// L2, and each cluster's center becomes the coordinate-wise MEDIAN of its
/// assigned points (`median_of`) instead of their mean. The median is the
/// whole reason this builtin exists — it moves far less than the mean
/// does when a cluster contains one extreme outlier, which is exactly
/// what `kmedians_model`'s own doc comment and this pass's tests check
/// numerically against `kmeans_fit` on identical data.
fn kmedians_fit(x: &Matrix, k: usize, seed: u64) -> R<(Vec<usize>, Matrix)> {
    const MAX_ITERS: usize = 100;
    let (n, d) = x.shape();
    if k == 0 || k > n {
        return e(format!("kmedians: k={k} must be between 1 and the number of rows ({n})"));
    }
    let rows: Vec<Vec<f64>> = (0..n).map(|r| (0..d).map(|c| x.get(r, c).unwrap_or(0.0)).collect()).collect();

    let mut rng = Rng::new(seed);
    let mut order: Vec<usize> = (0..n).collect();
    for i in 0..k {
        let j = i + (rng.next_u64() as usize) % (n - i);
        order.swap(i, j);
    }
    let mut centers: Vec<Vec<f64>> = order[..k].iter().map(|&i| rows[i].clone()).collect();

    let l1 = |a: &[f64], b: &[f64]| -> f64 { a.iter().zip(b).map(|(u, v)| (u - v).abs()).sum() };
    let mut labels = vec![0usize; n];
    for _ in 0..MAX_ITERS {
        let mut changed = false;
        for (i, row) in rows.iter().enumerate() {
            let (best, _) = centers
                .iter()
                .enumerate()
                .map(|(c, center)| (c, l1(row, center)))
                .min_by(|a, b| a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal))
                .unwrap();
            if labels[i] != best {
                labels[i] = best;
                changed = true;
            }
        }
        if !changed {
            break;
        }
        let mut members: Vec<Vec<usize>> = vec![Vec::new(); k];
        for (i, &lbl) in labels.iter().enumerate() {
            members[lbl].push(i);
        }
        for c in 0..k {
            if !members[c].is_empty() {
                for col in 0..d {
                    let mut vals: Vec<f64> = members[c].iter().map(|&i| rows[i][col]).collect();
                    centers[c][col] = median_of_mut(&mut vals);
                }
            }
            // else: no points assigned this round — keep the previous
            // center rather than leaving it undefined.
        }
    }
    let center_matrix = Matrix::from_rows(&centers).map_err(|se| EvalError { msg: se.to_string() })?;
    Ok((labels, center_matrix))
}

/// k-medoids via PAM (Partitioning Around Medoids), scoped down from full
/// exhaustive PAM to keep the per-round swap evaluation at the `O(k*n)`
/// the backlog asked for: after assigning every point to its nearest
/// medoid (plain Euclidean distance), each cluster independently tries
/// swapping ITS OWN medoid for each of its own non-medoid members and
/// keeps the swap if it lowers that cluster's own total distance to its
/// candidate medoid. This is the "standard algorithm" as specified —
/// evaluate a swap by its effect on the cluster actually being
/// reconsidered — rather than full PAM's pricier variant of
/// recomputing the global assignment cost for every candidate swap across
/// every cluster. Runs to convergence (no swap improves anything) or
/// `MAX_ITERS`. Returns `(label per row, medoid row-index per cluster)` —
/// deliberately indices into `x`, not a centroid matrix, since the actual
/// row values are trivially recoverable from them and the caller
/// (`kmedoids_model`) wants the indices too, to expose `medoid_indices`.
fn kmedoids_fit(x: &Matrix, k: usize, seed: u64) -> R<(Vec<usize>, Vec<usize>)> {
    const MAX_ITERS: usize = 100;
    let (n, d) = x.shape();
    if k == 0 || k > n {
        return e(format!("kmedoids: k={k} must be between 1 and the number of rows ({n})"));
    }
    let rows: Vec<Vec<f64>> = (0..n).map(|r| (0..d).map(|c| x.get(r, c).unwrap_or(0.0)).collect()).collect();
    let dist = |a: &[f64], b: &[f64]| -> f64 { a.iter().zip(b).map(|(u, v)| (u - v) * (u - v)).sum::<f64>().sqrt() };

    let mut rng = Rng::new(seed);
    let mut order: Vec<usize> = (0..n).collect();
    for i in 0..k {
        let j = i + (rng.next_u64() as usize) % (n - i);
        order.swap(i, j);
    }
    let mut medoids: Vec<usize> = order[..k].to_vec();

    let assign = |medoids: &[usize]| -> Vec<usize> {
        (0..n)
            .map(|i| {
                medoids
                    .iter()
                    .enumerate()
                    .map(|(c, &m)| (c, dist(&rows[i], &rows[m])))
                    .min_by(|a, b| a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal))
                    .map(|(c, _)| c)
                    .unwrap_or(0)
            })
            .collect()
    };

    let mut labels = assign(&medoids);
    for _ in 0..MAX_ITERS {
        let mut improved = false;
        for c in 0..k {
            let members: Vec<usize> = (0..n).filter(|&i| labels[i] == c).collect();
            if members.len() < 2 {
                continue; // no non-medoid member to try swapping in
            }
            let current_cost: f64 = members.iter().map(|&i| dist(&rows[i], &rows[medoids[c]])).sum();
            let mut best_cost = current_cost;
            let mut best_candidate = medoids[c];
            for &cand in &members {
                if cand == medoids[c] {
                    continue;
                }
                let cost: f64 = members.iter().map(|&i| dist(&rows[i], &rows[cand])).sum();
                if cost < best_cost {
                    best_cost = cost;
                    best_candidate = cand;
                }
            }
            if best_candidate != medoids[c] {
                medoids[c] = best_candidate;
                improved = true;
            }
        }
        if !improved {
            break;
        }
        labels = assign(&medoids);
    }
    Ok((labels, medoids))
}

/// PCA via `qu_core::linalg::svd` of the column-mean-centered `X`. Returns
/// `(projected (n,k), components (k,d), explained_variance_ratio (len k),
/// column_means (len d))` in one pass — `pca`/`pca_components`/
/// `pca_explained_variance` each pick the piece they need; re-running this
/// (no randomness involved, unlike `kmeans_fit`) is exactly reproducible,
/// not just cheap. `column_means` is only consumed by `pca_model`, which
/// needs the exact centering `X` was fit with to project new data
/// consistently in `.predict`.
fn pca_fit(x: &Matrix, k: usize) -> R<(Matrix, Matrix, Vec<f64>, Vec<f64>)> {
    let (n, d) = x.shape();
    let max_k = n.min(d);
    if k == 0 || k > max_k {
        return e(format!("pca: k={k} must be between 1 and min(rows, cols)={max_k}"));
    }
    let means: Vec<f64> = (0..d)
        .map(|c| (0..n).map(|r| x.get(r, c).unwrap_or(0.0)).sum::<f64>() / n as f64)
        .collect();
    let centered_rows: Vec<Vec<f64>> = (0..n)
        .map(|r| (0..d).map(|c| x.get(r, c).unwrap_or(0.0) - means[c]).collect())
        .collect();
    let centered = Matrix::from_rows(&centered_rows).map_err(|se| EvalError { msg: se.to_string() })?;
    let svd = numeric::linalg::svd(&centered).map_err(|le| EvalError { msg: le.to_string() })?;

    let total_variance: f64 = svd.singular_values.iter().map(|s| s * s).sum();
    let ratios: Vec<f64> = svd.singular_values[..k]
        .iter()
        .map(|s| if total_variance > 0.0 { (s * s) / total_variance } else { 0.0 })
        .collect();

    // components: the first k rows of V^T (already (rank, d)).
    let (vt_rows, vt_cols) = svd.v_t.shape();
    let component_rows: Vec<Vec<f64>> = (0..k.min(vt_rows))
        .map(|r| (0..vt_cols).map(|c| svd.v_t.get(r, c).unwrap_or(0.0)).collect())
        .collect();
    let components = Matrix::from_rows(&component_rows).map_err(|se| EvalError { msg: se.to_string() })?;

    // projected = U[:, :k] * diag(singular_values[:k]).
    let (u_rows, _) = svd.u.shape();
    let projected_rows: Vec<Vec<f64>> = (0..u_rows)
        .map(|r| (0..k).map(|c| svd.u.get(r, c).unwrap_or(0.0) * svd.singular_values[c]).collect())
        .collect();
    let projected = Matrix::from_rows(&projected_rows).map_err(|se| EvalError { msg: se.to_string() })?;

    Ok((projected, components, ratios, means))
}

// ---- DBSCAN / Gaussian Mixture Model / t-SNE ----

/// Standard density-based clustering (Ester, Kriegel, Sander & Xu 1996):
/// for each unvisited point, find its `eps`-neighborhood (Euclidean,
/// including the point itself — the same convention scikit-learn's
/// `min_samples` uses); if it has at least `min_samples` neighbors it
/// seeds a new cluster, which absorbs every point density-reachable from
/// it (a neighbor's own neighborhood only gets folded into the search
/// queue if that neighbor is *itself* dense enough — a "border" point
/// joins the cluster but doesn't further expand it). Points no cluster
/// ever reaches are noise, labeled `-1`. O(n^2) (a full pairwise distance
/// scan per point) — fine for the dataset sizes this interpreter targets;
/// a spatial index would be the next step for very large `n`.
fn dbscan_fit(x: &Matrix, eps: f64, min_samples: usize) -> R<Vec<f64>> {
    let (n, d) = x.shape();
    if eps <= 0.0 {
        return e("dbscan: eps must be positive");
    }
    if min_samples == 0 {
        return e("dbscan: min_samples must be at least 1");
    }
    if n == 0 {
        return Ok(Vec::new());
    }
    let rows: Vec<Vec<f64>> = (0..n).map(|r| matrix_row(x, r)).collect();
    let eps2 = eps * eps;
    let region_query = |p: usize| -> Vec<usize> {
        (0..n)
            .filter(|&q| {
                let dist2: f64 = (0..d).map(|c| { let diff = rows[p][c] - rows[q][c]; diff * diff }).sum();
                dist2 <= eps2
            })
            .collect()
    };
    let mut visited = vec![false; n];
    let mut labels: Vec<i64> = vec![-1; n];
    let mut cluster_id: i64 = 0;
    for p in 0..n {
        if visited[p] {
            continue;
        }
        visited[p] = true;
        let neighbors = region_query(p);
        if neighbors.len() < min_samples {
            continue; // stays -1 (noise) unless a later cluster absorbs it as a border point
        }
        labels[p] = cluster_id;
        let mut queue: std::collections::VecDeque<usize> = neighbors.into_iter().collect();
        while let Some(q) = queue.pop_front() {
            if !visited[q] {
                visited[q] = true;
                let q_neighbors = region_query(q);
                if q_neighbors.len() >= min_samples {
                    queue.extend(q_neighbors);
                }
            }
            if labels[q] == -1 {
                labels[q] = cluster_id;
            }
        }
        cluster_id += 1;
    }
    Ok(labels.into_iter().map(|l| l as f64).collect())
}

/// Weighted sample covariance of `rows` around `mean`: `sum_i w_i (x_i -
/// mean)(x_i - mean)^T / total_weight` — `gmm_fit`'s shared building
/// block for both its k-means-warm-start initialization (`weights` all
/// `1.0`, `total_weight` = member count) and its EM M-step (`weights` =
/// that component's responsibilities, `total_weight` = their sum `N_k`).
fn weighted_covariance(rows: &[Vec<f64>], weights: &[f64], mean: &[f64], total_weight: f64, d: usize) -> Matrix {
    let mut cov = vec![vec![0.0; d]; d];
    for (row, &w) in rows.iter().zip(weights) {
        if w == 0.0 {
            continue;
        }
        let diff: Vec<f64> = (0..d).map(|j| row[j] - mean[j]).collect();
        for a in 0..d {
            for b in 0..d {
                cov[a][b] += w * diff[a] * diff[b];
            }
        }
    }
    let denom = total_weight.max(1e-12);
    for row in cov.iter_mut() {
        for v in row.iter_mut() {
            *v /= denom;
        }
    }
    Matrix::from_rows(&cov).expect("weighted_covariance always builds a square matrix")
}

/// `chol(cov + reg*I)`, growing `reg` geometrically (starting at `eps`)
/// until it succeeds — a covariance estimated from too few/too collinear
/// points can drift to not-quite-positive-definite by floating-point
/// error alone, and `gmm_fit`'s EM loop needs a fresh Cholesky factor
/// every single iteration (for both the log-density and, via `mvnpdf`'s
/// own reasoning, to avoid ever forming an explicit inverse).
fn regularized_cholesky(cov: &Matrix, eps: f64) -> R<Matrix> {
    let d = cov.rows();
    let mut reg = eps.max(1e-12);
    for _ in 0..12 {
        let mut m = cov.clone();
        for i in 0..d {
            let v = m.get(i, i).unwrap_or(0.0);
            m.set(i, i, v + reg).ok();
        }
        if let Ok(result) = numeric::linalg::cholesky(&m) {
            return Ok(result.l);
        }
        reg *= 10.0;
    }
    e("gmm_model: a component's covariance matrix would not become positive-definite even after regularization")
}

/// The multivariate Gaussian **log**-density at `point`, given `mean` and
/// the Cholesky factor `l` of its covariance — the same numerically-stable
/// `log det = 2*sum(log diag(L))` / "quadratic form via forward
/// substitution" formulation as the `mvnpdf` builtin, kept in log-space
/// here (rather than exponentiating immediately) since `gmm_fit`'s
/// responsibilities need `log(weight) + log_density` summed via
/// log-sum-exp for numerical stability across possibly many components.
fn gmm_log_density(point: &[f64], mean: &[f64], l: &Matrix) -> f64 {
    let k = point.len();
    let log_det: f64 = 2.0 * (0..k).map(|i| l.get(i, i).unwrap_or(1.0).ln()).sum::<f64>();
    let const_term = -0.5 * k as f64 * (2.0 * std::f64::consts::PI).ln() - 0.5 * log_det;
    let diff: Vec<f64> = point.iter().zip(mean).map(|(x, m)| x - m).collect();
    let y = forward_substitute(l, &diff);
    let quad: f64 = y.iter().map(|v| v * v).sum();
    const_term - 0.5 * quad
}

/// Slice component `c`'s own `(d,d)` covariance out of `gmm_model`'s
/// stacked `(k*d, d)` `.covariances` field (rows `[c*d, (c+1)*d)`) — see
/// that field's own doc comment for why it's stacked instead of a genuine
/// 3-D tensor (Qu doesn't have one).
fn gmm_component_cov(covariances: &Matrix, c: usize, d: usize) -> Matrix {
    let rows: Vec<Vec<f64>> = (0..d)
        .map(|i| (0..d).map(|j| covariances.get(c * d + i, j).unwrap_or(0.0)).collect())
        .collect();
    Matrix::from_rows(&rows).unwrap_or_else(|_| Matrix::zeros(d, d))
}

/// Gaussian Mixture Model via Expectation-Maximization (Dempster, Laird &
/// Rubin 1977). Warm-starts from `kmeans_fit`'s own hard partition: each
/// component's initial mean/covariance/weight comes from the points
/// `kmeans_fit` assigned it (falling back to the whole dataset's own
/// covariance for a component `kmeans_fit` handed fewer than 2 points,
/// which can't estimate its own covariance). Then alternates:
/// - **E-step**: `resp[i][c]` = the posterior probability point `i` came
///   from component `c`, computed via `gmm_log_density` and a
///   log-sum-exp normalization (so this doesn't underflow for points far
///   from every component, or overflow for high-dimensional `X`).
/// - **M-step**: each component's weight/mean/covariance re-estimated as
///   the responsibility-weighted mean/covariance of the *whole* dataset
///   (via `weighted_covariance`) — a component with near-zero total
///   responsibility this round (`N_k < 1e-9`) keeps its previous
///   mean/covariance/weight rather than dividing by ~zero.
///
/// Returns `(means (k,d), covariances (k*d,d) stacked, weights (len k),
/// log_likelihood (one entry per EM iteration actually run))` — the total
/// log-likelihood is a real, checkable EM invariant: it never decreases
/// iteration over iteration (verified in this pass's own test). Stops
/// once the log-likelihood's iteration-over-iteration change is below a
/// combined absolute/relative tolerance, or after `max_iter`, whichever
/// comes first.
fn gmm_fit(x: &Matrix, k: usize, seed: u64, max_iter: usize) -> R<(Matrix, Matrix, Vec<f64>, Vec<f64>)> {
    let (n, d) = x.shape();
    if k == 0 || k > n {
        return e(format!("gmm_model: k={k} must be between 1 and the number of rows ({n})"));
    }
    let rows: Vec<Vec<f64>> = (0..n).map(|r| matrix_row(x, r)).collect();

    let (labels, centers) = kmeans_fit(x, k, seed)?;
    let mut means: Vec<Vec<f64>> = (0..k).map(|c| matrix_row(&centers, c)).collect();

    let global_mean: Vec<f64> = (0..d).map(|j| rows.iter().map(|r| r[j]).sum::<f64>() / n as f64).collect();
    let ones = vec![1.0; n];
    let global_cov = weighted_covariance(&rows, &ones, &global_mean, n as f64, d);

    let mut covs: Vec<Matrix> = (0..k)
        .map(|c| {
            let member_rows: Vec<Vec<f64>> = rows
                .iter()
                .zip(&labels)
                .filter(|(_, &l)| l == c)
                .map(|(r, _)| r.clone())
                .collect();
            if member_rows.len() < 2 {
                global_cov.clone()
            } else {
                let w = vec![1.0; member_rows.len()];
                weighted_covariance(&member_rows, &w, &means[c], member_rows.len() as f64, d)
            }
        })
        .collect();

    let mut weights: Vec<f64> = (0..k)
        .map(|c| (labels.iter().filter(|&&l| l == c).count().max(1)) as f64 / n as f64)
        .collect();
    let weight_sum: f64 = weights.iter().sum();
    for w in weights.iter_mut() {
        *w /= weight_sum;
    }

    const REG: f64 = 1e-6;
    const TOL: f64 = 1e-6;
    let mut ll_history: Vec<f64> = Vec::new();
    let mut resp = vec![vec![0.0; k]; n];

    for _ in 0..max_iter {
        let chols: Vec<Matrix> = covs
            .iter()
            .map(|c| regularized_cholesky(c, REG))
            .collect::<R<Vec<_>>>()?;

        let mut total_ll = 0.0;
        for i in 0..n {
            let mut log_terms = vec![0.0; k];
            for c in 0..k {
                log_terms[c] = weights[c].max(1e-300).ln() + gmm_log_density(&rows[i], &means[c], &chols[c]);
            }
            let m = log_terms.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
            let sum_exp: f64 = log_terms.iter().map(|&v| (v - m).exp()).sum();
            let log_sum = m + sum_exp.ln();
            total_ll += log_sum;
            for c in 0..k {
                resp[i][c] = (log_terms[c] - log_sum).exp();
            }
        }
        ll_history.push(total_ll);
        if ll_history.len() >= 2 {
            let prev = ll_history[ll_history.len() - 2];
            if (total_ll - prev).abs() < TOL * (1.0 + total_ll.abs()) {
                break;
            }
        }

        for c in 0..k {
            let nk: f64 = (0..n).map(|i| resp[i][c]).sum();
            if nk < 1e-9 {
                continue;
            }
            let mut new_mean = vec![0.0; d];
            for i in 0..n {
                let r = resp[i][c];
                for j in 0..d {
                    new_mean[j] += r * rows[i][j];
                }
            }
            for v in new_mean.iter_mut() {
                *v /= nk;
            }
            let rw: Vec<f64> = (0..n).map(|i| resp[i][c]).collect();
            covs[c] = weighted_covariance(&rows, &rw, &new_mean, nk, d);
            means[c] = new_mean;
            weights[c] = nk / n as f64;
        }
    }

    let means_mat = Matrix::from_rows(&means).map_err(|se| EvalError { msg: se.to_string() })?;
    let mut cov_rows: Vec<Vec<f64>> = Vec::with_capacity(k * d);
    for cov in &covs {
        for i in 0..d {
            cov_rows.push((0..d).map(|j| cov.get(i, j).unwrap_or(0.0)).collect());
        }
    }
    let covs_mat = Matrix::from_rows(&cov_rows).map_err(|se| EvalError { msg: se.to_string() })?;

    Ok((means_mat, covs_mat, weights, ll_history))
}

/// `model.predict`/`.score` for a `"gmm"` model: evaluates every row of
/// `x` against every component (via `gmm_log_density` on each
/// component's own `regularized_cholesky` factor), returning both the
/// total log-likelihood (`.score`'s answer) and the hard
/// `argmax`-responsibility label per row (`.predict`'s answer) from one
/// shared pass, since both need the same per-component log-densities.
fn gmm_evaluate(x: &Matrix, means: &Matrix, covariances: &Matrix, weights: &[f64]) -> R<(f64, Vec<f64>)> {
    let k = weights.len();
    let d = means.cols();
    if x.cols() != d {
        return e(format!(
            "gmm: model was fit on {d} feature(s), input has {} — a single new point needs an \
             explicit orientation, e.g. `[a, b] as matrix(1, 2)`, since a bare vector defaults to a column",
            x.cols()
        ));
    }
    let chols: Vec<Matrix> = (0..k)
        .map(|c| regularized_cholesky(&gmm_component_cov(covariances, c, d), 1e-6))
        .collect::<R<Vec<_>>>()?;
    let mean_rows: Vec<Vec<f64>> = (0..k).map(|c| matrix_row(means, c)).collect();
    let n = x.rows();
    let mut total_ll = 0.0;
    let mut labels = vec![0.0; n];
    for i in 0..n {
        let row = matrix_row(x, i);
        let mut log_terms = vec![0.0; k];
        for c in 0..k {
            log_terms[c] = weights[c].max(1e-300).ln() + gmm_log_density(&row, &mean_rows[c], &chols[c]);
        }
        let m = log_terms.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
        let sum_exp: f64 = log_terms.iter().map(|&v| (v - m).exp()).sum();
        total_ll += m + sum_exp.ln();
        let (best_c, _) = log_terms
            .iter()
            .enumerate()
            .max_by(|a, b| a.1.partial_cmp(b.1).unwrap_or(std::cmp::Ordering::Equal))
            .expect("k >= 1");
        labels[i] = best_c as f64;
    }
    Ok((total_ll, labels))
}

/// The `Hbeta` step from van der Maaten & Hinton's original t-SNE
/// pseudocode: given one point's squared distances `di` to every *other*
/// point and a precision `beta = 1/(2*sigma^2)`, returns `(H, P)` where
/// `P` is the normalized conditional affinity row and `H` is its Shannon
/// entropy in nats (so `exp(H)` is that row's perplexity) — `tsne_fit`'s
/// binary search adjusts `beta` until `H` matches `ln(target_perplexity)`.
fn tsne_hbeta(di: &[f64], beta: f64) -> (f64, Vec<f64>) {
    let p: Vec<f64> = di.iter().map(|&dd| (-dd * beta).exp()).collect();
    let sum_p: f64 = p.iter().sum::<f64>().max(1e-300);
    let sum_dp: f64 = di.iter().zip(&p).map(|(&dd, &pp)| dd * pp).sum();
    let h = sum_p.ln() + beta * sum_dp / sum_p;
    let p_norm: Vec<f64> = p.iter().map(|&pp| pp / sum_p).collect();
    (h, p_norm)
}

/// Pairwise squared Euclidean distances for every row of `x` against
/// every other row, via `||a-b||^2 = ||a||^2 + ||b||^2 - 2*a.b` — the
/// `a.b` cross term is exactly the matmul `X * X^T`, a deliberate
/// reformulation (not the obvious triple-nested loop) because `tsne_fit`
/// calls this twice: once for the high-dimensional input (a one-off), and
/// then again on the low-dimensional embedding on **every single
/// gradient-descent iteration** (`Y` changes every step) — a real,
/// repeated matmul-shaped hot loop, not a one-time bulk transform. Under
/// `--features gpu` this routes the cross term through the same
/// `qu_gpu::GpuContext` the `gpu_matmul` builtin uses (see its own doc
/// comment, and `gram_matrix` below); unlike that builtin, which is a
/// user-invoked call that surfaces a GPU failure as a script error, this
/// is an internal performance choice with no script-level call to fail
/// loudly to, so it silently falls back to `Matrix::matmul` (CPU, itself
/// rayon-parallel above `qu_core`'s own threshold) if no GPU is available
/// or dispatch fails — the numerical result is identical either way, just
/// f32-precision on the GPU path (matching `gpu_matmul`'s own documented
/// tradeoff) versus full f64 on the CPU path.
fn pairwise_sqdist_via_matmul(interp: &mut Interp, x: &Matrix) -> R<Matrix> {
    let (n, d) = x.shape();
    let norms: Vec<f64> = (0..n)
        .map(|i| (0..d).map(|c| { let v = x.get(i, c).unwrap_or(0.0); v * v }).sum())
        .collect();
    let cross = gram_matrix(interp, x)?;
    // Column-major flat buffer built directly (`Matrix`'s own storage
    // order — see `Matrix::from_col_major`) instead of through `Matrix::
    // set`'s per-call bounds-checked `Result` wrapper: this is an O(n^2)
    // fill, and from `tsne_fit` runs once per gradient-descent iteration
    // (up to 300x), so per-element call overhead is real. Parallelized by
    // column above a size threshold for the same reason/style as
    // `generate_random_fill`'s `PARALLEL_RNG_THRESHOLD` — each column j is
    // independent (only reads `norms`/`cross`, writes its own slice).
    const PARALLEL_SQDIST_THRESHOLD: usize = 64;
    let mut d2_data = vec![0.0; n * n];
    if n >= PARALLEL_SQDIST_THRESHOLD {
        use rayon::prelude::*;
        d2_data.par_chunks_mut(n).enumerate().for_each(|(j, col)| {
            for (i, slot) in col.iter_mut().enumerate() {
                *slot = (norms[i] + norms[j] - 2.0 * cross.get(i, j).unwrap_or(0.0)).max(0.0);
            }
        });
    } else {
        for j in 0..n {
            for i in 0..n {
                d2_data[j * n + i] = (norms[i] + norms[j] - 2.0 * cross.get(i, j).unwrap_or(0.0)).max(0.0);
            }
        }
    }
    Ok(Matrix::from_col_major(n, n, d2_data))
}

/// `X * X^T` — the Gram matrix `pairwise_sqdist_via_matmul`'s cross term
/// needs (also reused by `svm_cross_term`, an unrelated caller with the
/// same "small matmul, GPU dispatch is pure overhead" shape). Only worth
/// an actual GPU round trip above the `gpu_probe` module's measured
/// crossover; below it, without `--features gpu`, or if the GPU context
/// failed to initialize, this is plain `Matrix::matmul`. DBSCAN (neighbor
/// search/graph traversal) and GMM's covariance-heavy E/M-steps have no
/// comparable matmul-shaped bottleneck to route through here — not
/// attempted, matching how e.g. scikit-learn's own CPU-only DBSCAN has no
/// GPU path either.
///
/// Was a hardcoded `GPU_GRAM_THRESHOLD` constant (see git history) sized
/// from one session's one-off measurement on one machine; now uses
/// `gpu_probe::probe()`'s own REAL, per-process measurement instead — see
/// that module's doc comment for the benchmark and IMPL.md's dated entry
/// for the numbers measured on this repo's own dev machine.
#[cfg(feature = "gpu")]
fn gram_matrix(_interp: &mut Interp, x: &Matrix) -> R<Matrix> {
    let (n, d) = x.shape();
    let work = n.saturating_mul(n).saturating_mul(d);
    let probe = gpu_probe::probe();
    if probe.should_use_gpu(work) {
        if let Some(ctx) = probe.context.as_ref() {
            let to_row_major_f32 = |mat: &Matrix| -> Vec<f32> {
                let (r, c) = mat.shape();
                (0..r)
                    .flat_map(|row| (0..c).map(move |col| (row, col)))
                    .map(|(row, col)| mat.get(row, col).unwrap_or(0.0) as f32)
                    .collect()
            };
            let a_f32 = to_row_major_f32(x);
            let xt = x.transpose();
            let b_f32 = to_row_major_f32(&xt);
            if let Ok(raw) = ctx.matmul(&a_f32, n, d, &b_f32, n) {
                gpu_probe::record_dispatch();
                let out_rows: Vec<Vec<f64>> = (0..n)
                    .map(|r| raw[r * n..(r + 1) * n].iter().map(|&v| v as f64).collect())
                    .collect();
                if let Ok(m) = Matrix::from_rows(&out_rows) {
                    return Ok(m);
                }
            }
        }
    }
    x.matmul(&x.transpose()).map_err(|se| EvalError { msg: se.to_string() })
}

#[cfg(not(feature = "gpu"))]
fn gram_matrix(_interp: &mut Interp, x: &Matrix) -> R<Matrix> {
    x.matmul(&x.transpose()).map_err(|se| EvalError { msg: se.to_string() })
}

/// Barnes-Hut acceleration structure for `tsne_fit`'s `method="barnes_hut"`
/// path: a 2-D quadtree over the current embedding, used to approximate
/// the O(n^2) repulsive-force sum as O(n log n) per gradient-descent
/// iteration (van der Maaten, "Accelerating t-SNE using Tree-Based
/// Algorithms", JMLR 2014) — the same algorithm scikit-learn's own
/// `TSNE(method="barnes_hut")` (its default) uses. Arena-allocated
/// (`Vec<QuadNode>` + `usize` indices, not `Rc`/boxed pointers) for the
/// same reason `TreeArrays` is flat rather than a linked structure
/// elsewhere in this file: cheap to rebuild from scratch every iteration
/// (the embedding moves every step — this isn't updated incrementally)
/// and friendly to recursive traversal without borrow-checker fights.
/// Hardcodes 2 dimensions (a "quad" tree, not a general k-d tree) because
/// `tsne_fit` only offers this method for `n_components == 2` — see that
/// function's own doc comment for why.
struct QuadNode {
    cx: f64,
    cy: f64,
    half: f64,
    mass: f64,
    sum_x: f64,
    sum_y: f64,
    children: Option<[usize; 4]>,
    /// Only meaningful (as "the" point this leaf holds) while `mass ==
    /// 1.0` and `children` is `None`. Once more than one point lands in
    /// the same cell after hitting `QUADTREE_MAX_DEPTH` (near- or
    /// exactly-coincident embedded points — see `insert`'s own doc
    /// comment), this becomes a stale marker on a multi-point "bucket"
    /// leaf that callers must not trust as an exact single point.
    point: Option<usize>,
}

struct QuadTree<'a> {
    nodes: Vec<QuadNode>,
    y: &'a [f64],
}

/// Depth at which a leaf gives up trying to subdivide further and instead
/// becomes a multi-point "bucket", approximated as one aggregate even
/// during what would otherwise be an exact single-point leaf computation.
/// Only reachable by points whose coordinates agree to within
/// `bounding_box_size * 2^-50` — i.e. genuinely coincident (or
/// numerically indistinguishable) embedded points, not merely close ones;
/// halving a bounding box this many times exhausts `f64`'s usable
/// precision long before any real embedding would need it.
const QUADTREE_MAX_DEPTH: usize = 50;

impl<'a> QuadTree<'a> {
    fn pos(&self, i: usize) -> (f64, f64) {
        (self.y[i * 2], self.y[i * 2 + 1])
    }

    /// Builds a fresh tree over every row of `y` (`n` points, 2 components
    /// each) by inserting one point at a time into a root cell sized to
    /// the data's own bounding box (padded slightly so a point exactly on
    /// the boundary still lands strictly inside a child, not on a seam).
    fn build(y: &'a [f64], n: usize) -> Self {
        let (mut min_x, mut max_x, mut min_y, mut max_y) =
            (f64::INFINITY, f64::NEG_INFINITY, f64::INFINITY, f64::NEG_INFINITY);
        for i in 0..n {
            let (x, yv) = (y[i * 2], y[i * 2 + 1]);
            min_x = min_x.min(x);
            max_x = max_x.max(x);
            min_y = min_y.min(yv);
            max_y = max_y.max(yv);
        }
        let cx = (min_x + max_x) / 2.0;
        let cy = (min_y + max_y) / 2.0;
        let half = ((max_x - min_x).max(max_y - min_y) / 2.0).max(1e-10) * 1.001;
        let mut tree = QuadTree {
            nodes: vec![QuadNode { cx, cy, half, mass: 0.0, sum_x: 0.0, sum_y: 0.0, children: None, point: None }],
            y,
        };
        for i in 0..n {
            tree.insert(0, i, 0);
        }
        tree
    }

    fn quadrant(&self, node: usize, x: f64, y: f64) -> usize {
        let nd = &self.nodes[node];
        match (x >= nd.cx, y >= nd.cy) {
            (false, false) => 0,
            (true, false) => 1,
            (false, true) => 2,
            (true, true) => 3,
        }
    }

    fn child_box(&self, node: usize, quadrant: usize) -> (f64, f64, f64) {
        let nd = &self.nodes[node];
        let h = nd.half / 2.0;
        let (dx, dy) = match quadrant {
            0 => (-h, -h),
            1 => (h, -h),
            2 => (-h, h),
            _ => (h, h),
        };
        (nd.cx + dx, nd.cy + dy, h)
    }

    /// Inserts point `i` under `node`, updating every ancestor's running
    /// mass/center-of-mass on the way down. A leaf already holding one
    /// point subdivides into 4 children and re-homes both points — unless
    /// `QUADTREE_MAX_DEPTH` is hit first, in which case it becomes a
    /// multi-point bucket instead (see `QuadNode::point`'s own doc
    /// comment).
    fn insert(&mut self, node: usize, i: usize, depth: usize) {
        let (x, y) = self.pos(i);
        self.nodes[node].mass += 1.0;
        self.nodes[node].sum_x += x;
        self.nodes[node].sum_y += y;

        if let Some(children) = self.nodes[node].children {
            let q = self.quadrant(node, x, y);
            self.insert(children[q], i, depth + 1);
            return;
        }

        match self.nodes[node].point {
            None => {
                self.nodes[node].point = Some(i);
            }
            Some(existing) => {
                if depth >= QUADTREE_MAX_DEPTH {
                    return;
                }
                let mut new_children = [0usize; 4];
                for q in 0..4 {
                    let (ccx, ccy, chalf) = self.child_box(node, q);
                    self.nodes.push(QuadNode {
                        cx: ccx,
                        cy: ccy,
                        half: chalf,
                        mass: 0.0,
                        sum_x: 0.0,
                        sum_y: 0.0,
                        children: None,
                        point: None,
                    });
                    new_children[q] = self.nodes.len() - 1;
                }
                self.nodes[node].children = Some(new_children);
                self.nodes[node].point = None;
                let (ex, ey) = self.pos(existing);
                let eq = self.quadrant(node, ex, ey);
                self.insert(new_children[eq], existing, depth + 1);
                let q = self.quadrant(node, x, y);
                self.insert(new_children[q], i, depth + 1);
            }
        }
    }

    /// The Barnes-Hut approximation itself: walks the tree from `node`
    /// (call with `0`, the root) accumulating point `i`'s (at `(xi, yi)`)
    /// contribution to the global normalizer and its own unnormalized
    /// repulsive force. A cell is treated as one aggregate point at its
    /// center of mass — instead of recursing into its contents — once
    /// `cell_size / distance < theta`; a smaller `theta` means more exact
    /// (and slower), matching scikit-learn's own `angle` parameter.
    /// Returns `(z_i, rx, ry)`: `z_i = sum_{j!=i} num_ij` (this point's
    /// share of the shared normalizer `Z`, meaningful only once every
    /// point has been visited and summed) and `(rx, ry) = sum_{j!=i}
    /// num_ij^2 * (y_i - y_j)` (the repulsive force before dividing by
    /// that same `Z`).
    fn accumulate(&self, node: usize, i: usize, xi: f64, yi: f64, theta: f64) -> (f64, f64, f64) {
        let nd = &self.nodes[node];
        if nd.mass <= 0.0 {
            return (0.0, 0.0, 0.0);
        }
        if nd.mass == 1.0 && nd.point == Some(i) {
            return (0.0, 0.0, 0.0);
        }
        let com_x = nd.sum_x / nd.mass;
        let com_y = nd.sum_y / nd.mass;
        let dx = xi - com_x;
        let dy = yi - com_y;
        let dist2 = dx * dx + dy * dy;
        let size = nd.half * 2.0;
        // `dist2 > 0.0` forces recursion when `i` sits (at, or very near)
        // exactly on a cell's own center of mass — the only guard needed
        // against approximating a cell that contains `i` itself as a
        // distant aggregate: the ratio naturally blows up as `i`
        // approaches any point contributing to that center of mass,
        // including itself, which is why real Barnes-Hut t-SNE
        // implementations don't need an explicit "does this cell contain
        // `i`?" containment check on top of the ordinary theta test.
        let far_enough = nd.children.is_none() || (dist2 > 0.0 && size * size < theta * theta * dist2);
        if far_enough {
            let num = 1.0 / (1.0 + dist2);
            let z = nd.mass * num;
            let mult = nd.mass * num * num;
            return (z, mult * dx, mult * dy);
        }
        let children = nd.children.unwrap();
        let mut z = 0.0;
        let mut rx = 0.0;
        let mut ry = 0.0;
        for &c in &children {
            let (zc, rxc, ryc) = self.accumulate(c, i, xi, yi, theta);
            z += zc;
            rx += rxc;
            ry += ryc;
        }
        (z, rx, ry)
    }
}

/// Shared by both of `tsne_fit`'s methods: applies one step of the
/// paper's momentum + per-parameter adaptive-gain update rule to `y` from
/// an already-computed gradient `dy`, then re-centers `y` to zero mean
/// per component. Both methods need exactly this same update — only how
/// `dy` itself gets computed (dense O(n^2) sum vs. sparse-P +
/// Barnes-Hut-approximated) differs between them.
fn tsne_apply_gradient_step(
    y: &mut [f64],
    iy: &mut [f64],
    gains: &mut [f64],
    dy: &[f64],
    n: usize,
    n_components: usize,
    iter: usize,
) {
    const ETA: f64 = 200.0;
    const MIN_GAIN: f64 = 0.01;
    let momentum = if iter < 20 { 0.5 } else { 0.8 };
    for i in 0..n {
        for c in 0..n_components {
            let idx = i * n_components + c;
            let sign_changed = (dy[idx] > 0.0) != (iy[idx] > 0.0);
            gains[idx] = if sign_changed { gains[idx] + 0.2 } else { gains[idx] * 0.8 };
            if gains[idx] < MIN_GAIN {
                gains[idx] = MIN_GAIN;
            }
            iy[idx] = momentum * iy[idx] - ETA * gains[idx] * dy[idx];
            y[idx] += iy[idx];
        }
    }
    for c in 0..n_components {
        let mean: f64 = (0..n).map(|i| y[i * n_components + c]).sum::<f64>() / n as f64;
        for i in 0..n {
            y[i * n_components + c] -= mean;
        }
    }
}

/// t-SNE (van der Maaten & Hinton, "Visualizing Data using t-SNE", JMLR
/// 2008) — see the `"tsne"` builtin's own doc comment for the parameter
/// defaults and the scoped-down `max_iter` tradeoff. Follows the paper's
/// reference implementation's own constants (early exaggeration `4x` for
/// the first 100 iterations, momentum `0.5` for the first 20 iterations
/// then `0.8`, per-parameter adaptive gains with `min_gain=0.01`,
/// learning rate `200`) rather than inventing new ones, since a wrong
/// gradient or mistuned schedule produces a plausible-looking-but-
/// meaningless embedding with no obvious symptom.
///
/// `method` selects between two ways of computing the *same* gradient:
/// `"exact"` is the paper's own O(n^2)-per-iteration dense computation
/// (unchanged from before this parameter existed — every candidate
/// point-pair really is considered, every iteration); `"barnes_hut"`
/// (van der Maaten 2014, and what scikit-learn's own `TSNE` defaults to)
/// approximates it in O(n log n): the attractive term only sums each
/// point's ~3*`perplexity` nearest neighbors by affinity (see the
/// `neighbors` sparsification below) instead of all `n`, and the
/// repulsive term is approximated via `QuadTree::accumulate` instead of
/// summed exactly. Only supports `n_components == 2` — a "quad" tree is
/// inherently 2-D; scikit-learn's own Barnes-Hut mode has the identical
/// restriction (extending to 3 components would need an octree, and
/// beyond that the tree approach stops paying for itself at all, which
/// is why scikit-learn itself falls back to exact above 3 components).
/// `angle` is `QuadTree::accumulate`'s `theta` — smaller is more exact
/// and slower; named to match scikit-learn's own parameter.
fn tsne_fit(
    interp: &mut Interp,
    x: &Matrix,
    n_components: usize,
    perplexity: f64,
    seed: u64,
    max_iter: usize,
    method: &str,
    angle: f64,
) -> R<Matrix> {
    let n = x.rows();
    if n_components == 0 {
        return e("tsne: n_components must be at least 1");
    }
    if perplexity <= 0.0 {
        return e("tsne: perplexity must be positive");
    }
    if perplexity >= n as f64 {
        return e(format!(
            "tsne: perplexity={perplexity} must be smaller than the number of rows ({n})"
        ));
    }
    if method != "exact" && method != "barnes_hut" {
        return e(format!("tsne: unknown method \"{method}\" — expected \"exact\" or \"barnes_hut\""));
    }
    if method == "barnes_hut" && n_components != 2 {
        return e(format!(
            "tsne: method=\"barnes_hut\" only supports n_components=2 (got {n_components}) — \
             use method=\"exact\" for other dimensionalities"
        ));
    }

    // --- high-dimensional affinities: per-point binary search on beta so
    // each row's conditional distribution matches the target perplexity.
    let d2 = pairwise_sqdist_via_matmul(interp, x)?;
    let log_perp = perplexity.ln();
    // Row-major flat n*n buffers (not `Vec<Vec<f64>>`) for `p_cond`/`p`
    // below: both are read O(n^2) times on *every* gradient-descent
    // iteration (up to `max_iter=300` of them), and a nested `Vec<Vec<f64>>`
    // pays an extra heap-allocated-row indirection on every one of those
    // reads that a flat buffer doesn't.
    let mut p_cond = vec![0.0; n * n];
    for i in 0..n {
        let di: Vec<f64> = (0..n).filter(|&j| j != i).map(|j| d2.get(i, j).unwrap_or(0.0)).collect();
        let mut beta = 1.0;
        let mut beta_min = f64::NEG_INFINITY;
        let mut beta_max = f64::INFINITY;
        let (mut h, mut p_row) = tsne_hbeta(&di, beta);
        let mut h_diff = h - log_perp;
        let mut tries = 0;
        while h_diff.abs() > 1e-5 && tries < 50 {
            if h_diff > 0.0 {
                beta_min = beta;
                beta = if beta_max.is_infinite() { beta * 2.0 } else { (beta + beta_max) / 2.0 };
            } else {
                beta_max = beta;
                beta = if beta_min.is_infinite() { beta / 2.0 } else { (beta + beta_min) / 2.0 };
            }
            let (h2, p2) = tsne_hbeta(&di, beta);
            h = h2;
            p_row = p2;
            h_diff = h - log_perp;
            tries += 1;
        }
        let mut idx = 0;
        for j in 0..n {
            if j == i {
                continue;
            }
            p_cond[i * n + j] = p_row[idx];
            idx += 1;
        }
    }

    const EXAGGERATION: f64 = 4.0;

    // --- gradient descent on the low-dimensional embedding.
    //
    // Below this many points, rayon dispatch overhead isn't worth it —
    // same threshold-style guard `generate_random_fill`'s own
    // `PARALLEL_RNG_THRESHOLD` uses.
    const PARALLEL_TSNE_THRESHOLD: usize = 64;
    let parallel = n >= PARALLEL_TSNE_THRESHOLD;

    let mut rng = Rng::new(seed);
    // Flat row-major buffers (`y[i*n_components+c]`), for the same
    // cache-locality/allocation-churn reasons as `p_cond` above — read or
    // written up to O(n^2) times per iteration, for up to `max_iter`
    // iterations.
    let mut y: Vec<f64> = (0..n * n_components).map(|_| rng.normal() * 1e-4).collect();
    let mut iy = vec![0.0; n * n_components];
    let mut gains = vec![1.0; n * n_components];

    if method == "barnes_hut" {
        // Sparsify to each point's ~3*`perplexity` nearest neighbors by
        // conditional probability (symmetrized: `j` counts as `i`'s
        // neighbor if *either* direction's raw `p_cond` survives the
        // top-k cut, the standard construction) instead of keeping the
        // full dense affinity matrix — this is what actually lets the
        // attractive term below run in O(n*k) instead of O(n^2) per
        // iteration; `QuadTree` separately handles the O(n log n)
        // repulsive term. `total` is `2n` analytically — every `p_cond`
        // row already sums to exactly 1.0 from `tsne_hbeta`'s own
        // normalization, and symmetrizing sums two such rows per point —
        // rather than accumulated from the (now sparse) kept entries,
        // which would otherwise under-count and skew the normalization.
        let k_neighbors = ((3.0 * perplexity).ceil() as usize).clamp(1, n - 1);
        let mut neighbor_sets: Vec<std::collections::BTreeSet<usize>> = vec![std::collections::BTreeSet::new(); n];
        for i in 0..n {
            let mut ranked: Vec<(f64, usize)> = (0..n).filter(|&j| j != i).map(|j| (p_cond[i * n + j], j)).collect();
            ranked.sort_by(|a, b| b.0.partial_cmp(&a.0).unwrap_or(std::cmp::Ordering::Equal));
            for &(_, j) in ranked.iter().take(k_neighbors) {
                neighbor_sets[i].insert(j);
                neighbor_sets[j].insert(i);
            }
        }
        let total = 2.0 * n as f64;
        let mut neighbors: Vec<Vec<(usize, f64)>> = Vec::with_capacity(n);
        for i in 0..n {
            let row: Vec<(usize, f64)> = neighbor_sets[i]
                .iter()
                .map(|&j| {
                    let v = ((p_cond[i * n + j] + p_cond[j * n + i]) / total).max(1e-12) * EXAGGERATION;
                    (j, v)
                })
                .collect();
            neighbors.push(row);
        }
        drop(p_cond);
        drop(neighbor_sets);

        let mut dy = vec![0.0; n * n_components];
        for iter in 0..max_iter {
            // Rebuilt from scratch every iteration (the embedding moves
            // every step — see `QuadTree`'s own doc comment).
            let tree = QuadTree::build(&y, n);
            // One traversal per point gives both this point's share of
            // the shared normalizer `Z` and its own unnormalized
            // repulsive force; `Z` itself isn't known until every point
            // has been visited, so the division happens in the second
            // pass below (`compute_row`), not here.
            let per_point: Vec<(f64, f64, f64)> = if parallel {
                use rayon::prelude::*;
                (0..n)
                    .into_par_iter()
                    .map(|i| tree.accumulate(0, i, y[i * 2], y[i * 2 + 1], angle))
                    .collect()
            } else {
                (0..n).map(|i| tree.accumulate(0, i, y[i * 2], y[i * 2 + 1], angle)).collect()
            };
            let z: f64 = per_point.iter().map(|&(zi, _, _)| zi).sum::<f64>().max(1e-300);
            let inv_z4 = 4.0 / z;

            let compute_row = |i: usize, out: &mut [f64]| {
                let (mut ax, mut ay) = (0.0, 0.0);
                for &(j, pv) in &neighbors[i] {
                    let dx = y[i * 2] - y[j * 2];
                    let dyv = y[i * 2 + 1] - y[j * 2 + 1];
                    let numij = 1.0 / (1.0 + dx * dx + dyv * dyv);
                    let mult = pv * numij * 4.0;
                    ax += mult * dx;
                    ay += mult * dyv;
                }
                let (_, rx, ry) = per_point[i];
                out[0] = ax - inv_z4 * rx;
                out[1] = ay - inv_z4 * ry;
            };
            if parallel {
                use rayon::prelude::*;
                dy.par_chunks_mut(n_components).enumerate().for_each(|(i, out)| compute_row(i, out));
            } else {
                for i in 0..n {
                    let start = i * n_components;
                    compute_row(i, &mut dy[start..start + n_components]);
                }
            }

            tsne_apply_gradient_step(&mut y, &mut iy, &mut gains, &dy, n, n_components, iter);

            if iter == 100 {
                for row in neighbors.iter_mut() {
                    for (_, v) in row.iter_mut() {
                        *v /= EXAGGERATION;
                    }
                }
            }
        }
    } else {
        // symmetrize, normalize to sum 1, floor to avoid an exact-zero affinity.
        let mut p = vec![0.0; n * n];
        let mut total = 0.0;
        for i in 0..n {
            for j in 0..n {
                let v = p_cond[i * n + j] + p_cond[j * n + i];
                p[i * n + j] = v;
                total += v;
            }
        }
        let total = total.max(1e-300);
        for v in p.iter_mut() {
            *v = (*v / total).max(1e-12);
        }
        for v in p.iter_mut() {
            *v *= EXAGGERATION;
        }

        // Flat row-major `num`/`dy` buffers, allocated once and reused
        // every iteration rather than rebuilt as a fresh `Vec<Vec<f64>>`
        // each time — `num` is read/written up to O(n^2) times per
        // iteration.
        let mut num = vec![0.0; n * n];
        let mut dy = vec![0.0; n * n_components];

        for iter in 0..max_iter {
            // Column-major buffer `pairwise_sqdist_via_matmul`'s `Matrix`
            // needs, built from the row-major `y` this loop otherwise
            // works in — O(n * n_components), negligible next to the
            // O(n^2) work below.
            let mut y_col_major = vec![0.0; n * n_components];
            for c in 0..n_components {
                for i in 0..n {
                    y_col_major[c * n + i] = y[i * n_components + c];
                }
            }
            let y_mat = Matrix::from_col_major(n, n_components, y_col_major);
            let y_d2 = pairwise_sqdist_via_matmul(interp, &y_mat)?;

            // Every off-diagonal `num` entry is unconditionally overwritten
            // (never accumulated) each pass, so the buffer needs no reset
            // between iterations — only its one-time allocation is reused.
            if parallel {
                use rayon::prelude::*;
                num.par_chunks_mut(n).enumerate().for_each(|(i, row)| {
                    for (j, slot) in row.iter_mut().enumerate() {
                        *slot = if i == j { 0.0 } else { 1.0 / (1.0 + y_d2.get(i, j).unwrap_or(0.0)) };
                    }
                });
            } else {
                for i in 0..n {
                    for j in 0..n {
                        num[i * n + j] = if i == j { 0.0 } else { 1.0 / (1.0 + y_d2.get(i, j).unwrap_or(0.0)) };
                    }
                }
            }
            let sum_num = if parallel {
                use rayon::prelude::*;
                num.par_iter().sum::<f64>().max(1e-300)
            } else {
                num.iter().sum::<f64>().max(1e-300)
            };

            // Row `i`'s gradient only ever *writes* `dy[i]`; it *reads*
            // every row of `y`/`p`/`num` (not just its own), so rows are
            // independent and safe to fan out across threads — each
            // closure invocation below only ever touches its own disjoint
            // slice of `dy`. The trailing `* 4.0` from the original
            // two-pass version (accumulate, then scale the finished sum)
            // is folded into `mult` here instead; scaling by a power of
            // two is exact in IEEE 754, so `4*sum(term)` and
            // `sum(4*term)` are the same bits, not just approximately
            // equal — this is a layout change, not a numeric one.
            let compute_dy_row = |i: usize, out: &mut [f64]| {
                for j in 0..n {
                    if i == j {
                        continue;
                    }
                    let q = (num[i * n + j] / sum_num).max(1e-12);
                    let mult = (p[i * n + j] - q) * num[i * n + j] * 4.0;
                    for c in 0..n_components {
                        out[c] += mult * (y[i * n_components + c] - y[j * n_components + c]);
                    }
                }
            };
            if parallel {
                use rayon::prelude::*;
                dy.par_chunks_mut(n_components).enumerate().for_each(|(i, out)| {
                    out.iter_mut().for_each(|v| *v = 0.0);
                    compute_dy_row(i, out);
                });
            } else {
                for i in 0..n {
                    let start = i * n_components;
                    for c in 0..n_components {
                        dy[start + c] = 0.0;
                    }
                    compute_dy_row(i, &mut dy[start..start + n_components]);
                }
            }

            tsne_apply_gradient_step(&mut y, &mut iy, &mut gains, &dy, n, n_components, iter);

            if iter == 100 {
                for v in p.iter_mut() {
                    *v /= EXAGGERATION;
                }
            }
        }
    }

    let y_rows: Vec<Vec<f64>> = (0..n).map(|i| y[i * n_components..(i + 1) * n_components].to_vec()).collect();
    Matrix::from_rows(&y_rows).map_err(|se| EvalError { msg: se.to_string() })
}

// ---- decision trees / random forest / gradient boosting ----
//
// Shared by `tree_model`, `random_forest_model`, and
// `gradient_boosting_model` (see each builtin's own call-site doc comment
// for its exact contract). One greedy CART-style builder (`TreeBuilder`)
// backs all three — a random forest is `TreeBuilder` run `n_trees` times
// on bootstrap-resampled rows and a random per-split feature subset;
// gradient boosting is `TreeBuilder` run `n_trees` times on the *same*
// full data, each round fit to the previous round's residual.

/// Default depth cap for `tree_model`/`random_forest_model` when no
/// `max_depth=` is given — deep enough that a tree still reaches a pure
/// leaf on any dataset small enough to hand-verify (recursion is bounded
/// by row count anyway: a node under `min_samples_split` rows always
/// stops), without an `Option<usize>` "unbounded" case that never actually
/// matters at this scale. `gradient_boosting_model` uses its own shallower
/// default (3) — see that builtin's doc comment for why.
const DEFAULT_MAX_DEPTH: usize = 20;

/// A single flattened decision tree — sklearn's own `tree_.feature`/
/// `threshold`/`children_left`/`children_right`/`value` array
/// representation, deliberately reused here: it maps directly onto plain
/// `Value::Vec` model fields (`m.feature`, `m.threshold`, ...) with no new
/// `Value` variant needed, and stacks cleanly into padded `Value::Mat`
/// fields for a forest (`pack_forest_arrays`) without inventing a "list of
/// models" value kind Qu doesn't have. Node `i`'s children are
/// `children_left[i]`/`children_right[i]`; a leaf has
/// `children_left[i] == -1.0` (`children_right[i]` is then also `-1.0`),
/// and its prediction is `value[i]`. An internal node's `feature[i]` is
/// the split column (a leaf's is the unused sentinel `-2.0`, sklearn's own
/// convention) and `threshold[i]` the split point: `row[feature] <=
/// threshold` goes left, `>` goes right (CART's own convention).
#[derive(Clone)]
struct TreeArrays {
    feature: Vec<f64>,
    threshold: Vec<f64>,
    children_left: Vec<f64>,
    children_right: Vec<f64>,
    value: Vec<f64>,
}

/// Greedy recursive CART-style builder. Builds nodes in pre-order (root
/// first) directly into a `TreeArrays`, exactly like sklearn's own `Tree`
/// builder, so a child's array index is already known by the time its
/// parent's `children_left`/`children_right` needs to record it.
struct TreeBuilder<'a> {
    x: &'a Matrix,
    y: &'a [f64],
    classification: bool,
    max_depth: usize,
    min_samples_split: usize,
    /// `Some(m)` — Random Forest's per-split feature subsampling: only `m`
    /// randomly chosen candidate features are tried at each node (the
    /// standard decorrelation trick — without it every tree in the forest
    /// tends to split on the same dominant feature first, and the trees
    /// end up highly correlated, defeating the point of bagging). `None`
    /// — `tree_model`/`gradient_boosting_model`: every feature is tried.
    max_features: Option<usize>,
    rng: &'a mut Rng,
    out: TreeArrays,
    /// Classification only: `y[i].round()` remapped to a dense `0..n_classes`
    /// index, precomputed once so `best_split`'s per-split-point class-count
    /// bookkeeping is plain array indexing instead of a `HashMap` lookup (and
    /// building a fresh `HashMap` from scratch, as the old impurity-from-
    /// scratch scan did, at every one of the O(n) candidate thresholds).
    class_of: Vec<usize>,
    n_classes: usize,
}

impl<'a> TreeBuilder<'a> {
    fn new(
        x: &'a Matrix,
        y: &'a [f64],
        classification: bool,
        max_depth: usize,
        min_samples_split: usize,
        max_features: Option<usize>,
        rng: &'a mut Rng,
    ) -> Self {
        let (class_of, n_classes) = if classification {
            let mut classes: Vec<i64> = y.iter().map(|&v| v.round() as i64).collect();
            classes.sort_unstable();
            classes.dedup();
            let class_of = y
                .iter()
                .map(|&v| classes.binary_search(&(v.round() as i64)).unwrap())
                .collect();
            (class_of, classes.len())
        } else {
            (Vec::new(), 0)
        };
        TreeBuilder {
            x,
            y,
            classification,
            max_depth,
            min_samples_split,
            max_features,
            rng,
            out: TreeArrays {
                feature: Vec::new(),
                threshold: Vec::new(),
                children_left: Vec::new(),
                children_right: Vec::new(),
                value: Vec::new(),
            },
            class_of,
            n_classes,
        }
    }

    fn finish(self) -> TreeArrays {
        self.out
    }

    /// Builds the subtree over `indices` (row indices into `self.x`/
    /// `self.y`, possibly with repeats — a bootstrap resample), returns
    /// its node id. Always allocates a leaf-shaped slot first (so the
    /// node's own id is known before recursing into children), and only
    /// overwrites it into a split if `best_split` finds one that actually
    /// improves impurity; a node that can't be usefully split (too few
    /// rows, already pure, or at `max_depth`) simply stays the leaf it
    /// started as.
    fn build_node(&mut self, indices: &[usize], depth: usize) -> usize {
        let node_id = self.out.feature.len();
        self.out.feature.push(-2.0);
        self.out.threshold.push(0.0);
        self.out.children_left.push(-1.0);
        self.out.children_right.push(-1.0);
        self.out.value.push(self.leaf_value(indices));

        if depth >= self.max_depth || indices.len() < self.min_samples_split || self.is_pure(indices) {
            return node_id;
        }
        if let Some((feat, threshold, left, right)) = self.best_split(indices) {
            self.out.feature[node_id] = feat as f64;
            self.out.threshold[node_id] = threshold;
            let left_id = self.build_node(&left, depth + 1);
            let right_id = self.build_node(&right, depth + 1);
            self.out.children_left[node_id] = left_id as f64;
            self.out.children_right[node_id] = right_id as f64;
        }
        node_id
    }

    fn leaf_value(&self, indices: &[usize]) -> f64 {
        if self.classification {
            majority_class(indices.iter().map(|&i| self.y[i]))
        } else {
            indices.iter().map(|&i| self.y[i]).sum::<f64>() / indices.len() as f64
        }
    }

    fn is_pure(&self, indices: &[usize]) -> bool {
        let first = self.y[indices[0]];
        indices.iter().all(|&i| (self.y[i] - first).abs() < 1e-12)
    }

    /// The candidate feature columns to try at this node: every column
    /// (`max_features: None`), or a random subset of size `max_features`
    /// drawn fresh at every node (`Some(m)`, Random Forest).
    fn candidate_features(&mut self) -> Vec<usize> {
        let d = self.x.cols();
        match self.max_features {
            None => (0..d).collect(),
            Some(m) if m >= d => (0..d).collect(),
            Some(m) => {
                let mut order: Vec<usize> = (0..d).collect();
                for i in 0..m {
                    let j = i + (self.rng.next_u64() as usize) % (d - i);
                    order.swap(i, j);
                }
                order.truncate(m);
                order
            }
        }
    }

    /// Scans every candidate feature's sorted values for the split that
    /// minimizes weighted child impurity (equivalently, maximizes
    /// impurity decrease from the parent, since the parent's impurity is
    /// fixed for a given node) — plain greedy CART, O(features x n log n)
    /// per node.
    ///
    /// For each feature this sorts `indices` once, then sweeps the boundary
    /// left-to-right maintaining the two children's impurity *incrementally*
    /// (running sum/sum-of-squares for regression's variance, running
    /// sum-of-squared-class-counts for classification's Gini) instead of
    /// recomputing each child's impurity from scratch — from every point in
    /// `indices` — at every one of the O(n) candidate thresholds. The
    /// from-scratch version was O(n) per threshold (O(n^2) per feature); the
    /// incremental update below is O(1) per threshold (O(n) per feature, so
    /// O(n log n) total once the sort is included). Classification's
    /// from-scratch impurity also built a fresh `HashMap` per threshold,
    /// which on top of the extra O(n) factor made it far more expensive
    /// per-operation than regression's plain float accumulation — that
    /// asymmetry (not just the shared O(n^2) scaling) is why classification
    /// forests were disproportionately slower than regression ones before
    /// this rewrite.
    ///
    /// Returns `None` if no split actually improves on the parent's own
    /// impurity (e.g. every candidate feature is constant on `indices`, or
    /// the best split would leave one side empty).
    fn best_split(&mut self, indices: &[usize]) -> Option<(usize, f64, Vec<usize>, Vec<usize>)> {
        let n = indices.len();
        let parent_impurity = self.impurity(indices);
        let mut best: Option<(usize, f64, f64)> = None; // (feature, threshold, weighted_impurity)

        // Totals over the full `indices` set — the same regardless of which
        // feature we're scanning (only the visiting order changes), so
        // computed once and reused as the sweep's starting point for every
        // feature below.
        let (total_sum, total_sq) = if !self.classification {
            let sum: f64 = indices.iter().map(|&i| self.y[i]).sum();
            let sq: f64 = indices.iter().map(|&i| self.y[i] * self.y[i]).sum();
            (sum, sq)
        } else {
            (0.0, 0.0)
        };
        let total_counts: Vec<usize> = if self.classification {
            let mut counts = vec![0usize; self.n_classes];
            for &i in indices {
                counts[self.class_of[i]] += 1;
            }
            counts
        } else {
            Vec::new()
        };

        for feat in self.candidate_features() {
            let mut sorted = indices.to_vec();
            sorted.sort_by(|&a, &b| {
                self.x
                    .get(a, feat)
                    .unwrap_or(0.0)
                    .partial_cmp(&self.x.get(b, feat).unwrap_or(0.0))
                    .unwrap_or(std::cmp::Ordering::Equal)
            });

            if self.classification {
                // Gini(S) = 1 - sum_c (count_c/|S|)^2, so
                // |left|*Gini(left) + |right|*Gini(right)
                //   = n - sum_c(left_count_c^2)/|left| - sum_c(right_count_c^2)/|right|
                // Track the two sum-of-squared-counts terms incrementally as
                // points move from right to left one at a time.
                let mut left_counts = vec![0usize; self.n_classes];
                let mut right_counts = total_counts.clone();
                let mut left_sq_sum = 0.0f64;
                let mut right_sq_sum: f64 = total_counts.iter().map(|&c| (c * c) as f64).sum();
                for i in 1..n {
                    let moved = self.class_of[sorted[i - 1]];
                    left_sq_sum += (2 * left_counts[moved] + 1) as f64;
                    left_counts[moved] += 1;
                    right_sq_sum -= (2 * right_counts[moved] - 1) as f64;
                    right_counts[moved] -= 1;

                    let v_prev = self.x.get(sorted[i - 1], feat).unwrap_or(0.0);
                    let v_cur = self.x.get(sorted[i], feat).unwrap_or(0.0);
                    if v_cur <= v_prev {
                        continue; // no real split point between equal values
                    }
                    let left_n = i as f64;
                    let right_n = (n - i) as f64;
                    let weighted = (n as f64 - left_sq_sum / left_n - right_sq_sum / right_n) / n as f64;
                    if best.as_ref().map(|(_, _, w)| weighted < *w).unwrap_or(true) {
                        best = Some((feat, (v_prev + v_cur) / 2.0, weighted));
                    }
                }
            } else {
                // n*Var(S) = sum_sq(S) - sum(S)^2/|S|, so
                // |left|*Var(left) + |right|*Var(right)
                //   = (left_sq - left_sum^2/|left|) + (right_sq - right_sum^2/|right|)
                let mut left_sum = 0.0f64;
                let mut left_sq = 0.0f64;
                for i in 1..n {
                    let yv = self.y[sorted[i - 1]];
                    left_sum += yv;
                    left_sq += yv * yv;

                    let v_prev = self.x.get(sorted[i - 1], feat).unwrap_or(0.0);
                    let v_cur = self.x.get(sorted[i], feat).unwrap_or(0.0);
                    if v_cur <= v_prev {
                        continue; // no real split point between equal values
                    }
                    let left_n = i as f64;
                    let right_n = (n - i) as f64;
                    let right_sum = total_sum - left_sum;
                    let right_sq = total_sq - left_sq;
                    let weighted = ((left_sq - left_sum * left_sum / left_n) + (right_sq - right_sum * right_sum / right_n))
                        / n as f64;
                    if best.as_ref().map(|(_, _, w)| weighted < *w).unwrap_or(true) {
                        best = Some((feat, (v_prev + v_cur) / 2.0, weighted));
                    }
                }
            }
        }
        let (feat, threshold, weighted) = best?;
        if weighted >= parent_impurity - 1e-12 {
            return None; // no candidate split actually helps
        }
        let left: Vec<usize> = indices.iter().copied().filter(|&i| self.x.get(i, feat).unwrap_or(0.0) <= threshold).collect();
        let right: Vec<usize> = indices.iter().copied().filter(|&i| self.x.get(i, feat).unwrap_or(0.0) > threshold).collect();
        if left.is_empty() || right.is_empty() {
            return None;
        }
        Some((feat, threshold, left, right))
    }

    /// Regression: variance (mean squared deviation from the node's own
    /// mean) — minimizing the weighted sum of this over the two children
    /// is exactly "variance reduction" splitting. Classification: Gini
    /// impurity `1 - sum(p_c^2)` — CART's own default (the alternative,
    /// entropy/information-gain, is a deliberate non-choice, not an
    /// oversight — both are standard, Gini is cheaper to compute and is
    /// what scikit-learn's `DecisionTreeClassifier` itself defaults to).
    /// Only called once per node (for the parent's own impurity) — the
    /// per-candidate-split scan in `best_split` tracks child impurity
    /// incrementally instead of calling this in a loop.
    fn impurity(&self, indices: &[usize]) -> f64 {
        let n = indices.len() as f64;
        if self.classification {
            let mut counts = vec![0usize; self.n_classes];
            for &i in indices {
                counts[self.class_of[i]] += 1;
            }
            1.0 - counts.iter().map(|&c| (c as f64 / n).powi(2)).sum::<f64>()
        } else {
            let mean = indices.iter().map(|&i| self.y[i]).sum::<f64>() / n;
            indices.iter().map(|&i| (self.y[i] - mean).powi(2)).sum::<f64>() / n
        }
    }
}

/// The most frequent value in `labels` (a classification leaf's
/// prediction, or a forest's majority vote across trees); ties broken by
/// the smallest label, for determinism. Labels are rounded to the nearest
/// integer first — classification targets are class ids, not continuous
/// values, matching this whole family's `kind="classification"` contract.
fn majority_class(labels: impl Iterator<Item = f64>) -> f64 {
    let mut counts: HashMap<i64, usize> = HashMap::new();
    for l in labels {
        *counts.entry(l.round() as i64).or_insert(0) += 1;
    }
    counts
        .into_iter()
        .max_by(|a, b| a.1.cmp(&b.1).then(b.0.cmp(&a.0)))
        .map(|(label, _)| label as f64)
        .unwrap_or(0.0)
}

/// Walks `tree` from the root (node 0) for one input row, following
/// `row[feature] <= threshold` left / `> threshold` right until a leaf
/// (`children_left == -1`), and returns that leaf's `value`.
fn tree_predict_row(tree: &TreeArrays, row: &[f64]) -> f64 {
    let mut node = 0usize;
    loop {
        if tree.children_left[node] < 0.0 {
            return tree.value[node];
        }
        let feat = tree.feature[node] as usize;
        if row[feat] <= tree.threshold[node] {
            node = tree.children_left[node] as usize;
        } else {
            node = tree.children_right[node] as usize;
        }
    }
}

/// The actual depth reached under `node` (0 at a leaf) — walked from the
/// finished arrays rather than tracked during `build_node`, so it works
/// identically for a forest's individual trees.
fn tree_depth(tree: &TreeArrays, node: usize) -> usize {
    if tree.children_left[node] < 0.0 {
        0
    } else {
        1 + tree_depth(tree, tree.children_left[node] as usize).max(tree_depth(tree, tree.children_right[node] as usize))
    }
}

/// Macro-averaged precision/recall/F1 (`precision`/`recall`/`f1`
/// builtins): tallies each class's true/false positives and false
/// negatives in one pass, computes precision/recall/F1 *per class*
/// (0.0 for a class with no predicted or no actual members, rather than a
/// division-by-zero panic), then returns the plain mean of each across
/// classes — sklearn's `average="macro"`, chosen over a binary-only
/// `pos_label=` convention so the same three builtins work unchanged on
/// `tree_model`/`random_forest_model`/`knn_model`'s multi-class output,
/// not just 0/1 labels. F1 is the mean of each class's *own* F1 (`2pr/
/// (p+r)`), not the harmonic mean of the macro-averaged P and R — those
/// are mathematically different quantities, and sklearn's `f1_score(
/// average="macro")` is the former.
fn classification_prf_macro(actual: &[f64], predicted: &[f64]) -> (f64, f64, f64) {
    let mut counts: HashMap<i64, (usize, usize, usize)> = HashMap::new(); // class -> (tp, fp, fn)
    for (&a, &p) in actual.iter().zip(predicted) {
        let ai = a.round() as i64;
        let pi = p.round() as i64;
        counts.entry(ai).or_insert((0, 0, 0));
        counts.entry(pi).or_insert((0, 0, 0));
        if ai == pi {
            counts.get_mut(&ai).unwrap().0 += 1;
        } else {
            counts.get_mut(&pi).unwrap().1 += 1;
            counts.get_mut(&ai).unwrap().2 += 1;
        }
    }
    let n_classes = counts.len().max(1) as f64;
    let (mut sum_p, mut sum_r, mut sum_f1) = (0.0, 0.0, 0.0);
    for &(tp, fp, fnc) in counts.values() {
        let p = if tp + fp == 0 { 0.0 } else { tp as f64 / (tp + fp) as f64 };
        let r = if tp + fnc == 0 { 0.0 } else { tp as f64 / (tp + fnc) as f64 };
        let f1 = if p + r == 0.0 { 0.0 } else { 2.0 * p * r / (p + r) };
        sum_p += p;
        sum_r += r;
        sum_f1 += f1;
    }
    (sum_p / n_classes, sum_r / n_classes, sum_f1 / n_classes)
}

/// R^2 for regression, plain accuracy for classification — shared by every
/// `tree_model`/`random_forest_model`/`gradient_boosting_model` training
/// diagnostic field and their common `.score(X, [y])` dispatch.
fn training_diagnostic(y: &[f64], predictions: &[f64], classification: bool) -> f64 {
    if classification {
        let correct = y.iter().zip(predictions).filter(|(a, b)| (**a - **b).abs() < 1e-9).count();
        correct as f64 / y.len() as f64
    } else {
        let y_mean = y.iter().sum::<f64>() / y.len() as f64;
        let ss_res: f64 = y.iter().zip(predictions).map(|(a, b)| (a - b).powi(2)).sum();
        let ss_tot: f64 = y.iter().map(|v| (v - y_mean).powi(2)).sum();
        if ss_tot > 0.0 {
            1.0 - ss_res / ss_tot
        } else if ss_res == 0.0 {
            1.0
        } else {
            0.0
        }
    }
}

// ---- §45 feature selection: mutual info, A*-mRMR, RFE (2026-08-25) ----
//
// Ported from Ahmed's own research tooling (novel_methods.py's
// `AStarMRMRHybrid` — the LITERAL A* variant, priority queue + real
// cross-validated g-score, not the faster-but-approximate beam-search
// "FastA*-mRMR" in gpu_accelerated_astar.py, which is a different,
// related-but-distinct algorithm). Every g-score evaluation here calls
// `TreeBuilder` *directly* in Rust rather than through `self.apply`/
// `call_builtin` — deliberately, so the expensive part (a real k-fold
// cross-validated fit per candidate, per beam slot) can run on rayon
// across cores instead of one at a time; the Python reference's own GPU/
// Numba variant exists specifically because this step dominates runtime.

/// Ross (2014) k-nearest-neighbor mutual information estimator between one
/// continuous feature column and discrete class labels — the algorithm
/// scikit-learn's `mutual_info_classif` implements
/// (`sklearn/feature_selection/_mutual_info.py::_compute_mi_cd`, verified
/// against its published source rather than approximated), A*-mRMR's own
/// relevance criterion in the reference implementation this was ported
/// from. Per feature column, not per dataset — `mutual_info_classif`
/// (the builtin) calls this once per column of `X`.
///
/// For each class, finds the distance to the `k`-th nearest same-class
/// neighbor (`k` shrinks to `class_count - 1` for a small class; a class
/// with only one member can't have a k-th neighbor at all and is excluded
/// from the whole estimate, matching sklearn's own masking), then counts
/// how many points *of any class* fall strictly within that radius. The
/// final estimate combines four digamma terms — `digamma(n) +
/// mean(digamma(k)) - mean(digamma(class_count)) - mean(digamma(m+1))` —
/// and is clamped to `>= 0` (a valid finite-sample estimator can dip
/// slightly negative; true mutual information never is).
fn mutual_info_classif_column(x: &[f64], y: &[f64], k_neighbors: usize) -> f64 {
    let n = x.len();
    let mut by_class: HashMap<i64, Vec<usize>> = HashMap::new();
    for (i, &yi) in y.iter().enumerate() {
        by_class.entry(yi.round() as i64).or_default().push(i);
    }
    let mut radius = vec![0.0f64; n];
    let mut k_all = vec![0.0f64; n];
    let mut label_counts = vec![0.0f64; n];
    let mut keep = vec![false; n];
    for idxs in by_class.values() {
        let count = idxs.len();
        for &i in idxs {
            label_counts[i] = count as f64;
        }
        if count > 1 {
            let k = k_neighbors.min(count - 1);
            for &i in idxs {
                let mut dists: Vec<f64> = idxs.iter().filter(|&&j| j != i).map(|&j| (x[j] - x[i]).abs()).collect();
                dists.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
                radius[i] = dists[k - 1];
                k_all[i] = k as f64;
                keep[i] = true;
            }
        }
    }
    let kept: Vec<usize> = (0..n).filter(|&i| keep[i]).collect();
    let n_kept = kept.len();
    if n_kept == 0 {
        return 0.0;
    }
    let m_of = |i: usize| -> f64 {
        kept.iter().filter(|&&j| j != i && (x[j] - x[i]).abs() < radius[i]).count() as f64
    };
    let mean_k = kept.iter().map(|&i| numeric::special::digamma(k_all[i])).sum::<f64>() / n_kept as f64;
    let mean_label = kept.iter().map(|&i| numeric::special::digamma(label_counts[i])).sum::<f64>() / n_kept as f64;
    let mean_m = kept.iter().map(|&i| numeric::special::digamma(m_of(i) + 1.0)).sum::<f64>() / n_kept as f64;
    let mi = numeric::special::digamma(n_kept as f64) + mean_k - mean_label - mean_m;
    mi.max(0.0)
}

/// One column of `x`, as a plain `Vec<f64>` — `matrix_row`'s column-major
/// counterpart, needed throughout feature selection (mutual info,
/// correlation, and column-subsetting all work per-feature, not per-row).
fn matrix_col(x: &Matrix, c: usize) -> Vec<f64> {
    (0..x.rows()).map(|r| x.get(r, c).unwrap_or(0.0)).collect()
}

/// `X[rows, cols]` — both a row AND column subset at once, needed by
/// every g-score evaluation below (one candidate feature subset, one
/// cross-validation fold). Builds the result directly rather than
/// composing two existing single-axis selectors, since this is called
/// inside rayon-parallel hot loops (once per beam candidate per fold) and
/// avoids an intermediate full-row-width allocation.
fn select_rows_cols(x: &Matrix, rows: &[usize], cols: &[usize]) -> Matrix {
    let block: Vec<Vec<f64>> = rows
        .iter()
        .map(|&r| cols.iter().map(|&c| x.get(r, c).unwrap_or(0.0)).collect())
        .collect();
    Matrix::from_rows(&block).unwrap_or_else(|_| Matrix::zeros(rows.len(), cols.len()))
}

/// A*-mRMR's / RFE's shared g-score: mean k-fold cross-validated
/// `training_diagnostic` (accuracy for classification, R^2 for
/// regression) of a single shallow `TreeBuilder` tree fit on exactly the
/// given feature columns. Calls `TreeBuilder` directly rather than going
/// through `self.apply`/`call_builtin` — the whole reason this is
/// possible to run on rayon (`par_iter` over the `k` folds): it never
/// touches `&mut Interp`, unlike an arbitrary named-Qu-function estimator
/// would. A single shallow tree (not a forest) is deliberately cheap:
/// this function is called once per beam candidate per A* node
/// expansion, so its own cost multiplies the search's total cost directly.
fn cv_score_tree_subset(
    x: &Matrix,
    y: &[f64],
    cols: &[usize],
    k_folds: usize,
    classification: bool,
    max_depth: usize,
    seed: u64,
) -> f64 {
    let n = x.rows();
    let mut rng = Rng::new(seed);
    let order = shuffled_row_order(&mut rng, n);
    let base = n / k_folds;
    let rem = n % k_folds;
    let mut fold_of = vec![0usize; n];
    let mut pos = 0;
    for fold in 0..k_folds {
        let len = base + if fold < rem { 1 } else { 0 };
        for &row in &order[pos..pos + len] {
            fold_of[row] = fold;
        }
        pos += len;
    }
    let scores: Vec<f64> = (0..k_folds)
        .into_par_iter()
        .map(|fold| {
            let train_idx: Vec<usize> = (0..n).filter(|&r| fold_of[r] != fold).collect();
            let test_idx: Vec<usize> = (0..n).filter(|&r| fold_of[r] == fold).collect();
            if train_idx.is_empty() || test_idx.is_empty() {
                return 0.0;
            }
            let x_train = select_rows_cols(x, &train_idx, cols);
            let y_train: Vec<f64> = train_idx.iter().map(|&r| y[r]).collect();
            let x_test = select_rows_cols(x, &test_idx, cols);
            let y_test: Vec<f64> = test_idx.iter().map(|&r| y[r]).collect();
            let mut tree_rng = Rng::new(seed.wrapping_add(fold as u64).wrapping_add(1));
            let indices: Vec<usize> = (0..x_train.rows()).collect();
            let mut builder = TreeBuilder::new(&x_train, &y_train, classification, max_depth, 2, None, &mut tree_rng);
            builder.build_node(&indices, 0);
            let tree = builder.finish();
            let preds: Vec<f64> = (0..x_test.rows()).map(|r| tree_predict_row(&tree, &matrix_row(&x_test, r))).collect();
            training_diagnostic(&y_test, &preds, classification)
        })
        .collect();
    scores.iter().sum::<f64>() / scores.len().max(1) as f64
}

/// A single A* search node: an f-score (`g + 0.5*h`, matching the
/// reference's own weighting) and the sorted, deduplicated set of feature
/// indices selected on this path. `BinaryHeap` is a max-heap, so unlike
/// the Python reference (which negates `f_score` to fake a min-heap out of
/// `heapq`'s min-heap default), this pushes `f_score` directly.
#[derive(Clone)]
struct AStarNode {
    f_score: f64,
    selected: Vec<usize>,
}
impl PartialEq for AStarNode {
    fn eq(&self, other: &Self) -> bool {
        self.f_score == other.f_score
    }
}
impl Eq for AStarNode {}
impl PartialOrd for AStarNode {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}
impl Ord for AStarNode {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        self.f_score.partial_cmp(&other.f_score).unwrap_or(std::cmp::Ordering::Equal)
    }
}

/// The literal A*-mRMR search (`AStarMRMRHybrid.select_features` in
/// `novel_methods.py`): a priority queue over partial feature subsets,
/// ordered by `f = g + 0.5*h` where `g` is a real cross-validated model
/// score on that subset (`cv_score_tree_subset`) and `h` is the mRMR
/// heuristic (`relevance - adaptive_alpha * redundancy`, with `alpha`
/// increasing as the subset fills up — the reference's own novelty over
/// textbook mRMR's fixed alpha). Each popped incomplete node expands only
/// its top `beam_width` mRMR-ranked candidates (bounding the branching
/// factor — pure A* would try all remaining features); each *complete*
/// node (already at `k` features) gets its real g-score evaluated as the
/// candidate final answer, tracking the best one seen. Falls back to
/// plain greedy mRMR (no CV, no search) if the queue empties or the
/// iteration cap is hit before any complete subset is found — the
/// reference's own documented behavior for a search space too large to
/// exhaust within budget, not a silent wrong answer.
///
/// Candidate expansion is rayon-parallel across the `beam_width`
/// candidates (each needs its own `cv_score_tree_subset` call) — the
/// actual hardware-acceleration target here, matching why the Python
/// reference has a GPU/Numba variant at all.
#[allow(clippy::too_many_arguments)]
fn astar_mrmr_search(
    x: &Matrix,
    y: &[f64],
    relevance: &[f64],
    k: usize,
    beam_width: usize,
    redundancy_weight: f64,
    cv_folds: usize,
    classification: bool,
    max_depth: usize,
    seed: u64,
) -> Vec<usize> {
    let n_features = x.cols();
    let redundancy_of = |candidate: usize, selected: &[usize]| -> f64 {
        if selected.is_empty() {
            return 0.0;
        }
        let cand_col = matrix_col(x, candidate);
        let mean_abs_corr = selected
            .iter()
            .map(|&s| pearson_corr(&cand_col, &matrix_col(x, s)).abs())
            .sum::<f64>()
            / selected.len() as f64;
        mean_abs_corr
    };
    let heuristic_of = |candidate: usize, selected: &[usize]| -> f64 {
        let progress = selected.len() as f64 / k as f64;
        let adaptive_alpha = redundancy_weight * (1.0 + 0.5 * progress);
        relevance[candidate] - adaptive_alpha * redundancy_of(candidate, selected)
    };

    let mut heap: std::collections::BinaryHeap<AStarNode> = std::collections::BinaryHeap::new();
    heap.push(AStarNode { f_score: 0.0, selected: Vec::new() });
    let mut visited: std::collections::HashSet<Vec<usize>> = std::collections::HashSet::new();
    let mut best_complete: Option<Vec<usize>> = None;
    let mut best_score = f64::NEG_INFINITY;
    let mut iterations = 0usize;
    let max_iterations = (k * beam_width * 3).max(5000);

    while let Some(node) = heap.pop() {
        if iterations >= max_iterations {
            break;
        }
        iterations += 1;

        if node.selected.len() == k {
            let g = cv_score_tree_subset(x, y, &node.selected, cv_folds, classification, max_depth, seed);
            if g > best_score {
                best_score = g;
                best_complete = Some(node.selected.clone());
            }
            continue;
        }
        if visited.contains(&node.selected) {
            continue;
        }
        visited.insert(node.selected.clone());

        let selected_set: std::collections::HashSet<usize> = node.selected.iter().copied().collect();
        let mut candidate_scores: Vec<(usize, f64)> = (0..n_features)
            .filter(|c| !selected_set.contains(c))
            .map(|c| (c, heuristic_of(c, &node.selected)))
            .collect();
        candidate_scores.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
        candidate_scores.truncate(beam_width);

        let expanded: Vec<AStarNode> = candidate_scores
            .into_par_iter()
            .filter_map(|(idx, h_score)| {
                let mut new_selected = node.selected.clone();
                new_selected.push(idx);
                new_selected.sort_unstable();
                if visited.contains(&new_selected) {
                    return None;
                }
                let g = cv_score_tree_subset(x, y, &new_selected, cv_folds, classification, max_depth, seed);
                Some(AStarNode { f_score: g + 0.5 * h_score, selected: new_selected })
            })
            .collect();
        for node in expanded {
            heap.push(node);
        }
    }

    best_complete.unwrap_or_else(|| {
        // Greedy mRMR fallback — no search, no CV, same as the Python
        // reference's own `_greedy_mrmr`.
        let mut selected: Vec<usize> = Vec::with_capacity(k);
        for _ in 0..k.min(n_features) {
            let best = (0..n_features)
                .filter(|c| !selected.contains(c))
                .map(|c| (c, heuristic_of(c, &selected)))
                .max_by(|a, b| a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal));
            if let Some((idx, _)) = best {
                selected.push(idx);
            }
        }
        selected.sort_unstable();
        selected
    })
}

/// Recursive feature elimination (model-agnostic backward selection):
/// starts with every feature, repeatedly drops whichever ONE remaining
/// feature's removal hurts `cv_score_tree_subset` the *least* (equivalently,
/// contributes the least to the current subset's CV score), until `k`
/// remain. Model-agnostic by construction — it measures each feature's
/// actual marginal contribution to a real cross-validated fit rather than
/// reading a model-specific `coef_`/`feature_importances_` (which
/// wouldn't even exist for every model kind), the same wrapper-style RFE
/// variant real implementations use for non-linear estimators. Each
/// round's per-feature ablation is rayon-parallel across the remaining
/// features — the expensive step, same reasoning as A*-mRMR's candidate
/// expansion.
fn rfe_select(x: &Matrix, y: &[f64], k: usize, cv_folds: usize, classification: bool, max_depth: usize, seed: u64) -> Vec<usize> {
    let n_features = x.cols();
    let mut remaining: Vec<usize> = (0..n_features).collect();
    while remaining.len() > k {
        let scored: Vec<(usize, f64)> = remaining
            .par_iter()
            .map(|&drop_candidate| {
                let subset: Vec<usize> = remaining.iter().copied().filter(|&f| f != drop_candidate).collect();
                let score = cv_score_tree_subset(x, y, &subset, cv_folds, classification, max_depth, seed);
                (drop_candidate, score)
            })
            .collect();
        // Drop whichever feature's ABSENCE leaves the HIGHEST score — i.e.
        // the one that was contributing least (or actively hurting, if
        // its absence scores even better than its presence).
        let to_drop = scored
            .into_iter()
            .max_by(|a, b| a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal))
            .map(|(idx, _)| idx);
        match to_drop {
            Some(idx) => remaining.retain(|&f| f != idx),
            None => break,
        }
    }
    remaining.sort_unstable();
    remaining
}

/// `ablation_study` / `cv_stability` / `hurst_exponent`
/// (2026-08-25, Ahmed: "make some functions" for feature ablation, plus
/// "persistence, variability, explainability... for time series or
/// regression or supervised learning"). Reuses `cv_score_tree_subset` —
/// the same direct-Rust, rayon-parallel g-score `astar_mrmr`/`rfe` already
/// build on — for the two model-performance diagnostics; `hurst_exponent`
/// is a standalone time-series statistic with no model involved.

/// One-feature-at-a-time ablation: the full model's CV score minus the
/// score with just that one feature removed, for every feature. Positive
/// = removing it hurt (a genuinely useful feature); negative or ~0 =
/// removing it didn't hurt, or even helped (redundant, or actively
/// harmful). Unlike RFE (which greedily removes the single least useful
/// feature and *keeps going* against the shrinking remainder) this always
/// measures every feature's contribution against the *same* full-model
/// baseline — a report to read, not a selection to act on.
fn ablation_study_scores(x: &Matrix, y: &[f64], cv_folds: usize, classification: bool, max_depth: usize, seed: u64) -> Vec<f64> {
    let n_features = x.cols();
    let all_cols: Vec<usize> = (0..n_features).collect();
    let baseline = cv_score_tree_subset(x, y, &all_cols, cv_folds, classification, max_depth, seed);
    (0..n_features)
        .into_par_iter()
        .map(|f| {
            let subset: Vec<usize> = all_cols.iter().copied().filter(|&c| c != f).collect();
            let ablated = cv_score_tree_subset(x, y, &subset, cv_folds, classification, max_depth, seed);
            baseline - ablated
        })
        .collect()
}

/// Repeated k-fold CV score — the *variability* diagnostic: how much does
/// this model's measured performance actually move around under a
/// different random train/test split of the same data? A model whose
/// score swings widely across repeats is a model you shouldn't trust a
/// single CV number from. Returns the raw per-repeat scores (not a
/// pre-computed mean/std) — `mean(...)`/`std(...)` on the result gives
/// both, and the full distribution is still there if a caller wants a
/// histogram or a percentile instead.
fn cv_stability_scores(x: &Matrix, y: &[f64], n_repeats: usize, cv_folds: usize, classification: bool, max_depth: usize, seed: u64) -> Vec<f64> {
    let all_cols: Vec<usize> = (0..x.cols()).collect();
    (0..n_repeats)
        .into_par_iter()
        .map(|r| cv_score_tree_subset(x, y, &all_cols, cv_folds, classification, max_depth, seed.wrapping_add(r as u64 * 104_729)))
        .collect()
}

/// Hurst exponent via classic rescaled-range (R/S) analysis — the
/// *persistence* diagnostic for a time series: `H ≈ 0.5` is a random walk
/// (no memory — tomorrow's move is unrelated to today's), `H > 0.5` is
/// persistent/trending (a move tends to be followed by a move in the same
/// direction), `H < 0.5` is anti-persistent/mean-reverting (a move tends
/// to reverse). Splits the series into successively larger equal-size
/// windows (geometric growth, `1.5x` each step, from 8 samples up to
/// `n/2`), computes the mean rescaled range `R/S` (the cumulative-
/// deviation range divided by the standard deviation) within each
/// window's chunks, then returns the slope of `ln(R/S)` against `ln
/// (window size)` — the standard log-log regression definition of `H`.
/// `NaN` for a series too short to get at least two usable window sizes
/// (needs `n >= 20`, same threshold every practical R/S implementation
/// uses — anything shorter doesn't have enough scales to regress a slope
/// through).
fn hurst_exponent(x: &[f64]) -> f64 {
    let n = x.len();
    if n < 20 {
        return f64::NAN;
    }
    let mut log_window = Vec::new();
    let mut log_rs = Vec::new();
    let mut window = 8usize;
    let max_window = n / 2;
    while window <= max_window {
        let n_chunks = n / window;
        if n_chunks < 1 {
            break;
        }
        let mut rs_values = Vec::with_capacity(n_chunks);
        for c in 0..n_chunks {
            let chunk = &x[c * window..(c + 1) * window];
            let mean = chunk.iter().sum::<f64>() / window as f64;
            let (mut cum_dev, mut max_cum, mut min_cum) = (0.0, f64::MIN, f64::MAX);
            for &v in chunk {
                cum_dev += v - mean;
                max_cum = max_cum.max(cum_dev);
                min_cum = min_cum.min(cum_dev);
            }
            let range = max_cum - min_cum;
            let std = (chunk.iter().map(|v| (v - mean).powi(2)).sum::<f64>() / window as f64).sqrt();
            if std > 1e-12 {
                rs_values.push(range / std);
            }
        }
        if !rs_values.is_empty() {
            let mean_rs = rs_values.iter().sum::<f64>() / rs_values.len() as f64;
            if mean_rs > 0.0 {
                log_window.push((window as f64).ln());
                log_rs.push(mean_rs.ln());
            }
        }
        window = ((window as f64) * 1.5).ceil() as usize;
    }
    if log_window.len() < 2 {
        return f64::NAN;
    }
    let n_pts = log_window.len() as f64;
    let mean_x = log_window.iter().sum::<f64>() / n_pts;
    let mean_y = log_rs.iter().sum::<f64>() / n_pts;
    let (mut num, mut den) = (0.0, 0.0);
    for i in 0..log_window.len() {
        num += (log_window[i] - mean_x) * (log_rs[i] - mean_y);
        den += (log_window[i] - mean_x).powi(2);
    }
    if den <= 0.0 {
        f64::NAN
    } else {
        num / den
    }
}

/// Groups a uniformly-sampled series by its position within a repeating
/// calendar-style cycle — "hour of day" is a 24-hour cycle (`period_
/// seconds=86400`) cut into 24 one-hour bins (`n_bins=24`); "day of week"
/// is a 7-day cycle cut into 7 bins; and so on — and computes one
/// statistic per bin. This is the mechanism behind `hourly_profile`/
/// `daily_profile`/`monthly_profile`/`minutely_profile` (thin presets
/// over this), and is itself exposed as `periodic_profile` for any other
/// cycle length. No real calendar/timestamp type exists in Qu, so
/// "elapsed time" is just `sample_index / fs` seconds, wrapped modulo
/// `period_seconds` — every cycle's worth of samples that land in the
/// same phase-bin get pooled together (all "3am" samples across many
/// days end up in the same bin, not just the first day's), which is
/// exactly the seasonal-decomposition behavior "how does this differ
/// across the day/week/year" needs.
///
/// `stat` per bin: `"mean"`/`"std"`/`"var"` (plain descriptive stats);
/// `"hurst"` (that bin's own R/S persistence, `hurst_exponent` — only
/// meaningful once a bin has pooled many cycles' worth of samples, not
/// just a handful); `"sad"` (mean absolute first difference within the
/// bin, `mean(|x[i]-x[i-1]|)` — a roughness/variability proxy; Ahmed's
/// own "SAD" terminology, interpreted this way as the standard meaning in
/// a time-series-variability context — flag if a different definition
/// was actually meant). A bin no sample ever lands in reads back `NaN`,
/// not a silently fabricated zero.
fn periodic_profile(x: &[f64], fs: f64, period_seconds: f64, n_bins: usize, stat: &str) -> Vec<f64> {
    let mut bins: Vec<Vec<f64>> = vec![Vec::new(); n_bins];
    for (i, &v) in x.iter().enumerate() {
        let t = i as f64 / fs;
        let phase = (t % period_seconds) / period_seconds; // in [0, 1)
        let bin = ((phase * n_bins as f64) as usize).min(n_bins - 1);
        bins[bin].push(v);
    }
    bins.iter()
        .map(|samples| {
            if samples.is_empty() {
                return f64::NAN;
            }
            match stat {
                "mean" => samples.iter().sum::<f64>() / samples.len() as f64,
                "std" | "var" => {
                    let mean = samples.iter().sum::<f64>() / samples.len() as f64;
                    let var = samples.iter().map(|v| (v - mean).powi(2)).sum::<f64>() / samples.len() as f64;
                    if stat == "std" { var.sqrt() } else { var }
                }
                "hurst" => hurst_exponent(samples),
                "sad" => {
                    if samples.len() < 2 {
                        0.0
                    } else {
                        samples.windows(2).map(|w| (w[1] - w[0]).abs()).sum::<f64>() / (samples.len() - 1) as f64
                    }
                }
                _ => f64::NAN,
            }
        })
        .collect()
}

/// The standard autocorrelation function: `acf[k] = Σ(x[i]-mean)(x[i+k]-
/// mean) / Σ(x[i]-mean)^2` for lags `k = 0..=max_lag`, normalized so
/// `acf[0] = 1` (unlike `xcorr`, which returns the *unnormalized* full
/// two-sided lag range `-N+1..=N-1` — this is the "how correlated is the
/// series with itself `k` steps later, on a -1..1 scale, non-negative
/// lags only" form every time-series textbook plots).
fn acf(x: &[f64], max_lag: usize) -> Vec<f64> {
    let n = x.len();
    let mean = x.iter().sum::<f64>() / n as f64;
    let denom: f64 = x.iter().map(|v| (v - mean).powi(2)).sum();
    (0..=max_lag)
        .map(|k| {
            if denom <= 0.0 || k >= n {
                return f64::NAN;
            }
            let num: f64 = (0..n - k).map(|i| (x[i] - mean) * (x[i + k] - mean)).sum();
            num / denom
        })
        .collect()
}

/// Wraps a single fitted `TreeArrays` as a `tree_model` `Value::Model`:
/// the flat arrays as plain, directly-inspectable `Value::Vec` fields
/// (`m.feature`, `m.threshold`, ...), plus `n_nodes`/`depth`/`max_depth`/
/// `n_features`, plus a cheap training-set diagnostic (R^2 for regression,
/// accuracy for classification — the same "score on the data you trained
/// on" spirit as `ols_model`'s own `r2` field).
fn tree_model_handle(tree: &TreeArrays, x: &Matrix, y: &[f64], classification: bool, max_depth: usize) -> ModelHandle {
    let n = x.rows();
    let predictions: Vec<f64> = (0..n).map(|r| tree_predict_row(tree, &matrix_row(x, r))).collect();
    let diagnostic = training_diagnostic(y, &predictions, classification);
    let fields = vec![
        ("feature".to_string(), Value::Vec(Arc::new(tree.feature.clone()))),
        ("threshold".to_string(), Value::Vec(Arc::new(tree.threshold.clone()))),
        ("children_left".to_string(), Value::Vec(Arc::new(tree.children_left.clone()))),
        ("children_right".to_string(), Value::Vec(Arc::new(tree.children_right.clone()))),
        ("value".to_string(), Value::Vec(Arc::new(tree.value.clone()))),
        ("n_nodes".to_string(), Value::Num(tree.feature.len() as f64)),
        ("depth".to_string(), Value::Num(tree_depth(tree, 0) as f64)),
        ("max_depth".to_string(), Value::Num(max_depth as f64)),
        ("n_features".to_string(), Value::Num(x.cols() as f64)),
        (
            (if classification { "accuracy" } else { "r2" }).to_string(),
            Value::Num(diagnostic),
        ),
    ];
    ModelHandle::new(if classification { "tree_classification" } else { "tree_regression" }, fields)
}

/// Packs `n_trees` fitted `TreeArrays` (`random_forest_model`'s bagged
/// trees, or `gradient_boosting_model`'s sequential ones) into the 5
/// padded-matrix fields a forest model shares. Trees have different node
/// counts, and Qu has no "list of models" value kind, so each array
/// becomes one `(n_trees, max_nodes)` `Value::Mat`: row `t` holds tree
/// `t`'s array left-justified, padded with harmless filler past its own
/// `node_counts[t]` — traversal never reads past a tree's own node count,
/// since every child index a tree's builder ever wrote points at one of
/// that same tree's own (earlier-built) slots, so the padding columns are
/// simply never visited by `tree_predict_row`. `forest_tree_at` is the
/// inverse: reconstructs tree `t`'s own `TreeArrays` back out of these.
fn pack_forest_arrays(trees: &[TreeArrays]) -> (Matrix, Matrix, Matrix, Matrix, Matrix, Vec<f64>) {
    let n_trees = trees.len();
    let max_nodes = trees.iter().map(|t| t.feature.len()).max().unwrap_or(1).max(1);
    let mut feature_mat = Matrix::zeros(n_trees, max_nodes);
    let mut threshold_mat = Matrix::zeros(n_trees, max_nodes);
    let mut left_mat = Matrix::zeros(n_trees, max_nodes);
    let mut right_mat = Matrix::zeros(n_trees, max_nodes);
    let mut value_mat = Matrix::zeros(n_trees, max_nodes);
    let mut node_counts = vec![0.0; n_trees];
    for (t, tree) in trees.iter().enumerate() {
        node_counts[t] = tree.feature.len() as f64;
        for (c, &v) in tree.feature.iter().enumerate() {
            let _ = feature_mat.set(t, c, v);
        }
        for (c, &v) in tree.threshold.iter().enumerate() {
            let _ = threshold_mat.set(t, c, v);
        }
        for (c, &v) in tree.children_left.iter().enumerate() {
            let _ = left_mat.set(t, c, v);
        }
        for (c, &v) in tree.children_right.iter().enumerate() {
            let _ = right_mat.set(t, c, v);
        }
        for (c, &v) in tree.value.iter().enumerate() {
            let _ = value_mat.set(t, c, v);
        }
    }
    (feature_mat, threshold_mat, left_mat, right_mat, value_mat, node_counts)
}

/// The 5 padded-matrix fields plus `node_counts`, as `ModelHandle` field
/// entries — `random_forest_model`/`gradient_boosting_model` each append
/// their own remaining fields (`n_trees`, `max_depth`, diagnostics, ...)
/// on top of this shared prefix.
fn forest_fields(feature: Matrix, threshold: Matrix, left: Matrix, right: Matrix, value: Matrix, node_counts: Vec<f64>) -> Vec<(String, Value)> {
    vec![
        ("feature".to_string(), Value::Mat(Arc::new(feature))),
        ("threshold".to_string(), Value::Mat(Arc::new(threshold))),
        ("children_left".to_string(), Value::Mat(Arc::new(left))),
        ("children_right".to_string(), Value::Mat(Arc::new(right))),
        ("value".to_string(), Value::Mat(Arc::new(value))),
        ("node_counts".to_string(), Value::Vec(Arc::new(node_counts))),
    ]
}

/// Reconstructs tree `t`'s `TreeArrays` from a forest model's padded
/// matrices — the inverse of `pack_forest_arrays`.
fn forest_tree_at(m: &ModelHandle, t: usize) -> R<TreeArrays> {
    let count = to_vec(m.field("node_counts").expect("forest model always has node_counts"))?[t] as usize;
    let row = |field: &str| -> R<Vec<f64>> {
        let Some(Value::Mat(mat)) = m.field(field) else {
            return e(format!("forest model is missing its `{field}` field"));
        };
        Ok((0..count).map(|c| mat.get(t, c).unwrap_or(0.0)).collect())
    };
    Ok(TreeArrays {
        feature: row("feature")?,
        threshold: row("threshold")?,
        children_left: row("children_left")?,
        children_right: row("children_right")?,
        value: row("value")?,
    })
}

/// `random_forest_model`'s aggregation across trees for one input row:
/// the mean prediction (regression) or the majority-voted predicted class
/// (classification, `majority_class` applied to the trees' own votes
/// rather than to raw labels). Not shared with `gradient_boosting_model`,
/// whose own `model_predict` arm accumulates `baseline + learning_rate *
/// tree.predict(row)` directly instead — a genuinely different combination
/// rule (a weighted running sum, not a plain average or a vote), so a
/// forced shared helper would cost more in parameters than it would save
/// in code.
fn forest_predict_row(trees: &[TreeArrays], row: &[f64], classification: bool) -> f64 {
    let preds: Vec<f64> = trees.iter().map(|t| tree_predict_row(t, row)).collect();
    if classification {
        majority_class(preds.into_iter())
    } else {
        preds.iter().sum::<f64>() / preds.len() as f64
    }
}

/// One LMS sample step — the `update` half of the `lms_init` state
/// protocol, reached as `state.update(x, d)` with `x` the new input
/// sample and `d` the desired/reference sample.
///
/// Per sample, in exactly this order (the order is the contract, not an
/// implementation detail):
///   1. shift `x` into `hist` (newest first; the oldest sample falls off
///      the end),
///   2. `y = dot(w, hist)`,
///   3. `e = d - y`,
///   4. `w = w + mu * e * hist`.
///
/// Because `y` is formed from the window that ALREADY contains `x`, the
/// 1-tap case reduces exactly to the textbook single-weight recursion
/// `e = d - w*x; w = w + mu*e*x` — the multi-tap form is a
/// generalization of it, not a separate algorithm, which is why there is
/// one code path here and not two. (Forming `y` from the PREVIOUS window
/// instead is the classic off-by-one in this filter: it still converges,
/// just to a one-sample-delayed answer, so it looks correct on a plot.)
///
/// Returns a NEW state; the receiver is untouched.
fn lms_update(m: &ModelHandle, args: &[Value]) -> R<Value> {
    let field = |name: &str| -> R<&Value> {
        m.field(name)
            .ok_or_else(|| EvalError { msg: format!("update: lms state is missing its {name} field") })
    };
    let w = to_vec(field("w")?)?;
    let hist_prev = to_vec(field("hist")?)?;
    let mu = field("mu")?.as_num().map_err(|msg| EvalError { msg })?;
    let x = arg_get(args, 1)
        .ok_or_else(|| EvalError {
            msg: "update(lms_state, x, d) needs an input sample `x` and a desired sample `d`".into(),
        })?
        .as_num()
        .map_err(|msg| EvalError { msg })?;
    let d = arg_get(args, 2)
        .ok_or_else(|| EvalError {
            msg: "update(lms_state, x, d) needs a desired sample `d` as its second argument".into(),
        })?
        .as_num()
        .map_err(|msg| EvalError { msg })?;
    if w.len() != hist_prev.len() || w.is_empty() {
        return e(format!(
            "update: malformed lms state (w has {} weight(s) but hist has {} sample(s))",
            w.len(),
            hist_prev.len()
        ));
    }

    // Shift the sliding window: newest sample first, oldest dropped.
    let mut hist = Vec::with_capacity(hist_prev.len());
    hist.push(x);
    hist.extend_from_slice(&hist_prev[..hist_prev.len() - 1]);

    let y: f64 = w.iter().zip(hist.iter()).map(|(wi, hi)| wi * hi).sum();
    let err = d - y;
    let w_new: Vec<f64> = w.iter().zip(hist.iter()).map(|(wi, hi)| wi + mu * err * hi).collect();

    Ok(Value::Model(Arc::new(ModelHandle::new(
        "lms",
        vec![
            ("w".to_string(), Value::Vec(Arc::new(w_new))),
            ("hist".to_string(), Value::Vec(Arc::new(hist))),
            ("mu".to_string(), Value::Num(mu)),
            ("y".to_string(), Value::Num(y)),
            ("e".to_string(), Value::Num(err)),
        ],
    ))))
}

/// One PID tick — the `update` half of the `pid_init` state protocol,
/// reached as `state.update(error)` with `error` the current
/// setpoint-minus-measurement.
///
/// Per tick, in exactly this order (the order is the contract):
///   1. `integral = integral + error * dt`  (then clamped, if a clamp
///      was given),
///   2. `deriv = (error - e_prev) / dt`,
///   3. `u = kp*error + ki*integral + kd*deriv`,
///   4. `e_prev = error`.
///
/// i.e. `u[k] = Kp*e[k] + Ki*sum(e[i]*dt, i=0..k) + Kd*(e[k]-e[k-1])/dt`.
/// Note that step 1 runs BEFORE `u` is formed, so the current error is
/// already inside the integral term on the very tick it arrives. That is
/// the standard discrete form; integrating after the output instead lags
/// the integral action by one sample, which on a slow plant is invisible
/// on a plot and shows up only as a tuning that will not transfer.
///
/// The error is supplied by the caller rather than a setpoint and a
/// measurement, and `u` is applied by the caller too: the controller
/// owns the recursion, not the loop. That keeps it usable for the cases
/// where the error is not a plain subtraction (a wrapped angle, a
/// ratio, a cascaded inner loop).
///
/// Anti-windup, when `integral_clamp` is set, is a symmetric clamp of
/// the ACCUMULATOR (`|integral| <= clamp`), not of `u` — clamping the
/// output instead leaves the accumulator free to grow without bound
/// behind it, which is precisely the windup the limit is there to
/// prevent. The clamped value is what is stored, so the state never
/// carries a number the next tick would have to re-clamp.
///
/// Returns a NEW state; the receiver is untouched.
fn pid_update(m: &ModelHandle, args: &[Value]) -> R<Value> {
    let field = |name: &str| -> R<f64> {
        m.field(name)
            .ok_or_else(|| EvalError { msg: format!("update: pid state is missing its {name} field") })?
            .as_num()
            .map_err(|msg| EvalError { msg })
    };
    let kp = field("kp")?;
    let ki = field("ki")?;
    let kd = field("kd")?;
    let dt = field("dt")?;
    let integral_prev = field("integral")?;
    let e_prev = field("e_prev")?;
    let clamp_field = m
        .field("integral_clamp")
        .ok_or_else(|| EvalError { msg: "update: pid state is missing its integral_clamp field".into() })?
        .clone();
    let err = arg_get(args, 1)
        .ok_or_else(|| EvalError {
            msg: "update(pid_state, error) needs the current error (setpoint - measurement) as its argument".into(),
        })?
        .as_num()
        .map_err(|msg| EvalError { msg })?;

    let mut integral = integral_prev + err * dt;
    if let Value::Num(c) = clamp_field {
        integral = integral.clamp(-c, c);
    }
    let deriv = (err - e_prev) / dt;
    let u = kp * err + ki * integral + kd * deriv;

    Ok(Value::Model(Arc::new(ModelHandle::new(
        "pid",
        vec![
            ("kp".to_string(), Value::Num(kp)),
            ("ki".to_string(), Value::Num(ki)),
            ("kd".to_string(), Value::Num(kd)),
            ("dt".to_string(), Value::Num(dt)),
            ("integral".to_string(), Value::Num(integral)),
            ("e_prev".to_string(), Value::Num(err)),
            ("u".to_string(), Value::Num(u)),
            ("integral_clamp".to_string(), clamp_field),
        ],
    ))))
}

// ---- control: sliding-mode and Mamdani fuzzy controllers (the `update`
// half of the `smc_init` / `fuzzy_pid_init` state protocols) ----

/// Read a controller state's numeric field, or say which one is missing.
fn ctrl_field(m: &ModelHandle, name: &str) -> R<f64> {
    m.field(name)
        .ok_or_else(|| EvalError { msg: format!("update: {} state is missing its {name} field", m.kind) })?
        .as_num()
        .map_err(|msg| EvalError { msg })
}

/// The error derivative for one controller step.
///
/// Returns `(e_dot, n_next)`. If the caller passed `error_dot=` it is used
/// verbatim — the controller never second-guesses a measured derivative.
/// Otherwise it is the backward difference `(e - e_prev)/dt`, and on the
/// VERY FIRST update (`n == 0`) it is 0 rather than `e/dt`: with no
/// previous sample there is no derivative, and pretending the error
/// stepped from 0 to `e` in one `dt` produces the classic derivative kick
/// — a huge spurious first output that looks like a tuning problem.
fn ctrl_error_dot(
    m: &ModelHandle,
    error: f64,
    dt: f64,
    style: &[(String, Value)],
) -> R<(f64, f64)> {
    let n = ctrl_field(m, "n")?;
    if let Some((_, v)) = style_entry(style, "error_dot") {
        let ed = v.as_num().map_err(|msg| EvalError { msg })?;
        return Ok((ed, n + 1.0));
    }
    let e_prev = ctrl_field(m, "e")?;
    let ed = if n < 1.0 { 0.0 } else { (error - e_prev) / dt };
    Ok((ed, n + 1.0))
}

/// The saturation function `sat(x) = clamp(x, -1, 1)`, and with a zero
/// boundary layer the literal `sign(x)` (with `sign(0) = 0`) that it
/// replaces. See `smc_init`'s doc comment for why `phi > 0` is the
/// default.
fn smc_sat(s: f64, phi: f64) -> f64 {
    if phi <= 0.0 {
        if s > 0.0 {
            1.0
        } else if s < 0.0 {
            -1.0
        } else {
            0.0
        }
    } else {
        (s / phi).clamp(-1.0, 1.0)
    }
}

/// One sliding-mode control step — `state.update(error, error_dot=)`.
///
/// Returns a NEW state; the receiver is untouched.
fn smc_update(m: &ModelHandle, args: &[Value], style: &[(String, Value)]) -> R<Value> {
    let error = arg_get(args, 1)
        .ok_or_else(|| EvalError {
            msg: "update(smc_state, error, error_dot=) needs the current error as its argument".into(),
        })?
        .as_num()
        .map_err(|msg| EvalError { msg })?;
    let k_gain = ctrl_field(m, "K")?;
    let lambda = ctrl_field(m, "lambda")?;
    let phi = ctrl_field(m, "phi")?;
    let dt = ctrl_field(m, "dt")?;
    let Some(Value::Str(surface)) = m.field("surface") else {
        return e("update: malformed smc state (missing surface field)".to_string());
    };
    let surface = surface.clone();
    let (e_dot, n_next) = ctrl_error_dot(m, error, dt, style)?;

    // The surface the state was BUILT with, not one re-derived from
    // whether `lambda` happens to be non-zero (see `smc_init`).
    let s = if surface == "e" { error } else { e_dot + lambda * error };
    // `u = u_eq + K*sat(s/phi)` with `u_eq = 0` (model-free).
    let u = k_gain * smc_sat(s, phi);

    Ok(Value::Model(Arc::new(ModelHandle::new(
        "smc",
        vec![
            ("K".to_string(), Value::Num(k_gain)),
            ("lambda".to_string(), Value::Num(lambda)),
            ("phi".to_string(), Value::Num(phi)),
            ("dt".to_string(), Value::Num(dt)),
            ("surface".to_string(), Value::Str(surface)),
            ("e".to_string(), Value::Num(error)),
            ("e_dot".to_string(), Value::Num(e_dot)),
            ("s".to_string(), Value::Num(s)),
            ("u".to_string(), Value::Num(u)),
            ("n".to_string(), Value::Num(n_next)),
        ],
    ))))
}

/// The five linguistic terms, in index order, shared by both inputs and
/// the output: 0 = NB (negative big) .. 4 = PB (positive big).
const FUZZY_CENTRES: [f64; 5] = [-1.0, -0.5, 0.0, 0.5, 1.0];
/// Triangle half-width. 0.5 = the spacing of `FUZZY_CENTRES`, so adjacent
/// memberships overlap and sum to exactly 1 everywhere on `-1..1`.
const FUZZY_HALF_WIDTH: f64 = 0.5;

/// The standard diagonal-symmetric 5x5 fuzzy-PD rule base.
///
/// Rows index the `error` term, columns the `error_dot` term, entries the
/// output term, all on the NB..PB scale above. Written out literally
/// rather than computed as `clamp(i + j - 2, 0, 4)` (which it equals)
/// precisely so it can be read straight off against the table in any
/// fuzzy-control text:
///
/// ```text
///  e \ e_dot |  NB  NS  ZE  PS  PB
///  ----------+---------------------
///        NB  |  NB  NB  NB  NS  ZE
///        NS  |  NB  NB  NS  ZE  PS
///        ZE  |  NB  NS  ZE  PS  PB
///        PS  |  NS  ZE  PS  PB  PB
///        PB  |  ZE  PS  PB  PB  PB
/// ```
///
/// The anti-diagonal is all ZE: a big negative error with a big positive
/// error-rate is already being corrected, so the controller does nothing
/// — that cancellation is the derivative action, and it is the reason
/// this is a PD-type and not a P-type table.
const FUZZY_RULES: [[usize; 5]; 5] = [
    [0, 0, 0, 1, 2],
    [0, 0, 1, 2, 3],
    [0, 1, 2, 3, 4],
    [1, 2, 3, 4, 4],
    [2, 3, 4, 4, 4],
];

/// Triangular membership of `x` in term `i`.
fn fuzzy_mf(x: f64, i: usize) -> f64 {
    (1.0 - (x - FUZZY_CENTRES[i]).abs() / FUZZY_HALF_WIDTH).max(0.0)
}

/// Mamdani inference + centre-of-gravity defuzzification on the
/// normalised `-1..1` universe.
///
/// Per rule: firing strength `w = min(mu_e[i], mu_edot[j])` (min is the
/// Mamdani AND), the rule's output triangle CLIPPED at `w` (min
/// implication). The 25 clipped sets are aggregated by max, and the
/// centroid of that aggregate is integrated numerically over a fixed
/// grid. A fully-unfired aggregate (only reachable if every strength is
/// 0, which the overlapping MFs make impossible on `-1..1`) defuzzifies
/// to 0 rather than dividing by zero.
fn fuzzy_defuzzify(e_n: f64, edot_n: f64) -> f64 {
    let mu_e: Vec<f64> = (0..5).map(|i| fuzzy_mf(e_n, i)).collect();
    let mu_ed: Vec<f64> = (0..5).map(|j| fuzzy_mf(edot_n, j)).collect();

    // Firing strength per OUTPUT term: several rules can point at the same
    // consequent, and max-aggregation means only the strongest matters.
    let mut out_strength = [0.0f64; 5];
    for i in 0..5 {
        for j in 0..5 {
            let w = mu_e[i].min(mu_ed[j]);
            let k = FUZZY_RULES[i][j];
            if w > out_strength[k] {
                out_strength[k] = w;
            }
        }
    }

    // Both integrals use the TRAPEZOIDAL rule, not a plain sum over the
    // samples. That is not a refinement for its own sake: the aggregate is
    // piecewise linear, so trapezoid integrates the denominator exactly
    // and leaves only O(h^2) in the numerator, and the centroid comes out
    // at the analytic value. A plain rectangle sum gives the two endpoints
    // full weight instead of half, which biases the centroid outward --
    // a fully saturated input defuzzified to 0.835 instead of the exact
    // 5/6 = 0.8333, a systematic 0.2% overshoot on every single output.
    const STEPS: usize = 400;
    let mut num = 0.0;
    let mut den = 0.0;
    for p in 0..=STEPS {
        let x = -1.0 + 2.0 * (p as f64) / (STEPS as f64);
        let mut agg = 0.0f64;
        for k in 0..5 {
            let clipped = fuzzy_mf(x, k).min(out_strength[k]);
            if clipped > agg {
                agg = clipped;
            }
        }
        let weight = if p == 0 || p == STEPS { 0.5 } else { 1.0 };
        num += weight * x * agg;
        den += weight * agg;
    }
    if den > 0.0 {
        num / den
    } else {
        0.0
    }
}

/// One fuzzy-controller step — `state.update(error, error_dot=)`.
///
/// Returns a NEW state; the receiver is untouched.
fn fuzzy_pid_update(m: &ModelHandle, args: &[Value], style: &[(String, Value)]) -> R<Value> {
    let error = arg_get(args, 1)
        .ok_or_else(|| EvalError {
            msg: "update(fuzzy_pid_state, error, error_dot=) needs the current error as its argument".into(),
        })?
        .as_num()
        .map_err(|msg| EvalError { msg })?;
    let e_scale = ctrl_field(m, "error_scale")?;
    let ed_scale = ctrl_field(m, "error_dot_scale")?;
    let u_scale = ctrl_field(m, "output_scale")?;
    let dt = ctrl_field(m, "dt")?;
    let (e_dot, n_next) = ctrl_error_dot(m, error, dt, style)?;

    // Onto the normalised universe the rule base is defined on. Clamping
    // (not wrapping, not rescaling) is what makes a too-small
    // `error_scale` saturate rather than alias.
    let e_n = (error / e_scale).clamp(-1.0, 1.0);
    let edot_n = (e_dot / ed_scale).clamp(-1.0, 1.0);
    let u = u_scale * fuzzy_defuzzify(e_n, edot_n);

    Ok(Value::Model(Arc::new(ModelHandle::new(
        "fuzzy_pid",
        vec![
            ("error_scale".to_string(), Value::Num(e_scale)),
            ("error_dot_scale".to_string(), Value::Num(ed_scale)),
            ("output_scale".to_string(), Value::Num(u_scale)),
            ("dt".to_string(), Value::Num(dt)),
            ("e".to_string(), Value::Num(error)),
            ("e_dot".to_string(), Value::Num(e_dot)),
            ("u".to_string(), Value::Num(u)),
            ("n".to_string(), Value::Num(n_next)),
        ],
    ))))
}

/// Extract a `Value::Model` handle, or a clear type error.
fn as_model(v: &Value) -> R<Arc<ModelHandle>> {
    match v {
        Value::Model(m) => Ok(m.clone()),
        other => e(format!("expected a fitted model, found {}", other.type_name())),
    }
}

// ---- reinforcement learning: gridworld dynamics + tabular-policy helpers
// (shared by the `"gridworld_env"`/`"reset"`/`"step"`/`"q_learning"`/
// `"sarsa"` match arms above) ----

/// The gridworld's actual transition function: `state` -> `(next_state,
/// reward, done)` for one `action` (`0`=up, `1`=right, `2`=down,
/// `3`=left). Shared by the `step` builtin (one call per script-visible
/// step) and `q_learning`/`sarsa`'s own training loop (many calls per
/// episode) so both go through identical dynamics — no risk of the
/// trained policy being evaluated against subtly different rules than it
/// was trained on. Moving off the grid edge clamps back in place (a
/// no-op move), not a wraparound and not an error — the standard
/// gridworld convention.
fn gridworld_transition(env: &ModelHandle, state: usize, action: i64) -> R<(usize, f64, bool)> {
    let n = env.field("n").and_then(|v| v.as_num().ok()).ok_or_else(|| EvalError {
        msg: "step: malformed gridworld_env (missing `n`)".into(),
    })? as usize;
    let n_states = n * n;
    if state >= n_states {
        return e(format!("step: state {state} is out of range for a {n}x{n} grid (0..{})", n_states - 1));
    }
    let goal = env.field("goal").and_then(|v| v.as_num().ok()).unwrap_or((n_states - 1) as f64) as usize;
    let step_reward = env.field("step_reward").and_then(|v| v.as_num().ok()).unwrap_or(-1.0);
    let goal_reward = env.field("goal_reward").and_then(|v| v.as_num().ok()).unwrap_or(10.0);
    let row = (state / n) as i64;
    let col = (state % n) as i64;
    let (dr, dc) = match action {
        0 => (-1, 0),
        1 => (0, 1),
        2 => (1, 0),
        3 => (0, -1),
        other => return e(format!("step: action must be 0..3 (up/right/down/left), got {other}")),
    };
    let nr = (row + dr).clamp(0, n as i64 - 1);
    let nc = (col + dc).clamp(0, n as i64 - 1);
    let next_state = (nr as usize) * n + (nc as usize);
    let done = next_state == goal;
    let reward = if done { goal_reward } else { step_reward };
    Ok((next_state, reward, done))
}

/// `argmax_a Q[state, a]`, ties broken toward the lowest action index
/// (deterministic — matches this codebase's existing "ties go to the
/// first occurrence" convention, e.g. `kmeans`'s own nearest-centroid
/// tie-break).
fn greedy_action(q: &Matrix, state: usize) -> usize {
    let mut best_a = 0usize;
    let mut best_v = q.get(state, 0).unwrap_or(f64::NEG_INFINITY);
    for a in 1..q.cols() {
        let v = q.get(state, a).unwrap_or(f64::NEG_INFINITY);
        if v > best_v {
            best_v = v;
            best_a = a;
        }
    }
    best_a
}

/// `max_a Q[state, a]` — the value of `greedy_action`'s pick, the
/// bootstrap target `q_learning`'s off-policy update needs.
fn greedy_action_value(q: &Matrix, state: usize) -> f64 {
    q.get(state, greedy_action(q, state)).unwrap_or(0.0)
}

/// Epsilon-greedy action selection: with probability `epsilon`, a
/// uniformly random action (exploration); otherwise the current greedy
/// action (exploitation) — the standard tabular-RL behavior policy, used
/// by both `q_learning` and `sarsa`.
fn epsilon_greedy_action(q: &Matrix, state: usize, epsilon: f64, rng: &mut Rng) -> usize {
    if rng.uniform() < epsilon {
        rng.randi(0, q.cols() as i64 - 1) as usize
    } else {
        greedy_action(q, state)
    }
}

// ---- feature scaling (`normalize`/`standardize`/`robust_scale`/
// `quantile_normalize`, `fit_scaler`/`.transform`/`.inverse_transform`) ----
//
// `qu_interp::scaler` holds the pure per-column math; everything here is
// `Value`-shape plumbing: a `Mat` scales **per column** (rows are samples,
// columns are features — see `scaler`'s own doc comment for why), a plain
// `Vec`/`Signal`/scalar scales as one feature, and a `Table` scales each
// numeric column independently (text columns pass through unchanged — same
// "no string-vector `Value` type yet" limit `corr_heatmap`/`eda` already
// live with elsewhere in this file).

/// Fits and applies `method` to `x` in one step — the one-shot verbs
/// (`normalize`="minmax", `standardize`="standard", `robust_scale`=
/// "robust", `quantile_normalize`="quantile") all funnel through this.
/// Fitting fresh on `x` every call, by design: these verbs have no "reuse
/// on different data" story (that's what `fit_scaler` is for), so there is
/// no fitted state worth keeping around afterward.
fn scale_value_one_shot(method: &str, x: &Value) -> R<Value> {
    match x {
        Value::Num(n) => {
            let p = scaler::fit_column(method, std::slice::from_ref(n))?;
            Ok(Value::Num(scaler::transform_column(&p, std::slice::from_ref(n))[0]))
        }
        Value::Bool(b) => {
            let n = if *b { 1.0 } else { 0.0 };
            let p = scaler::fit_column(method, &[n])?;
            Ok(Value::Num(scaler::transform_column(&p, &[n])[0]))
        }
        Value::Vec(xs) => {
            let p = scaler::fit_column(method, xs)?;
            Ok(Value::Vec(Arc::new(scaler::transform_column(&p, xs))))
        }
        Value::Signal(xs, fs, sm) => {
            let p = scaler::fit_column(method, xs)?;
            // Standardised/normalised values are dimensionless scores, not
            // the physical quantity that went in -- the axis survives, the
            // unit and the calibration do not.
            Ok(Value::Signal(
                Arc::new(scaler::transform_column(&p, xs)),
                *fs,
                Arc::new(sm.axis_only()),
            ))
        }
        Value::Mat(m) => {
            let (rows, cols) = m.shape();
            let mut data = vec![0.0; rows * cols];
            for c in 0..cols {
                let col = m.col_vec(c).map_err(|se| EvalError { msg: se.to_string() })?;
                let p = scaler::fit_column(method, &col)?;
                let out = scaler::transform_column(&p, &col);
                data[c * rows..(c + 1) * rows].copy_from_slice(&out);
            }
            Ok(mat_value(Matrix::from_col_major(rows, cols, data)))
        }
        Value::Table(t) => {
            let mut columns = Vec::with_capacity(t.ncols());
            for name in t.column_names() {
                match t.col(name).expect("column_names only lists columns that exist") {
                    Column::Num(v) => {
                        let p = scaler::fit_column(method, v)?;
                        columns.push((name.to_string(), Column::Num(scaler::transform_column(&p, v))));
                    }
                    Column::Str(v) => columns.push((name.to_string(), Column::Str(v.clone()))),
                }
            }
            Ok(Value::Table(Arc::new(Table::from_columns(columns).map_err(|msg| EvalError { msg })?)))
        }
        other => e(format!(
            "expected a Vec/Mat/Signal/Table/number, found {}",
            other.type_name()
        )),
    }
}

/// Rebuilds column `c`'s `ColumnParams` from a fitted `"scaler"` model's own
/// fields — the inverse of what `fit_scaler` below packs into them. `d`
/// (the number of fitted feature columns) is read alongside so callers can
/// validate `newX`'s own column count before indexing.
fn scaler_column_params(m: &ModelHandle, c: usize) -> R<ColumnParams> {
    let method = match m.field("method") {
        Some(Value::Str(s)) => s.as_str(),
        _ => return e("scaler model is missing its `method` field"),
    };
    match method {
        "standard" => {
            let mean = scaler_field_vec(m, "mean")?;
            let std = scaler_field_vec(m, "std")?;
            Ok(ColumnParams::Standard { mean: mean[c], std: std[c] })
        }
        "minmax" => {
            let min = scaler_field_vec(m, "min")?;
            let max = scaler_field_vec(m, "max")?;
            Ok(ColumnParams::MinMax { min: min[c], max: max[c] })
        }
        "robust" => {
            let median = scaler_field_vec(m, "median")?;
            let iqr = scaler_field_vec(m, "iqr")?;
            Ok(ColumnParams::Robust { median: median[c], iqr: iqr[c] })
        }
        "quantile" => match m.field("reference") {
            Some(Value::Mat(reference)) => {
                let col = reference.col_vec(c).map_err(|se| EvalError { msg: se.to_string() })?;
                Ok(ColumnParams::Quantile { reference: col })
            }
            _ => e("scaler model is missing its `reference` field"),
        },
        other => e(format!("scaler model has an unrecognized method `{other}`")),
    }
}

fn scaler_field_vec(m: &ModelHandle, name: &str) -> R<Arc<Vec<f64>>> {
    match m.field(name) {
        Some(Value::Vec(v)) => Ok(v.clone()),
        _ => e(format!("scaler model is missing its `{name}` field")),
    }
}

/// Shared by `optimizer_step`/`train_loop` (`sgd`/`adam`): reads a
/// numeric field off an optimizer's own `Value::Model` state. Free
/// functions rather than the local closures an earlier draft used, since
/// `train_loop` needs the exact same field access from a different match
/// arm — a closure defined inside `optimizer_step`'s own block can't be
/// named from there.
fn field_num(m: &ModelHandle, name: &str) -> R<f64> {
    m.field(name)
        .and_then(|v| v.as_num().ok())
        .ok_or_else(|| EvalError { msg: format!("optimizer_step: missing field `{}`", name) })
}

/// `optimizer_step`/`train_loop`'s vector-field counterpart to
/// [`field_num`] — see its own doc comment.
fn field_vec(m: &ModelHandle, name: &str) -> R<Arc<Vec<f64>>> {
    match m.field(name) {
        Some(Value::Vec(v)) => Ok(v.clone()),
        _ => e(format!("optimizer_step: missing field `{}`", name)),
    }
}

// ---- Multi-param (`List`-of-tensors) optimizer support (2026-08-26) ----
// `sgd`/`adam`/`optimizer_step`/`train_loop` used to accept only ONE flat
// scalar/vector/matrix parameter per optimizer `Model` (see BACKLOG.md's
// "found while building the GRU layer" entry) — every multi-layer example
// (`sequential_fit`, the GRU/CNN training code) worked around this with a
// hand-written per-tensor update loop instead. The three helpers below are
// the shared arithmetic core for the NEW list-of-tensors path: extracting
// a flat buffer from one already-untensored param value, and applying one
// in-place SGD/Adam update to one flat buffer. `optimizer_step`'s and
// `train_loop`'s own list-mode branches (`optimizer_step_sgd_list`/
// `optimizer_step_adam_list`/`train_loop_list`, further down) call these
// once per list element; `sequential_fit`'s own per-leaf update (see its
// doc comment) now calls the SAME two update functions too, so the model
// zoo's training code and the `sgd`/`adam` builtins can never drift apart
// on the actual update formula again.

/// Per-tensor flat buffer extraction shared by `sgd`/`adam`'s single- and
/// list-of-tensors construction paths — `v` must already be untensored
/// (a bare scalar/vector/matrix, never a `List`: nested lists of tensors
/// aren't supported, matching `eval_grad`'s own one-level-of-`List` shape).
fn optimizer_param_flat(v: &Value) -> R<Arc<Vec<f64>>> {
    match v {
        Value::Vec(v) => Ok(v.clone()),
        Value::Num(n) => Ok(Arc::new(vec![*n])),
        Value::Mat(m) => Ok(Arc::new(m.as_slice().to_vec())),
        other => e(format!("optimizer: params must be scalar, vector, or matrix, found {}", other.type_name())),
    }
}

/// In-place SGD update, `param[i] -= lr * grad[i]` — the exact formula
/// `optimizer_step`'s pre-existing single-tensor `"sgd"` arm already uses
/// inline; factored out so the new list-of-tensors paths (and
/// `sequential_fit`'s per-leaf update) can't silently diverge from it.
fn sgd_update_inplace(param: &mut [f64], grad: &[f64], lr: f64) -> R<()> {
    if grad.len() != param.len() {
        return e(format!(
            "sgd: gradient shape ({}) != params ({})",
            grad.len(), param.len()
        ));
    }
    for i in 0..param.len() {
        param[i] -= lr * grad[i];
    }
    Ok(())
}

/// In-place bias-corrected Adam update for one tensor's flat buffers,
/// given the step's `1 - beta1^t`/`1 - beta2^t` denominators pre-computed
/// ONCE per optimizer step (shared across every tensor in a list-of-
/// tensors optimizer that all take their step together, not recomputed
/// per-tensor) — the exact formula `optimizer_step`'s pre-existing
/// single-tensor `"adam"` arm already uses inline, factored out for the
/// same reason as [`sgd_update_inplace`].
fn adam_update_inplace(
    param: &mut [f64], m: &mut [f64], v: &mut [f64], grad: &[f64],
    lr: f64, beta1: f64, beta2: f64, eps: f64,
    one_minus_beta1: f64, one_minus_beta2: f64,
    one_minus_beta1_t: f64, one_minus_beta2_t: f64,
) -> R<()> {
    let n = param.len();
    if grad.len() != n || m.len() != n || v.len() != n {
        return e("adam: shape mismatch");
    }
    for i in 0..n {
        m[i] = beta1 * m[i] + one_minus_beta1 * grad[i];
        v[i] = beta2 * v[i] + one_minus_beta2 * grad[i] * grad[i];
        let mc = m[i] / one_minus_beta1_t;
        let vc = v[i] / one_minus_beta2_t;
        param[i] -= lr * mc / (vc.sqrt() + eps);
    }
    Ok(())
}

/// In-place RMSprop update for one tensor's flat buffers: a single
/// per-parameter running average of squared gradients (`v`), no bias
/// correction — the exact formula `optimizer_step`'s `"rmsprop"` arm and
/// `sequential_fit`'s per-leaf RMSprop branch both use, factored out for
/// the same reason as [`sgd_update_inplace`]/[`adam_update_inplace`]
/// (2026-08-26).
fn rmsprop_update_inplace(param: &mut [f64], v: &mut [f64], grad: &[f64], lr: f64, decay: f64, eps: f64) -> R<()> {
    let n = param.len();
    if grad.len() != n || v.len() != n {
        return e("rmsprop: shape mismatch");
    }
    for i in 0..n {
        v[i] = decay * v[i] + (1.0 - decay) * grad[i] * grad[i];
        param[i] -= lr * grad[i] / (v[i].sqrt() + eps);
    }
    Ok(())
}

/// In-place Adamax update for one tensor's flat buffers: `m` is Adam's own
/// bias-corrected first moment, `u` is the (unbiased-by-construction)
/// infinity-norm running max `max(beta2*u, |grad|)` — the exact formula
/// `optimizer_step`'s `"adamax"` arm and `sequential_fit`'s per-leaf
/// Adamax branch both use, factored out for the same reason as
/// [`adam_update_inplace`] (2026-08-26).
fn adamax_update_inplace(
    param: &mut [f64], m: &mut [f64], u: &mut [f64], grad: &[f64],
    lr: f64, beta1: f64, beta2: f64, eps: f64,
    one_minus_beta1: f64, one_minus_beta1_t: f64,
) -> R<()> {
    let n = param.len();
    if grad.len() != n || m.len() != n || u.len() != n {
        return e("adamax: shape mismatch");
    }
    for i in 0..n {
        m[i] = beta1 * m[i] + one_minus_beta1 * grad[i];
        u[i] = (beta2 * u[i]).max(grad[i].abs());
        param[i] -= (lr / one_minus_beta1_t) * m[i] / (u[i] + eps);
    }
    Ok(())
}

/// In-place practical Nesterov-SGD update for one tensor's flat buffers —
/// the SAME Keras/PyTorch `SGD(nesterov=True)` reformulation
/// `nesterov_sgd`'s own construction arm documents: `velocity` gets the
/// ordinary momentum update, but the PARAMETER step re-applies the
/// momentum term on top of the fresh velocity, giving the lookahead
/// correction from a single gradient evaluation at the CURRENT param (no
/// second forward/backward pass at `param + momentum*velocity` needed)
/// (2026-08-26).
fn nesterov_sgd_update_inplace(param: &mut [f64], velocity: &mut [f64], grad: &[f64], lr: f64, momentum: f64) -> R<()> {
    let n = param.len();
    if grad.len() != n || velocity.len() != n {
        return e("nesterov_sgd: shape mismatch");
    }
    for i in 0..n {
        velocity[i] = momentum * velocity[i] - lr * grad[i];
        param[i] += momentum * velocity[i] - lr * grad[i];
    }
    Ok(())
}

/// In-place Adagrad update for one tensor's flat buffers: `g_sq`
/// accumulates the RAW (never decayed) sum of squared gradients — unlike
/// RMSprop's EMA, this only grows, monotonically shrinking the effective
/// per-parameter lr (2026-08-26).
fn adagrad_update_inplace(param: &mut [f64], g_sq: &mut [f64], grad: &[f64], lr: f64, eps: f64) -> R<()> {
    let n = param.len();
    if grad.len() != n || g_sq.len() != n {
        return e("adagrad: shape mismatch");
    }
    for i in 0..n {
        g_sq[i] += grad[i] * grad[i];
        param[i] -= lr * grad[i] / (g_sq[i].sqrt() + eps);
    }
    Ok(())
}

/// In-place Nadam update for one tensor's flat buffers (Dozat 2016): `m`/
/// `v` are the SAME moment EMAs plain Adam keeps, and `v`'s bias
/// correction is identical too (`v_hat = v / (1 - beta2^t)`). The Nesterov
/// part is entirely in `m`'s bias-corrected estimate: instead of
/// `m_hat = m / (1 - beta1^t)`, Nadam mixes in the CURRENT gradient's own
/// bias-corrected estimate scaled by `(1-beta1)`, using `t+1`'s bias
/// correction on the momentum term (a "lookahead" to the momentum this
/// step's update would have accumulated by the NEXT step):
///   `m_hat = beta1*m/(1 - beta1^(t+1)) + (1-beta1)*grad/(1 - beta1^t)`
/// (2026-08-26).
fn nadam_update_inplace(
    param: &mut [f64], m: &mut [f64], v: &mut [f64], grad: &[f64],
    lr: f64, beta1: f64, beta2: f64, eps: f64,
    one_minus_beta1: f64, one_minus_beta2: f64,
    one_minus_beta1_t: f64, one_minus_beta1_t1: f64, one_minus_beta2_t: f64,
) -> R<()> {
    let n = param.len();
    if grad.len() != n || m.len() != n || v.len() != n {
        return e("nadam: shape mismatch");
    }
    for i in 0..n {
        m[i] = beta1 * m[i] + one_minus_beta1 * grad[i];
        v[i] = beta2 * v[i] + one_minus_beta2 * grad[i] * grad[i];
        let m_hat = beta1 * m[i] / one_minus_beta1_t1 + one_minus_beta1 * grad[i] / one_minus_beta1_t;
        let v_hat = v[i] / one_minus_beta2_t;
        param[i] -= lr * m_hat / (v_hat.sqrt() + eps);
    }
    Ok(())
}

/// In-place AdamW update for one tensor's flat buffers (Loshchilov &
/// Hutter 2019): the `m`/`v` moments and bias-corrected Adam step are
/// byte-for-byte the SAME formula [`adam_update_inplace`] uses — weight
/// decay never touches the gradient or the moments. The DECOUPLED decay
/// term (`-lr*weight_decay*param`, using the param's value BEFORE this
/// step's Adam update, matching the original paper's Algorithm 2) is
/// subtracted as a separate line, not folded into `grad` the way plain L2
/// regularization would be — that's the entire distinction from "Adam with
/// L2 regularization" this builtin exists to get right (2026-08-26).
fn adamw_update_inplace(
    param: &mut [f64], m: &mut [f64], v: &mut [f64], grad: &[f64],
    lr: f64, beta1: f64, beta2: f64, eps: f64, weight_decay: f64,
    one_minus_beta1: f64, one_minus_beta2: f64,
    one_minus_beta1_t: f64, one_minus_beta2_t: f64,
) -> R<()> {
    let n = param.len();
    if grad.len() != n || m.len() != n || v.len() != n {
        return e("adamw: shape mismatch");
    }
    for i in 0..n {
        m[i] = beta1 * m[i] + one_minus_beta1 * grad[i];
        v[i] = beta2 * v[i] + one_minus_beta2 * grad[i] * grad[i];
        let m_hat = m[i] / one_minus_beta1_t;
        let v_hat = v[i] / one_minus_beta2_t;
        let old_param = param[i];
        param[i] -= lr * m_hat / (v_hat.sqrt() + eps);
        param[i] -= lr * weight_decay * old_param;
    }
    Ok(())
}

/// In-place Adadelta update for one tensor's flat buffers (Zeiler 2012):
/// NO `lr` parameter at all — `eg2` (mean squared gradient) and `edx2`
/// (mean squared UPDATE, i.e. the previous step's own `delta`) are both
/// running averages decayed by `rho`, and their ratio self-calibrates the
/// step size (`delta = -sqrt(edx2+eps)/sqrt(eg2+eps) * grad`) instead of a
/// manually tuned lr. `edx2` is updated from `delta` AFTER it's computed
/// (using THIS step's own delta, not the previous one) — the defining
/// "no lr needed" property of the method (2026-08-26).
fn adadelta_update_inplace(param: &mut [f64], eg2: &mut [f64], edx2: &mut [f64], grad: &[f64], rho: f64, eps: f64) -> R<()> {
    let n = param.len();
    if grad.len() != n || eg2.len() != n || edx2.len() != n {
        return e("adadelta: shape mismatch");
    }
    let one_minus_rho = 1.0 - rho;
    for i in 0..n {
        eg2[i] = rho * eg2[i] + one_minus_rho * grad[i] * grad[i];
        let delta = -(edx2[i] + eps).sqrt() / (eg2[i] + eps).sqrt() * grad[i];
        param[i] += delta;
        edx2[i] = rho * edx2[i] + one_minus_rho * delta * delta;
    }
    Ok(())
}

/// `optimizer_step`'s list-of-tensors `"sgd"` branch — mirrors the
/// single-tensor arm right above its own call site in `optimizer_step`
/// field-for-field (same `params`-field-as-shape-template reconstruction,
/// same `_param_node` tape write-back, see that arm's own doc comment for
/// why), just once per list element via [`sgd_update_inplace`].
fn optimizer_step_sgd_list(interp: &mut Interp, opt: Arc<ModelHandle>, grads: &Value, lr: f64) -> R<Value> {
    let param_nodes = field_vec(&opt, "_param_node")?;
    let params_list = match opt.field("_params") {
        Some(Value::List(l)) => l.clone(),
        _ => return e("optimizer_step: optimizer missing `_params` list"),
    };
    let templates = match opt.field("params") {
        Some(Value::List(l)) => l.clone(),
        _ => return e("optimizer_step: optimizer missing `params` list"),
    };
    let grads_list = match grads {
        Value::List(items) => items.clone(),
        other => return e(format!(
            "optimizer_step SGD: expected a list of gradients for a list-of-tensors optimizer, found {}",
            other.type_name()
        )),
    };
    if grads_list.len() != params_list.len() || templates.len() != params_list.len() {
        return e(format!(
            "optimizer_step SGD: gradient list length ({}) != params list length ({})",
            grads_list.len(), params_list.len()
        ));
    }
    let mut new_params = Vec::with_capacity(params_list.len());
    for i in 0..params_list.len() {
        let mut buf = match &params_list[i] {
            Value::Vec(v) => v.clone(),
            other => return e(format!("optimizer_step: `_params` list entry must be a Vec, found {}", other.type_name())),
        };
        let grad_flat = to_vec(&grads_list[i])?;
        let buf_mut: &mut Vec<f64> = Arc::make_mut(&mut buf);
        sgd_update_inplace(buf_mut, &grad_flat, lr)?;
        let (template, _) = untensor(templates[i].clone());
        let new_val = flat_to_value(&template, buf.as_slice())?;
        if let Some(&node_f) = param_nodes.get(i) {
            if let Some(entry) = interp.tape.get_mut(node_f as usize) {
                entry.result = new_val;
            }
        }
        new_params.push(Value::Vec(buf));
    }
    let stages = opt.stages.clone();
    let mut fields = Arc::try_unwrap(opt).map(|m| m.fields).unwrap_or_else(|arc| arc.fields.clone());
    let mut new_params_opt = Some(Value::List(Arc::new(new_params)));
    for f in &mut fields {
        if f.0 == "_params" {
            if let Some(v) = new_params_opt.take() {
                f.1 = v;
            }
        }
    }
    Ok(Value::Model(Arc::new(ModelHandle { kind: "sgd".to_string(), fields, stages })))
}

/// `optimizer_step`'s list-of-tensors `"adam"` branch — same relationship
/// to the single-tensor `"adam"` arm as [`optimizer_step_sgd_list`] has to
/// `"sgd"`'s, via [`adam_update_inplace`]. The bias-correction step `t` is
/// shared across every tensor in the list (one optimizer step per call,
/// matching `sequential_fit`'s own established convention for several
/// tensors sharing one optimizer).
fn optimizer_step_adam_list(interp: &mut Interp, opt: Arc<ModelHandle>, grads: &Value) -> R<Value> {
    let lr = field_num(&opt, "lr")?;
    let beta1 = field_num(&opt, "beta1")?;
    let beta2 = field_num(&opt, "beta2")?;
    let eps = field_num(&opt, "eps")?;
    let param_nodes = field_vec(&opt, "_param_node")?;
    let t = field_num(&opt, "t")? + 1.0;
    let beta1_t = beta1.powi(t as i32);
    let beta2_t = beta2.powi(t as i32);
    let one_minus_beta1_t = 1.0 - beta1_t;
    let one_minus_beta2_t = 1.0 - beta2_t;
    let one_minus_beta1 = 1.0 - beta1;
    let one_minus_beta2 = 1.0 - beta2;
    let params_list = match opt.field("_params") {
        Some(Value::List(l)) => l.clone(),
        _ => return e("optimizer_step: optimizer missing `_params` list"),
    };
    let m_list = match opt.field("m") {
        Some(Value::List(l)) => l.clone(),
        _ => return e("optimizer_step: optimizer missing `m` list"),
    };
    let v_list = match opt.field("v") {
        Some(Value::List(l)) => l.clone(),
        _ => return e("optimizer_step: optimizer missing `v` list"),
    };
    let templates = match opt.field("params") {
        Some(Value::List(l)) => l.clone(),
        _ => return e("optimizer_step: optimizer missing `params` list"),
    };
    let grads_list = match grads {
        Value::List(items) => items.clone(),
        other => return e(format!(
            "optimizer_step Adam: expected a list of gradients for a list-of-tensors optimizer, found {}",
            other.type_name()
        )),
    };
    if grads_list.len() != params_list.len() || m_list.len() != params_list.len()
        || v_list.len() != params_list.len() || templates.len() != params_list.len()
    {
        return e("optimizer_step Adam: shape mismatch");
    }
    let mut new_params = Vec::with_capacity(params_list.len());
    let mut new_m = Vec::with_capacity(params_list.len());
    let mut new_v = Vec::with_capacity(params_list.len());
    for i in 0..params_list.len() {
        let mut p_buf = match &params_list[i] {
            Value::Vec(v) => v.clone(),
            _ => return e("optimizer_step: `_params` list entry must be a Vec"),
        };
        let mut m_buf = match &m_list[i] {
            Value::Vec(v) => v.clone(),
            _ => return e("optimizer_step: `m` list entry must be a Vec"),
        };
        let mut v_buf = match &v_list[i] {
            Value::Vec(v) => v.clone(),
            _ => return e("optimizer_step: `v` list entry must be a Vec"),
        };
        let grad_flat = to_vec(&grads_list[i])?;
        let p_mut: &mut Vec<f64> = Arc::make_mut(&mut p_buf);
        let m_mut: &mut Vec<f64> = Arc::make_mut(&mut m_buf);
        let v_mut: &mut Vec<f64> = Arc::make_mut(&mut v_buf);
        adam_update_inplace(
            p_mut, m_mut, v_mut, &grad_flat,
            lr, beta1, beta2, eps, one_minus_beta1, one_minus_beta2, one_minus_beta1_t, one_minus_beta2_t,
        )?;
        let (template, _) = untensor(templates[i].clone());
        let new_val = flat_to_value(&template, p_buf.as_slice())?;
        if let Some(&node_f) = param_nodes.get(i) {
            if let Some(entry) = interp.tape.get_mut(node_f as usize) {
                entry.result = new_val;
            }
        }
        new_params.push(Value::Vec(p_buf));
        new_m.push(Value::Vec(m_buf));
        new_v.push(Value::Vec(v_buf));
    }
    let stages = opt.stages.clone();
    let mut fields = Arc::try_unwrap(opt).map(|m| m.fields).unwrap_or_else(|arc| arc.fields.clone());
    let mut np = Some(Value::List(Arc::new(new_params)));
    let mut nm = Some(Value::List(Arc::new(new_m)));
    let mut nv = Some(Value::List(Arc::new(new_v)));
    for f in &mut fields {
        match f.0.as_str() {
            "_params" => { if let Some(val) = np.take() { f.1 = val; } }
            "m" => { if let Some(val) = nm.take() { f.1 = val; } }
            "v" => { if let Some(val) = nv.take() { f.1 = val; } }
            "t" => f.1 = Value::Num(t),
            _ => {}
        }
    }
    Ok(Value::Model(Arc::new(ModelHandle { kind: "adam".to_string(), fields, stages })))
}

/// `train_loop`'s list-of-tensors branch — mirrors the single-tensor loop
/// in `"train_loop"` field-for-field (same tape-clear-per-epoch reasoning,
/// same inline Rust update math via [`sgd_update_inplace`]/
/// [`adam_update_inplace`], no `call_builtin` dispatch per epoch, same
/// final `self.var_set` + `Value::List` of per-epoch losses return), just
/// walking a `List` of independent flat buffers instead of one. `loss_fn`
/// is called with exactly ONE argument each epoch: a fresh `Value::List`
/// of tracked tensors (never a bare `Value::Tensor`) — a script
/// destructures it itself (`params[0]`, `params[1]`, ...). `eval_grad`'s
/// own pre-existing `Value::List` form (see its doc comment) needs no
/// changes at all to differentiate w.r.t. this list: it already returns a
/// matching `List` of gradients.
fn train_loop_list(
    interp: &mut Interp, loss_fn: &str, mut opt: Arc<ModelHandle>, opt_name: &str,
    epochs: usize, kind: String, lr: f64, adam_beta1: f64, adam_beta2: f64, adam_eps: f64,
) -> R<Value> {
    let templates: Vec<Value> = match opt.field("params") {
        Some(Value::List(l)) => l.iter().map(|t| untensor(t.clone()).0).collect(),
        _ => return e("train_loop: optimizer missing `params` list"),
    };
    let mut losses = Vec::with_capacity(epochs);
    for ep in 0..epochs {
        interp.tape.clear();
        let params_list = match opt.field("_params") {
            Some(Value::List(l)) => l.clone(),
            _ => return e("train_loop: missing _params"),
        };
        if params_list.len() != templates.len() {
            return e("train_loop: internal error, _params/params list length mismatch");
        }
        let mut current: Vec<Value> = Vec::with_capacity(params_list.len());
        for (i, p) in params_list.iter().enumerate() {
            let flat = match p {
                Value::Vec(v) => v.as_slice(),
                other => return e(format!("train_loop: `_params` list entry must be a Vec, found {}", other.type_name())),
            };
            let plain = flat_to_value(&templates[i], flat)?;
            let leaf_node = interp.tape.len();
            interp.tape.push(TapeEntry {
                op: "leaf".to_string(),
                inputs: [None, None],
                input_vals: [Value::Nothing, Value::Nothing],
                result: plain.clone(),
            });
            current.push(Value::Tensor(Arc::new(TensorState { value: Box::new(plain), node: leaf_node })));
        }
        let current_params = Value::List(Arc::new(current));
        let loss = interp.apply(loss_fn, vec![current_params.clone()], Vec::new())?;
        let loss_num = match &loss {
            Value::Tensor(t) => {
                let grads = interp.eval_grad(loss.clone(), current_params.clone())?;
                let Value::List(grads) = grads else {
                    return e("train_loop: internal error, grad() did not return a list");
                };
                let params_list = match opt.field("_params") {
                    Some(Value::List(l)) => l.clone(),
                    _ => return e("train_loop: missing _params"),
                };
                if grads.len() != params_list.len() {
                    return e("train_loop: internal error, gradient list length != params list length");
                }
                match kind.as_str() {
                    "sgd" => {
                        let mut new_params = Vec::with_capacity(params_list.len());
                        for (i, p) in params_list.iter().enumerate() {
                            let mut buf = match p {
                                Value::Vec(v) => v.clone(),
                                _ => return e("train_loop: `_params` list entry must be a Vec"),
                            };
                            let grad_flat = to_vec(&grads[i])?;
                            let buf_mut: &mut Vec<f64> = Arc::make_mut(&mut buf);
                            sgd_update_inplace(buf_mut, &grad_flat, lr)?;
                            new_params.push(Value::Vec(buf));
                        }
                        let mut np = Some(Value::List(Arc::new(new_params)));
                        for f in Arc::make_mut(&mut opt).fields.iter_mut() {
                            if f.0 == "_params" {
                                if let Some(v) = np.take() { f.1 = v; }
                            }
                        }
                    }
                    "adam" => {
                        let t_step = ep as f64 + 1.0;
                        let beta1_t = adam_beta1.powi(t_step as i32);
                        let beta2_t = adam_beta2.powi(t_step as i32);
                        let one_minus_beta1_t = 1.0 - beta1_t;
                        let one_minus_beta2_t = 1.0 - beta2_t;
                        let one_minus_beta1 = 1.0 - adam_beta1;
                        let one_minus_beta2 = 1.0 - adam_beta2;
                        let m_list = match opt.field("m") {
                            Some(Value::List(l)) => l.clone(),
                            _ => return e("train_loop: missing m"),
                        };
                        let v_list = match opt.field("v") {
                            Some(Value::List(l)) => l.clone(),
                            _ => return e("train_loop: missing v"),
                        };
                        let mut new_params = Vec::with_capacity(params_list.len());
                        let mut new_m = Vec::with_capacity(params_list.len());
                        let mut new_v = Vec::with_capacity(params_list.len());
                        for i in 0..params_list.len() {
                            let mut p_buf = match &params_list[i] {
                                Value::Vec(v) => v.clone(),
                                _ => return e("train_loop: `_params` list entry must be a Vec"),
                            };
                            let mut m_buf = match &m_list[i] {
                                Value::Vec(v) => v.clone(),
                                _ => return e("train_loop: `m` list entry must be a Vec"),
                            };
                            let mut v_buf = match &v_list[i] {
                                Value::Vec(v) => v.clone(),
                                _ => return e("train_loop: `v` list entry must be a Vec"),
                            };
                            let grad_flat = to_vec(&grads[i])?;
                            let p_mut: &mut Vec<f64> = Arc::make_mut(&mut p_buf);
                            let m_mut: &mut Vec<f64> = Arc::make_mut(&mut m_buf);
                            let v_mut: &mut Vec<f64> = Arc::make_mut(&mut v_buf);
                            adam_update_inplace(
                                p_mut, m_mut, v_mut, &grad_flat,
                                lr, adam_beta1, adam_beta2, adam_eps,
                                one_minus_beta1, one_minus_beta2, one_minus_beta1_t, one_minus_beta2_t,
                            )?;
                            new_params.push(Value::Vec(p_buf));
                            new_m.push(Value::Vec(m_buf));
                            new_v.push(Value::Vec(v_buf));
                        }
                        let mut np = Some(Value::List(Arc::new(new_params)));
                        let mut nm = Some(Value::List(Arc::new(new_m)));
                        let mut nv = Some(Value::List(Arc::new(new_v)));
                        for f in Arc::make_mut(&mut opt).fields.iter_mut() {
                            match f.0.as_str() {
                                "_params" => { if let Some(v) = np.take() { f.1 = v; } }
                                "m" => { if let Some(v) = nm.take() { f.1 = v; } }
                                "v" => { if let Some(v) = nv.take() { f.1 = v; } }
                                "t" => f.1 = Value::Num(t_step),
                                _ => {}
                            }
                        }
                    }
                    _ => return e(format!("train_loop: unknown optimizer kind `{kind}`")),
                }
                to_vec(&t.value)?.first().copied().unwrap_or(0.0)
            }
            _ => return e("train_loop: loss must be a tracked tensor. Ensure params are wrapped with param() and flow through the loss computation."),
        };
        losses.push(Value::Num(loss_num));
    }
    // Refresh `params` to the final trained value, same as the single-
    // tensor path's own tail does — a `List` of the per-element final
    // plain values (via each element's own template), not tensors.
    let final_list = match opt.field("_params") {
        Some(Value::List(l)) => l.clone(),
        _ => return e("train_loop: missing _params"),
    };
    let mut final_params = Vec::with_capacity(final_list.len());
    for (i, p) in final_list.iter().enumerate() {
        let flat = match p {
            Value::Vec(v) => v.as_slice(),
            _ => return e("train_loop: `_params` list entry must be a Vec"),
        };
        final_params.push(flat_to_value(&templates[i], flat)?);
    }
    let mut final_opt = Some(Value::List(Arc::new(final_params)));
    for f in Arc::make_mut(&mut opt).fields.iter_mut() {
        if f.0 == "params" {
            if let Some(v) = final_opt.take() {
                f.1 = v;
            }
        }
    }
    interp.var_set(opt_name, Value::Model(opt));
    Ok(Value::List(Arc::new(losses)))
}

/// The number of feature columns a fitted `"scaler"` model was fit on —
/// `newX` passed to `.transform`/`.inverse_transform` must match this
/// (a plain `Vec`/`Signal`/scalar counts as 1 column, a `Mat`'s own column
/// count otherwise).
fn scaler_num_columns(m: &ModelHandle) -> R<usize> {
    match m.field("method") {
        Some(Value::Str(s)) if s == "standard" => Ok(scaler_field_vec(m, "mean")?.len()),
        Some(Value::Str(s)) if s == "minmax" => Ok(scaler_field_vec(m, "min")?.len()),
        Some(Value::Str(s)) if s == "robust" => Ok(scaler_field_vec(m, "median")?.len()),
        Some(Value::Str(s)) if s == "quantile" => match m.field("reference") {
            Some(Value::Mat(reference)) => Ok(reference.shape().1),
            _ => e("scaler model is missing its `reference` field"),
        },
        Some(Value::Str(other)) => e(format!("scaler model has an unrecognized method `{other}`")),
        _ => e("scaler model is missing its `method` field"),
    }
}

/// Shared by `transform`/`inverse_transform`: applies `per_column` (one of
/// `scaler::transform_column`/`scaler::inverse_transform_column`, wrapped to
/// a common signature) to every feature column of `newX`, using the fitted
/// `m`'s own stored parameters rather than fitting fresh on `newX` — this
/// reuse (fit once on train, apply unchanged to test) is the entire reason
/// `fit_scaler` exists alongside the one-shot verbs.
fn apply_fitted_scaler(m: &ModelHandle, new_x: &Value, per_column: impl Fn(&ColumnParams, &[f64]) -> R<Vec<f64>>) -> R<Value> {
    let d = scaler_num_columns(m)?;
    match new_x {
        Value::Num(n) => {
            if d != 1 {
                return e(format!("scaler: fitted on {d} feature column(s), but got a single number"));
            }
            let p = scaler_column_params(m, 0)?;
            Ok(Value::Num(per_column(&p, std::slice::from_ref(n))?[0]))
        }
        Value::Vec(xs) => {
            if d != 1 {
                return e(format!(
                    "scaler: fitted on {d} feature column(s), but got a plain vector (1 column) — pass a matrix with {d} columns instead"
                ));
            }
            let p = scaler_column_params(m, 0)?;
            Ok(Value::Vec(Arc::new(per_column(&p, xs)?)))
        }
        Value::Signal(xs, fs, sm) => {
            if d != 1 {
                return e(format!("scaler: fitted on {d} feature column(s), but got a single-column signal"));
            }
            let p = scaler_column_params(m, 0)?;
            // As in `scale_value_one_shot`: a scaled score is no longer the
            // input's physical quantity, so only the axis rides along.
            Ok(Value::Signal(
                Arc::new(per_column(&p, xs)?),
                *fs,
                Arc::new(sm.axis_only()),
            ))
        }
        Value::Mat(mat) => {
            let (rows, cols) = mat.shape();
            if cols != d {
                return e(format!("scaler: fitted on {d} feature column(s), but got a matrix with {cols}"));
            }
            let mut data = vec![0.0; rows * cols];
            for c in 0..cols {
                let col = mat.col_vec(c).map_err(|se| EvalError { msg: se.to_string() })?;
                let p = scaler_column_params(m, c)?;
                let out = per_column(&p, &col)?;
                data[c * rows..(c + 1) * rows].copy_from_slice(&out);
            }
            Ok(mat_value(Matrix::from_col_major(rows, cols, data)))
        }
        other => e(format!(
            "scaler: expected a Vec/Mat/Signal/number, found {}",
            other.type_name()
        )),
    }
}

/// Semantic diagnostic shared by every Hz-cutoff filter-design builtin
/// (`butter`/`ellip`/`fir1`): a `cutoff` at or above the Nyquist frequency
/// (`fs/2`) can't be realized by a digital filter (the analog prewarp
/// (`tan(pi*fc/fs)`) blows up at exactly `fs/2` and is meaningless beyond
/// it), so this rejects it up front with the actual numbers involved
/// instead of letting the design either panic or silently produce a
/// nonsensical/numerically unstable filter. Called with every requested
/// cutoff (both edges for `"band"`/`"stop"`).
fn check_cutoff_below_nyquist(fn_name: &str, cutoff: &[f64], fs: f64) -> R<()> {
    let nyquist = fs / 2.0;
    for &c in cutoff {
        if c >= nyquist {
            return e(format!(
                "{fn_name}: cutoff {c} Hz exceeds Nyquist frequency {nyquist} Hz for fs={fs} Hz — cutoff must be below fs/2"
            ));
        }
    }
    Ok(())
}

/// A `Sos`'s coefficients as a matrix, one section per row:
/// `[b0, b1, b2, a1, a2]` — the `"filter"` model's own `sos` field
/// representation.
fn sos_to_matrix(sos: &numeric::filter::Sos) -> Matrix {
    let mut m = Matrix::zeros(sos.sections.len(), 5);
    for (r, bq) in sos.sections.iter().enumerate() {
        let _ = m.set(r, 0, bq.b0);
        let _ = m.set(r, 1, bq.b1);
        let _ = m.set(r, 2, bq.b2);
        let _ = m.set(r, 3, bq.a1);
        let _ = m.set(r, 4, bq.a2);
    }
    m
}

fn matrix_to_sos(m: &Matrix) -> numeric::filter::Sos {
    let sections = (0..m.rows())
        .map(|r| numeric::filter::Biquad {
            b0: m.get(r, 0).unwrap_or(0.0),
            b1: m.get(r, 1).unwrap_or(0.0),
            b2: m.get(r, 2).unwrap_or(0.0),
            a1: m.get(r, 3).unwrap_or(0.0),
            a2: m.get(r, 4).unwrap_or(0.0),
        })
        .collect();
    numeric::filter::Sos { sections }
}

/// Which representation a `"filter"` model uses -- `sos` (IIR, cascaded
/// biquads) or `b` (FIR, plain taps, no feedback at all). Every generic
/// filter function (`sosfilt`/`filtfilt`/`freqz`/`group_delay`/`fvtool`/
/// `filter_init`/`filter_next`/`poles`/`zeros`/`is_stable`/`pzplot`)
/// branches on this rather than assuming IIR -- see `fir1`'s own doc
/// comment for why FIR can't just be squeezed into the `Sos` shape.
enum FilterRepr {
    Iir(numeric::filter::Sos),
    Fir(Vec<f64>),
}

fn filter_repr_from_model(m: &ModelHandle) -> R<FilterRepr> {
    if m.kind != "filter" {
        return e(format!("expected a filter design, got a `{}` model", m.kind));
    }
    if let Some(Value::Mat(sos_mat)) = m.field("sos") {
        return Ok(FilterRepr::Iir(matrix_to_sos(sos_mat)));
    }
    if let Some(b_val) = m.field("b") {
        return Ok(FilterRepr::Fir(to_vec(b_val)?));
    }
    e("filter design is missing both its sos and b fields".to_string())
}

fn filter_repr_from_value(v: &Value) -> R<FilterRepr> {
    let m = as_model(v)?;
    filter_repr_from_model(&m)
}

fn repr_filt(repr: &FilterRepr, x: &[f64]) -> R<Vec<f64>> {
    match repr {
        FilterRepr::Iir(sos) => Ok(numeric::filter::sosfilt(sos, x)),
        FilterRepr::Fir(b) => numeric::filter::fir_filt(b, x).map_err(|ne| EvalError { msg: ne.to_string() }),
    }
}

// ---- shared multirate (sample-rate conversion) filter machinery ----
//
// `resample_to`, `upsample`, `downsample` and `resample_int` all need the
// same thing: one Hamming-windowed linear-phase FIR lowpass, designed and
// applied causally. They go through the two helpers below rather than each
// growing its own copy, so there is exactly ONE place where the window, the
// design call and the application live — and it is the same
// `numeric::filter::fir1` + `numeric::filter::fir_filt` pair the `fir1(...)`
// and `sosfilt(...)` builtins themselves dispatch to, not a parallel
// implementation that could drift from them.

/// Default FIR order for every multirate builtin's anti-alias/interpolation
/// filter. 60 is long enough for a genuinely useful stopband at the ratios
/// people actually resample by, and it keeps the group delay an exact whole
/// number of samples (`order/2 == 30`).
const MULTIRATE_FIR_ORDER: usize = 60;

/// The order actually used for a length-`n` input.
///
/// An FIR filter longer than the signal it is applied to produces nothing
/// but its own startup transient, so a requested order is reduced to the
/// largest EVEN order that still fits (`n - 1` or one less). Even, because
/// an even order has an odd tap count and therefore an exact whole-sample
/// group delay of `order/2` — which is the number every one of these
/// builtins documents and every delay-aligned test subtracts. Returns `0`
/// when the signal is too short for any filter worth designing (`n < 5`),
/// which the callers read as "pass the samples through unfiltered": below
/// about five samples there is no band to protect and no filter that would
/// leave anything but transient behind.
fn multirate_effective_order(requested: usize, n: usize) -> usize {
    if n < 5 {
        return 0;
    }
    let fits = requested.min(n - 1);
    let even = fits - (fits % 2);
    if even < 2 {
        0
    } else {
        even
    }
}

/// Design a Hamming-windowed FIR lowpass of order `order` with the -6 dB
/// cutoff at `cutoff_hz` for a sample rate of `fs_hz`, and apply it
/// causally — exactly what `sosfilt(fir1(order, cutoff_hz, kind="low",
/// fs=fs_hz), x)` does at Qu level, called directly from Rust.
///
/// **Causal, so the result is delayed by `order/2` samples** (linear phase,
/// constant across frequency, by construction of a symmetric FIR). That
/// delay is deliberate and is documented at each call site rather than
/// cancelled here: `fir_filtfilt` would remove it, but at the cost of
/// squaring the magnitude response (double the attenuation, a different
/// filter than the one the caller asked for) and of smearing transients
/// backwards in time, which is not a thing a resampler should do silently.
fn multirate_lowpass(order: usize, cutoff_hz: f64, fs_hz: f64, x: &[f64]) -> R<Vec<f64>> {
    if order == 0 || x.is_empty() {
        return Ok(x.to_vec());
    }
    let window = raised_cosine_window(order + 1, 0.54, 0.46, 0.0);
    let b = numeric::filter::fir1(order, numeric::filter::FilterKind::Low, &[cutoff_hz], fs_hz, &window)
        .map_err(|ne| EvalError { msg: ne.to_string() })?;
    numeric::filter::fir_filt(&b, x).map_err(|ne| EvalError { msg: ne.to_string() })
}

/// Read the shared `order=` keyword argument. Must be a positive EVEN
/// integer, for the whole-sample group delay reason in
/// `multirate_effective_order`'s own comment — an odd order is rejected
/// with a message that says which even orders bracket it, rather than
/// silently rounded (a silently-changed filter order is exactly the kind of
/// "it ran, so it must have done what I asked" outcome these builtins exist
/// to remove from `resample_to`).
fn multirate_order_arg(style: &[(String, Value)], f: &str) -> R<usize> {
    // `style_num_checked`, not `style_num`: the latter maps a wrong-typed
    // value to `None`, which would silently fall back to the default order
    // when someone writes `order="60"`.
    let v = style_num_checked(style, "order", MULTIRATE_FIR_ORDER as f64, f)?;
    if !v.is_finite() || v < 2.0 || v.fract() != 0.0 {
        return e(format!("{f}: order= must be an even integer of at least 2, got {}", fmt_num(v)));
    }
    let n = v as usize;
    if n % 2 != 0 {
        return e(format!(
            "{f}: order= must be even (for an exact whole-sample group delay of order/2), got {n} — use {} or {}",
            n - 1,
            n + 1
        ));
    }
    Ok(n)
}

/// Read the shared `fs=` keyword argument, falling back to the input's own
/// `Fs` when it is a `Signal` and to 1.0 Hz for a plain vector. Only the
/// RATIO of rates matters to any of these filters' designs, so `fs=` never
/// changes the numbers a plain vector comes back with — it only sets the
/// `Fs` the returned `Signal` carries.
fn multirate_fs_arg(style: &[(String, Value)], x_arg: &Value, f: &str) -> R<f64> {
    let fallback = match x_arg {
        Value::Signal(_, fs, _) => *fs,
        _ => 1.0,
    };
    let fs = style_num_checked(style, "fs", fallback, f)?;
    if !(fs > 0.0) || !fs.is_finite() {
        return e(format!("{f}: fs= must be a positive sample rate, got {}", fmt_num(fs)));
    }
    Ok(fs)
}

/// Wrap a multirate result to match the shape of its input: a `Signal` in
/// gives a `Signal` out carrying the NEW rate, a plain `Vec` in gives a
/// plain `Vec` out. Unlike `sosfilt`/`filtfilt`, which preserve `Fs`
/// because filtering does not move samples in time, these builtins change
/// the rate — so the `Fs` that comes out is deliberately not the one that
/// went in.
fn signal_or_vec(xs: Vec<f64>, was_signal: bool, fs: f64) -> Value {
    if was_signal {
        Value::Signal(Arc::new(xs), fs, SigMeta::none())
    } else {
        Value::Vec(Arc::new(xs))
    }
}

/// The integer factor argument (`L`/`M`) shared by `upsample`/`downsample`/
/// `resample_int`: a whole number of at least 1.
fn multirate_factor_arg(args: &[Value], idx: usize, f: &str, name: &str) -> R<usize> {
    let v = arg_get(args, idx).ok_or_else(|| EvalError {
        msg: format!("{f}: needs an integer {name} factor"),
    })?;
    let n = v.as_num().map_err(|_| EvalError {
        msg: format!("{f}: {name} must be a number, got {}", v.type_name()),
    })?;
    if !n.is_finite() || n.fract() != 0.0 || n < 1.0 {
        return e(format!("{f}: {name} must be a whole number of at least 1, got {}", fmt_num(n)));
    }
    Ok(n as usize)
}

fn repr_filtfilt(repr: &FilterRepr, x: &[f64]) -> R<Vec<f64>> {
    match repr {
        FilterRepr::Iir(sos) => Ok(numeric::filter::filtfilt(sos, x)),
        FilterRepr::Fir(b) => numeric::filter::fir_filtfilt(b, x).map_err(|ne| EvalError { msg: ne.to_string() }),
    }
}

fn repr_freqz(repr: &FilterRepr, n: usize) -> Vec<Complex64> {
    match repr {
        FilterRepr::Iir(sos) => numeric::filter::freqz(sos, n),
        FilterRepr::Fir(b) => numeric::filter::fir_freqz(b, n),
    }
}

fn repr_group_delay(repr: &FilterRepr, n: usize) -> Vec<f64> {
    match repr {
        FilterRepr::Iir(sos) => numeric::filter::group_delay(sos, n),
        FilterRepr::Fir(b) => numeric::filter::fir_group_delay(b, n),
    }
}

fn repr_poles(repr: &FilterRepr) -> Vec<Complex64> {
    match repr {
        FilterRepr::Iir(sos) => numeric::filter::sos_poles(sos),
        FilterRepr::Fir(b) => numeric::filter::fir_poles(b),
    }
}

fn repr_zeros(repr: &FilterRepr) -> R<Vec<Complex64>> {
    match repr {
        FilterRepr::Iir(sos) => Ok(numeric::filter::sos_zeros(sos)),
        FilterRepr::Fir(b) => numeric::filter::fir_zeros(b).map_err(|ne| EvalError { msg: ne.to_string() }),
    }
}

/// `f64` -> JSON. Plain JSON numbers can't represent NaN/Infinity (`serde_
/// json` silently turns them into `null`, which would then fail to load
/// back at all) — encoded as the strings `"NaN"`/`"Infinity"`/
/// `"-Infinity"` instead, `json_to_f64`'s own inverse, so a signal that
/// legitimately contains a `NaN` (a common enough real value — a divide-
/// by-zero result, a filter's transient) survives a save/load round trip
/// instead of silently corrupting to `0.0` or erroring.
fn f64_to_json(x: f64) -> serde_json::Value {
    if x.is_nan() {
        serde_json::Value::String("NaN".to_string())
    } else if x.is_infinite() {
        serde_json::Value::String(if x > 0.0 { "Infinity" } else { "-Infinity" }.to_string())
    } else {
        serde_json::json!(x)
    }
}

fn f64_vec_to_json(xs: &[f64]) -> serde_json::Value {
    serde_json::Value::Array(xs.iter().map(|&x| f64_to_json(x)).collect())
}

/// A signal's §10 annotations -> JSON, for `save`.
///
/// Only called when the metadata is non-empty, and every sub-object is
/// likewise written only when populated, so the saved form of a signal
/// nobody annotated is unchanged from before this field existed. That is
/// what keeps files written by an older Qu loadable by this one AND files
/// written by this one loadable by an older one, as long as nothing was
/// annotated -- the ordinary case.
fn signal_meta_to_json(m: &SigMeta) -> serde_json::Value {
    use serde_json::json;
    let mut j = json!({});
    if m.t0 != 0.0 {
        j["t0"] = f64_to_json(m.t0);
    }
    if let Some(u) = &m.unit {
        j["unit"] = json!(u);
    }
    if let Some(c) = &m.cal {
        let mut cj = json!({
            "slope": f64_to_json(c.slope),
            "offset": f64_to_json(c.offset),
            "unit": json!(c.unit),
            "source": json!(c.source),
        });
        if let Some(r) = c.reference {
            cj["reference"] = f64_to_json(r);
        }
        j["cal"] = cj;
    }
    if !m.fields.is_empty() {
        j["fields"] = serde_json::Value::Array(
            m.fields
                .iter()
                .filter_map(|(k, v)| {
                    // Metadata values are restricted to Num/Str/Bool by
                    // `set_metadata`, all of which serialise, so the
                    // `Err` arm is unreachable in practice; dropping
                    // rather than failing the whole `save` is the right
                    // trade if it ever stops being.
                    value_to_json(v).ok().map(|vj| json!({"k": k, "v": vj}))
                })
                .collect(),
        );
    }
    if !m.markers.is_empty() {
        j["markers"] = serde_json::Value::Array(
            m.markers
                .iter()
                .map(|k| json!({"t": f64_to_json(k.time), "label": json!(k.label)}))
                .collect(),
        );
    }
    if !m.regions.is_empty() {
        j["regions"] = serde_json::Value::Array(
            m.regions
                .iter()
                .map(|r| {
                    json!({
                        "a": f64_to_json(r.start),
                        "b": f64_to_json(r.end),
                        "label": json!(r.label),
                    })
                })
                .collect(),
        );
    }
    j
}

/// `signal_meta_to_json`'s inverse.
///
/// Every part is OPTIONAL and a missing one means the default, so this also
/// accepts a `meta` object written by a future Qu that added a field this
/// build does not know -- it reads what it recognises. That is the right
/// call here and the opposite of `SpectrumNorm`'s: an unknown NORMALISATION
/// changes what the numbers mean and must be refused, whereas an unknown
/// annotation is additional information, and ignoring it loses a label
/// rather than producing a wrong number.
fn signal_meta_from_json(j: &serde_json::Value) -> R<SigMeta> {
    let num = |v: Option<&serde_json::Value>, dflt: f64| -> f64 {
        match v {
            Some(serde_json::Value::String(s)) => match s.as_str() {
                "NaN" => f64::NAN,
                "Infinity" => f64::INFINITY,
                "-Infinity" => f64::NEG_INFINITY,
                _ => dflt,
            },
            Some(v) => v.as_f64().unwrap_or(dflt),
            None => dflt,
        }
    };
    let mut m = SigMeta { t0: num(j.get("t0"), 0.0), ..SigMeta::default() };
    if let Some(u) = j.get("unit").and_then(|v| v.as_str()) {
        m.unit = Some(u.to_string());
    }
    if let Some(cj) = j.get("cal") {
        m.cal = Some(signal_meta::Calibration {
            slope: num(cj.get("slope"), 1.0),
            offset: num(cj.get("offset"), 0.0),
            unit: cj.get("unit").and_then(|v| v.as_str()).unwrap_or("").to_string(),
            reference: cj.get("reference").map(|v| num(Some(v), 0.0)),
            // `source` is provenance text, not behaviour, so an
            // unrecognised one degrades to "linear" rather than refusing a
            // file that is otherwise perfectly readable.
            source: match cj.get("source").and_then(|v| v.as_str()) {
                Some("sensitivity") => "sensitivity",
                Some("tone") => "tone",
                Some("curve") => "curve",
                _ => "linear",
            },
        });
    }
    if let Some(arr) = j.get("fields").and_then(|v| v.as_array()) {
        for f in arr {
            if let (Some(k), Some(v)) = (f.get("k").and_then(|v| v.as_str()), f.get("v")) {
                if let (Some(canon), Ok(val)) = (signal_meta::canonical_field(k), json_to_value(v))
                {
                    m.set_field(canon, val);
                }
            }
        }
    }
    if let Some(arr) = j.get("markers").and_then(|v| v.as_array()) {
        for k in arr {
            m.markers.push(signal_meta::Marker {
                time: num(k.get("t"), 0.0),
                label: k.get("label").and_then(|v| v.as_str()).unwrap_or("").to_string(),
            });
        }
    }
    if let Some(arr) = j.get("regions").and_then(|v| v.as_array()) {
        for r in arr {
            m.regions.push(signal_meta::Region {
                start: num(r.get("a"), 0.0),
                end: num(r.get("b"), 0.0),
                label: r.get("label").and_then(|v| v.as_str()).unwrap_or("").to_string(),
            });
        }
    }
    Ok(m)
}

/// `Value` -> JSON, for `save`/`save_all`. A hand-written conversion (not
/// `#[derive(Serialize)]` on `Value` itself) specifically so
/// `Worker`/`Mutex`/`Semaphore` — live runtime handles, not data — can
/// refuse with a clear error instead of a derive silently doing *something*
/// with them (there is no meaningful "value" to write for a live thread
/// handle or a lock). Every other variant round-trips through
/// `json_to_value` below.
fn value_to_json(v: &Value) -> R<serde_json::Value> {
    use serde_json::json;
    Ok(match v {
        // A handle indexes into a figure that only exists in this process.
        Value::Artist(_) => return e("a plot handle cannot be serialized"),
        Value::Report(_) => return e("a report handle cannot be serialized"),
        Value::Layer(_) => return e("a layer cannot be serialized"),
        Value::Module(_) => return e("a module cannot be serialized"),
        // Code, not data: a body and the variables it closed over mean
        // nothing to a reader on the other side of the file.
        Value::Func(_) => return e("a function cannot be serialized"),
        // No serialized form YET. Refusing beats writing the numbers and
        // dropping the unit -- a failure that would only surface when
        // someone loaded the file and got bare numbers that used to be
        // ohms. Nothing can hit this today (the variant is new), so it
        // breaks nothing and is well-marked follow-up.
        Value::Quantity(_, _) => {
            return e("a value with a unit cannot be serialized yet -- strip it first \
                      (the unit would be lost silently otherwise)")
        }
        Value::Num(n) => json!({"type": "num", "v": f64_to_json(*n)}),
        Value::Bool(b) => json!({"type": "bool", "v": b}),
        Value::Str(s) => json!({"type": "str", "v": s}),
        Value::Vec(xs) => json!({"type": "vec", "v": f64_vec_to_json(xs)}),
        Value::Mat(m) => {
            let (rows, cols) = m.shape();
            json!({"type": "mat", "rows": rows, "cols": cols, "v": f64_vec_to_json(m.as_slice())})
        }
        Value::Complex(c) => json!({"type": "complex", "re": f64_to_json(c.re), "im": f64_to_json(c.im)}),
        Value::CVec(xs) => {
            let flat: Vec<f64> = xs.iter().flat_map(|c| [c.re, c.im]).collect();
            json!({"type": "cvec", "v": f64_vec_to_json(&flat)})
        }
        Value::CMat(m) => {
            let (rows, cols) = m.shape();
            let flat: Vec<f64> = m.as_slice().iter().flat_map(|z| [z.re, z.im]).collect();
            json!({"type": "cmat", "rows": rows, "cols": cols, "v": f64_vec_to_json(&flat)})
        }
        // The §10 annotations are written only when there is something to
        // write, so a plain signal's JSON is byte-for-byte what it was
        // before this field existed and every file already on disk still
        // loads. `meta` absent means `SigMeta::none()`, which is what the
        // reader assumes.
        Value::Signal(xs, fs, m) => {
            let mut j = json!({"type": "signal", "v": f64_vec_to_json(xs), "fs": f64_to_json(*fs)});
            if !m.is_empty() {
                j["meta"] = signal_meta_to_json(m);
            }
            j
        }
        Value::Spectrum(xs, fs, n, norm) => {
            let flat: Vec<f64> = xs.iter().flat_map(|c| [c.re, c.im]).collect();
            json!({"type": "spectrum", "v": f64_vec_to_json(&flat), "fs": f64_to_json(*fs), "n": n, "norm": norm.name()})
        }
        // Topology and parameters separately, which is exactly what the spec
        // grammar separates -- so this round-trips through `circuit(spec, p)`
        // rather than needing a second serialisation format.
        Value::Circuit(c) => json!({
            "type": "circuit",
            "spec": circuit_spec::to_spec(c),
            "params": f64_vec_to_json(&circuit_spec::to_params(c)),
        }),
        Value::Mask(m) => json!({"type": "mask", "v": m}),
        Value::Table(t) => {
            // column order lives in its own array, not the JSON object's
            // key order (serde_json's default map is a BTreeMap, which
            // would silently alphabetize the columns otherwise).
            let mut columns = serde_json::Map::new();
            for name in t.column_names() {
                let col = t.col(name).expect("column_names() only returns real columns");
                let entry = match col {
                    Column::Num(v) => json!({"kind": "num", "v": f64_vec_to_json(v)}),
                    Column::Str(v) => json!({"kind": "str", "v": v}),
                };
                columns.insert(name.to_string(), entry);
            }
            json!({"type": "table", "columns": t.column_names(), "data": columns})
        }
        Value::Model(m) => {
            let mut fields = serde_json::Map::new();
            for (name, field_value) in &m.fields {
                fields.insert(name.clone(), value_to_json(field_value)?);
            }
            json!({"type": "model", "kind": m.kind, "fields": fields, "stages": m.stages})
        }
        // A plain JSON array — order is a JSON array's own native
        // property, no `Table`/`Model`-style side-channel needed. Each
        // element recurses through `value_to_json` itself, so a nested
        // `List`/`Record`/`Vec`/anything-else round-trips exactly like a
        // top-level one.
        Value::List(items) => {
            let elems: R<Vec<serde_json::Value>> = items.iter().map(value_to_json).collect();
            json!({"type": "list", "v": elems?})
        }
        // Field order lives in its own `keys` array, same reason as
        // `Table`'s `columns` above: `serde_json::Map` here is a
        // (order-losing) `BTreeMap`, not `preserve_order`'s `IndexMap`.
        Value::Record(fields) => {
            let keys: Vec<&str> = fields.iter().map(|(k, _)| k.as_str()).collect();
            let mut data = serde_json::Map::new();
            for (name, field_value) in fields.iter() {
                data.insert(name.clone(), value_to_json(field_value)?);
            }
            json!({"type": "record", "keys": keys, "data": data})
        }
        Value::Nothing => json!({"type": "nothing"}),
        // Genuinely plain data (§ enum, 2026-08-24), not a live handle like
        // `Worker`/`Mutex`/etc. below — round-trips like any other value.
        // `load` reconstructs the `Value` directly without re-checking it
        // against the *loading* interpreter's own `enums` table (same as
        // `Model`, which doesn't re-validate its `kind`/fields against any
        // live registry either) — a saved enum value stays meaningful even
        // if loaded into a session that never ran the matching `enum ...
        // end` declaration.
        Value::EnumVal(v) => json!({"type": "enum_val", "enum": v.0, "variant": v.1}),
        Value::EnumType(name) => json!({"type": "enum_type", "name": name.as_ref()}),
        Value::Worker(_) => e("save: a worker handle can't be saved (it's a live thread reference, not data)")?,
        Value::Mutex(_) => e("save: a mutex can't be saved (it's live shared state, not data)")?,
        Value::Semaphore(_) => e("save: a semaphore can't be saved (it's live shared state, not data)")?,
        // Not a live handle like the three above (an image is plain data),
        // but `save`/`load`'s JSON round trip isn't this pass's scope, and a
        // wrong/lossy ad-hoc encoding here would be worse than pointing at
        // the real, tested round trip (`save_image`/`load_image`, BMP).
        Value::Image(_) => e("save: an image isn't supported by save()/save_all() yet — use save_image(path, img) instead")?,
        // A live handle just like `Worker`/`Mutex`/`Semaphore` above — its
        // running/paused state and accumulated time are transient, not
        // data meant to round-trip through a saved workspace.
        Value::Timer(_) => e("save: a timer can't be saved (it's live stopwatch state, not data)")?,
        // A live handle just like `Timer`/`Worker`/`Mutex`/`Semaphore` above
        // — an open OS file descriptor and read/write cursor position are
        // not data meant to round-trip through a saved workspace.
        Value::File(_) => e("save: a file handle can't be saved (it's a live OS file reference, not data)")?,
        // A live handle just like `File`/`Timer`/`Worker`/`Mutex`/
        // `Semaphore` above — a spawned OS process, its reader threads and
        // its accumulated output buffers are not data meant to round-trip
        // through a saved workspace.
        Value::Process(_) => e("save: a process handle can't be saved (it's a live OS process reference, not data)")?,
        Value::Mmap(_) => e("save: a memory-mapped file handle can't be saved (it's a live OS mapping, not data)")?,
        // A still-pending lazy binding has no computed value to save yet —
        // clear error rather than either silently saving the unevaluated
        // expression (meaningless outside this interpreter) or silently
        // forcing it as a save-time side effect (surprising: `save` reading
        // a variable would itself trigger the deferred computation).
        Value::Lazy(_) => e("save: a lazy variable that hasn't been read yet has no value to save — read it at least once first")?,
        Value::UrlStream(_) => e("save: a URL stream handle can't be saved (it's a live, position-tracking handle, not data)")?,
        Value::Serial(_) => e("save: a serial port handle can't be saved (it's a live OS device connection, not data)")?,
        Value::Fifo(_) => e("save: a fifo can't be saved (it's a live ring buffer, not data)")?,
        Value::DoubleBuffer(_) => e("save: a double buffer can't be saved (it's a live front/back handle, not data)")?,
        Value::LinkedList(_) => e("save: a linked list can't be saved (it's a live handle, not data) — use .to_vec() first if you want to save its contents")?,
        Value::Graph(_) => e("save: a graph can't be saved (it's a live handle, not data)")?,
        Value::Channel(_) => e("save: a channel can't be saved (it's a live message queue, not data)")?,
        // The tape's node indices are only meaningful within *this*
        // interpreter's own live `tape` — not portable data, same
        // reasoning as every other live-handle refusal above.
        Value::Tensor(_) => e("save: a tensor can't be saved (its gradient tape is live interpreter state, not data)")?,
        // Live OS sockets, same reasoning as `File`/`Channel` above — a
        // saved workspace can't meaningfully round-trip an open network
        // connection.
        Value::TcpListener(_) => e("save: a TCP listener can't be saved (it's a live OS socket, not data)")?,
        Value::TcpConn(_) => e("save: a TCP connection can't be saved (it's a live OS socket, not data)")?,
        Value::Queue(_) => e("save: a queue can't be saved (it's a live job list, not data)")?,
        Value::Pool(_) => e("save: a pool can't be saved (it's a live worker-pool handle, not data)")?,
        // Genuinely plain data (§47.4 `dict`, 2026-08-26), not a live
        // handle — round-trips like `List`/`Record` above. Keys are
        // already plain `String`s (normalized at construction time), so
        // this is `Record`'s own `keys` + `data` shape verbatim, just
        // under the `"dict"` tag so `load` reconstructs a `Value::Dict`
        // rather than a `Value::Record`.
        Value::Dict(pairs) => {
            let keys: Vec<&str> = pairs.iter().map(|(k, _)| k.as_str()).collect();
            let mut data = serde_json::Map::new();
            for (k, v) in pairs.iter() {
                data.insert(k.clone(), value_to_json(v)?);
            }
            json!({"type": "dict", "keys": keys, "data": data})
        }
        // Design doc `docs/design/physical-units.md`, phase 1: round-trips
        // the declared scale (not a Kelvin conversion), matching
        // `display_value`'s own "print what the user wrote" convention.
        Value::Unit(n, UnitTag::Temp(scale)) => {
            json!({"type": "unit_temp", "v": f64_to_json(*n), "scale": scale.unit_name()})
        }
        // Phase 3 (design doc §8): the magnitude is already SI-normalized
        // (unlike `Temp`, there's no "declared scale" to preserve). Round-
        // trips the raw exponent vector, not just a family name -- a
        // derived dimension (`V * A`, no preferred spelling) has no name
        // to save, but it still has a `Dim` that must survive `save`/
        // `load`. `spelling` is the optional preferred display unit.
        Value::Unit(n, UnitTag::Dim(dim, spelling)) => {
            json!({
                "type": "unit_dim",
                "v": f64_to_json(*n),
                "dim": dim.0,
                "spelling": spelling,
            })
        }
    })
}

/// JSON -> `Value`, `value_to_json`'s inverse. `load` calls this once per
/// top-level saved entry.
fn json_to_value(j: &serde_json::Value) -> R<Value> {
    fn field<'a>(j: &'a serde_json::Value, key: &str) -> R<&'a serde_json::Value> {
        j.get(key).ok_or_else(|| EvalError {
            msg: format!("load: malformed saved value, missing `{key}`"),
        })
    }
    // `f64_to_json`'s inverse: a JSON number decodes normally, but the
    // `"NaN"`/`"Infinity"`/`"-Infinity"` string sentinels decode back to
    // their real float — without this, a saved NaN/Infinity (a legitimate
    // signal value, not just an error state) would fail to load at all.
    fn as_f64(j: &serde_json::Value) -> R<f64> {
        match j {
            serde_json::Value::Number(_) => {
                j.as_f64().ok_or_else(|| EvalError { msg: "load: malformed number".into() })
            }
            serde_json::Value::String(s) => match s.as_str() {
                "NaN" => Ok(f64::NAN),
                "Infinity" => Ok(f64::INFINITY),
                "-Infinity" => Ok(f64::NEG_INFINITY),
                other => e(format!("load: expected a number, found string `{other}`")),
            },
            other => e(format!("load: expected a number, found {other}")),
        }
    }
    fn as_f64_vec(j: &serde_json::Value) -> R<Vec<f64>> {
        j.as_array()
            .ok_or_else(|| EvalError { msg: "load: expected an array of numbers".into() })?
            .iter()
            .map(as_f64)
            .collect()
    }
    fn as_usize(j: &serde_json::Value) -> R<usize> {
        j.as_u64().map(|n| n as usize).ok_or_else(|| EvalError { msg: "load: expected a non-negative integer".into() })
    }

    let kind = field(j, "type")?
        .as_str()
        .ok_or_else(|| EvalError { msg: "load: malformed saved value, `type` is not a string".into() })?;
    Ok(match kind {
        "num" => Value::Num(as_f64(field(j, "v")?)?),
        "bool" => Value::Bool(field(j, "v")?.as_bool().ok_or_else(|| EvalError { msg: "load: malformed bool".into() })?),
        "str" => Value::Str(
            field(j, "v")?.as_str().ok_or_else(|| EvalError { msg: "load: malformed str".into() })?.to_string(),
        ),
        "vec" => Value::Vec(Arc::new(as_f64_vec(field(j, "v")?)?)),
        "mat" => {
            let rows = as_usize(field(j, "rows")?)?;
            let cols = as_usize(field(j, "cols")?)?;
            Value::Mat(Arc::new(Matrix::from_col_major(rows, cols, as_f64_vec(field(j, "v")?)?)))
        }
        "complex" => Value::Complex(Complex64 {
            re: field(j, "re")?.as_f64().ok_or_else(|| EvalError { msg: "load: malformed complex".into() })?,
            im: field(j, "im")?.as_f64().ok_or_else(|| EvalError { msg: "load: malformed complex".into() })?,
        }),
        "cvec" => {
            let flat = as_f64_vec(field(j, "v")?)?;
            Value::CVec(Arc::new(flat.chunks(2).map(|c| Complex64 { re: c[0], im: c[1] }).collect()))
        }
        "cmat" => {
            let rows = as_usize(field(j, "rows")?)?;
            let cols = as_usize(field(j, "cols")?)?;
            let flat = as_f64_vec(field(j, "v")?)?;
            let data: Vec<Complex64> = flat.chunks(2).map(|c| Complex64 { re: c[0], im: c[1] }).collect();
            Value::CMat(Arc::new(CMatrix::from_col_major(rows, cols, data)))
        }
        "signal" => {
            let xs = as_f64_vec(field(j, "v")?)?;
            let fs = field(j, "fs")?.as_f64().ok_or_else(|| EvalError { msg: "load: malformed signal".into() })?;
            match j.get("meta") {
                Some(mj) => Value::Signal(xs.into(), fs, Arc::new(signal_meta_from_json(mj)?)),
                None => Value::Signal(xs.into(), fs, SigMeta::none()),
            }
        }
        "circuit" => {
            let spec = field(j, "spec")?.as_str().unwrap_or_default().to_string();
            let params = as_f64_vec(field(j, "params")?)?;
            Value::Circuit(Arc::new(
                circuit_spec::parse(&spec, &params).map_err(|m| EvalError {
                    msg: format!("load: malformed circuit: {m}"),
                })?,
            ))
        }
        "spectrum" => {
            let flat = as_f64_vec(field(j, "v")?)?;
            let fs = field(j, "fs")?.as_f64().ok_or_else(|| EvalError { msg: "load: malformed spectrum".into() })?;
            let n = as_usize(field(j, "n")?)?;
            // An unrecognised convention is refused rather than defaulted:
            // silently reading a future `density` spectrum back as raw
            // transform output is exactly the wrong answer this tag exists
            // to prevent.
            let norm = match field(j, "norm")?.as_str().and_then(SpectrumNorm::from_name) {
                Some(n) => n,
                None => {
                    let other = field(j, "norm")?.as_str();
                    return e(format!(
                        "load: spectrum has an unknown normalisation {other:?} -- \
                         written by a newer Qu than this one"
                    ))
                }
            };
            Value::Spectrum(
                Arc::new(flat.chunks(2).map(|c| Complex64 { re: c[0], im: c[1] }).collect()),
                fs,
                n,
                norm,
            )
        }
        "mask" => {
            let arr = field(j, "v")?.as_array().ok_or_else(|| EvalError { msg: "load: malformed mask".into() })?;
            Value::Mask(arr.iter().map(|b| b.as_bool().unwrap_or(false)).collect())
        }
        "table" => {
            let names: Vec<String> = field(j, "columns")?
                .as_array()
                .ok_or_else(|| EvalError { msg: "load: malformed table".into() })?
                .iter()
                .filter_map(|v| v.as_str().map(|s| s.to_string()))
                .collect();
            let data = field(j, "data")?
                .as_object()
                .ok_or_else(|| EvalError { msg: "load: malformed table".into() })?;
            let mut columns = Vec::with_capacity(names.len());
            for name in names {
                let col_json = data.get(&name).ok_or_else(|| EvalError {
                    msg: format!("load: table column `{name}` listed but missing"),
                })?;
                let col_kind = field(col_json, "kind")?
                    .as_str()
                    .ok_or_else(|| EvalError { msg: "load: malformed table column".into() })?;
                let col = match col_kind {
                    "num" => Column::Num(as_f64_vec(field(col_json, "v")?)?),
                    "str" => Column::Str(
                        field(col_json, "v")?
                            .as_array()
                            .ok_or_else(|| EvalError { msg: "load: malformed table column".into() })?
                            .iter()
                            .map(|v| v.as_str().unwrap_or("").to_string())
                            .collect(),
                    ),
                    other => return e(format!("load: unknown table column kind `{other}`")),
                };
                columns.push((name, col));
            }
            Value::Table(Arc::new(Table::from_columns(columns).map_err(|msg| EvalError { msg })?))
        }
        "model" => {
            let model_kind = field(j, "kind")?
                .as_str()
                .ok_or_else(|| EvalError { msg: "load: malformed model".into() })?
                .to_string();
            let fields_obj = field(j, "fields")?
                .as_object()
                .ok_or_else(|| EvalError { msg: "load: malformed model".into() })?;
            let mut fields = Vec::with_capacity(fields_obj.len());
            for (name, field_value) in fields_obj {
                fields.push((name.clone(), json_to_value(field_value)?));
            }
            let stages = field(j, "stages")?
                .as_array()
                .ok_or_else(|| EvalError { msg: "load: malformed model".into() })?
                .iter()
                .map(|s| s.as_str().unwrap_or("").to_string())
                .collect();
            Value::Model(Arc::new(ModelHandle::with_stages(model_kind, fields, stages)))
        }
        "list" => {
            let arr = field(j, "v")?
                .as_array()
                .ok_or_else(|| EvalError { msg: "load: malformed list".into() })?;
            let items: R<Vec<Value>> = arr.iter().map(json_to_value).collect();
            Value::List(Arc::new(items?))
        }
        "record" => {
            let keys: Vec<String> = field(j, "keys")?
                .as_array()
                .ok_or_else(|| EvalError { msg: "load: malformed record".into() })?
                .iter()
                .filter_map(|v| v.as_str().map(|s| s.to_string()))
                .collect();
            let data = field(j, "data")?
                .as_object()
                .ok_or_else(|| EvalError { msg: "load: malformed record".into() })?;
            let mut fields = Vec::with_capacity(keys.len());
            for k in keys {
                let v = data.get(&k).ok_or_else(|| EvalError {
                    msg: format!("load: record field `{k}` listed but missing"),
                })?;
                fields.push((k, json_to_value(v)?));
            }
            Value::Record(Arc::new(fields))
        }
        // `dict(...)` (§47.4, 2026-08-26) — `value_to_json`'s own "dict"
        // tag, `"record"`'s inverse verbatim since the on-disk shape is
        // identical (`keys` + `data`), just reconstructing a `Value::Dict`.
        "dict" => {
            let keys: Vec<String> = field(j, "keys")?
                .as_array()
                .ok_or_else(|| EvalError { msg: "load: malformed dict".into() })?
                .iter()
                .filter_map(|v| v.as_str().map(|s| s.to_string()))
                .collect();
            let data = field(j, "data")?
                .as_object()
                .ok_or_else(|| EvalError { msg: "load: malformed dict".into() })?;
            let mut pairs = Vec::with_capacity(keys.len());
            for k in keys {
                let v = data.get(&k).ok_or_else(|| EvalError {
                    msg: format!("load: dict key `{k}` listed but missing"),
                })?;
                pairs.push((k, json_to_value(v)?));
            }
            Value::Dict(Arc::new(pairs))
        }
        "nothing" => Value::Nothing,
        "enum_val" => {
            let enum_name = field(j, "enum")?
                .as_str()
                .ok_or_else(|| EvalError { msg: "load: malformed enum value".into() })?
                .to_string();
            let variant = field(j, "variant")?
                .as_str()
                .ok_or_else(|| EvalError { msg: "load: malformed enum value".into() })?
                .to_string();
            Value::EnumVal(Arc::new((enum_name, variant)))
        }
        "enum_type" => {
            let enum_name = field(j, "name")?
                .as_str()
                .ok_or_else(|| EvalError { msg: "load: malformed enum type".into() })?
                .to_string();
            Value::EnumType(Arc::new(enum_name))
        }
        "unit_temp" => {
            let n = as_f64(field(j, "v")?)?;
            let scale = field(j, "scale")?
                .as_str()
                .ok_or_else(|| EvalError { msg: "load: malformed unit value".into() })?;
            match scale {
                "degC" => Value::Unit(n, UnitTag::Temp(TempScale::Celsius)),
                "degF" => Value::Unit(n, UnitTag::Temp(TempScale::Fahrenheit)),
                other => return e(format!("load: unknown temperature scale `{other}`")),
            }
        }
        // Phase 3 shape (current `value_to_json`): the raw exponent vector
        // plus the optional preferred spelling, so a derived (unnamed)
        // dimension round-trips exactly, not just the 9 named families.
        "unit_dim" => {
            let n = as_f64(field(j, "v")?)?;
            let arr = field(j, "dim")?
                .as_array()
                .ok_or_else(|| EvalError { msg: "load: malformed unit value".into() })?;
            if arr.len() != 7 {
                return e("load: malformed unit value -- `dim` must have 7 entries".to_string());
            }
            let mut d = [0i8; 7];
            for (i, v) in arr.iter().enumerate() {
                let n = v.as_i64().ok_or_else(|| EvalError { msg: "load: malformed unit value".into() })?;
                d[i] = n as i8;
            }
            // `spelling` is a static preferred display name -- re-
            // canonicalize the saved string to one of the known `&'static
            // str`s (`UnitTag::Dim` doesn't own a `String`) by matching it
            // against `qu_lexer::UNITS`. A spelling that no longer names a
            // known unit (or `null`, meaning "none was set") degrades to
            // `None` -- composed display -- rather than failing to load.
            let spelling = field(j, "spelling")?.as_str().and_then(|s| {
                qu_lexer::UNITS.iter().find(|&&u| u == s).copied()
            });
            Value::Unit(n, UnitTag::Dim(Dim(d), spelling))
        }
        // Legacy shape, from before phase 3 (§8): only the 9 canonical
        // family names, no arbitrary derived dimension. Kept so a file
        // saved by an older build still loads. This decoder used to list
        // only 8 of `unit_family`'s 9 names -- `"m"` (length) was missing,
        // so a saved length quantity failed to load while every other
        // family round-tripped; a length is common enough (any `save`
        // after a `5 km`-shaped literal) that this was a real, silent-ish
        // data-loss bug, not a theoretical gap. Found in passing during
        // the phase 3 port, fixed here alongside it.
        "unit_family" => {
            let n = as_f64(field(j, "v")?)?;
            let fam = field(j, "family")?
                .as_str()
                .ok_or_else(|| EvalError { msg: "load: malformed unit value".into() })?;
            match dim_for_name(fam) {
                Some(d) => {
                    let spelling = qu_lexer::UNITS.iter().find(|&&u| u == fam).copied();
                    Value::Unit(n, UnitTag::Dim(d, spelling))
                }
                None => return e(format!("load: unknown unit family `{fam}`")),
            }
        }
        other => return e(format!("load: unknown saved value type `{other}`")),
    })
}

/// `jsonify(value) -> str` — `value_to_json` (above) plus
/// `serde_json::to_string`. Exists as its own function (rather than being
/// inlined at its one call site) purely so `json2csv`/`csv2json`/etc. below
/// can compose it as `do_csvify(&do_jsonify(...)?)`-style one-liners
/// without duplicating the `serde_json::to_string` + error-wrapping step.
fn do_jsonify(v: &Value) -> R<String> {
    serde_json::to_string(&value_to_json(v)?).map_err(|err| EvalError { msg: format!("jsonify: {err}") })
}

/// `parse_json(str) -> value` — `jsonify`'s inverse: `serde_json::from_str`
/// plus `json_to_value` (above).
/// A JSON array of numbers is a vector; of like-shaped objects, a table;
/// of anything else, a list.
///
/// The shapes matter because they decide what a script can DO with the
/// result. `[1, 2, 3]` as a list of three scalars cannot be summed or
/// plotted; as a vector it can. An array of records with matching keys is
/// exactly a table, which is what an API returning rows means.
fn general_json_to_value(j: &serde_json::Value) -> Value {
    use serde_json::Value as J;
    match j {
        J::Array(items) if !items.is_empty() && items.iter().all(|v| v.is_number()) => {
            Value::Vec(Arc::new(
                items.iter().map(|v| v.as_f64().unwrap_or(f64::NAN)).collect(),
            ))
        }
        J::Array(items) if !items.is_empty() && items.iter().all(|v| v.is_object()) => {
            // Rows only when every object carries the SAME keys. A ragged
            // array is a list of records: forcing it into a table would
            // have to invent values for the missing cells, and an invented
            // number is worse than a shape the caller has to handle.
            let first_keys: Vec<&String> = match &items[0] {
                J::Object(m) => m.keys().collect(),
                _ => return list_of(items),
            };
            let same_shape = items.iter().all(|it| match it {
                J::Object(m) => m.len() == first_keys.len() && first_keys.iter().all(|k| m.contains_key(*k)),
                _ => false,
            });
            if !same_shape {
                return list_of(items);
            }
            let mut columns: Vec<(String, table::Column)> = Vec::with_capacity(first_keys.len());
            for key in &first_keys {
                let cells: Vec<&J> = items.iter().map(|it| &it[key.as_str()]).collect();
                let column = if cells.iter().all(|c| c.is_number()) {
                    table::Column::Num(cells.iter().map(|c| c.as_f64().unwrap_or(f64::NAN)).collect())
                } else {
                    table::Column::Str(
                        cells
                            .iter()
                            .map(|c| match c {
                                J::String(s) => s.clone(),
                                other => other.to_string(),
                            })
                            .collect(),
                    )
                };
                columns.push(((*key).clone(), column));
            }
            match table::Table::from_columns(columns) {
                Ok(t) => Value::Table(Arc::new(t)),
                // A table this cannot build is still perfectly good data.
                Err(_) => list_of(items),
            }
        }
        J::Object(map) => Value::Record(Arc::new(
            map.iter().map(|(k, v)| (k.clone(), general_json_to_value(v))).collect(),
        )),
        J::Array(items) => list_of(items),
        other => py_exec::plain_json_to_value(other),
    }
}

fn list_of(items: &[serde_json::Value]) -> Value {
    Value::List(Arc::new(items.iter().map(general_json_to_value).collect()))
}

/// A value as ORDINARY JSON -- the shape another program expects, not
/// Qu's save envelope.
///
/// `jsonify` writes the envelope on purpose: it is what `load` reads back,
/// and round-tripping a Qu value needs the type tags. But `csv2json` and
/// `xml2json` are named as CONVERTERS, and a converter that emits
/// `{"columns":[...],"data":{"x":{"kind":"num",...}},"type":"table"}` has
/// not converted anything anyone else can use. A table becomes an array of
/// row objects, which is what every CSV-to-JSON tool produces and what an
/// API consumer expects.
fn do_json_rows(v: &Value) -> R<String> {
    let json = match v {
        Value::Table(t) => {
            let names: Vec<String> = t.column_names().into_iter().map(str::to_string).collect();
            let n = t.nrows();
            let mut rows = Vec::with_capacity(n);
            for r in 0..n {
                let mut obj = serde_json::Map::new();
                for name in &names {
                    let cell = match t.col(name) {
                        Some(table::Column::Num(xs)) => xs
                            .get(r)
                            .and_then(|x| serde_json::Number::from_f64(*x))
                            .map(serde_json::Value::Number)
                            // NaN and infinity are not JSON numbers; null
                            // is the standard stand-in and survives a
                            // round trip through any consumer.
                            .unwrap_or(serde_json::Value::Null),
                        Some(table::Column::Str(xs)) => {
                            serde_json::Value::String(xs.get(r).cloned().unwrap_or_default())
                        }
                        _ => serde_json::Value::Null,
                    };
                    obj.insert(name.clone(), cell);
                }
                rows.push(serde_json::Value::Object(obj));
            }
            serde_json::Value::Array(rows)
        }
        other => py_exec::value_to_plain_json(other)?,
    };
    serde_json::to_string(&json).map_err(|err| EvalError { msg: format!("could not serialize to JSON: {err}") })
}

/// `parse_json(str)` -- ORDINARY JSON, plus Qu's own save envelope.
///
/// This used to accept only the save-file envelope, so `parse_json("{a: 1}")`
/// answered "load: malformed saved value, missing `type`" -- a message that
/// never mentions JSON, for input that is perfectly good JSON. Qu ships
/// `http_get` and then could not parse what almost any endpoint returns,
/// which made `parse_json`, `json2csv`, `json2xml` and `csv2json` a
/// save-format round trip wearing converter names.
///
/// A saved value is recognised by its `"type"` tag and still goes to the
/// loader, so existing save files keep working. Everything else gets the
/// general mapping.
fn do_parse_json(s: &str) -> R<Value> {
    let j: serde_json::Value =
        serde_json::from_str(s).map_err(|err| EvalError { msg: format!("parse_json: not valid JSON: {err}") })?;
    // The envelope is an object with a `type` STRING. A plain document that
    // happens to have a `type` field holding a number or an object is not
    // one, and must not be dragged into the loader to fail there.
    let is_saved_value = j
        .get("type")
        .map(|t| t.is_string())
        .unwrap_or(false);
    if is_saved_value {
        // Fall back to the general mapping if it turns out not to be a
        // save envelope after all -- a document with a `"type": "user"`
        // field is ordinary JSON, not a corrupt save file.
        return json_to_value(&j).or_else(|_| Ok(general_json_to_value(&j)));
    }
    Ok(general_json_to_value(&j))
}

/// `csvify(table) -> str` — `Table::to_csv` (`table.rs`), already
/// string-based; this only adds the "must actually be a table" check
/// `write_csv` already makes at its own call site, worded for a value with
/// no file-path argument to blame instead.
fn do_csvify(v: &Value) -> R<String> {
    match v {
        Value::Table(t) => Ok(t.to_csv()),
        other => e(format!("csvify: expected a table, found {} (only a table has a CSV shape)", other.type_name())),
    }
}

/// `parse_csv(str) -> table` — `Table::from_csv` (`table.rs`), the same
/// default `headers=true, sep=",", decimal="."` convention `read_csv` uses
/// (see `Table::from_csv_opts`'s own doc comment for the full parsing
/// rules); unlike `read_csv`, `parse_csv` takes the CSV text directly
/// rather than a file path, so there's no keyword-argument slot to forward
/// `headers=`/`sep=`/`decimal=` through — use `read_csv` on a real file for
/// those.
fn do_parse_csv(s: &str) -> R<Value> {
    Table::from_csv(s).map(|t| Value::Table(Arc::new(t))).map_err(|msg| EvalError { msg: format!("parse_csv: {msg}") })
}

/// Shared by `ols_model`/`ridge_model`: mean-center `X`/`y`, solve the
/// (optionally L2-regularized) least-squares problem on the centered data,
/// then recover the intercept the centering removed — the standard
/// `fit_intercept=True` construction. `alpha=0.0` is plain OLS.
fn model_fit_linear(x: &Matrix, y: &[f64], alpha: f64) -> R<Value> {
    let (n, d) = x.shape();
    let x_means: Vec<f64> = (0..d)
        .map(|c| (0..n).map(|r| x.get(r, c).unwrap_or(0.0)).sum::<f64>() / n as f64)
        .collect();
    let y_mean = y.iter().sum::<f64>() / n as f64;
    let mut rows: Vec<Vec<f64>> = (0..n)
        .map(|r| (0..d).map(|c| x.get(r, c).unwrap_or(0.0) - x_means[c]).collect())
        .collect();
    let mut targets: Vec<f64> = y.iter().map(|v| v - y_mean).collect();
    if alpha > 0.0 {
        let s = alpha.sqrt();
        for i in 0..d {
            let mut row = vec![0.0; d];
            row[i] = s;
            rows.push(row);
        }
        targets.extend(std::iter::repeat_n(0.0, d));
    }
    let design = Matrix::from_rows(&rows).map_err(|se| EvalError { msg: se.to_string() })?;
    let observed = Matrix::from_column(&targets);
    let solution = numeric::linalg::least_squares(&design, &observed, None)
        .map_err(|le| EvalError { msg: le.to_string() })?;
    let coef = solution.as_slice().to_vec();
    let intercept = y_mean - x_means.iter().zip(&coef).map(|(m, b)| m * b).sum::<f64>();

    let fitted = linear_predict_rows(x, &coef, intercept);
    let residuals: Vec<f64> = y.iter().zip(&fitted).map(|(a, b)| a - b).collect();
    let ss_res: f64 = residuals.iter().map(|r| r * r).sum();
    let ss_tot: f64 = y.iter().map(|v| (v - y_mean).powi(2)).sum();
    let r2 = if ss_tot > 0.0 {
        1.0 - ss_res / ss_tot
    } else if ss_res == 0.0 {
        1.0
    } else {
        0.0
    };

    let kind = if alpha > 0.0 { "ridge" } else { "ols" };
    let fields = vec![
        ("coef".to_string(), Value::Vec(Arc::new(coef))),
        ("intercept".to_string(), Value::Num(intercept)),
        ("fitted".to_string(), Value::Vec(Arc::new(fitted))),
        ("residuals".to_string(), Value::Vec(Arc::new(residuals))),
        ("r2".to_string(), Value::Num(r2)),
    ];
    Ok(Value::Model(Arc::new(ModelHandle::new(kind, fields))))
}

/// Fits an AR(p) model's coefficients via the Yule-Walker equations:
/// `rho[k] = sum_{j=1}^{p} phi_j * rho[k-j]` for `k = 1..=p`, where `rho`
/// is `x`'s own normalized autocorrelation (the existing `acf` free
/// function — chosen over building a fresh lagged design matrix and
/// re-solving via `least_squares` the way `ols_model` does, since Yule-
/// Walker's whole point is that its normal equations are already stated
/// directly in terms of the ACF, and `acf` already exists in this
/// codebase). In matrix form this is the `(p, p)` symmetric Toeplitz
/// system `R * phi = r` (`R[i][j] = rho(|i-j|)`, `r[i] = rho(i+1)`, both
/// 0-indexed) — small and always square, so `numeric::linalg::
/// least_squares`'s direct LU-solve fast path handles it, the same solver
/// `ridge`/`model_fit_linear` already reuse for their own (larger,
/// rectangular) systems.
///
/// `mean`/`history` (the series' own mean and its last `order` values, in
/// chronological order) are carried on the returned model purely so
/// `.predict(n_ahead)` (`ar_predict`, below) has something to recurse
/// from — an AR model forecasts its own future from its own fitted
/// history, unlike `ols_model`/`ridge_model`'s `predict(Xnew)` against
/// caller-supplied new rows. `fitted`/`residuals` are the classic
/// one-step-ahead training diagnostics (`ols_model`'s own convention):
/// `fitted[t]` uses `x`'s TRUE lagged history, never a prior forecast —
/// only `.predict`'s own multi-step recursion feeds forecasts back into
/// themselves.
fn ar_fit_model(x: &[f64], order: usize) -> R<Value> {
    let rho = acf(x, order);
    if rho.iter().any(|v| !v.is_finite()) {
        return e("ar_model: autocorrelation is undefined (series has zero variance, or too few points for this order)");
    }
    let rows: Vec<Vec<f64>> = (0..order)
        .map(|i| (0..order).map(|j| rho[i.abs_diff(j)]).collect())
        .collect();
    let r_vec: Vec<f64> = (1..=order).map(|k| rho[k]).collect();
    let design = Matrix::from_rows(&rows).map_err(|se| EvalError { msg: se.to_string() })?;
    let observed = Matrix::from_column(&r_vec);
    let solution = numeric::linalg::least_squares(&design, &observed, None)
        .map_err(|le| EvalError { msg: le.to_string() })?;
    let coef = solution.as_slice().to_vec();

    let n = x.len();
    let mean = x.iter().sum::<f64>() / n as f64;
    let history: Vec<f64> = x[n - order..].to_vec();

    let mut fitted = Vec::with_capacity(n - order);
    let mut residuals = Vec::with_capacity(n - order);
    for t in order..n {
        let pred = mean + (0..order).map(|j| coef[j] * (x[t - 1 - j] - mean)).sum::<f64>();
        fitted.push(pred);
        residuals.push(x[t] - pred);
    }

    let fields = vec![
        ("coef".to_string(), Value::Vec(Arc::new(coef))),
        ("order".to_string(), Value::Num(order as f64)),
        ("mean".to_string(), Value::Num(mean)),
        ("history".to_string(), Value::Vec(Arc::new(history))),
        ("fitted".to_string(), Value::Vec(Arc::new(fitted))),
        ("residuals".to_string(), Value::Vec(Arc::new(residuals))),
    ];
    Ok(Value::Model(Arc::new(ModelHandle::new("ar", fields))))
}

/// `ar_model.predict(n_ahead)` — recursively applies the fitted AR
/// equation (`x_t = mean + sum_j coef[j] * (x_{t-1-j} - mean)`) to
/// generate `n_ahead` future values, each new value's own lagged inputs
/// being whatever the growing `history` buffer holds at that point: real
/// fitted data for the first `order` steps of the recursion, and this
/// same function's OWN prior forecasts once `n_ahead` exceeds `order` —
/// the defining behavior of a multi-step AR forecast (a true out-of-sample
/// future is never available to condition on, so the model necessarily
/// forecasts from itself).
fn ar_predict(m: &ModelHandle, n_ahead: usize) -> R<Value> {
    let coef = to_vec(m.field("coef").expect("ar model always has coef"))?;
    let order = coef.len();
    let mean = m.field("mean").expect("ar model always has mean").as_num().unwrap_or(0.0);
    let mut history = to_vec(m.field("history").expect("ar model always has history"))?;
    let mut forecasts = Vec::with_capacity(n_ahead);
    for _ in 0..n_ahead {
        let h = history.len();
        let next = mean + (0..order).map(|j| coef[j] * (history[h - 1 - j] - mean)).sum::<f64>();
        forecasts.push(next);
        history.push(next);
    }
    Ok(Value::Vec(Arc::new(forecasts)))
}

/// `Xnew * coef + intercept`, one dot product per row.
fn linear_predict_rows(x: &Matrix, coef: &[f64], intercept: f64) -> Vec<f64> {
    let (n, d) = x.shape();
    (0..n)
        .map(|r| (0..d).map(|c| x.get(r, c).unwrap_or(0.0) * coef[c]).sum::<f64>() + intercept)
        .collect()
}

/// The row index of `centers` nearest `row` (squared Euclidean) —
/// nearest-centroid assignment, the same rule `kmeans_fit`'s own
/// iteration loop uses internally.
fn nearest_center(row: &[f64], centers: &Matrix) -> usize {
    let (k, d) = centers.shape();
    (0..k)
        .map(|c| {
            let dist2: f64 = (0..d)
                .map(|j| {
                    let diff = row[j] - centers.get(c, j).unwrap_or(0.0);
                    diff * diff
                })
                .sum();
            (c, dist2)
        })
        .min_by(|a, b| a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal))
        .map(|(c, _)| c)
        .unwrap_or(0)
}

/// Harmonic-number approximation of the average path length of an
/// unsuccessful BST search over `n` points — `c(n)` in Liu, Ting & Zhou
/// (2008). This is what makes an isolation-forest score comparable across
/// different subsample sizes: a raw path length is meaningless without the
/// depth a tree of that size would reach *by construction*, and every
/// published iForest score divides by it.
fn iforest_c(n: f64) -> f64 {
    if n <= 1.0 {
        0.0
    } else if n == 2.0 {
        1.0
    } else {
        // H(n-1) = ln(n-1) + gamma (Euler–Mascheroni), the standard
        // approximation the paper itself uses.
        2.0 * ((n - 1.0).ln() + 0.5772156649015329) - 2.0 * (n - 1.0) / n
    }
}

/// One isolation tree, grown on the row indices `idx` of `rows`, appended
/// into the shared flat `nodes` arena. Returns the index of this subtree's
/// root.
///
/// The arena layout (`[feature, threshold, left, right, size]` per row) is
/// the same "a model handle holds matrices, not Rust structs" constraint
/// `random_forest_model`'s own tree storage lives under — `ModelHandle`
/// fields are `Value`s, so a recursive node type has to be flattened to be
/// storable at all. A leaf is marked by `feature = -1` (with `left`/`right`
/// also `-1`) and carries the number of training rows that reached it in
/// `size`, which is exactly what the `c(size)` depth correction needs at
/// predict time.
///
/// Splits are uniform-random in BOTH the feature and the cut point — the
/// defining property of the algorithm, not a shortcut. Anomalies are
/// isolated by *few* random cuts precisely because they sit in sparse
/// regions, so no impurity criterion is wanted or used here.
fn iforest_build(
    rows: &[Vec<f64>],
    idx: &[usize],
    depth: usize,
    height_limit: usize,
    rng: &mut Rng,
    nodes: &mut Vec<[f64; 5]>,
) -> usize {
    let d = rows.first().map(|r| r.len()).unwrap_or(0);
    if idx.len() <= 1 || depth >= height_limit || d == 0 {
        nodes.push([-1.0, 0.0, -1.0, -1.0, idx.len() as f64]);
        return nodes.len() - 1;
    }
    // Try features in a random order and take the first one that is not
    // constant over this node. Picking a single random feature and giving
    // up when it happens to be constant would turn a perfectly splittable
    // node into a leaf and shorten every path through it — a silent bias
    // toward calling things anomalous.
    let mut order: Vec<usize> = (0..d).collect();
    for i in 0..d {
        let j = i + (rng.next_u64() as usize) % (d - i);
        order.swap(i, j);
    }
    let mut chosen: Option<(usize, f64)> = None;
    for &q in &order {
        let mut lo = f64::INFINITY;
        let mut hi = f64::NEG_INFINITY;
        for &i in idx {
            let v = rows[i][q];
            if v < lo {
                lo = v;
            }
            if v > hi {
                hi = v;
            }
        }
        if hi > lo && lo.is_finite() && hi.is_finite() {
            chosen = Some((q, rng.uniform_range(lo, hi)));
            break;
        }
    }
    let Some((q, p)) = chosen else {
        // Every feature is constant here: these rows are duplicates, and
        // no cut can ever separate them.
        nodes.push([-1.0, 0.0, -1.0, -1.0, idx.len() as f64]);
        return nodes.len() - 1;
    };
    let mut left: Vec<usize> = Vec::new();
    let mut right: Vec<usize> = Vec::new();
    for &i in idx {
        if rows[i][q] < p {
            left.push(i);
        } else {
            right.push(i);
        }
    }
    if left.is_empty() || right.is_empty() {
        // `uniform_range` landed exactly on the minimum (possible in
        // floating point); a degenerate split would recurse forever.
        nodes.push([-1.0, 0.0, -1.0, -1.0, idx.len() as f64]);
        return nodes.len() - 1;
    }
    let me = nodes.len();
    nodes.push([q as f64, p, -1.0, -1.0, idx.len() as f64]);
    let l = iforest_build(rows, &left, depth + 1, height_limit, rng, nodes);
    let r = iforest_build(rows, &right, depth + 1, height_limit, rng, nodes);
    nodes[me][2] = l as f64;
    nodes[me][3] = r as f64;
    me
}

/// The path length of one row through one tree: the number of cuts it took
/// to isolate it, PLUS `c(leaf_size)` when the walk stopped at a leaf that
/// still held several points (because the height limit was reached, not
/// because isolation finished). Without that correction a height-capped
/// tree reports the same depth for a point in a dense cluster as for a
/// genuine outlier.
fn iforest_path_len(nodes: &Matrix, root: usize, row: &[f64]) -> f64 {
    let mut node = root;
    let mut depth = 0.0;
    loop {
        let feature = nodes.get(node, 0).unwrap_or(-1.0);
        if feature < 0.0 {
            let size = nodes.get(node, 4).unwrap_or(1.0);
            return depth + iforest_c(size);
        }
        let q = feature as usize;
        let p = nodes.get(node, 1).unwrap_or(0.0);
        let next = if row.get(q).copied().unwrap_or(0.0) < p {
            nodes.get(node, 2).unwrap_or(-1.0)
        } else {
            nodes.get(node, 3).unwrap_or(-1.0)
        };
        if next < 0.0 {
            return depth + 1.0;
        }
        node = next as usize;
        depth += 1.0;
    }
}

/// `s(x) = 2^(-E[h(x)] / c(psi))` — the isolation-forest anomaly score, on
/// `(0, 1)`: near 1 means "isolated in very few cuts by every tree", i.e.
/// anomalous; near 0 means "took much longer than average to isolate";
/// around 0.5 is the score of an unremarkable point, which is the
/// conventional cut-off the paper recommends when no contamination rate is
/// supplied.
fn iforest_scores(nodes: &Matrix, roots: &[f64], xnew: &Matrix, psi: f64) -> Vec<f64> {
    let norm = iforest_c(psi);
    (0..xnew.rows())
        .map(|r| {
            let row = matrix_row(xnew, r);
            let mean_h: f64 = roots
                .iter()
                .map(|&root| iforest_path_len(nodes, root as usize, &row))
                .sum::<f64>()
                / roots.len().max(1) as f64;
            if norm <= 0.0 {
                0.5
            } else {
                2f64.powf(-mean_h / norm)
            }
        })
        .collect()
}

/// `isolation_forest(X, ...)`'s fit — see the builtin arm's own doc comment
/// for the argument contract. Each tree is grown on its own subsample of
/// `psi = min(max_samples, N)` rows drawn WITHOUT replacement (a partial
/// Fisher-Yates shuffle, the same draw `kmeans_fit`'s init uses), which is
/// the other half of what makes iForest cheap: no tree ever sees the whole
/// dataset, and swamping/masking by dense regions is diluted rather than
/// reinforced.
fn isolation_forest_fit(
    x: &Matrix,
    n_trees: usize,
    max_samples: usize,
    seed: u64,
) -> R<(Matrix, Vec<f64>, f64)> {
    let (n, d) = x.shape();
    if n == 0 || d == 0 {
        return e("isolation_forest: X must have at least one row and one column");
    }
    if n_trees == 0 {
        return e("isolation_forest: n_trees must be at least 1");
    }
    let psi = max_samples.min(n).max(1);
    let height_limit = if psi <= 2 { 1 } else { (psi as f64).log2().ceil() as usize };
    let rows: Vec<Vec<f64>> = (0..n).map(|r| matrix_row(x, r)).collect();
    let mut rng = Rng::new(seed);
    let mut nodes: Vec<[f64; 5]> = Vec::new();
    let mut roots: Vec<f64> = Vec::with_capacity(n_trees);
    let mut pool: Vec<usize> = (0..n).collect();
    for _ in 0..n_trees {
        for i in 0..psi {
            let j = i + (rng.next_u64() as usize) % (n - i);
            pool.swap(i, j);
        }
        let sample: Vec<usize> = pool[..psi].to_vec();
        let root = iforest_build(&rows, &sample, 0, height_limit, &mut rng, &mut nodes);
        roots.push(root as f64);
    }
    let node_rows: Vec<Vec<f64>> = nodes.iter().map(|nd| nd.to_vec()).collect();
    let node_matrix = Matrix::from_rows(&node_rows).map_err(|se| EvalError { msg: se.to_string() })?;
    Ok((node_matrix, roots, psi as f64))
}

/// The value at fractional position `q` of `sorted` (already ascending),
/// by linear interpolation between neighbours — the quantile rule
/// `contamination=` needs to turn a rate into a score cut-off.
fn sorted_quantile(sorted: &[f64], q: f64) -> f64 {
    if sorted.is_empty() {
        return f64::NAN;
    }
    let pos = q.clamp(0.0, 1.0) * (sorted.len() - 1) as f64;
    let lo = pos.floor() as usize;
    let hi = pos.ceil() as usize;
    if lo == hi {
        sorted[lo]
    } else {
        let frac = pos - lo as f64;
        sorted[lo] * (1.0 - frac) + sorted[hi] * frac
    }
}

/// One entry of a Gaussian-process covariance function, for two rows.
///
/// `"rbf"` (squared exponential) is the default and the one a GP is
/// usually pictured with: infinitely differentiable, so it assumes the
/// underlying function is very smooth. `"matern32"` is the standard
/// less-credulous alternative (once differentiable), which fits
/// measurement data that is continuous but not glass-smooth without the
/// RBF's tendency to over-certify between points.
fn gp_kernel(kind: &str, a: &[f64], b: &[f64], length_scale: f64, sigma_f: f64) -> f64 {
    let d2: f64 = a.iter().zip(b).map(|(u, v)| (u - v) * (u - v)).sum();
    match kind {
        "matern32" => {
            let r = d2.sqrt();
            let s = 3f64.sqrt() * r / length_scale;
            sigma_f * sigma_f * (1.0 + s) * (-s).exp()
        }
        // "rbf"
        _ => sigma_f * sigma_f * (-0.5 * d2 / (length_scale * length_scale)).exp(),
    }
}

/// `L z = b` by forward substitution, `L` lower-triangular.
fn solve_lower(l: &Matrix, b: &[f64]) -> R<Vec<f64>> {
    let n = l.rows();
    let mut z = vec![0.0; n];
    for i in 0..n {
        let mut acc = b[i];
        for j in 0..i {
            acc -= l.get(i, j).unwrap_or(0.0) * z[j];
        }
        let diag = l.get(i, i).unwrap_or(0.0);
        if diag == 0.0 {
            return e("gaussian_process: the kernel matrix is singular — raise `noise=` or `length_scale=`");
        }
        z[i] = acc / diag;
    }
    Ok(z)
}

/// `L^T z = b` by back substitution, with `L` given lower-triangular (so
/// the caller never has to materialize the transpose).
fn solve_lower_transpose(l: &Matrix, b: &[f64]) -> R<Vec<f64>> {
    let n = l.rows();
    let mut z = vec![0.0; n];
    for ii in (0..n).rev() {
        let mut acc = b[ii];
        for j in (ii + 1)..n {
            acc -= l.get(j, ii).unwrap_or(0.0) * z[j];
        }
        let diag = l.get(ii, ii).unwrap_or(0.0);
        if diag == 0.0 {
            return e("gaussian_process: the kernel matrix is singular — raise `noise=` or `length_scale=`");
        }
        z[ii] = acc / diag;
    }
    Ok(z)
}

/// The median of all pairwise distances in `rows` — the standard,
/// data-driven default for a GP's `length_scale` when the caller gives
/// none. A hard-coded `1.0` is wrong the moment the inputs are not in
/// order-1 units (volts vs microvolts vs hertz), and a GP with a
/// length scale far off its data's own spacing either interpolates
/// nothing or interpolates everything — both of which look like a working
/// fit at a glance.
fn median_pairwise_distance(rows: &[Vec<f64>]) -> f64 {
    let n = rows.len();
    if n < 2 {
        return 1.0;
    }
    let mut dists: Vec<f64> = Vec::with_capacity(n * (n - 1) / 2);
    for i in 0..n {
        for j in (i + 1)..n {
            let d2: f64 = rows[i].iter().zip(&rows[j]).map(|(u, v)| (u - v) * (u - v)).sum();
            dists.push(d2.sqrt());
        }
    }
    dists.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    let m = sorted_quantile(&dists, 0.5);
    if m > 0.0 && m.is_finite() {
        m
    } else {
        1.0
    }
}

/// `gaussian_process(X, y, ...)`'s fit: builds the training covariance
/// `K = k(X, X) + noise*I`, factors it once with `qu_core::linalg::
/// cholesky` (the same decomposition `mvnpdf` and the Kalman covariance
/// updates already build on — not a second, hand-rolled one), and keeps
/// `L` plus `alpha = K^-1 (y - mean(y))`. Everything `.predict` needs is
/// then two triangular solves per batch, and the expensive `O(n^3)` step
/// happens exactly once, at fit time.
///
/// `y` is centered on its own mean, because the GP prior mean is zero: a
/// GP fit on un-centered data reverts to 0 far from the training points
/// rather than to the data's own level, which is a visibly wrong forecast
/// and an easy one not to notice near the data.
///
/// Returns `(L, alpha, y_mean, log_marginal_likelihood, effective_noise)`.
#[allow(clippy::type_complexity)]
fn gp_fit(
    rows: &[Vec<f64>],
    y: &[f64],
    kernel: &str,
    length_scale: f64,
    sigma_f: f64,
    noise: f64,
) -> R<(Matrix, Vec<f64>, f64, f64, f64)> {
    let n = rows.len();
    let y_mean = y.iter().sum::<f64>() / n as f64;
    let yc: Vec<f64> = y.iter().map(|v| v - y_mean).collect();
    // A covariance matrix built from near-duplicate rows is positive
    // SEMI-definite in exact arithmetic and indefinite in floating point,
    // so Cholesky legitimately fails on perfectly reasonable data. Raising
    // the jitter and retrying is the standard remedy; the noise level
    // actually used is reported back so `.noise` never lies about it.
    let mut jitter = noise;
    for attempt in 0..6 {
        let mut k = Matrix::zeros(n, n);
        for i in 0..n {
            for j in 0..n {
                let mut v = gp_kernel(kernel, &rows[i], &rows[j], length_scale, sigma_f);
                if i == j {
                    v += jitter;
                }
                let _ = k.set(i, j, v);
            }
        }
        match numeric::linalg::cholesky(&k) {
            Ok(chol) => {
                let l = chol.l;
                let z = solve_lower(&l, &yc)?;
                let alpha = solve_lower_transpose(&l, &z)?;
                let log_det: f64 = (0..n).map(|i| l.get(i, i).unwrap_or(1.0).ln()).sum();
                let quad: f64 = yc.iter().zip(&alpha).map(|(a, b)| a * b).sum();
                let lml = -0.5 * quad - log_det - 0.5 * n as f64 * std::f64::consts::TAU.ln();
                return Ok((l, alpha, y_mean, lml, jitter));
            }
            Err(_) if attempt < 5 => {
                jitter = if jitter > 0.0 { jitter * 100.0 } else { 1e-10 };
            }
            Err(le) => {
                return e(format!(
                    "gaussian_process: the kernel matrix stayed non-positive-definite up to noise={jitter:e} ({le}) — \
                     duplicate rows in X, or a length_scale far larger than the data's own spread, are the usual causes"
                ));
            }
        }
    }
    e("gaussian_process: could not factor the kernel matrix")
}

/// `gp.predict(Xnew)` — the GP posterior at each new row.
///
/// Returns `(mean, variance)`. The variance is the point of a GP over any
/// other regressor, so it is computed on the same pass rather than left to
/// a second call that could be given different hyper-parameters: `var_* =
/// k(x*, x*) - v·v` where `L v = k(X, x*)`. It is small near the training
/// rows (where the data already pins the function down) and rises toward
/// the prior variance `sigma_f^2` far from all of them.
fn gp_posterior(
    train_rows: &[Vec<f64>],
    l: &Matrix,
    alpha: &[f64],
    y_mean: f64,
    xnew: &Matrix,
    kernel: &str,
    length_scale: f64,
    sigma_f: f64,
) -> R<(Vec<f64>, Vec<f64>)> {
    let m = xnew.rows();
    let mut means = Vec::with_capacity(m);
    let mut vars = Vec::with_capacity(m);
    let prior = gp_kernel(kernel, &[0.0], &[0.0], length_scale, sigma_f);
    for r in 0..m {
        let row = matrix_row(xnew, r);
        let ks: Vec<f64> = train_rows
            .iter()
            .map(|tr| gp_kernel(kernel, tr, &row, length_scale, sigma_f))
            .collect();
        let mean: f64 = ks.iter().zip(alpha).map(|(a, b)| a * b).sum::<f64>() + y_mean;
        let v = solve_lower(l, &ks)?;
        let var = prior - v.iter().map(|z| z * z).sum::<f64>();
        means.push(mean);
        // Clamped at zero: the true posterior variance cannot be negative,
        // and a tiny negative value here is round-off in the subtraction,
        // not information.
        vars.push(var.max(0.0));
    }
    Ok((means, vars))
}

/// Unpacks a `"gaussian_process"` handle and evaluates its posterior at
/// `xnew`, returning `(mean, variance)`. The single place both `predict`
/// spellings go through, so the mean a script gets from `.predict(Xnew)`
/// and the mean inside `.predict(Xnew, variance=true)` cannot drift apart.
fn gp_predict_parts(m: &ModelHandle, xnew: &Matrix) -> R<(Vec<f64>, Vec<f64>)> {
    let train = match m.field("x") {
        Some(Value::Mat(xx)) => xx.clone(),
        _ => return e("gaussian_process model is missing its x field"),
    };
    if xnew.cols() != train.cols() {
        return e(format!(
            "predict: model was fit on {} feature(s), input has {} — a single new point \
             needs an explicit orientation, e.g. `[a, b] as matrix(1, 2)`, since a bare \
             vector defaults to a column",
            train.cols(),
            xnew.cols()
        ));
    }
    let l = match m.field("l") {
        Some(Value::Mat(ll)) => ll.clone(),
        _ => return e("gaussian_process model is missing its l field"),
    };
    let alpha = to_vec(m.field("alpha").expect("gaussian_process model always has alpha"))?;
    let y_mean = m.field("y_mean").expect("gaussian_process model always has y_mean").as_num().unwrap_or(0.0);
    let kernel = match m.field("kernel") {
        Some(Value::Str(s)) => s.to_string(),
        _ => "rbf".to_string(),
    };
    let length_scale = m.field("length_scale").expect("gaussian_process model always has length_scale").as_num().unwrap_or(1.0);
    let sigma_f = m.field("sigma_f").expect("gaussian_process model always has sigma_f").as_num().unwrap_or(1.0);
    let train_rows: Vec<Vec<f64>> = (0..train.rows()).map(|r| matrix_row(&train, r)).collect();
    gp_posterior(&train_rows, &l, &alpha, y_mean, xnew, &kernel, length_scale, sigma_f)
}

/// `||X - W H||_F`, the Frobenius reconstruction error NMF minimizes.
fn nmf_error(x: &Matrix, w: &Matrix, h: &Matrix) -> f64 {
    let (n, d) = x.shape();
    let k = h.rows();
    let mut acc = 0.0;
    for i in 0..n {
        for j in 0..d {
            let mut wh = 0.0;
            for c in 0..k {
                wh += w.get(i, c).unwrap_or(0.0) * h.get(c, j).unwrap_or(0.0);
            }
            let diff = x.get(i, j).unwrap_or(0.0) - wh;
            acc += diff * diff;
        }
    }
    acc.sqrt()
}

/// One multiplicative update of `W` with `H` held fixed:
/// `W <- W * (X H^T) / (W H H^T + eps)` (Lee & Seung 2001, Frobenius
/// objective). Shared by the fit loop and by `.predict`, which is exactly
/// this same update run on new rows against the ALREADY fitted `H` —
/// having one function rather than two is what keeps "transform new data"
/// and "fit" from silently diverging.
fn nmf_update_w(x: &Matrix, w: &mut Matrix, h: &Matrix) {
    const EPS: f64 = 1e-10;
    let (n, d) = x.shape();
    let k = h.rows();
    // (k, k) = H H^T, formed once per update rather than per element.
    let mut hht = vec![0.0; k * k];
    for a in 0..k {
        for b in 0..k {
            let mut acc = 0.0;
            for j in 0..d {
                acc += h.get(a, j).unwrap_or(0.0) * h.get(b, j).unwrap_or(0.0);
            }
            hht[a * k + b] = acc;
        }
    }
    for i in 0..n {
        // (k,) = X_i H^T
        let mut xht = vec![0.0; k];
        for a in 0..k {
            let mut acc = 0.0;
            for j in 0..d {
                acc += x.get(i, j).unwrap_or(0.0) * h.get(a, j).unwrap_or(0.0);
            }
            xht[a] = acc;
        }
        let w_row: Vec<f64> = (0..k).map(|c| w.get(i, c).unwrap_or(0.0)).collect();
        for a in 0..k {
            let denom: f64 = (0..k).map(|b| w_row[b] * hht[b * k + a]).sum::<f64>() + EPS;
            let _ = w.set(i, a, w_row[a] * xht[a] / denom);
        }
    }
}

/// `H <- H * (W^T X) / (W^T W H + eps)`, the companion half of the same
/// multiplicative scheme.
fn nmf_update_h(x: &Matrix, w: &Matrix, h: &mut Matrix) {
    const EPS: f64 = 1e-10;
    let (n, d) = x.shape();
    let k = h.rows();
    let mut wtw = vec![0.0; k * k];
    for a in 0..k {
        for b in 0..k {
            let mut acc = 0.0;
            for i in 0..n {
                acc += w.get(i, a).unwrap_or(0.0) * w.get(i, b).unwrap_or(0.0);
            }
            wtw[a * k + b] = acc;
        }
    }
    for j in 0..d {
        let mut wtx = vec![0.0; k];
        for a in 0..k {
            let mut acc = 0.0;
            for i in 0..n {
                acc += w.get(i, a).unwrap_or(0.0) * x.get(i, j).unwrap_or(0.0);
            }
            wtx[a] = acc;
        }
        let h_col: Vec<f64> = (0..k).map(|c| h.get(c, j).unwrap_or(0.0)).collect();
        for a in 0..k {
            let denom: f64 = (0..k).map(|b| wtw[a * k + b] * h_col[b]).sum::<f64>() + EPS;
            let _ = h.set(a, j, h_col[a] * wtx[a] / denom);
        }
    }
}

/// `nmf(X, ...)`'s fit — alternating multiplicative updates until the
/// relative improvement in `||X - WH||_F` drops below `tol` or `max_iter`
/// is reached. Returns `(W, H, per-iteration errors)`.
///
/// The updates are multiplicative, so a factor entry that starts positive
/// stays positive and non-negativity is maintained for free — no
/// projection, no clipping. That is the whole reason this algorithm, and
/// not plain gradient descent, is the standard one.
fn nmf_fit(
    x: &Matrix,
    k: usize,
    max_iter: usize,
    tol: f64,
    seed: u64,
) -> R<(Matrix, Matrix, Vec<f64>)> {
    let (n, d) = x.shape();
    if k == 0 || k > n.min(d) {
        return e(format!(
            "nmf: n_components={k} must be between 1 and min(rows, cols) = {}",
            n.min(d)
        ));
    }
    if let Some(bad) = x.as_slice().iter().find(|v| **v < 0.0 || !v.is_finite()) {
        return e(format!(
            "nmf: X must be non-negative and finite (found {bad}) — NMF is defined only on non-negative data"
        ));
    }
    // Scaled random init (the `sqrt(mean(X)/k)` scale is the conventional
    // one): it puts `W H` in the right ballpark immediately, so the first
    // few updates are not spent on magnitude alone.
    let mean = x.as_slice().iter().sum::<f64>() / (n * d).max(1) as f64;
    let scale = (mean.max(1e-12) / k as f64).sqrt();
    let mut rng = Rng::new(seed);
    let mut w = Matrix::zeros(n, k);
    let mut h = Matrix::zeros(k, d);
    for i in 0..n {
        for c in 0..k {
            let _ = w.set(i, c, scale * (rng.uniform() + 0.1));
        }
    }
    for c in 0..k {
        for j in 0..d {
            let _ = h.set(c, j, scale * (rng.uniform() + 0.1));
        }
    }
    let mut errors: Vec<f64> = Vec::new();
    let mut prev = f64::INFINITY;
    for _ in 0..max_iter.max(1) {
        nmf_update_h(x, &w, &mut h);
        nmf_update_w(x, &mut w, &h);
        let err = nmf_error(x, &w, &h);
        errors.push(err);
        if prev.is_finite() && prev > 0.0 && (prev - err) / prev < tol {
            break;
        }
        prev = err;
    }
    Ok((w, h, errors))
}

/// `d`-th order differencing of `x`, keeping the last value of every
/// intermediate level so a forecast can be integrated back up.
/// Returns `(differenced series, last value at each level 0..d)`.
fn difference_series(x: &[f64], d: usize) -> (Vec<f64>, Vec<f64>) {
    let mut cur = x.to_vec();
    let mut levels = Vec::with_capacity(d);
    for _ in 0..d {
        levels.push(*cur.last().unwrap_or(&0.0));
        cur = cur.windows(2).map(|w| w[1] - w[0]).collect();
    }
    (cur, levels)
}

/// `arima(x, p=, d=, q=)`'s fit, by Hannan–Rissanen: the standard two-stage
/// estimator, and the one that is honest about what it is.
///
/// Stage 1 fits a long pure-AR model by least squares to get usable
/// estimates of the unobservable shocks `e_t`. Stage 2 then regresses the
/// differenced series on its own lags AND those estimated shocks, which
/// turns MA estimation — genuinely a nonlinear problem — into one more
/// linear least-squares solve on `qu_core::linalg::least_squares`, the same
/// solver `ar_model` and `ridge` already use.
///
/// This is NOT exact maximum likelihood (what R's `arima()` defaults to),
/// and the difference shows up as slightly different coefficients on short
/// series. It is stated here rather than glossed: Hannan–Rissanen is
/// consistent, is what most textbooks present as *the* practical ARMA
/// estimator, and needs no optimizer to go wrong silently.
///
/// Returns `(ar coefficients, ma coefficients, mu, fitted, residuals)` in
/// the differenced series' own space.
#[allow(clippy::type_complexity)]
fn arima_fit(
    z: &[f64],
    p: usize,
    q: usize,
) -> R<(Vec<f64>, Vec<f64>, f64, Vec<f64>, Vec<f64>)> {
    let n = z.len();
    let mu = z.iter().sum::<f64>() / n as f64;
    let zc: Vec<f64> = z.iter().map(|v| v - mu).collect();

    // Stage 1: a long AR whose residuals stand in for the shocks. Order
    // grows with the series (the usual `log(n)^1.something` rule of thumb),
    // capped so the design matrix stays well-determined.
    let stage1_order = if q > 0 {
        ((n as f64).ln().powf(1.5).ceil() as usize)
            .max(p + q + 1)
            .min(n / 3)
            .max(1)
    } else {
        0
    };
    let mut resid_est = vec![0.0; n];
    if q > 0 {
        let m = stage1_order;
        if n <= m + 1 {
            return e(format!(
                "arima: series has {n} differenced point(s) — too few to estimate an MA part of order {q}"
            ));
        }
        let design_rows: Vec<Vec<f64>> = (m..n).map(|t| (1..=m).map(|j| zc[t - j]).collect()).collect();
        let target: Vec<f64> = (m..n).map(|t| zc[t]).collect();
        let design = Matrix::from_rows(&design_rows).map_err(|se| EvalError { msg: se.to_string() })?;
        let observed = Matrix::from_column(&target);
        let phi = numeric::linalg::least_squares(&design, &observed, None)
            .map_err(|le| EvalError { msg: format!("arima: stage-1 AR fit failed ({le})") })?;
        let phi = phi.as_slice().to_vec();
        for t in m..n {
            let pred: f64 = (1..=m).map(|j| phi[j - 1] * zc[t - j]).sum();
            resid_est[t] = zc[t] - pred;
        }
    }

    // Stage 2: regress on `p` own lags and `q` estimated shock lags at once.
    let start = p.max(q).max(stage1_order);
    if n <= start + p.max(q) || n <= start + 1 {
        return e(format!(
            "arima: series has {n} differenced point(s) — too few for p={p}, q={q}"
        ));
    }
    let width = p + q;
    if width == 0 {
        // ARIMA(0, d, 0): the differenced series is white noise about `mu`.
        let fitted = vec![mu; n];
        let residuals: Vec<f64> = z.iter().map(|v| v - mu).collect();
        return Ok((Vec::new(), Vec::new(), mu, fitted, residuals));
    }
    let design_rows: Vec<Vec<f64>> = (start..n)
        .map(|t| {
            let mut row = Vec::with_capacity(width);
            for j in 1..=p {
                row.push(zc[t - j]);
            }
            for j in 1..=q {
                row.push(resid_est[t - j]);
            }
            row
        })
        .collect();
    let target: Vec<f64> = (start..n).map(|t| zc[t]).collect();
    let design = Matrix::from_rows(&design_rows).map_err(|se| EvalError { msg: se.to_string() })?;
    let observed = Matrix::from_column(&target);
    let theta = numeric::linalg::least_squares(&design, &observed, None)
        .map_err(|le| EvalError { msg: format!("arima: stage-2 ARMA fit failed ({le})") })?;
    let theta = theta.as_slice().to_vec();
    if theta.iter().any(|v| !v.is_finite()) {
        return e("arima: the fit produced non-finite coefficients (the series may be constant, or p/q too large for its length)");
    }
    let ar: Vec<f64> = theta[..p].to_vec();
    let ma: Vec<f64> = theta[p..].to_vec();

    // In-sample one-step-ahead fit, with the residuals regenerated from
    // the FINAL coefficients (not stage 1's) so `.residuals` describes the
    // model actually returned.
    let mut resid = vec![0.0; n];
    let mut fitted = vec![mu; n];
    for t in start..n {
        let ar_part: f64 = (1..=p).map(|j| ar[j - 1] * zc[t - j]).sum();
        let ma_part: f64 = (1..=q).map(|j| ma[j - 1] * resid[t - j]).sum();
        fitted[t] = mu + ar_part + ma_part;
        resid[t] = zc[t] - ar_part - ma_part;
    }
    Ok((ar, ma, mu, fitted, resid))
}

/// `arima_model.predict(n_ahead)` — forecasts the differenced series
/// recursively (future shocks are zero, which is what a conditional
/// expectation of an unobserved mean-zero innovation IS, and past shocks
/// come from the fit's own residual tail), then integrates the result back
/// up through `d` levels of differencing to return values in the ORIGINAL
/// series' units. Forecasting the differences and handing those back would
/// be the classic off-by-a-transform bug.
fn arima_predict(m: &ModelHandle, n_ahead: usize) -> R<Value> {
    let ar = to_vec(m.field("ar").expect("arima model always has ar"))?;
    let ma = to_vec(m.field("ma").expect("arima model always has ma"))?;
    let mu = m.field("mu").expect("arima model always has mu").as_num().unwrap_or(0.0);
    let mut history = to_vec(m.field("history").expect("arima model always has history"))?;
    let mut shocks = to_vec(m.field("shock_history").expect("arima model always has shock_history"))?;
    let levels = to_vec(m.field("levels").expect("arima model always has levels"))?;
    let p = ar.len();
    let q = ma.len();
    let mut out = Vec::with_capacity(n_ahead);
    for _ in 0..n_ahead {
        let h = history.len();
        let s = shocks.len();
        let ar_part: f64 = (1..=p).map(|j| ar[j - 1] * (history[h - j] - mu)).sum();
        let ma_part: f64 = (1..=q).map(|j| ma[j - 1] * shocks[s - j]).sum();
        let next = mu + ar_part + ma_part;
        out.push(next);
        history.push(next);
        // The forecast's own shock is zero by construction: there is no
        // future observation to take a residual against.
        shocks.push(0.0);
    }
    // Integrate: `levels[i]` is the last observed value of the i-th
    // difference (level 0 = the original series), so running a cumulative
    // sum from the innermost level outward undoes exactly the `d`
    // differences taken at fit time.
    for i in (0..levels.len()).rev() {
        let mut acc = levels[i];
        for v in out.iter_mut() {
            acc += *v;
            *v = acc;
        }
    }
    Ok(Value::Vec(Arc::new(out)))
}

fn matrix_row(x: &Matrix, r: usize) -> Vec<f64> {
    (0..x.cols()).map(|c| x.get(r, c).unwrap_or(0.0)).collect()
}

/// The numeric core of `conv1d`, for one 1-D sequence: "valid" (no padding,
/// stride 1) cross-correlation — the operation every ML framework actually
/// means by "conv1d" (kernel is applied as-is, not spatially flipped the way
/// textbook/DSP convolution is defined; matching that convention, not the
/// signal-processing one, is what makes a *learned* kernel meaningful here).
/// `out[i] = sum_j x[i+j] * k[j]`, for `i` in `0..=(x.len()-k.len())`.
fn conv1d_row(x: &[f64], k: &[f64]) -> Vec<f64> {
    if x.len() < k.len() {
        return Vec::new();
    }
    let out_len = x.len() - k.len() + 1;
    (0..out_len)
        .map(|i| (0..k.len()).map(|j| x[i + j] * k[j]).sum())
        .collect()
}

/// `conv1d(x, kernel)` forward pass — see the `"conv1d"` builtin's doc
/// comment for the full scope (single output channel, stride 1, no padding).
/// `x` a lone sequence (`Value::Vec`) convolves straight to a `Value::Vec`;
/// `x` a batch (`Value::Mat`, one sequence per row — the same row-major
/// batch convention `train_test_split`/`k_fold` use elsewhere) convolves
/// each row independently against the SAME shared kernel (real weight
/// sharing, not a per-row kernel) and stacks the results back into a
/// `Value::Mat`.
fn conv1d_forward(x: &Value, k: &[f64]) -> R<Value> {
    match x {
        Value::Vec(xs) => {
            if xs.len() < k.len() {
                return e("conv1d: kernel is longer than the input sequence");
            }
            Ok(Value::Vec(Arc::new(conv1d_row(xs, k))))
        }
        Value::Mat(m) => {
            let (rows, cols) = m.shape();
            if cols < k.len() {
                return e("conv1d: kernel is longer than each row's sequence length");
            }
            let out_rows: Vec<Vec<f64>> = (0..rows)
                .map(|r| conv1d_row(&matrix_row(m, r), k))
                .collect();
            Ok(mat_value(Matrix::from_rows(&out_rows).map_err(|se| EvalError { msg: se.to_string() })?))
        }
        other => e(format!("conv1d: expected a Vec or Mat sequence, found {}", other.type_name())),
    }
}

/// `conv1d`'s backward numeric core, for one row: given the row's original
/// input `x`, the shared `kernel`, and the upstream adjoint for that row's
/// output, returns `(dx, dk)` — the local gradient w.r.t. that row's slice
/// of `x` and w.r.t. the kernel. Every output position `i` touched
/// `x[i..i+K]` scaled by `k`, so by the product rule each contributes
/// `upstream[i] * k[j]` to `dx[i+j]` and `upstream[i] * x[i+j]` to `dk[j]` —
/// summed over `i` since `k[j]` (and, within a row, several `x` positions)
/// feeds more than one output element.
fn conv1d_backward_row(x: &[f64], k: &[f64], upstream: &[f64]) -> (Vec<f64>, Vec<f64>) {
    let mut dx = vec![0.0; x.len()];
    let mut dk = vec![0.0; k.len()];
    for (i, &u) in upstream.iter().enumerate() {
        for (j, &kj) in k.iter().enumerate() {
            dx[i + j] += u * kj;
            dk[j] += u * x[i + j];
        }
    }
    (dx, dk)
}

/// Read one logical "row" out of any value `conv1d_forward` might have
/// produced or consumed — `Value::Mat` via the real `matrix_row` (its
/// column-major layout means a naive `to_vec` flatten is NOT row order),
/// `Value::Vec` as its one and only row, and `Value::Num` as `mat_value`'s
/// own 1x1-collapse case (a batch of exactly one row and one output
/// position collapses a `Mat` result down to a bare scalar, same as
/// anywhere else `mat_value` is used) — so `conv1d`'s backward pass can
/// treat a batched `Value::Mat` input's upstream adjoint uniformly even
/// when that adjoint arrives already collapsed.
fn value_row(v: &Value, r: usize) -> Vec<f64> {
    match v {
        Value::Mat(m) => matrix_row(m, r),
        Value::Vec(xs) => xs.as_ref().clone(),
        Value::Num(n) => vec![*n],
        _ => Vec::new(),
    }
}

/// Reads one named field out of a `Value::Record` (the `{a = 1, b = 2}`
/// literal type — see its own doc comment) — the lookup `gru_cell_compute`
/// uses to pull `wz`/`uz`/`bz`/... out of a GRU's weights bundle. A plain
/// linear scan, same as `eval_field`'s own `Value::Record` arm: fine for
/// the handful of fields a weights record actually has, and there's no
/// reason to duplicate `eval_field`'s own error message shape here beyond
/// naming which builtin's argument was wrong.
fn record_field(v: &Value, name: &str) -> R<Value> {
    match v {
        Value::Record(fields) => fields
            .iter()
            .find(|(k, _)| k == name)
            .map(|(_, v)| v.clone())
            .ok_or_else(|| EvalError {
                msg: format!("gru: weights record is missing field `{name}`"),
            }),
        other => e(format!(
            "gru: expected a weights record (from gru_init, or a matching {{wz=..., uz=..., ...}} literal), found {}",
            other.type_name()
        )),
    }
}

/// Same lookup as [`record_field`] above (kept as its own function, not a
/// generalized shared one, since `record_field`'s error wording is GRU-
/// specific) — for LSTM's two use sites: reading a gate's weight out of
/// the `weights` record `lstm_cell`/`lstm_forward` take, and reading `h`/
/// `c` back out of `lstm_cell_compute`'s own `{h, c}` return record.
fn lstm_field(v: &Value, name: &str) -> R<Value> {
    match v {
        Value::Record(fields) => fields
            .iter()
            .find(|(k, _)| k == name)
            .map(|(_, v)| v.clone())
            .ok_or_else(|| EvalError {
                msg: format!("lstm: record is missing field `{name}`"),
            }),
        other => e(format!(
            "lstm: expected a record (a weights record from lstm_init, or an {{h, c}} cell-state pair), found {}",
            other.type_name()
        )),
    }
}

/// Same lookup as [`record_field`] above, for `profile_end`'s one
/// argument -- the record `profile_start()` returned. Reads back as
/// `f64` directly since both of `profile_start`'s fields (`t0`/`mem0`)
/// are always numbers it wrote itself; a non-`Record` or a record
/// missing the field means the caller passed something other than a
/// genuine, unmodified `profile_start()` result.
fn profile_field(v: &Value, name: &str) -> R<f64> {
    match v {
        Value::Record(fields) => fields
            .iter()
            .find(|(k, _)| k == name)
            .map(|(_, v)| v.clone())
            .ok_or_else(|| EvalError {
                msg: format!(
                    "profile_end: handle is missing field `{name}` -- pass the record profile_start() returned, unmodified"
                ),
            })
            .and_then(|v| match v {
                Value::Num(n) => Ok(n),
                other => e(format!(
                    "profile_end: handle field `{name}` should be a number, found {}",
                    other.type_name()
                )),
            }),
        other => e(format!(
            "profile_end: expected the record profile_start() returned, found {}",
            other.type_name()
        )),
    }
}

/// Same lookup as [`record_field`] above, for the transformer/attention
/// builtins' own weights records (`{wq, wk, wv, wo}` per head,
/// `{heads, ln1_gamma, ..., w2, b2}` for `transformer_block`) — kept as a
/// separate function (not a shared rename of `record_field`) purely so a
/// missing-field error names the right feature instead of pointing a
/// transformer script at `gru_init`.
fn mha_field(v: &Value, name: &str) -> R<Value> {
    match v {
        Value::Record(fields) => fields
            .iter()
            .find(|(k, _)| k == name)
            .map(|(_, v)| v.clone())
            .ok_or_else(|| EvalError {
                msg: format!("expected a weights record with field `{name}`"),
            }),
        other => e(format!(
            "expected a weights record (e.g. a {{wq=..., wk=..., wv=..., wo=...}} literal), found {}",
            other.type_name()
        )),
    }
}

/// A `rows x cols` matrix of iid `N(0, std^2)` samples — `gru_init`'s
/// weight initializer. A free function (not an `Interp` method) taking
/// `rng: &mut Rng` directly rather than `&mut self`, purely so
/// `"gru_init"`'s builtin arm can call it six times in a row (once per
/// weight matrix) without each call fighting the borrow checker over a
/// second `&mut self` borrow the way a closure capturing `self` would.
fn random_matrix(rng: &mut Rng, rows: usize, cols: usize, std: f64) -> Matrix {
    let mut m = Matrix::zeros(rows, cols);
    for r in 0..rows {
        for c in 0..cols {
            let _ = m.set(r, c, rng.normal_with(0.0, std));
        }
    }
    m
}

// --------------------------------- Sequential model (2026-08-25) — see the
// `"dense_layer"`/`"sequential"`/`"forward"` builtin arms' own doc comments
// for the user-facing contract; everything below is the shared machinery
// those arms and `"predict"`/`"fit"`'s `"sequential"` branches call into.

/// Same lookup as [`record_field`]/[`mha_field`] above, for a Sequential
/// layer spec or per-layer weights `Record` — kept separate purely so a
/// missing-field error names this feature rather than GRU's or the
/// transformer's.
fn seq_field(v: &Value, name: &str) -> R<Value> {
    match v {
        Value::Record(fields) => fields
            .iter()
            .find(|(k, _)| k == name)
            .map(|(_, v)| v.clone())
            .ok_or_else(|| EvalError {
                msg: format!("sequential: layer spec is missing field `{name}`"),
            }),
        other => e(format!(
            "sequential: expected a layer-spec record (from dense_layer/dropout_layer), found {}",
            other.type_name()
        )),
    }
}

/// `sequential(...)`'s per-layer weight initializer — a free function (not
/// an `Interp` method) taking `interp: &mut Interp` explicitly, the same
/// "avoid fighting the borrow checker across a loop of calls" reasoning as
/// `random_matrix`'s own doc comment. `"dense"` gets a `{w, b}` weights
/// `Record` (`w` is `(in_dim, out_dim)` so `dense(x, w, b)` == `x @ w + b`
/// needs no transpose); `w` is scaled-random-normal — He (`sqrt(2/in_dim)`)
/// when the layer's own `activation` is `"relu"` (matching the ReLU
/// convention `gru_init`'s own doc comment gestures at for CNN work), a
/// milder Xavier-ish `sqrt(1/in_dim)` otherwise — and `b` starts at zero,
/// the standard convention every real framework uses. `"dropout"` has no
/// weights at all: an empty `Record`, kept in the params list purely so
/// `sequential_forward` can zip `layers`/`params` by index without a
/// separate "does this layer have params" branch.
fn sequential_init_layer(interp: &mut Interp, layer: &Value) -> R<Value> {
    let kind = match seq_field(layer, "kind")? {
        Value::Str(s) => s,
        other => return e(format!("sequential: layer `kind` must be a string, found {}", other.type_name())),
    };
    match kind.as_str() {
        "dense" => {
            let in_dim = seq_field(layer, "in_dim")?.as_index().map_err(|msg| EvalError { msg })?;
            let out_dim = seq_field(layer, "out_dim")?.as_index().map_err(|msg| EvalError { msg })?;
            let activation = match seq_field(layer, "activation") {
                Ok(Value::Str(s)) => s,
                _ => "none".to_string(),
            };
            let std = if activation == "relu" {
                (2.0 / in_dim as f64).sqrt()
            } else {
                (1.0 / in_dim as f64).sqrt()
            };
            let w = mat_value(random_matrix(&mut interp.rng, in_dim, out_dim, std));
            let b = Value::Vec(Arc::new(vec![0.0; out_dim]));
            Ok(Value::Record(Arc::new(vec![("w".to_string(), w), ("b".to_string(), b)])))
        }
        "dropout" => Ok(Value::Record(Arc::new(Vec::new()))),
        other => e(format!(
            "sequential: unsupported layer kind `{other}` (from dense_layer/dropout_layer)"
        )),
    }
}

/// Runs `x_in` through every `(layer spec, layer params)` pair in order —
/// the shared core behind `net.forward(x)` (`training=true`) and
/// `net.predict(x)`/the training loop's own forward pass (`training=false`/
/// `true` respectively). `"dense"` layers compute `dense(h, w, b)` then
/// apply the spec's `activation` (`relu` or none); `"dropout"` layers apply
/// `dropout(h, rate)` ONLY when `training` (inference is always the
/// identity — the standard train/eval-mode distinction every real
/// framework makes). When `training`, each `"dense"` layer's stored plain
/// `w`/`b` are freshly wrapped via `param()` (a new tape leaf) rather than
/// reused across calls — the exact manual `W1 = param(W1_init)` idiom
/// `benchmarks/mlp/bench.qu`/the GRU/CNN acceptance tests already use by
/// hand, needed because a tape node from a PREVIOUS call is meaningless
/// once that earlier call's tape state is gone. Every such leaf is
/// appended to `leaves` as `(layer_index, "w"|"b", the Tensor)`, in
/// creation order — `sequential_fit` reads `leaves` back to know exactly
/// which tensors to `grad()` against and where each gradient's update
/// belongs.
fn sequential_forward(
    interp: &mut Interp,
    layers: &[Value],
    params: &[Value],
    x_in: Value,
    training: bool,
    leaves: &mut Vec<(usize, &'static str, Value)>,
) -> R<Value> {
    if layers.len() != params.len() {
        return e("sequential: layers/params length mismatch (corrupt model)");
    }
    let mut h = x_in;
    for (idx, (layer, p)) in layers.iter().zip(params.iter()).enumerate() {
        let kind = match seq_field(layer, "kind")? {
            Value::Str(s) => s,
            other => return e(format!("sequential: layer `kind` must be a string, found {}", other.type_name())),
        };
        match kind.as_str() {
            "dense" => {
                let w_plain = seq_field(p, "w")?;
                let b_plain = seq_field(p, "b")?;
                let (w, b) = if training {
                    let wt = interp.call_builtin("param", vec![w_plain], None, Vec::new())?;
                    let bt = interp.call_builtin("param", vec![b_plain], None, Vec::new())?;
                    leaves.push((idx, "w", wt.clone()));
                    leaves.push((idx, "b", bt.clone()));
                    (wt, bt)
                } else {
                    (w_plain, b_plain)
                };
                h = interp.call_builtin("dense", vec![h, w, b], None, Vec::new())?;
                let activation = match seq_field(layer, "activation") {
                    Ok(Value::Str(s)) => s,
                    _ => "none".to_string(),
                };
                if activation == "relu" {
                    h = interp.call_builtin("relu", vec![h], None, Vec::new())?;
                }
            }
            "dropout" => {
                if training {
                    let rate = seq_field(layer, "rate")?.as_num().map_err(|msg| EvalError { msg })?;
                    h = interp.call_builtin("dropout", vec![h], None, vec![("rate".to_string(), Value::Num(rate))])?;
                }
            }
            other => return e(format!("sequential: unsupported layer kind `{other}`")),
        }
    }
    Ok(h)
}

/// `net.predict(X)` — `sequential_forward` with `training=false` (no
/// `param()` wrapping, dropout off), then unwraps any residual
/// `Value::Tensor` back to a plain value (defensive: only triggers if `X`
/// itself arrived already `Tensor`-wrapped, since a `training=false` pass
/// never wraps anything on its own) — the task's "returns plain values not
/// Tensors" contract.
fn sequential_predict(interp: &mut Interp, m: &ModelHandle, xnew: &Value) -> R<Value> {
    let layers = match m.field("layers") {
        Some(Value::List(l)) => l.clone(),
        _ => return e("predict: sequential model is missing its layers field"),
    };
    let params = match m.field("params") {
        Some(Value::List(l)) => l.clone(),
        _ => return e("predict: sequential model is missing its params field"),
    };
    let mut leaves = Vec::new();
    let out = sequential_forward(interp, &layers, &params, xnew.clone(), false, &mut leaves)?;
    Ok(untensor(out).0)
}

/// `tensor_binop`/`binop` dispatch, mirroring `eval`'s own `Expr::Binary`
/// arm (see its doc comment) — used by `sequential_loss` and `sequential_
/// fit`'s per-param update since neither runs through the AST evaluator.
fn auto_binop(interp: &mut Interp, op: &str, a: Value, b: Value) -> R<Value> {
    if matches!(a, Value::Tensor(_)) || matches!(b, Value::Tensor(_)) {
        interp.tensor_binop(op, a, b)
    } else {
        interp.binop(op, a, b)
    }
}

/// `net.fit(...)`'s loss function, built entirely from already-tensor-aware
/// builtins (`softmax_rows`/`ln`/`row_sum`/`mean` — see `TENSOR_MATH1`/the
/// transformer work's own doc comments) plus `auto_binop`, so the result is
/// a tracked `Value::Tensor` whenever `pred` is — exactly the same
/// composition `benchmarks/mlp/bench.qu` writes out by hand:
/// `"mse"`: `mean((pred - y) .* (pred - y))`, elementwise over every
/// output unit (a plain regression loss, e.g. XOR's single sigmoid-free
/// output). `"cross_entropy"`: `-mean(row_sum(y .* ln(softmax_rows(pred) +
/// 1e-9)))` — `pred` is expected to be raw logits (the last layer should
/// have `activation="none"`), `y` one-hot rows, matching every real
/// framework's "loss owns the final softmax" convention.
fn sequential_loss(interp: &mut Interp, kind: &str, pred: Value, y: Value) -> R<Value> {
    match kind {
        "mse" => {
            let diff = auto_binop(interp, "-", pred, y)?;
            let sq = auto_binop(interp, ".*", diff.clone(), diff)?;
            interp.call_builtin("mean", vec![sq], None, Vec::new())
        }
        "cross_entropy" => {
            let probs = interp.call_builtin("softmax_rows", vec![pred], None, Vec::new())?;
            let probs_eps = auto_binop(interp, "+", probs, Value::Num(1e-9))?;
            let logp = interp.call_builtin("ln", vec![probs_eps], None, Vec::new())?;
            let prod = auto_binop(interp, ".*", y, logp)?;
            let ce = interp.call_builtin("row_sum", vec![prod], None, Vec::new())?;
            let mean_ce = interp.call_builtin("mean", vec![ce], None, Vec::new())?;
            auto_binop(interp, "-", Value::Num(0.0), mean_ce)
        }
        other => e(format!("fit: loss must be \"mse\" or \"cross_entropy\", got \"{other}\"")),
    }
}

/// The DEFAULT, always-on [`TensorBackend`] implementation (2026-08-26,
/// `backend-torch` vertical slice — see `tensor_backend.rs`'s own module doc
/// comment for the full design). A THIN wrapper: every method just calls
/// the SAME `param`/`dense`/`relu`/`eval_grad`/`sgd_update_inplace`/
/// `flat_to_value`/`untensor`/`to_vec` machinery `sequential_fit` already
/// used before this trait existed — zero new math, zero behavior change.
/// Exists so `train_dense_mlp` can be proven against two real backends
/// through one shared code path; `sequential_fit`'s own native loop below
/// does NOT route through this (see that function's doc comment) — this is
/// only exercised by `sequential_fit_torch`'s tests and any caller that
/// explicitly wants the trait-generic path on the native side.
///
/// Never constructed by a `--release` build (tests aren't compiled into
/// one) -- that is the design working as documented above, not a gap.
#[allow(dead_code)]
struct NativeBackend<'a> {
    interp: &'a mut Interp,
}

impl<'a> TensorBackend for NativeBackend<'a> {
    type T = Value;

    fn from_rows(&mut self, rows: usize, cols: usize, data: Vec<f64>) -> R<Value> {
        if data.len() != rows * cols {
            return e(format!("NativeBackend: expected {} elements for a {rows}x{cols} tensor, got {}", rows * cols, data.len()));
        }
        if rows == 1 {
            // Matches `sequential_init_layer`'s own convention: a
            // single-row shape (a bias vector, or a lone sample) is a
            // plain `Value::Vec`, not a 1xN `Value::Mat` -- `dense`/
            // `binop`'s row-broadcast rules already treat a `Vec` as a
            // row, and `sequential_init_layer` stores biases as `Vec`.
            Ok(Value::Vec(Arc::new(data)))
        } else {
            let rows_data: Vec<Vec<f64>> = data.chunks(cols).map(|c| c.to_vec()).collect();
            Ok(mat_value(Matrix::from_rows(&rows_data).map_err(|se| EvalError { msg: se.to_string() })?))
        }
    }

    fn to_rows(&mut self, t: &Value) -> R<(usize, usize, Vec<f64>)> {
        let (plain, _) = untensor(t.clone());
        match &plain {
            Value::Num(n) => Ok((1, 1, vec![*n])),
            Value::Vec(v) => Ok((1, v.len(), v.as_ref().clone())),
            Value::Mat(m) => {
                let (r, c) = m.shape();
                let mut data = Vec::with_capacity(r * c);
                for row in 0..r {
                    data.extend(m.row_vec(row).map_err(|se| EvalError { msg: se.to_string() })?);
                }
                Ok((r, c, data))
            }
            other => e(format!("NativeBackend: expected a Num/Vec/Mat/Tensor, found {}", other.type_name())),
        }
    }

    fn param(&mut self, t: Value) -> R<Value> {
        self.interp.call_builtin("param", vec![t], None, Vec::new())
    }

    fn dense(&mut self, x: &Value, w: &Value, b: &Value) -> R<Value> {
        self.interp.call_builtin("dense", vec![x.clone(), w.clone(), b.clone()], None, Vec::new())
    }

    fn relu(&mut self, x: &Value) -> R<Value> {
        self.interp.call_builtin("relu", vec![x.clone()], None, Vec::new())
    }

    fn mse(&mut self, pred: &Value, y: &Value) -> R<Value> {
        sequential_loss(self.interp, "mse", pred.clone(), y.clone())
    }

    fn backward_and_grads(&mut self, loss: &Value, params: &[Value]) -> R<Vec<Value>> {
        let grads = self.interp.eval_grad(loss.clone(), Value::List(Arc::new(params.to_vec())))?;
        match grads {
            Value::List(l) => Ok(l.iter().cloned().collect()),
            other => Ok(vec![other]),
        }
    }

    fn sgd_update(&mut self, param: &Value, grad: &Value, lr: f64) -> R<Value> {
        let (plain, _) = untensor(param.clone());
        let mut flat = to_vec(&plain)?;
        let g_flat = to_vec(grad)?;
        sgd_update_inplace(&mut flat, &g_flat, lr)?;
        flat_to_value(&plain, &flat)
    }

    fn scalar(&mut self, t: &Value) -> R<f64> {
        to_vec(t)?.first().copied().ok_or_else(|| EvalError { msg: "NativeBackend: empty loss tensor".into() })
    }

    // ---- Extended surface (2026-08-26, conv2d/GRU/attention follow-on) —
    // see `TensorBackend`'s own doc comments for each method's exact
    // scope/shape contract. Every one of these is "nearly free plumbing"
    // exactly like the original six above: it calls the SAME already-
    // gradient-checked native builtin (`call_builtin`) or tracked-op helper
    // (`auto_binop`/`trr`/`tt`) `sequential_fit`/`simple_cnn_fit`/
    // `simple_rnn_forward`/the transformer builtins already use elsewhere
    // in this file — zero new math on the native side.

    fn elementwise_mul(&mut self, a: &Value, b: &Value) -> R<Value> {
        auto_binop(self.interp, ".*", a.clone(), b.clone())
    }

    fn add(&mut self, a: &Value, b: &Value) -> R<Value> {
        auto_binop(self.interp, "+", a.clone(), b.clone())
    }

    fn matmul(&mut self, a: &Value, b: &Value) -> R<Value> {
        auto_binop(self.interp, "*", a.clone(), b.clone())
    }

    fn sum_all(&mut self, t: &Value) -> R<Value> {
        self.interp.call_builtin("sum", vec![t.clone()], None, Vec::new())
    }

    fn scale(&mut self, t: &Value, s: f64) -> R<Value> {
        auto_binop(self.interp, "*", t.clone(), Value::Num(s))
    }

    fn conv2d(&mut self, x: &Value, kernel: &Value, stride: usize, padding: &str) -> R<Value> {
        self.interp.call_builtin(
            "conv2d",
            vec![x.clone(), kernel.clone(), Value::Num(stride as f64), Value::Str(padding.to_string())],
            None,
            Vec::new(),
        )
    }

    fn maxpool2d(&mut self, x: &Value, pool: usize, stride: usize) -> R<Value> {
        self.interp.call_builtin(
            "maxpool2d",
            vec![x.clone(), Value::Num(pool as f64), Value::Num(stride as f64)],
            None,
            Vec::new(),
        )
    }

    fn gru_cell(&mut self, x: &Value, h: &Value, w: &tensor_backend::GruWeights<Value>) -> R<Value> {
        let w_record = Value::Record(Arc::new(vec![
            ("wz".to_string(), w.wz.clone()),
            ("uz".to_string(), w.uz.clone()),
            ("bz".to_string(), w.bz.clone()),
            ("wr".to_string(), w.wr.clone()),
            ("ur".to_string(), w.ur.clone()),
            ("br".to_string(), w.br.clone()),
            ("wh".to_string(), w.wh.clone()),
            ("uh".to_string(), w.uh.clone()),
            ("bh".to_string(), w.bh.clone()),
        ]));
        self.interp.call_builtin("gru_cell", vec![x.clone(), h.clone(), w_record], None, Vec::new())
    }

    fn scaled_dot_product_attention(&mut self, q: &Value, k: &Value, v: &Value) -> R<Value> {
        self.interp.call_builtin("scaled_dot_product_attention", vec![q.clone(), k.clone(), v.clone()], None, Vec::new())
    }

    fn row_of_gru_output(&mut self, t: &Value) -> R<Value> {
        self.interp.tt(t.clone())
    }

    fn transpose(&mut self, t: &Value) -> R<Value> {
        self.interp.tt(t.clone())
    }

    fn softmax_cross_entropy(&mut self, logits: &[Value], target: usize) -> R<Value> {
        softmax_ce_from_list(self.interp, logits, target)
    }
}

/// Which base per-tensor update rule a resolved optimizer applies each
/// epoch inside `sequential_fit` — every resolved optimizer (plain `sgd`/
/// `adam`, or one wrapped in an `LrController`) ultimately bottoms out at
/// exactly one of these two, via [`apply_sgd_update`]/[`apply_adam_update`].
#[derive(Clone, Copy, PartialEq, Eq)]
enum SequentialFitBase {
    Sgd,
    Adam,
    /// `optimizer=rmsprop(...)` (2026-08-26) — see [`apply_rmsprop_update`].
    Rmsprop,
    /// `optimizer=adamax(...)` (2026-08-26) — see [`apply_adamax_update`].
    Adamax,
    /// `optimizer=nesterov_sgd(...)` (2026-08-26) — see
    /// [`apply_nesterov_update`].
    Nesterov,
    /// `optimizer=adagrad(...)` (2026-08-26) — see [`apply_adagrad_update`].
    Adagrad,
    /// `optimizer=nadam(...)` (2026-08-26) — see [`apply_nadam_update`].
    Nadam,
    /// `optimizer=adamw(...)` (2026-08-26) — see [`apply_adamw_update`].
    AdamW,
    /// `optimizer=adadelta(...)` (2026-08-26) — see
    /// [`apply_adadelta_update`].
    Adadelta,
}

/// An optional learning-rate CONTROLLER wrapping the base update rule
/// above — resolved from an `optimizer=lr_adaptive(...)`/`lr_plateau(...)`
/// spec (2026-08-26), see `sequential_fit`'s own doc comment for the
/// priority order it's resolved at. `None` is the pre-2026-08-26 behavior:
/// a fixed `lr` for the whole run.
enum LrController {
    /// `lr_adaptive(lr=, increase_factor=1.1, decrease_factor=0.5)` —
    /// LM-style bidirectional trust region. SGD-only: see this variant's
    /// own note in `sequential_fit`'s doc comment for why Adam isn't
    /// supported here.
    Adaptive { increase_factor: f64, decrease_factor: f64 },
    /// `lr_plateau(lr=, patience=10, factor=0.5, min_lr=0.0, base=)` —
    /// classic ReduceLROnPlateau: monotonic decay, no step rejection.
    /// Composes with either base rule (see doc comment).
    Plateau { patience: usize, factor: f64, min_lr: f64 },
}

/// Apply one plain-SGD update (`param -= lr * grad`, via
/// [`sgd_update_inplace`]) to every leaf tensor named in `leaves`/`grads`,
/// returning a NEW params list — `base_params` itself is left untouched.
/// Used both by the ordinary per-epoch update (mirroring what this
/// function inlined before 2026-08-26) and by `lr_adaptive`'s
/// reject-and-retry loop, which needs to try several candidate `lr`
/// values from the SAME starting point without committing any of them
/// until one is accepted.
fn apply_sgd_update(
    base_params: &[Value],
    leaves: &[(usize, &'static str, Value)],
    grads: &[Value],
    lr: f64,
) -> R<Vec<Value>> {
    let mut params = base_params.to_vec();
    for ((layer_idx, field, _), g) in leaves.iter().zip(grads.iter()) {
        let prec = match &params[*layer_idx] {
            Value::Record(r) => r.as_ref().clone(),
            other => return e(format!("fit: internal error, expected a params record, found {}", other.type_name())),
        };
        let old = prec.iter().find(|(k, _)| k == field).map(|(_, v)| v.clone()).ok_or_else(|| EvalError {
            msg: format!("fit: internal error, missing `{field}` in layer {layer_idx} params"),
        })?;
        let g_flat = to_vec(g)?;
        let mut old_flat = to_vec(&old)?;
        sgd_update_inplace(&mut old_flat, &g_flat, lr)?;
        let new_val = flat_to_value(&old, &old_flat)?;
        let mut new_rec = prec;
        for entry in new_rec.iter_mut() {
            if entry.0 == *field {
                entry.1 = new_val.clone();
            }
        }
        params[*layer_idx] = Value::Record(Arc::new(new_rec));
    }
    Ok(params)
}

/// Adam counterpart to [`apply_sgd_update`] — same "return a new params
/// list, `base_params` untouched" contract, via [`adam_update_inplace`].
/// `adam_state`'s per-leaf `(m, v)` buffers ARE mutated in place (Adam's
/// moment EMAs are persistent optimizer state, not something a caller
/// would want to try-and-discard the way `lr_adaptive` tries-and-discards
/// candidate weights — see `sequential_fit`'s doc comment for why
/// `lr_adaptive` doesn't call this function at all).
fn apply_adam_update(
    base_params: &[Value],
    leaves: &[(usize, &'static str, Value)],
    grads: &[Value],
    adam_state: &mut HashMap<(usize, &'static str), (Vec<f64>, Vec<f64>)>,
    lr: f64, beta1: f64, beta2: f64, eps: f64,
    one_minus_beta1_t: f64, one_minus_beta2_t: f64,
) -> R<Vec<Value>> {
    let mut params = base_params.to_vec();
    for ((layer_idx, field, _), g) in leaves.iter().zip(grads.iter()) {
        let prec = match &params[*layer_idx] {
            Value::Record(r) => r.as_ref().clone(),
            other => return e(format!("fit: internal error, expected a params record, found {}", other.type_name())),
        };
        let old = prec.iter().find(|(k, _)| k == field).map(|(_, v)| v.clone()).ok_or_else(|| EvalError {
            msg: format!("fit: internal error, missing `{field}` in layer {layer_idx} params"),
        })?;
        let g_flat = to_vec(g)?;
        let n = g_flat.len();
        let (m_buf, v_buf) = adam_state.entry((*layer_idx, *field))
            .or_insert_with(|| (vec![0.0; n], vec![0.0; n]));
        if m_buf.len() != n {
            return e("fit: internal error, Adam moment buffer shape mismatch");
        }
        let mut old_flat = to_vec(&old)?;
        adam_update_inplace(
            &mut old_flat, m_buf, v_buf, &g_flat,
            lr, beta1, beta2, eps, 1.0 - beta1, 1.0 - beta2, one_minus_beta1_t, one_minus_beta2_t,
        )?;
        let new_val = flat_to_value(&old, &old_flat)?;
        let mut new_rec = prec;
        for entry in new_rec.iter_mut() {
            if entry.0 == *field {
                entry.1 = new_val.clone();
            }
        }
        params[*layer_idx] = Value::Record(Arc::new(new_rec));
    }
    Ok(params)
}

/// RMSprop counterpart to [`apply_sgd_update`]/[`apply_adam_update`]
/// (2026-08-26) — same "return a new params list, `base_params` untouched"
/// contract, via [`rmsprop_update_inplace`]. `rmsprop_state`'s per-leaf `v`
/// buffer (the running average of squared gradients) is persistent
/// optimizer state, mutated in place exactly like Adam's `m`/`v` in
/// [`apply_adam_update`].
fn apply_rmsprop_update(
    base_params: &[Value],
    leaves: &[(usize, &'static str, Value)],
    grads: &[Value],
    rmsprop_state: &mut HashMap<(usize, &'static str), Vec<f64>>,
    lr: f64, decay: f64, eps: f64,
) -> R<Vec<Value>> {
    let mut params = base_params.to_vec();
    for ((layer_idx, field, _), g) in leaves.iter().zip(grads.iter()) {
        let prec = match &params[*layer_idx] {
            Value::Record(r) => r.as_ref().clone(),
            other => return e(format!("fit: internal error, expected a params record, found {}", other.type_name())),
        };
        let old = prec.iter().find(|(k, _)| k == field).map(|(_, v)| v.clone()).ok_or_else(|| EvalError {
            msg: format!("fit: internal error, missing `{field}` in layer {layer_idx} params"),
        })?;
        let g_flat = to_vec(g)?;
        let n = g_flat.len();
        let v_buf = rmsprop_state.entry((*layer_idx, *field)).or_insert_with(|| vec![0.0; n]);
        if v_buf.len() != n {
            return e("fit: internal error, RMSprop moment buffer shape mismatch");
        }
        let mut old_flat = to_vec(&old)?;
        rmsprop_update_inplace(&mut old_flat, v_buf, &g_flat, lr, decay, eps)?;
        let new_val = flat_to_value(&old, &old_flat)?;
        let mut new_rec = prec;
        for entry in new_rec.iter_mut() {
            if entry.0 == *field {
                entry.1 = new_val.clone();
            }
        }
        params[*layer_idx] = Value::Record(Arc::new(new_rec));
    }
    Ok(params)
}

/// Adamax counterpart to [`apply_adam_update`] (2026-08-26) — same
/// contract, via [`adamax_update_inplace`]. `adamax_state`'s per-leaf
/// `(m, u)` buffers (first moment EMA / infinity-norm running max) are
/// persistent optimizer state, mutated in place exactly like Adam's own.
