/// Adagrad counterpart to [`apply_sgd_update`] (2026-08-26) — same
/// contract, via [`adagrad_update_inplace`]. `g_sq_state`'s per-leaf buffer
/// (the RAW, never-decayed sum of squared gradients) is persistent
/// optimizer state, mutated in place.
fn apply_adagrad_update(
    base_params: &[Value],
    leaves: &[(usize, &'static str, Value)],
    grads: &[Value],
    g_sq_state: &mut HashMap<(usize, &'static str), Vec<f64>>,
    lr: f64, eps: f64,
) -> R<Vec<Value>> {
    let mut params = base_params.to_vec();
    for ((layer_idx, field, _), g) in leaves.iter().zip(grads.iter()) {
        let prec = match &params[*layer_idx] {
            Value::Record(r) => r.as_ref().clone(),
            other => return e(format!("fit: internal error, expected a params record, found {}", other.type_name())),
        };
        let old = prec.iter().find(|(k, _)| k == field).map(|(_, v)| v.clone()).ok_or_else(|| EvalError {
            msg: format!("fit: internal error, missing `{field}` in layer {layer_idx} params"),
        })?;
        let g_flat = to_vec(g)?;
        let n = g_flat.len();
        let g_sq = g_sq_state.entry((*layer_idx, *field)).or_insert_with(|| vec![0.0; n]);
        if g_sq.len() != n {
            return e("fit: internal error, Adagrad accumulator buffer shape mismatch");
        }
        let mut old_flat = to_vec(&old)?;
        adagrad_update_inplace(&mut old_flat, g_sq, &g_flat, lr, eps)?;
        let new_val = flat_to_value(&old, &old_flat)?;
        let mut new_rec = prec;
        for entry in new_rec.iter_mut() {
            if entry.0 == *field {
                entry.1 = new_val.clone();
            }
        }
        params[*layer_idx] = Value::Record(Arc::new(new_rec));
    }
    Ok(params)
}

/// Nadam counterpart to [`apply_adam_update`] (2026-08-26) — same
/// contract, via [`nadam_update_inplace`]. `moment_state`'s per-leaf
/// `(m, v)` buffers are persistent optimizer state, mutated in place
/// exactly like Adam's own.
fn apply_nadam_update(
    base_params: &[Value],
    leaves: &[(usize, &'static str, Value)],
    grads: &[Value],
    moment_state: &mut HashMap<(usize, &'static str), (Vec<f64>, Vec<f64>)>,
    lr: f64, beta1: f64, beta2: f64, eps: f64,
    one_minus_beta1_t: f64, one_minus_beta1_t1: f64, one_minus_beta2_t: f64,
) -> R<Vec<Value>> {
    let mut params = base_params.to_vec();
    for ((layer_idx, field, _), g) in leaves.iter().zip(grads.iter()) {
        let prec = match &params[*layer_idx] {
            Value::Record(r) => r.as_ref().clone(),
            other => return e(format!("fit: internal error, expected a params record, found {}", other.type_name())),
        };
        let old = prec.iter().find(|(k, _)| k == field).map(|(_, v)| v.clone()).ok_or_else(|| EvalError {
            msg: format!("fit: internal error, missing `{field}` in layer {layer_idx} params"),
        })?;
        let g_flat = to_vec(g)?;
        let n = g_flat.len();
        let (m_buf, v_buf) = moment_state.entry((*layer_idx, *field))
            .or_insert_with(|| (vec![0.0; n], vec![0.0; n]));
        if m_buf.len() != n {
            return e("fit: internal error, Nadam moment buffer shape mismatch");
        }
        let mut old_flat = to_vec(&old)?;
        nadam_update_inplace(
            &mut old_flat, m_buf, v_buf, &g_flat,
            lr, beta1, beta2, eps, 1.0 - beta1, 1.0 - beta2,
            one_minus_beta1_t, one_minus_beta1_t1, one_minus_beta2_t,
        )?;
        let new_val = flat_to_value(&old, &old_flat)?;
        let mut new_rec = prec;
        for entry in new_rec.iter_mut() {
            if entry.0 == *field {
                entry.1 = new_val.clone();
            }
        }
        params[*layer_idx] = Value::Record(Arc::new(new_rec));
    }
    Ok(params)
}

/// AdamW counterpart to [`apply_adam_update`] (2026-08-26) — same contract,
