    #[test]
    fn truthiness_covers_every_runtime_value_kind() {
        assert!(!truthy(&Value::Mat(Arc::new(Matrix::zeros(0, 0)))));
        assert!(truthy(&Value::Mat(Arc::new(Matrix::zeros(1, 1)))));
        assert!(!truthy(&Value::Complex(Complex64::new(0.0, 0.0))));
        assert!(truthy(&Value::Complex(Complex64::new(0.0, 1.0))));
        assert!(!truthy(&Value::CVec(Arc::new(Vec::new()))));
        assert!(truthy(&Value::CVec(Arc::new(vec![Complex64::new(0.0, 0.0)]))));
        assert!(!truthy(&Value::Image(Arc::new(Image::new(0, 0, Vec::new()).unwrap()))));
        assert!(truthy(&Value::Image(Arc::new(Image::filled(1, 1, (0, 0, 0))))));
    }

    #[test]
    fn matrix_reductions_honor_axis_keyword() {
        let it = run("m = [1, 2; 3, 4]\ns0 = sum(m, axis=0)\ns1 = mean(m, axis=1)");
        assert_eq!(vec_of(&it, "s0"), vec![4.0, 6.0]);
        assert_eq!(vec_of(&it, "s1"), vec![1.5, 3.5]);
    }

    #[test]
    fn pinv_builtin_satisfies_matrix_reconstruction() {
        let it = run("a = [1, 2; 3, 4; 5, 7]\np = pinv(a)\nr = a * p * a");
        let Some(Value::Mat(actual)) = it.get("r") else {
            panic!("expected matrix reconstruction")
        };
        let expected =
            Matrix::from_rows(&[vec![1.0, 2.0], vec![3.0, 4.0], vec![5.0, 7.0]]).unwrap();
        let max_error = actual
            .as_slice()
            .iter()
            .zip(expected.as_slice())
            .map(|(left, right)| (left - right).abs())
            .fold(0.0, f64::max);
        assert!(max_error < 1.0e-12, "pinv reconstruction error {max_error}");
    }

    #[test]
    fn chol_reconstruction_l_times_lt_recovers_a_covariance_like_matrix() {
        let it = run(
            "A = [25, 15, -5; 15, 18, 0; -5, 0, 11]\nL = chol(A)\nR = L * L'",
        );
        let Some(Value::Mat(l)) = it.get("L") else { panic!("L not a matrix") };
        // upper triangle must be exactly zero.
        assert_eq!(l.get(0, 1).unwrap(), 0.0);
        assert_eq!(l.get(0, 2).unwrap(), 0.0);
        assert_eq!(l.get(1, 2).unwrap(), 0.0);
        let Some(Value::Mat(reconstructed)) = it.get("R") else { panic!("R not a matrix") };
        let expected = Matrix::from_rows(&[
            vec![25.0, 15.0, -5.0],
            vec![15.0, 18.0, 0.0],
            vec![-5.0, 0.0, 11.0],
        ])
        .unwrap();
        for (got, want) in reconstructed.as_slice().iter().zip(expected.as_slice()) {
            assert!((got - want).abs() < 1e-9, "{got} vs {want}");
        }
    }

