    #[test]
    fn ukf_predict_then_update_matches_a_hand_computed_nonlinear_example() {
        // Same x0=2/P0=10/obs=x^2/z=9/R=0.5/Q=0.001 problem as the EKF hand-
        // computed test above, but via sigma points instead of a Jacobian
        // (`method="ukf"`). Values independently worked out in Python
        // (numpy sigma-point implementation, not this codebase): x'=1.44513,
        // P'=5.56252 after the predict+update pair below.
        let it = run(
            "proc(x) := x\n\
             obs(x) := [x[0]^2]\n\
             s = kalman_init([2], [10])\n\
             s = s.predict(\"proc\", [0.001], method=\"ukf\")\n\
             s = s.update(\"obs\", [9], [0.5], method=\"ukf\")\n\
             x = s.x\nP = s.P",
        );
        assert!((vec_of(&it, "x")[0] - 1.44513473).abs() < 1e-4, "x = {:?}", vec_of(&it, "x"));
        let Some(Value::Mat(p)) = it.get("P") else { panic!("P not a matrix") };
        assert!((p.get(0, 0).unwrap() - 5.56252163).abs() < 1e-3, "P = {}", p.get(0, 0).unwrap());
    }

