    #[test]
    fn ukf_and_a_linear_process_agree_with_the_plain_linear_kalman_filter() {
        // The standard UKF sanity check applied end-to-end: for a *linear*
        // process/observation, the unscented filter must reach the same
        // state as the plain linear Kalman filter, since sigma points are a
        // generalization of the linear math, not an approximation of it.
        let it = run(
            "s_lin = kalman_init([0], [10])\n\
             s_lin = s_lin.predict([1], [0.01])\n\
             s_lin = s_lin.update([1], [2], [1])\n\
             lin_x = s_lin.x\nlin_P = s_lin.P\n\
             lin_fn(x) := x\n\
             obs_fn(x) := x\n\
             s_ukf = kalman_init([0], [10])\n\
             s_ukf = s_ukf.predict(\"lin_fn\", [0.01], method=\"ukf\")\n\
             s_ukf = s_ukf.update(\"obs_fn\", [2], [1], method=\"ukf\")\n\
             ukf_x = s_ukf.x\nukf_P = s_ukf.P",
        );
        assert!((vec_of(&it, "lin_x")[0] - vec_of(&it, "ukf_x")[0]).abs() < 1e-6);
        let Some(Value::Mat(lin_p)) = it.get("lin_P") else { panic!("lin_P not a matrix") };
        let Some(Value::Mat(ukf_p)) = it.get("ukf_P") else { panic!("ukf_P not a matrix") };
        assert!((lin_p.get(0, 0).unwrap() - ukf_p.get(0, 0).unwrap()).abs() < 1e-6);
    }

