    #[test]
    fn particle_filter_move_advances_constant_velocity_motion_deterministically_with_zero_process_noise() {
        // process_noise=0 AND spread=0 collapse every particle to an exact
        // point mass at `initial_state` -- the standard constant-velocity
        // sanity check: `position += velocity*dt` exactly, velocity
        // unchanged, identically for every particle (no scatter, no noise
        // to blur the formula).
        let it = run(
            "pf = particle_filter(20, [0, 5, 2, -1], process_noise=0, spread=0, seed=2)\n\
             pf = pf.move(0.5)\n\
             row0 = pf.particles[0, :]\n\
             row1 = pf.particles[1, :]",
        );
        let row0 = vec_of(&it, "row0");
        let row1 = vec_of(&it, "row1");
        // velocity components (indices 2, 3) are untouched by motion.
        assert!((row0[2] - 2.0).abs() < 1e-9);
        assert!((row0[3] - (-1.0)).abs() < 1e-9);
        // position components (indices 0, 1) advanced by exactly velocity*dt.
        assert!((row0[0] - (0.0 + 2.0 * 0.5)).abs() < 1e-9, "row0[0]={}", row0[0]);
        assert!((row0[1] - (5.0 + -1.0 * 0.5)).abs() < 1e-9, "row0[1]={}", row0[1]);
        // every particle is identical (zero spread, zero process noise).
        assert_eq!(row0, row1);
    }

