    fn particle_filter_predict_and_move_are_the_same_operation() {
        let it_predict = run("pf = particle_filter(30, [0, 1], process_noise=0.2, spread=1.0, seed=9)\npf = pf.predict(0.25)\nrow = pf.particles[0, :]");
        let it_move = run("pf = particle_filter(30, [0, 1], process_noise=0.2, spread=1.0, seed=9)\npf = pf.move(0.25)\nrow = pf.particles[0, :]");
        assert_eq!(vec_of(&it_predict, "row"), vec_of(&it_move, "row"));
    }

