    #[test]
    fn particle_filter_tracks_a_1d_constant_velocity_target_within_rms_tolerance() {
        // Real correctness check against a known synthetic ground truth
        // (not just "it runs"): a target moving at constant velocity,
        // observed through Gaussian noise every step. The filter's own
        // `.estimate()` must track the TRUE position to within a modest
        // RMS error over the whole run, confirming the predict/update/
        // resample loop actually converges rather than drifting or staying
        // put.
        let it = run(
            "seed(11)\n\
             true_x = 0.0\n\
             true_v = 1.0\n\
             dt = 0.1\n\
             pf = particle_filter(500, [0, 1], process_noise=0.05, obs_noise=0.5, spread=2.0, seed=11)\n\
             sum_sq_err = 0.0\n\
             n_steps = 60\n\
             for i = 1 to n_steps\n\
             \x20   true_x = true_x + true_v * dt\n\
             \x20   obs = true_x + 0.5 * randn()\n\
             \x20   pf = pf.move(dt)\n\
             \x20   pf = pf.update([obs])\n\
             \x20   est = pf.estimate()\n\
             \x20   err = est[0] - true_x\n\
             \x20   sum_sq_err = sum_sq_err + err * err\n\
             end for\n\
             rms = sqrt(sum_sq_err / n_steps)\n\
             final_true = true_x\n\
             final_est = pf.estimate()\n\
             final_est_pos = final_est[0]\n\
             final_est_vel = final_est[1]",
        );
        let rms = num(&it, "rms");
        assert!(rms < 1.0, "RMS tracking error {rms} should be well under the observation noise scale");
        let final_true = num(&it, "final_true");
        let final_est_pos = num(&it, "final_est_pos");
        assert!((final_est_pos - final_true).abs() < 1.0, "final position estimate {final_est_pos} should track the true position {final_true}");
        let final_est_vel = num(&it, "final_est_vel");
        assert!((final_est_vel - 1.0).abs() < 0.5, "final velocity estimate {final_est_vel} should have converged near the true velocity 1.0");
    }

    #[test]
    #[cfg(feature = "gpu")]
    fn particle_tracker_gpu_matmul_matches_cpu_matmul_for_the_deterministic_motion_step() {
        // Isolates the ONE backend-dependent part of `.predict(dt)`/
        // `.move(dt)` (the matmul `particle_tracker_matmul` dispatches to
        // the GPU above `gpu_probe`'s measured crossover) from the
        // separately-stochastic resampling step in `.update(...)`: this
        // motion update has no randomness in it at all (process noise is
        // added afterward, identically, by `particle_tracker_advance`
        // regardless of backend), so CPU and GPU must agree within f32
        // precision, not just "on average" or "for a fixed seed".
        let mut probe = Interp::new();
        if probe.run("c = gpu_matmul([1,2;3,4], [1,0;0,1])").is_err() {
            eprintln!(
                "GPU SKIP (no adapter?): particle_tracker_gpu_matmul_matches_cpu_matmul_for_the_deterministic_motion_step"
            );
            return;
        }
        let particles = Matrix::from_rows(&[
            vec![0.0, 1.0, 2.0, -0.5],
            vec![1.0, -2.0, 0.3, 0.7],
            vec![-3.0, 0.2, -1.0, 1.5],
        ])
        .unwrap();
        let dt = 0.1;
        let a_t = particle_tracker_transition_matrix(4, dt).transpose();
        let cpu = particles.matmul(&a_t).unwrap();

        let probe_result = gpu_probe::probe();
        let ctx = probe_result.context.as_ref().expect("adapter probe above already confirmed a GPU context");
        let to_row_major_f32 = |mat: &Matrix| -> Vec<f32> {
            let (r, c) = mat.shape();
            (0..r).flat_map(|row| (0..c).map(move |col| (row, col)))
                .map(|(row, col)| mat.get(row, col).unwrap_or(0.0) as f32)
                .collect()
        };
        let (n, d) = particles.shape();
        let (_, out_d) = a_t.shape();
        let raw = ctx
            .matmul(&to_row_major_f32(&particles), n, d, &to_row_major_f32(&a_t), out_d)
            .expect("GPU matmul dispatch should succeed on this small shape");
        // `Matrix::as_slice()` is `cpu`'s own internal (column-major)
        // storage order, but `raw` comes back ROW-major (the shader's own
        // convention, matching `gpu_matmul`'s builtin arm) -- for a
        // non-square result those two flat orders are NOT
        // elementwise-comparable, so re-flatten `cpu` row-major via `.get`
        // first, the same way `to_row_major_f32` above does for the inputs.
        let cpu_row_major: Vec<f64> = (0..n).flat_map(|row| (0..out_d).map(move |col| (row, col)))
            .map(|(row, col)| cpu.get(row, col).unwrap_or(0.0))
            .collect();
        let max_error = cpu_row_major
            .iter()
            .zip(raw.iter())
            .map(|(a, b)| (a - *b as f64).abs())
            .fold(0.0, f64::max);
        assert!(max_error < 1e-4, "gpu/cpu particle-tracker motion mismatch: {max_error}");
    }

    #[test]
    fn argmin_and_argmax_find_the_first_occurring_extremum() {
        // ties must resolve to the FIRST occurrence, matching min/max's own
        // left-to-right reduce.
        let it = run("x = [5, 2, 9, 1, 1, 9]\nlo = argmin(x)\nhi = argmax(x)");
        assert_eq!(num(&it, "lo"), 3.0);
        assert_eq!(num(&it, "hi"), 2.0);
    }

    #[test]
    fn argmin_and_argmax_skip_a_leading_nan_instead_of_getting_stuck_on_it() {
        // Bug: `arg_extremum` used to start its running-best scan at index
        // 0 and only ever displace it via a strict `<`/`>` comparison —
        // both always false against a NaN operand, so once `xs[0]` itself
        // was NaN, no later element could ever displace it and
        // argmin/argmax silently returned 0 no matter where the real
        // extremum was. `min`/`max` (via `f64::min`/`f64::max`, IEEE
        // `minNum`/`maxNum`) already ignore a NaN operand instead, so this
        // broke the `x[argmin(x)] == min(x)` invariant that must hold for
        // every non-degenerate input. Verified two independent ways here:
        // against `min`/`max` directly, and against `where(x == min(x))`.
        let it = run(
            "x = [nan, 1, 2]\n\
             lo = argmin(x)\nlo_val = x[argmin(x)]\nlo_min = min(x)\n\
             y = [nan, 5, 1, 9]\n\
             hi = argmax(y)\nhi_val = y[argmax(y)]\nhi_max = max(y)\n\
             idx_check = where(x == min(x))",
        );
        assert_eq!(num(&it, "lo"), 1.0);
        assert_eq!(num(&it, "lo_val"), num(&it, "lo_min"));
        assert_eq!(num(&it, "hi"), 3.0);
        assert_eq!(num(&it, "hi_val"), num(&it, "hi_max"));
        // where(x == min(x)) independently agrees argmin should be 1.
        match it.get("idx_check") {
            Some(Value::Vec(v)) => assert_eq!(v.as_slice(), &[1.0]),
            other => panic!("expected a Vec, got {other:?}"),
        }
    }

