    #[test]
    fn shape_builtins_push_onto_current_panel() {
        let it = run(
            "vline(3)\nhline(0)\nrectangle(0, 0, 1, 1)\nxspan(2, 4)\nyspan(-1, 1)",
        );
        assert_eq!(it.figure.panels[0].shapes.len(), 5);
    }

    #[test]
    fn annotation_builtins_push_callouts() {
        let it = run(
            "text(1, 1, \"hi\")\nannotate(2, 2, \"note\")\narrow(0, 0, 1, 1)\narrowtext(0, 0, 1, 1, \"go\")\npoint(3, 4)",
        );
        let callouts = &it.figure.panels[0].callouts;
        assert_eq!(callouts.len(), 5);
        assert_eq!(callouts[0].text, "hi");
        assert!(!callouts[0].marker);
        assert!(callouts[1].marker); // annotate() marks its point
        assert!(callouts[2].arrow_to.is_some());
        assert_eq!(callouts[3].text, "go");
        assert!(callouts[4].marker); // point() is the "radioactive" callout
        assert!(callouts[4].text.contains('3') && callouts[4].text.contains('4'));
    }

    #[test]
    fn grid_and_box_commands_toggle_panel_flags() {
        let it = run("grid off\nbox off");
        let p = &it.figure.panels[0];
        // `Some(false)`, not just falsy: an explicit `grid off` must be
        // distinguishable from "the theme decides", or a theme could never
        // turn the grid off without making `grid on` impossible.
        assert_eq!(p.show_grid, Some(false));
        assert!(!p.show_box);
    }

    #[test]
    fn grid_minor_toggles_independently_of_the_major_grid() {
        let it = run("grid off\ngrid minor");
        let p = &it.figure.panels[0];
        assert_eq!(p.show_grid, Some(false), "grid minor should not turn the major grid back on");
        assert_eq!(p.show_minor_grid, Some(true), "`minor grid on` is an explicit yes, not \"follow the theme\"");
        let it2 = run("grid minor\ngrid minor off");
        assert_eq!(it2.figure.panels[0].show_minor_grid, Some(false), "`minor grid off` is explicit, and a theme must not override it");
    }

