    #[test]
    fn tex_of_a_table_returns_a_tabular_environment_not_dollar_wrapped_math() {
        let mut it = Interp::new();
        let dir = std::env::temp_dir();
        let path = dir.join("qu_table_tex_render_test.csv");
        std::fs::write(&path, "name,score\nal,1\nbo,22\n").unwrap();
        let csv_path = path.display().to_string().replace('\\', "\\\\");
        it.run(&format!("t = read_csv(\"{csv_path}\")\ns = tex(t)")).unwrap();
        let Some(Value::Str(s)) = it.get("s") else { panic!("expected a string") };
        assert!(s.starts_with("\\begin{tabular}{lr}"));
        assert!(s.trim_end().ends_with("\\end{tabular}"));
        assert!(!s.starts_with('$'));
        assert!(s.contains("name & score"));
        assert!(s.contains("al & 1"));
        assert!(s.contains("bo & 22"));
        let _ = std::fs::remove_file(path);
    }

    #[test]
    fn printtex_of_a_table_with_tricky_names_and_content_escapes_correctly() {
        // A column name with an underscore, and cell content with a `%` —
        // both must survive `printtex` escaped, so the emitted LaTeX
        // actually compiles instead of erroring on a bare `_`/`%`.
        let mut it = Interp::new();
        let dir = std::env::temp_dir();
        let path = dir.join("qu_table_printtex_escape_test.csv");
        std::fs::write(&path, "a_b\n50%\nx\n").unwrap();
        let csv_path = path.display().to_string().replace('\\', "\\\\");
        it.run(&format!("t = read_csv(\"{csv_path}\")\nprinttex(t)")).unwrap();
        assert!(it.out.contains("a\\_b"));
        assert!(it.out.contains("50\\%"));
        // balanced begin/end, single tabular block
        assert_eq!(it.out.matches("\\begin{tabular}").count(), 1);
        assert_eq!(it.out.matches("\\end{tabular}").count(), 1);
        let _ = std::fs::remove_file(path);
    }

