    #[test]
    fn for_loop_building_labeled_series_from_parallel_parameter_lists() {
        // The "map"-style idiom: generate several series from indexed
        // parameter lists inside a `for` loop, with `str()` + string
        // concatenation building a distinct label each iteration.
        let it = run(
            "function f(x, r)\n\
             return r .* x\n\
             end function\n\
             x = 0 to 3\n\
             rates = [2, 3, 4]\n\
             for i = 0 to 2\n\
             y = f(x, rates[i])\n\
             plot(x, y, label=\"s\" + str(i+1))\n\
             end for",
        );
        let series = &it.figure.panels[0].series;
        assert_eq!(series.len(), 3);
        assert_eq!(series[0].label.as_deref(), Some("s1"));
        assert_eq!(series[2].label.as_deref(), Some("s3"));
    }

