    #[test]
    fn var_matches_std_squared() {
        let it = run("x = [1, 2, 3, 4, 5]\nv = var(x)\ns2 = std(x)^2");
        let v = it.get("v").unwrap().as_num().unwrap();
        let s2 = it.get("s2").unwrap().as_num().unwrap();
        assert!((v - 2.5).abs() < 1e-9);
        assert!((v - s2).abs() < 1e-9);
    }

    #[test]
    fn cov_of_a_linear_transform_matches_the_scaled_variance() {
        // y = 2x + 1 => cov(x, y) == 2 * var(x)
        let it = run("x = [1, 2, 3, 4, 5]\ny = 2 .* x + 1\nc = cov(x, y)\nv2 = 2 * var(x)");
        let c = it.get("c").unwrap().as_num().unwrap();
        let v2 = it.get("v2").unwrap().as_num().unwrap();
        assert!((c - v2).abs() < 1e-9);
    }

    #[test]
    fn mode_returns_the_most_frequent_value_breaking_ties_low() {
        let it = run("m = mode([1, 1, 2, 3])");
        assert!(matches!(it.get("m"), Some(Value::Num(n)) if (*n - 1.0).abs() < 1e-9));
        // 2 and 3 both appear twice; tie broken by the smaller value.
        let it2 = run("m = mode([2, 2, 3, 3, 1])");
        assert!(matches!(it2.get("m"), Some(Value::Num(n)) if (*n - 2.0).abs() < 1e-9));
    }

    #[test]
    fn skewness_is_zero_for_a_symmetric_sample() {
        let it = run("s = skewness([1, 2, 3, 4, 5])");
        assert!(matches!(it.get("s"), Some(Value::Num(n)) if n.abs() < 1e-9));
    }

    #[test]
    fn kurtosis_of_a_small_uniform_sample_is_below_the_normal_value_of_three() {
        // A discrete-uniform-like sample is platykurtic (flatter than
        // normal), so this pins the convention: Pearson/non-excess form,
        // where a normal distribution scores 3.0 — not SciPy's default
        // "excess kurtosis" (which would center a normal at 0).
        let it = run("k = kurtosis([1, 2, 3, 4, 5])");
        assert!(matches!(it.get("k"), Some(Value::Num(n)) if *n > 0.0 && *n < 3.0));
    }

    #[test]
    fn percentile_and_iqr_match_quantile() {
        let it = run(
            "x = [1, 2, 3, 4, 5]\n\
             p50 = percentile(x, 50)\n\
             q50 = quantile(x, 0.5)\n\
             r = iqr(x)\n\
             expected_iqr = quantile(x, 0.75) - quantile(x, 0.25)",
        );
        let p50 = it.get("p50").unwrap().as_num().unwrap();
        let q50 = it.get("q50").unwrap().as_num().unwrap();
        let r = it.get("r").unwrap().as_num().unwrap();
        let expected = it.get("expected_iqr").unwrap().as_num().unwrap();
        assert!((p50 - q50).abs() < 1e-9);
        assert!((r - expected).abs() < 1e-9);
    }

    #[test]
    fn bare_print_command_interpolates_like_the_function_call_form() {
        let it = run("x = 3.14159\nprint \"x = {x:.2f}\"");
        assert_eq!(it.out.trim(), "x = 3.14");
    }

    #[test]
    fn bare_print_accepts_an_arbitrary_expression_not_just_a_string() {
        // Ahmed's exact report: `print argmax(x)` used to be a parse error
        // ("expected end of statement... found Op(\"(\")") because the bare
        // form only ever collected literal words, never parsed a real
        // expression. `print`/`disp`/`writeline`/`echo` now desugar
        // `<verb> <expr>` (no parens) to `<verb>(<expr>)` via a full
        // expression parse, so a function call, a bare variable, and
        // arithmetic all work the same as the parenthesized form.
        let x = "x = [3, 1, 4, 1, 5, 9, 2, 6]\n";
        assert_eq!(run(&format!("{x}print argmax(x)")).out.trim(), "5");
        assert_eq!(run(&format!("{x}print max(x)")).out.trim(), "9");
        assert_eq!(run(&format!("{x}print where(x == max(x))")).out.trim(), "[5]");
        assert_eq!(run("y = 3.14159\nprint y").out.trim(), "3.14159");
        assert_eq!(run("y = 3\nprint y + 1").out.trim(), "4");
    }

    #[test]
    fn two_statements_on_one_line_without_a_separator_is_a_clear_parse_error() {
        let mut it = Interp::new();
        let err = it.run("print \"hi\"\nx = 1 \"stray\"").unwrap_err();
        assert!(err.msg.contains("expected end of statement"), "got: {}", err.msg);
    }

    #[test]
    fn randn_and_zeros_accept_a_size_shape_vector() {
        // `size(x)` returns a 2-element `[rows, cols]` shape vector; passing
        // it straight through used to silently collapse to a 1x1 default
        // (`Value::as_num` can't unwrap a multi-element `Vec`) instead of
        // matching `x`'s actual length — the classic `zeros(size(x))`/
        // `randn(size(x))` idiom.
        let it = run("x = 0 to 9\nz = zeros(size(x))\nr = randn(size(x), seed=1)");
        assert!(matches!(it.get("z"), Some(Value::Vec(v)) if v.len() == 10 && v.iter().all(|&n| n == 0.0)));
        assert!(matches!(it.get("r"), Some(Value::Vec(v)) if v.len() == 10));
    }

