    #[test]
    fn diagram_file_writes_svg_and_refuses_png_like_savefig_does() {
        let mut it = Interp::new();
        it.run("function f(x)\n  return x\nend function").unwrap();
        let dir = std::env::temp_dir();
        let svg_path = dir.join("qu_algorigram_test.svg");
        let png_path = dir.join("qu_algorigram_test.png");
        it.run(&format!(
            "algorigram(\"f\", file=\"{}\")",
            svg_path.display().to_string().replace('\\', "\\\\")
        ))
        .unwrap();
        let written = std::fs::read_to_string(&svg_path).unwrap();
        assert!(written.starts_with("<svg"));
        std::fs::remove_file(&svg_path).ok();

        let err = it
            .run(&format!(
                "algorigram(\"f\", file=\"{}\")",
                png_path.display().to_string().replace('\\', "\\\\")
            ))
            .unwrap_err();
        assert!(err.msg.contains("rasterizer"), "got: {}", err.msg);
    }

    #[test]
    fn savefig_writes_svg_html_and_tikz_with_expected_markers() {
        let mut it = Interp::new();
        it.run("x = 0 to 9\nplot(x, sin(x))\nxlabel(\"t\")\nlegend(\"sin\")\nlegend best")
            .unwrap();
        let dir = std::env::temp_dir();
        let svg_path = dir.join("qu_savefig_test.svg");
        let html_path = dir.join("qu_savefig_test.html");
        let tikz_path = dir.join("qu_savefig_test.tikz");
        it.run(&format!("savefig(\"{}\")", svg_path.display().to_string().replace('\\', "\\\\")))
            .unwrap();
        it.run(&format!("savefig(\"{}\")", html_path.display().to_string().replace('\\', "\\\\")))
            .unwrap();
        it.run(&format!("savefig(\"{}\")", tikz_path.display().to_string().replace('\\', "\\\\")))
            .unwrap();
        let svg = std::fs::read_to_string(&svg_path).unwrap();
        assert!(svg.starts_with("<svg"));
        assert!(svg.contains("<polyline"));
        let html = std::fs::read_to_string(&html_path).unwrap();
        assert!(html.contains("<svg") && html.starts_with("<!doctype"));
        let tikz = std::fs::read_to_string(&tikz_path).unwrap();
        assert!(tikz.contains("\\begin{tikzpicture}") && tikz.contains("\\end{tikzpicture}"));
        for path in [svg_path, html_path, tikz_path] {
            let _ = std::fs::remove_file(path);
        }
    }

    #[test]
    fn savefig_rejects_full_figure_png_with_a_clear_scoped_error() {
        // `.png` for a whole FIGURE stays unsupported (needs a real
        // rasterizer -- see BACKLOG.md item [25]/IMPL.md) even now that
        // `.pdf` works; the error must say so, and must not be confused
        // with `save_image`'s real PNG support for raster content.
        let mut it = Interp::new();
        it.run("plot(0 to 3, 0 to 3)").unwrap();
        let err = it.run("savefig(\"out.png\")").unwrap_err();
        assert!(err.msg.contains("rasterizer"), "got: {}", err.msg);
        assert!(err.msg.contains("save_image"), "got: {}", err.msg);
    }

    /// Byte-string search helper for the PDF structural test below --
    /// `str::find` doesn't apply directly to a `Vec<u8>` that may contain
    /// non-UTF-8 bytes (the PDF's binary-marker comment line).
    fn find_bytes(haystack: &[u8], needle: &[u8]) -> Option<usize> {
        haystack.windows(needle.len()).position(|w| w == needle)
    }

    #[test]
    fn savefig_writes_a_structurally_valid_pdf() {
        // Real multi-series plot (line + scatter + bar), plus a math-markup
        // title, so the PDF backend's text/anchor/rotate path and its
        // documented `$...$`-flattening both get exercised, not just a bare
        // line plot.
        let mut it = Interp::new();
        it.run(concat!(
            "x = 0 to 9\n",
            "plot(x, sin(x))\n",
            "scatter([1, 2, 3], [3, 1, 2])\n",
            "bar([4, 5, 6])\n",
            "xlabel(\"t\")\n",
            "title(\"$x^2$ demo\")\n",
            "legend(\"sin\")\n",
            "legend best"
        ))
        .unwrap();
        let dir = std::env::temp_dir();
        let pdf_path = dir.join("qu_savefig_test.pdf");
        it.run(&format!("savefig(\"{}\")", pdf_path.display().to_string().replace('\\', "\\\\")))
            .unwrap();
        let bytes = std::fs::read(&pdf_path).unwrap();
        let _ = std::fs::remove_file(&pdf_path);

        assert!(bytes.starts_with(b"%PDF-1."), "missing PDF header");
        let tail_start = bytes.len().saturating_sub(16);
        let tail = String::from_utf8_lossy(&bytes[tail_start..]);
        assert!(tail.trim_end().ends_with("%%EOF"), "missing PDF trailer marker, tail was: {tail:?}");
        assert!(find_bytes(&bytes, b"/Type /Catalog").is_some());
        assert!(find_bytes(&bytes, b"BT").is_some() && find_bytes(&bytes, b"Tj").is_some() && find_bytes(&bytes, b"ET").is_some(), "expected text operators for the title/axis labels/legend");
        assert!(find_bytes(&bytes, b" m ").is_some() && find_bytes(&bytes, b" l ").is_some(), "expected moveto/lineto path operators for the line plot");
        assert!(find_bytes(&bytes, b"BT").is_some() && find_bytes(&bytes, b"Tj").is_some() && find_bytes(&bytes, b"ET").is_some(), "expected text operators for the title/axis labels/legend");
        assert!(find_bytes(&bytes, b" m ").is_some() && find_bytes(&bytes, b" l ").is_some(), "expected moveto/lineto path operators for the line plot");
        // The default theme asks for Inter, so the PDF must now carry an
        // EMBEDDED font program rather than referencing base-14 Helvetica by
        // name. A figure that says Inter and renders Helvetica is the wrong
        // output, and this assertion used to require the wrong output.
        assert!(
            find_bytes(&bytes, b"/FontFile2").is_some() || find_bytes(&bytes, b"/FontFile3").is_some(),
            "expected an embedded font program, not a base-14 reference"
        );
        assert!(find_bytes(&bytes, b"/FontDescriptor").is_some(), "an embedded font needs a descriptor");
        assert!(find_bytes(&bytes, b"/Widths").is_some(), "an embedded simple font needs its own widths");


        // `startxref` must point exactly at the literal `xref` keyword.
        let sx = find_bytes(&bytes, b"startxref").expect("startxref");
        // `startxref` is followed by its own end-of-line, then the offset
        // digits, then another end-of-line -- skip the first before scanning
        // for where the number ends.
        let after = &bytes[sx + b"startxref".len()..];
        let digits_start = after.iter().position(|&b| b.is_ascii_digit()).expect("digits after startxref");
        let digits_end = after[digits_start..].iter().position(|&b| !b.is_ascii_digit()).map(|i| digits_start + i).unwrap_or(after.len());
        let xref_offset: usize = std::str::from_utf8(&after[digits_start..digits_end]).unwrap().parse().unwrap();
        assert_eq!(&bytes[xref_offset..xref_offset + 4], b"xref", "startxref offset must point at `xref`");

        // Every in-use xref entry (`nnnnnnnnnn 00000 n `, 20 bytes each,
        // right after the `xref\n0 N\n` header) must point at the matching
        // `K 0 obj` marker -- the exact correctness property an xref table
        // exists to provide, and the same kind of check a real PDF reader
        // performs before trusting an offset.
        // Skip the `xref\n` keyword line, then read the `0 N` subsection
        // header line that follows it.
        let subsection_start = xref_offset + b"xref\n".len();
        let subsection_line_end = find_bytes(&bytes[subsection_start..], b"\n").unwrap() + subsection_start;
        let header_line = std::str::from_utf8(&bytes[subsection_start..subsection_line_end]).unwrap();
        let count: usize = header_line.split_whitespace().nth(1).unwrap().parse().unwrap();
        let header_end = subsection_line_end + 1;
        let mut checked_objects = 0;
        for obj_num in 1..count {
            let entry_start = header_end + obj_num * 20;
            let entry = std::str::from_utf8(&bytes[entry_start..entry_start + 20]).unwrap();
            let offset: usize = entry[0..10].parse().unwrap();
            let marker = format!("{obj_num} 0 obj");
            assert_eq!(
                &bytes[offset..offset + marker.len()],
                marker.as_bytes(),
                "xref entry for object {obj_num} points at offset {offset}, expected `{marker}` there"
            );
            checked_objects += 1;
        }
        assert_eq!(checked_objects, count - 1, "expected to check every non-free xref entry");

        // The content stream's `/Length` must match its actual byte count.
        let obj4 = find_bytes(&bytes, b"4 0 obj").expect("content stream object");
        let length_kw = find_bytes(&bytes[obj4..], b"/Length ").unwrap() + obj4 + b"/Length ".len();
        let length_end = bytes[length_kw..].iter().position(|&b| b == b' ' || b == b'\n' || b == b'\r').unwrap() + length_kw;
        let declared_len: usize = std::str::from_utf8(&bytes[length_kw..length_end]).unwrap().trim().parse().unwrap();
        let stream_kw = find_bytes(&bytes[obj4..], b"stream\n").unwrap() + obj4 + b"stream\n".len();
        let endstream_kw = find_bytes(&bytes[stream_kw..], b"endstream").unwrap() + stream_kw;
        assert_eq!(endstream_kw - stream_kw, declared_len, "/Length must match the actual stream byte count");
    }

