    #[test]
    fn save_image_writes_a_real_png_that_decodes_pixel_exact() {
        let mut it = Interp::new();
        it.run("img = image_new(4, 3, r=10, g=20, b=30)").unwrap();
        let dir = std::env::temp_dir();
        let png_path = dir.join("qu_save_image_test.png");
        it.run(&format!("save_image(\"{}\", img)", png_path.display().to_string().replace('\\', "\\\\")))
            .unwrap();
        let bytes = std::fs::read(&png_path).unwrap();
        let _ = std::fs::remove_file(&png_path);
        assert_eq!(&bytes[0..8], &[0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A], "not a valid PNG signature");
        assert_eq!(&bytes[12..16], b"IHDR");
        // width/height are stored big-endian right after the IHDR chunk header.
        let width = u32::from_be_bytes(bytes[16..20].try_into().unwrap());
        let height = u32::from_be_bytes(bytes[20..24].try_into().unwrap());
        assert_eq!((width, height), (4, 3));
        assert_eq!(&bytes[bytes.len() - 8..bytes.len() - 4], b"IEND");
    }

    #[test]
    fn polyfit_recovers_exact_line_and_polyval_matches_source_data() {
        // y = 3x + 2, exactly -- a degree-1 fit should recover it exactly.
        let it = run("x = 0 to 5\ny = 3*x + 2\nc = polyfit(x, y, 1)\nyhat = polyval(c, x)");
        let c = vec_of(&it, "c");
        assert!((c[0] - 3.0).abs() < 1e-9, "slope: {c:?}");
        assert!((c[1] - 2.0).abs() < 1e-9, "intercept: {c:?}");
        let (yhat, y) = (vec_of(&it, "yhat"), vec_of(&it, "y"));
        for (a, b) in yhat.iter().zip(&y) {
            assert!((a - b).abs() < 1e-9, "{yhat:?} vs {y:?}");
        }
    }

    #[test]
    fn polyfit_least_squares_on_noisy_data_and_polyval_on_a_scalar() {
        // y = x^2 exactly at these points -- a degree-2 fit should recover
        // [1, 0, 0] (coefficients highest-degree-first).
        let it = run("x = -2 to 2\ny = x .* x\nc = polyfit(x, y, 2)\np = polyval(c, 3)");
        let c = vec_of(&it, "c");
        assert!((c[0] - 1.0).abs() < 1e-9, "{c:?}");
        assert!(c[1].abs() < 1e-9, "{c:?}");
        assert!(c[2].abs() < 1e-9, "{c:?}");
        assert!(matches!(it.get("p"), Some(Value::Num(n)) if (*n - 9.0).abs() < 1e-9));
    }

