    #[test]
    fn kmeans_separates_two_well_separated_clusters() {
        let it = run(
            "x = [0, 0; 0.1, -0.1; 10, 10; 10.1, 9.9]\nlabels = kmeans(x, 2, seed = 1)",
        );
        let labels = vec_of(&it, "labels");
        assert_eq!(labels.len(), 4);
        assert_eq!(labels[0], labels[1], "the two near-origin points should share a label: {labels:?}");
        assert_eq!(labels[2], labels[3], "the two near-(10,10) points should share a label: {labels:?}");
        assert_ne!(labels[0], labels[2], "the two clusters should get different labels: {labels:?}");
    }

    #[test]
    fn kmeans_centers_are_near_the_true_cluster_means() {
        let it = run("x = [0, 0; 0.2, -0.2; 10, 10; 9.8, 10.2]\nc = kmeans_centers(x, 2, seed = 1)");
        let Some(Value::Mat(centers)) = it.get("c") else {
            panic!("c is not a matrix");
        };
        assert_eq!(centers.shape(), (2, 2));
        // one center near (0,0), the other near (10,10) -- order is not
        // guaranteed, so check by whichever is closer to which.
        let near_origin = (0..2).find(|&r| centers.get(r, 0).unwrap().abs() < 5.0).expect("a center near the origin");
        let near_ten = 1 - near_origin;
        assert!((centers.get(near_origin, 0).unwrap() - 0.1).abs() < 1.0);
        assert!((centers.get(near_ten, 0).unwrap() - 9.9).abs() < 1.0);
    }

