    #[test]
    fn voronoi_of_a_square_has_one_shared_finite_vertex_and_four_unbounded_cells() {
        // Four corners of a square are concyclic, so BOTH possible Delaunay
        // diagonal choices produce triangles sharing the exact same
        // circumcenter -- the square's own center (1,1) -- making this
        // geometric fact independent of which diagonal `spade` happens to
        // pick.
        let it = run("pts = [0, 0; 2, 0; 0, 2; 2, 2]\nv = voronoi(pts)");
        let m = model_of(&it, "v");
        let bounded = to_vec(m.field("bounded").unwrap()).unwrap();
        assert_eq!(bounded.len(), 4);
        assert!(bounded.iter().all(|&b| b == 0.0), "every corner cell of a square is unbounded: {bounded:?}");
        let Value::List(cells) = m.field("cells").unwrap() else {
            panic!("voronoi model's `cells` field should be a List");
        };
        let mut all_vertices: Vec<(f64, f64)> = Vec::new();
        for cell in cells.iter() {
            let Value::Mat(mat) = cell else {
                panic!("each voronoi cell should be a Mat");
            };
            for r in 0..mat.rows() {
                all_vertices.push((mat.get(r, 0).unwrap(), mat.get(r, 1).unwrap()));
            }
        }
        assert!(!all_vertices.is_empty(), "expected at least one finite voronoi vertex");
        for (x, y) in &all_vertices {
            assert!(
                (x - 1.0).abs() < 1e-9 && (y - 1.0).abs() < 1e-9,
                "expected every finite vertex to be the shared center (1,1), got ({x}, {y})"
            );
        }
    }

