    #[test]
    fn random_walk_named_drift_and_volatility_match_the_positional_form() {
        // Regression test for a real bug (found 2026-09-01 while writing
        // catalog/qu_random_walk.qu): the doc comment on `random_walk`
        // documents `[drift=0]`/`[volatility=1]` as nameable, but the
        // implementation only ever read them positionally --
        // `random_walk(n, drift=0.05)` silently used drift=0.0 instead.
        // Fixed via `positional_or_named_num`.
        let it = run(
            "a = random_walk(50, drift=0.05, volatility=2, seed=7)\n\
             b = random_walk(50, 0.05, 2, seed=7)",
        );
        assert_eq!(vec_of(&it, "a"), vec_of(&it, "b"));
    }

    #[test]
    fn random_walk_final_position_variance_grows_roughly_linearly_with_step_count() {
        // A driftless random walk with volatility `sigma` has Var(x[n]) =
        // n * sigma^2 (sum of n i.i.d. unit-variance increments). Checked
        // statistically across 2000 independently-seeded runs at two
        // different step counts, not just "it runs" -- the variance ratio
        // between n=100 and n=25 should land close to the theoretical 4x.
        let it = run(
            "n_runs = 2000\nv25 = zeros(n_runs)\nv100 = zeros(n_runs)\n\
             for i = 0 to n_runs - 1\n\
             \x20\x20\x20\x20w1 = random_walk(25, 0, 1, seed=i)\n\
             \x20\x20\x20\x20v25[i] = w1[25]\n\
             \x20\x20\x20\x20w2 = random_walk(100, 0, 1, seed=i + 1000000)\n\
             \x20\x20\x20\x20v100[i] = w2[100]\n\
             end for",
        );
        let v25 = vec_of(&it, "v25");
        let v100 = vec_of(&it, "v100");
        let var25 = variance(&v25);
        let var100 = variance(&v100);
        let ratio = var100 / var25;
        assert!(ratio > 2.5 && ratio < 6.0, "var100={var100} var25={var25} ratio={ratio}");
    }

