    #[test]
    fn kmedians_centers_resist_outliers_more_than_kmeans_centers() {
        // Two tight blobs (near (0,0) and near (100,100)), each with ONE
        // extreme outlier along a third axis direction that stays clearly
        // closer to its own blob than to the other (so both algorithms
        // assign it to the same cluster as its blob, isolating the
        // mean-vs-median center-update rule as the only variable).
        let it = run(
            "X = [0,0; 0.2,0; 0,0.2; 0.2,0.2; 0.1,0.1; 0,15; \
                  100,100; 100.2,100; 100,100.2; 100.2,100.2; 100.1,100.1; 100,85]\n\
             km = kmeans_model(X, 2, seed=1)\nkmed = kmedians_model(X, 2, seed=1)",
        );
        let km = model_of(&it, "km");
        let kmed = model_of(&it, "kmed");
        let Some(Value::Mat(km_centers)) = km.field("centers") else { panic!("km centers missing") };
        let Some(Value::Mat(kmed_centers)) = kmed.field("centers") else { panic!("kmed centers missing") };
        // whichever row sits on the (near-origin) blob's side, identified
        // by its x-coordinate being well under the other blob's x=100.
        let km_row = (0..2).find(|&r| km_centers.get(r, 0).unwrap() < 50.0).expect("a near-origin kmeans center");
        let kmed_row = (0..2).find(|&r| kmed_centers.get(r, 0).unwrap() < 50.0).expect("a near-origin kmedians center");
        let km_y = km_centers.get(km_row, 1).unwrap();
        let kmed_y = kmed_centers.get(kmed_row, 1).unwrap();
        // the outlier-free blob's true y is 0.1; kmeans's mean update gets
        // dragged hard toward the y=15 outlier, kmedians's median barely
        // moves off it.
        assert!((km_y - 0.1).abs() > 2.0, "expected kmeans to be pulled toward the outlier: {km_y}");
        assert!((kmed_y - 0.1).abs() < 0.2, "expected kmedians to resist the outlier: {kmed_y}");
        assert!(
            (kmed_y - 0.1).abs() < (km_y - 0.1).abs(),
            "kmedians should land closer to the true center than kmeans: kmedians={kmed_y} kmeans={km_y}"
        );
    }

