    #[test]
    fn kmedoids_medoids_are_exact_rows_of_the_original_data() {
        // The mechanically-checkable property that actually distinguishes
        // k-medoids from k-means/k-medians: every fitted center must be an
        // exact row of X, not an average or a median.
        let it = run(
            "X = [0, 0; 0.3, -0.2; -0.2, 0.3; 8, 8; 8.3, 7.7; 7.6, 8.4; 16, 0; 16.2, 0.3; 15.7, -0.4]\n\
             m = kmedoids_model(X, 3, seed=7)",
        );
        let m = model_of(&it, "m");
        let Some(Value::Mat(x)) = it.get("X") else { panic!("X is not a matrix") };
        let Some(Value::Mat(centers)) = m.field("centers") else { panic!("centers missing") };
        let medoid_indices = to_vec(m.field("medoid_indices").unwrap()).unwrap();
        assert_eq!(medoid_indices.len(), 3);
        for (c, &idx_f) in medoid_indices.iter().enumerate() {
            let idx = idx_f as usize;
            for col in 0..2 {
                let center_val = centers.get(c, col).unwrap();
                let x_val = x.get(idx, col).unwrap();
                assert!(
                    (center_val - x_val).abs() < 1e-12,
                    "medoid {c} should be exactly row {idx} of X: center={center_val} x_row={x_val}"
                );
            }
        }
    }

