    // ---- reinforcement learning: environment protocol + tabular
    // Q-learning/SARSA (2026-08-25) ----

    #[test]
    fn gridworld_env_reset_returns_start_and_step_matches_hand_computed_transitions() {
        // 3x3 grid: states 0..8 row-major, default start=0 (top-left),
        // goal=8 (bottom-right), step_reward=-1, goal_reward=10.
        let it = run(
            "env = gridworld_env(3)\n\
             s0 = env.reset()\n\
             r_move = env.step(0, 1)\n\
             r_wall = env.step(0, 0)\n\
             r_goal = env.step(7, 1)",
        );
        assert_eq!(num(&it, "s0"), 0.0);
        // action 1 = right: (0,0) -> (0,1) = state 1, ordinary non-goal move.
        let Some(Value::Record(r_move)) = it.get("r_move") else { panic!("r_move not a record") };
        let field = |r: &[(String, Value)], name: &str| r.iter().find(|(k, _)| k == name).map(|(_, v)| v.clone()).unwrap();
        assert_eq!(field(r_move, "next_state").as_num().unwrap(), 1.0);
        assert_eq!(field(r_move, "reward").as_num().unwrap(), -1.0);
        assert!(matches!(field(r_move, "done"), Value::Bool(false)));
        // action 0 = up from the top row: off-grid, clamps back in place.
        let Some(Value::Record(r_wall)) = it.get("r_wall") else { panic!("r_wall not a record") };
        assert_eq!(field(r_wall, "next_state").as_num().unwrap(), 0.0);
        assert_eq!(field(r_wall, "reward").as_num().unwrap(), -1.0);
        // action 1 = right from state 7 (row 2, col 1) -> state 8, the goal.
        let Some(Value::Record(r_goal)) = it.get("r_goal") else { panic!("r_goal not a record") };
        assert_eq!(field(r_goal, "next_state").as_num().unwrap(), 8.0);
        assert_eq!(field(r_goal, "reward").as_num().unwrap(), 10.0);
        assert!(matches!(field(r_goal, "done"), Value::Bool(true)));
    }

    #[test]
    fn gridworld_env_step_rejects_an_out_of_range_action() {
        let mut it = Interp::new();
        let err = it.run("env = gridworld_env(3)\nenv.step(0, 7)").unwrap_err();
        assert!(err.msg.contains("action must be 0..3"), "got: {}", err.msg);
    }

    #[test]
    fn q_learning_single_step_update_matches_hand_computed_math() {
        // 2x2 grid: start=0, goal=3 (both defaults). epsilon=0 forces the
        // deterministic greedy action every time; with an all-zero Q-table,
        // `greedy_action`'s tie-break always picks action 0 (up) first,
        // which off a top-left corner is a wall-bump back to state 0 (not
        // the goal). One episode, one step, alpha=0.5:
        //   target = reward + gamma * max_a Q[0, a] = -1 + 0.9*0 = -1
        //   Q[0,0] = old + alpha*(target - old) = 0 + 0.5*(-1 - 0) = -0.5
        // every other cell must stay exactly 0 (untouched).
        let it = run("env = gridworld_env(2)\nm = q_learning(env, 1, alpha=0.5, gamma=0.9, epsilon=0, max_steps=1, seed=0)");
        let m = model_of(&it, "m");
        assert_eq!(m.kind, "q_learning");
        let Some(Value::Mat(q)) = m.field("q_table") else { panic!("q_table missing") };
        assert_eq!(q.shape(), (4, 4));
        assert!((q.get(0, 0).unwrap() - (-0.5)).abs() < 1e-9, "Q[0,0] = {:?}", q.get(0, 0));
        for r in 0..4 {
            for c in 0..4 {
                if r == 0 && c == 0 {
                    continue;
                }
                assert_eq!(q.get(r, c).unwrap(), 0.0, "Q[{r},{c}] should be untouched");
            }
        }
    }

    #[test]
    fn q_learning_reward_per_episode_improves_over_training_with_a_fixed_seed() {
        let it = run("env = gridworld_env(4)\nm = q_learning(env, 300, alpha=0.3, gamma=0.9, epsilon=0.1, seed=7)");
        let m = model_of(&it, "m");
        let rewards = to_vec(m.field("rewards").unwrap()).unwrap();
        assert_eq!(rewards.len(), 300);
        let early: f64 = rewards[0..20].iter().sum::<f64>() / 20.0;
        let late: f64 = rewards[280..300].iter().sum::<f64>() / 20.0;
        assert!(late > early + 1.0, "expected late-training reward clearly above early-training: early={early}, late={late}");
    }

    #[test]
    fn sarsa_reward_per_episode_improves_over_training_with_a_fixed_seed() {
        let it = run("env = gridworld_env(4)\nm = sarsa(env, 300, alpha=0.3, gamma=0.9, epsilon=0.1, seed=7)");
        let m = model_of(&it, "m");
        assert_eq!(m.kind, "sarsa");
        let rewards = to_vec(m.field("rewards").unwrap()).unwrap();
        let early: f64 = rewards[0..20].iter().sum::<f64>() / 20.0;
        let late: f64 = rewards[280..300].iter().sum::<f64>() / 20.0;
        assert!(late > early + 1.0, "expected late-training reward clearly above early-training: early={early}, late={late}");
    }

    #[test]
    fn q_learning_learned_policy_reaches_the_goal_from_the_start_state() {
        // Verifies the OTHER half of "did RL actually work": not just that
        // reward trended upward, but that greedily following the learned
        // Q-table from the start state actually reaches the goal, in no
        // more steps than the grid's own worst-case diameter.
        let it = run(
            "env = gridworld_env(4)\n\
             m = q_learning(env, 400, alpha=0.3, gamma=0.9, epsilon=0.1, seed=7)\n\
             state = env.reset()\n\
             steps = 0\n\
             done = false\n\
             while done == false and steps < 20\n\
             action = m.predict(state)\n\
             result = env.step(state, action)\n\
             state = result.next_state\n\
             steps = steps + 1\n\
             done = result.done\n\
             end while",
        );
        assert!(matches!(it.get("done"), Some(Value::Bool(true))), "greedy policy never reached the goal");
        // a 4x4 grid's Manhattan diameter (corner to corner) is 6; a
        // trained policy should never need more than that.
        assert!(num(&it, "steps") <= 6.0, "steps = {}", num(&it, "steps"));
    }

    #[test]
    fn pca_model_predict_matches_the_training_projection() {
        let it = run(
            "X = [1, 2, 1; 2, 4, 2; 3, 5, 3.2; 4, 9, 3.8; 5, 10, 5.1; 6, 11, 6.3]\n\
             pm = pca_model(X, 1)\nproj = pm.predict(X)\ndirect = pca(X, 1)",
        );
        let Some(Value::Mat(proj)) = it.get("proj") else { panic!("proj not a matrix") };
        let Some(Value::Mat(direct)) = it.get("direct") else { panic!("direct not a matrix") };
        assert_eq!(proj.shape(), direct.shape());
        // both paths project the same centered X onto the same V^T rows
        // (pca_fit's own U*S identity vs. pca_project's (Xc @ components^T)
        // formula for new data) -- exactly equal, not just up to sign.
        for i in 0..proj.as_slice().len() {
            assert!(
                (proj.as_slice()[i] - direct.as_slice()[i]).abs() < 1e-6,
                "pca_model.predict on its own training data should match pca(X,k): {} vs {}",
                proj.as_slice()[i],
                direct.as_slice()[i]
            );
        }
    }

    #[test]
    fn dbscan_separates_two_dense_clusters_from_scattered_noise() {
        // two tight 6-point clusters ~10 units apart (eps=1.0 comfortably
        // spans each cluster's own ~0.5-unit spread but not the gap between
        // clusters) plus two far-flung points that have no 4-point
        // neighborhood anywhere (min_samples=4, scikit-learn's "including
        // self" convention).
        let it = run(
            "pts = [0,0; 0.2,0.1; -0.1,0.2; 0.1,-0.1; -0.2,-0.1; 0.15,0.15; \
             10,10; 10.2,9.9; 9.8,10.1; 10.1,10.2; 9.9,9.8; 10.15,9.95; \
             50,50; -50,-50]\n\
             labels = dbscan(pts, 1.0, 4)",
        );
        let labels = vec_of(&it, "labels");
        assert_eq!(labels.len(), 14);
        let first_cluster = labels[0];
        let second_cluster = labels[6];
        assert_ne!(first_cluster, second_cluster, "the two dense blobs must land in different clusters");
        assert_ne!(first_cluster, -1.0);
        assert_ne!(second_cluster, -1.0);
        for &l in &labels[0..6] {
            assert_eq!(l, first_cluster, "every point in the first blob should share one cluster id");
        }
        for &l in &labels[6..12] {
            assert_eq!(l, second_cluster, "every point in the second blob should share one cluster id");
        }
        assert_eq!(labels[12], -1.0, "a lone far-away point has no eps-neighborhood and must be noise");
        assert_eq!(labels[13], -1.0, "a lone far-away point has no eps-neighborhood and must be noise");
    }

