    fn dbscan_rejects_a_non_positive_eps() {
        let mut it = Interp::new();
        let err = it.run("labels = dbscan([1,1;2,2;3,3], 0.0, 2)").unwrap_err();
        assert!(err.msg.contains("eps must be positive"), "got: {}", err.msg);
    }

    #[test]
    fn gmm_model_recovers_well_separated_gaussian_means_and_log_likelihood_never_decreases() {
        // two overlapping-but-separable Gaussian blobs (std 1.4, centers
        // 5 units apart) -- overlapping enough that the k-means warm start
        // needs several real EM refinements before converging, unlike a
        // trivially well-separated case where EM would stop after 1-2
        // iterations with nothing to check monotonicity against.
        let it = run(
            "n1 = 40\nn2 = 40\nX = zeros(n1 + n2, 2)\n\
             b1 = randn(n1, 2, seed=1) * 1.4\nb2 = randn(n2, 2, seed=2) * 1.4 + 5\n\
             for i = 0 to n1 - 1\n  X[i, 0] = b1[i, 0]\n  X[i, 1] = b1[i, 1]\nend for\n\
             for i = 0 to n2 - 1\n  X[n1 + i, 0] = b2[i, 0]\n  X[n1 + i, 1] = b2[i, 1]\nend for\n\
             m = gmm_model(X, 2, seed=7, max_iter=100)",
        );
        let m = model_of(&it, "m");
        assert_eq!(m.kind, "gmm");
        let Some(Value::Mat(means)) = m.field("means") else { panic!("means not a matrix") };
        assert_eq!(means.shape(), (2, 2));
        // component order isn't guaranteed -- match each true center to
        // its nearest fitted mean instead of assuming row order.
        for true_center in [[0.0_f64, 0.0], [5.0, 5.0]] {
            let nearest = (0..2)
                .map(|r| {
                    let dx = means.get(r, 0).unwrap() - true_center[0];
                    let dy = means.get(r, 1).unwrap() - true_center[1];
                    (dx * dx + dy * dy).sqrt()
                })
                .fold(f64::INFINITY, f64::min);
            assert!(nearest < 1.0, "no fitted mean within 1.0 of true center {true_center:?}, means={means}");
        }
        let ll = to_vec(m.field("log_likelihood").unwrap()).unwrap();
        assert!(ll.len() >= 2, "expected more than one EM iteration on overlapping data, got {}", ll.len());
        for pair in ll.windows(2) {
            assert!(pair[1] >= pair[0] - 1e-6, "log-likelihood decreased: {} -> {}", pair[0], pair[1]);
        }
    }

    #[test]
    fn gmm_model_predict_separates_new_points_and_score_matches_training_log_likelihood() {
        let it = run(
            "n1 = 25\nn2 = 25\nX = zeros(n1 + n2, 2)\n\
             b1 = randn(n1, 2, seed=1) * 0.6\nb2 = randn(n2, 2, seed=2) * 0.6 + 12\n\
             for i = 0 to n1 - 1\n  X[i, 0] = b1[i, 0]\n  X[i, 1] = b1[i, 1]\nend for\n\
             for i = 0 to n2 - 1\n  X[n1 + i, 0] = b2[i, 0]\n  X[n1 + i, 1] = b2[i, 1]\nend for\n\
             m = gmm_model(X, 2, seed=7, max_iter=50)\n\
             hi = [12, 12] as matrix(1, 2)\nlo = [0, 0] as matrix(1, 2)\n\
             label_hi = m.predict(hi)\nlabel_lo = m.predict(lo)\nscore_val = m.score(X)",
        );
        let label_hi = vec_of(&it, "label_hi");
        let label_lo = vec_of(&it, "label_lo");
        assert_ne!(label_hi[0], label_lo[0], "points near opposite blobs must get different hard assignments");
        let score = num(&it, "score_val");
        let m = model_of(&it, "m");
        let ll = to_vec(m.field("log_likelihood").unwrap()).unwrap();
        let last_train_ll = *ll.last().unwrap();
        assert!(
            (score - last_train_ll).abs() < 1e-6,
            "score(X) on the training set should match the final training log-likelihood: {score} vs {last_train_ll}"
        );
    }

    #[test]
    fn gmm_model_rejects_k_larger_than_row_count() {
        let mut it = Interp::new();
        let err = it.run("m = gmm_model([1,1;2,2], 5)").unwrap_err();
        assert!(err.msg.contains("must be between"), "got: {}", err.msg);
    }

    /// Shared by every "does t-SNE actually separate the blobs" test below
    /// (default method, explicit `"exact"`, explicit `"barnes_hut"`):
    /// t-SNE's actual job is preserving local neighborhood structure, so
    /// the real check is that the average within-blob embedded distance
    /// stays well below the average between-blob embedded distance, not
    /// just "produces 2 columns of numbers" — and that check should hold
    /// regardless of which method computed the gradient, since both are
    /// meant to converge toward the same embedding, just at different
    /// speeds.
    fn assert_tsne_separates_two_blobs(extra_tsne_args: &str) {
        let it = run(&format!(
            "n1 = 15\nn2 = 15\nd = 5\nX = zeros(n1 + n2, d)\n\
             b1 = randn(n1, d, seed=11) * 0.5\nb2 = randn(n2, d, seed=12) * 0.5 + 8\n\
             for i = 0 to n1 - 1\n  for j = 0 to d - 1\n    X[i, j] = b1[i, j]\n  end for\nend for\n\
             for i = 0 to n2 - 1\n  for j = 0 to d - 1\n    X[n1 + i, j] = b2[i, j]\n  end for\nend for\n\
             Y = tsne(X, n_components=2, seed=3, max_iter=600{extra_tsne_args})",
        ));
        let Some(Value::Mat(y)) = it.get("Y") else { panic!("Y not a matrix") };
        assert_eq!(y.shape(), (30, 2));
        let (n1, n) = (15usize, 30usize);
        let mut sum_within = 0.0;
        let mut cnt_within = 0.0;
        let mut sum_between = 0.0;
        let mut cnt_between = 0.0;
        for i in 0..n {
            for j in (i + 1)..n {
                let dx = y.get(i, 0).unwrap() - y.get(j, 0).unwrap();
                let dy = y.get(i, 1).unwrap() - y.get(j, 1).unwrap();
                let dist = (dx * dx + dy * dy).sqrt();
                if (i < n1) == (j < n1) {
                    sum_within += dist;
                    cnt_within += 1.0;
                } else {
                    sum_between += dist;
                    cnt_between += 1.0;
                }
            }
        }
        let avg_within = sum_within / cnt_within;
        let avg_between = sum_between / cnt_between;
        assert!(
            avg_between > 1.3 * avg_within,
            "expected the two blobs to stay visibly separated in the embedding: avg_within={avg_within}, avg_between={avg_between}"
        );
    }

    #[test]
    fn tsne_keeps_two_well_separated_high_dimensional_blobs_apart_in_the_embedding() {
        // no `method=` -- exercises the default, which is `"barnes_hut"`
        // for `n_components=2` (see the two explicit-method tests below
        // for direct coverage of each path on its own).
        assert_tsne_separates_two_blobs("");
    }

    #[test]
    fn tsne_method_exact_keeps_two_well_separated_blobs_apart() {
        assert_tsne_separates_two_blobs(", method=\"exact\"");
    }

    #[test]
    fn tsne_method_barnes_hut_keeps_two_well_separated_blobs_apart() {
        assert_tsne_separates_two_blobs(", method=\"barnes_hut\"");
    }

