    #[test]
    fn svm_model_predicts_back_in_the_callers_own_label_space() {
        // y uses 0/1, not -1/+1 -- predictions must come back as 0/1 too,
        // even though the fit maps internally to -1/+1.
        let it = run(
            "X = [1,1; 1.1,0.9; 0.9,1.1; 8,8; 8.1,7.9; 7.9,8.1]\n\
             y = [0,0,0,1,1,1]\n\
             m = svm_model(X, y)\nacc = m.score(X, y)\npred = m.predict(X)",
        );
        assert!((num(&it, "acc") - 1.0).abs() < 1e-9);
        let pred = vec_of(&it, "pred");
        for &p in &pred {
            assert!(p == 0.0 || p == 1.0, "predictions should use the caller's own labels (0/1), got {p}");
        }
        assert_eq!(&pred[0..3], &[0.0, 0.0, 0.0]);
        assert_eq!(&pred[3..6], &[1.0, 1.0, 1.0]);
    }

