    #[test]
    fn random_forest_model_reduces_variance_versus_a_single_tree() {
        // same noisy training set fit by both a single (deep enough to
        // overfit the noise) tree and a 40-tree forest; measured against
        // the *noiseless* underlying line, the forest's bootstrap-averaged
        // prediction should land closer to the truth than the single
        // overfit tree's does -- the real, measurable point of bagging.
        let it = run(
            "v = 0:1:29\nX = v as matrix(30, 1)\ntruth = 3 * v + 5\n\
             y = truth + 5 * randn(30, seed=1)\n\
             tree = tree_model(X, y, max_depth=8)\n\
             forest = random_forest_model(X, y, 40, max_depth=8, seed=1)\n\
             tree_pred = tree.predict(X)\nforest_pred = forest.predict(X)\n\
             tree_err = mean((tree_pred - truth) ** 2)\n\
             forest_err = mean((forest_pred - truth) ** 2)",
        );
        let tree_err = num(&it, "tree_err");
        let forest_err = num(&it, "forest_err");
        assert!(forest_err < tree_err, "forest MSE {forest_err} should beat single-tree MSE {tree_err}");
    }

    #[test]
    fn random_forest_model_is_reproducible_under_the_same_seed() {
        let it = run(
            "v = 0:1:19\nX = v as matrix(20, 1)\ny = 3 * v + 5 + 2 * randn(20, seed=9)\n\
             a = random_forest_model(X, y, 10, seed=3)\nb = random_forest_model(X, y, 10, seed=3)\n\
             pa = a.predict(X)\npb = b.predict(X)",
        );
        assert_eq!(vec_of(&it, "pa"), vec_of(&it, "pb"));
    }

