    #[test]
    fn waterfall_pushes_one_offset_line_series_per_matrix_row() {
        let it = run("x = 0 to 3\nZ = [1, 2, 3, 4; 5, 6, 7, 8]\nwaterfall(x, Z)");
        let panel = &it.figure.panels[0];
        assert_eq!(panel.series.len(), 2);
        // later rows (further "back") get a larger offset, so the first
        // pushed trace (row 0) should NOT start at the unshifted x[0]=0.
        assert!(panel.series[0].x[0] > 0.0);
        assert_eq!(panel.series[1].x[0], 0.0); // last row: zero offset
    }

