    #[test]
    fn scatterfit_pushes_scatter_points_and_a_fit_line() {
        let it = run("x = 0 to 9\ny = 2*x + 1\nscatterfit(x, y)");
        let panel = &it.figure.panels[0];
        assert_eq!(panel.series.len(), 2);
        assert_eq!(panel.series[0].marker, "o");
        assert_eq!(panel.series[1].marker, "line");
        // the fit is exact (data is a perfect line), so it should reproduce
        // y = 2x + 1 at the fit line's own endpoints.
        let fit = &panel.series[1];
        assert!((fit.y[0] - (2.0 * fit.x[0] + 1.0)).abs() < 1e-6);
    }

    #[test]
    fn splineplot_passes_through_every_control_point() {
        let it = run("splineplot([0, 1, 2, 3], [0, 1, 0, 1])");
        let s = &it.figure.panels[0].series[0];
        // the dense resampled curve must hit each original control point's
        // value at (or extremely near) its x location.
        for (cx, cy) in [(0.0, 0.0), (1.0, 1.0), (2.0, 0.0), (3.0, 1.0)] {
            let closest = s.x.iter().zip(&s.y).min_by(|(ax, _), (bx, _)| {
                (**ax - cx).abs().partial_cmp(&(**bx - cx).abs()).unwrap()
            }).unwrap();
            assert!((closest.1 - cy).abs() < 0.05, "near x={cx}: got {closest:?}");
        }
    }

    #[test]
    fn pwl_recovers_an_exact_piecewise_linear_signal() {
        // a true 2-segment piecewise-linear "tent" function: up then down,
        // peaking exactly at the midpoint breakpoint.
        let it = run("x = 0 to 10\ny = min(x, 10 - x)\nc = pwl(x, y, 2)");
        let panel = &it.figure.panels[0];
        let fit = &panel.series[0];
        assert_eq!(fit.x.len(), 3); // 2 segments -> 3 breakpoints
        assert!((fit.y[0] - 0.0).abs() < 1e-6);
        assert!((fit.y[1] - 5.0).abs() < 1e-6);
        assert!((fit.y[2] - 0.0).abs() < 1e-6);
    }

