    #[test]
    fn table_constructor_builds_a_str_column_from_a_bracket_list_literal() {
        // Before bracket literals could hold strings, the only way to get a
        // `Column::Str` into a table was to read one out of a CSV.
        let it = run(r#"df = DataFrame(name=["Alice", "Bob"], age=[30, 25])"#);
        let Some(Value::Table(t)) = it.get("df") else { panic!("expected a table") };
        assert_eq!(t.column_names(), vec!["name", "age"]);
        match t.col("name") {
            Some(Column::Str(v)) => assert_eq!(v, &vec!["Alice".to_string(), "Bob".to_string()]),
            other => panic!("expected a Str column, got {other:?}"),
        }
        match t.col("age") {
            Some(Column::Num(v)) => assert_eq!(v, &vec![30.0, 25.0]),
            other => panic!("expected a Num column, got {other:?}"),
        }
    }

    #[test]
    fn table_from_csv_text_reads_headers_then_rows() {
        // The column-wise constructor makes you transpose the data by hand
        // before the language sees it. This is the same table written the
        // way it arrives.
        let it = run(
            "runs = table(\"\n\
             channel, baseline, treated\n\
             1,       0.412,    0.240\n\
             2,       0.508,    0.301\n\
             \")",
        );
        let Some(Value::Table(t)) = it.get("runs") else { panic!("expected a table") };
        assert_eq!(t.column_names(), vec!["channel", "baseline", "treated"]);
        match t.col("baseline") {
            Some(Column::Num(v)) => assert_eq!(v, &vec![0.412, 0.508]),
            other => panic!("expected a Num column, got {other:?}"),
        }
    }

    #[test]
    fn table_from_csv_text_trims_alignment_padding_and_ignores_blank_lines() {
        // The padding that lines the columns up in the source must not
        // reach the table: a string column would otherwise carry it, and
        // `t.name == "steel"` would quietly be false.
        let it = run(
            "t = table(\"\n\
             name  | mass\n\
             steel | 7.85\n\
             \n\
             alu   | 2.70\n\
             \", sep = \"|\")",
        );
        let Some(Value::Table(t)) = it.get("t") else { panic!("expected a table") };
        match t.col("name") {
            Some(Column::Str(v)) => {
                assert_eq!(v, &vec!["steel".to_string(), "alu".to_string()]);
            }
            other => panic!("expected a Str column, got {other:?}"),
        }
        match t.col("mass") {
            Some(Column::Num(v)) => assert_eq!(v, &vec![7.85, 2.70]),
            other => panic!("expected a Num column, got {other:?}"),
        }
    }

    #[test]
    fn table_from_csv_text_without_headers_names_the_columns_itself() {
        let it = run("t = table(\"1, 2\n3, 4\", headers = false)");
        let Some(Value::Table(t)) = it.get("t") else { panic!("expected a table") };
        assert_eq!(t.column_names(), vec!["col1", "col2"]);
    }

    #[test]
    fn table_from_csv_text_reports_a_ragged_row_rather_than_padding_it() {
        // Silently filling the gap with a zero would make a typo look like
        // data, which is the failure mode this whole form has to avoid.
        let err = run_err("t = table(\"a, b\n1\")").msg;
        assert!(
            err.contains("a row has 1 field, the header has 2"),
            "got: {err}"
        );
    }

    #[test]
    fn table_filter_select_sort_and_head_compose() {
        let it = run(
            "df = table(x = 0 to 9, y = 0 to 9)\nbig = filter(df, df.x > 5)\nn = nrow(big)\ntop = head(sort_by(df, \"x\", true), 2)",
        );
        assert!(matches!(it.get("n"), Some(Value::Num(n)) if (*n - 4.0).abs() < 1e-9));
        let Some(Value::Table(top)) = it.get("top") else { panic!("expected a table") };
        assert_eq!(top.col_num("x").unwrap(), &[9.0, 8.0]);
    }

    // `Value::Table` became `Arc`-wrapped (§ table perf, 2026-08-31) so a
    // plain variable read is a refcount bump instead of a full deep clone
    // of every column. Since every `Table` method takes `&self` and
    // returns a brand-new `Table` (no in-place mutation exists anywhere in
    // `table.rs`), two variables that alias the same underlying `Table` via
    // that cheap `Arc` clone can never observe each other's "changes" —
    // this pins that down: reassigning one alias via `filter`/`sort_by`
    // must leave every other alias (and the original) completely
    // untouched, exactly as if each read had still been a deep clone.
    #[test]
    fn table_arc_sharing_does_not_let_one_alias_mutate_another() {
        let it = run(
            "df = table(x = 0 to 4, y = 10 to 14)\n\
             alias1 = df\n\
             alias2 = df\n\
             alias1 = filter(alias1, alias1.x > 2)\n\
             alias2 = sort_by(alias2, \"x\", true)",
        );
        // The original `df` must be untouched: all 5 rows, original order.
        let Some(Value::Table(orig)) = it.get("df") else { panic!("expected a table") };
        assert_eq!(orig.col_num("x").unwrap(), &[0.0, 1.0, 2.0, 3.0, 4.0]);
        assert_eq!(orig.col_num("y").unwrap(), &[10.0, 11.0, 12.0, 13.0, 14.0]);
        // `alias1`'s filter must not have leaked into `alias2`'s sort, or
        // vice versa.
        let Some(Value::Table(a1)) = it.get("alias1") else { panic!("expected a table") };
        assert_eq!(a1.col_num("x").unwrap(), &[3.0, 4.0]);
        let Some(Value::Table(a2)) = it.get("alias2") else { panic!("expected a table") };
        assert_eq!(a2.col_num("x").unwrap(), &[4.0, 3.0, 2.0, 1.0, 0.0]);
    }

    #[test]
    fn table_csv_round_trip_via_files() {
        let dir = std::env::temp_dir();
        let path = dir.join("qu_table_test.csv");
        let mut it = Interp::new();
        it.run(&format!(
            "df = table(x = 0 to 3, label = \"a\")\nwrite_csv(df, \"{}\")",
            path.display().to_string().replace('\\', "\\\\")
        )).unwrap();
        let mut it2 = Interp::new();
        it2.run(&format!(
            "df2 = read_csv(\"{}\")\nn = nrow(df2)\nxv = df2.x",
            path.display().to_string().replace('\\', "\\\\")
        )).unwrap();
        assert!(matches!(it2.get("n"), Some(Value::Num(n)) if (*n - 4.0).abs() < 1e-9));
        assert_eq!(vec_of(&it2, "xv"), vec![0.0, 1.0, 2.0, 3.0]);
        let _ = std::fs::remove_file(path);
    }

    #[test]
    fn table_group_by_agg_builtin_reduces_each_group() {
        let mut it = Interp::new();
        let dir = std::env::temp_dir();
        let path = dir.join("qu_table_groupby_test.csv");
        std::fs::write(&path, "group,value\na,1\na,3\nb,10\nb,20\n").unwrap();
        it.run(&format!(
            "df = read_csv(\"{}\")\nagg = group_by_agg(df, \"group\", \"value\", \"mean\")\nn = nrow(agg)\nmeans = agg.mean_value",
            path.display().to_string().replace('\\', "\\\\")
        )).unwrap();
        assert!(matches!(it.get("n"), Some(Value::Num(n)) if (*n - 2.0).abs() < 1e-9));
        assert_eq!(vec_of(&it, "means"), vec![2.0, 15.0]);
        let _ = std::fs::remove_file(path);
    }

    /// `group_by_agg(table, "group_col", [(col,agg), ...])` — the multi-spec
    /// calling form, at the `.qu` script level: one call computing several
    /// `(column, aggregate)` pairs (across two different value columns)
    /// together, and the result must equal what three separate single-spec
    /// calls would produce.
    #[test]
    fn table_group_by_agg_multi_spec_builtin_matches_separate_single_calls() {
        let mut it = Interp::new();
        let dir = std::env::temp_dir();
        let path = dir.join("qu_table_groupby_multi_test.csv");
        std::fs::write(&path, "group,value,qty\na,1,5\na,3,7\nb,10,1\nb,20,2\n").unwrap();
        let csv_path = path.display().to_string().replace('\\', "\\\\");
        it.run(&format!(
            "df = read_csv(\"{csv_path}\")\n\
             multi = group_by_agg(df, \"group\", ((\"value\", \"mean\"), (\"value\", \"sum\"), (\"qty\", \"max\")))\n\
             mean_value = multi.mean_value\n\
             sum_value = multi.sum_value\n\
             max_qty = multi.max_qty\n\
             s1 = group_by_agg(df, \"group\", \"value\", \"mean\")\n\
             s2 = group_by_agg(df, \"group\", \"value\", \"sum\")\n\
             s3 = group_by_agg(df, \"group\", \"qty\", \"max\")\n\
             single_mean = s1.mean_value\n\
             single_sum = s2.sum_value\n\
             single_max = s3.max_qty"
        )).unwrap();
        assert_eq!(vec_of(&it, "mean_value"), vec![2.0, 15.0]);
        assert_eq!(vec_of(&it, "sum_value"), vec![4.0, 30.0]);
        assert_eq!(vec_of(&it, "max_qty"), vec![7.0, 2.0]);
        assert_eq!(vec_of(&it, "mean_value"), vec_of(&it, "single_mean"));
        assert_eq!(vec_of(&it, "sum_value"), vec_of(&it, "single_sum"));
        assert_eq!(vec_of(&it, "max_qty"), vec_of(&it, "single_max"));
        let _ = std::fs::remove_file(path);
    }

    // ---- table row index + bracket indexing + drop/insert + `.=`/`@`
    // (§ table row index, 2026-08-26) ----

    fn record_field<'a>(v: &'a Value, key: &str) -> &'a Value {
        let Value::Record(fields) = v else { panic!("expected a record, found {}", v.type_name()) };
        &fields.iter().find(|(k, _)| k == key).unwrap_or_else(|| panic!("record has no field `{key}`")).1
    }

    #[test]
    fn default_index_bracket_lookup_is_by_row_position() {
        let it = run("t = table(x = 0 to 3, y = [10, 20, 30, 40])\nr = t[2]\nrx = r.x\nry = r.y");
        assert!(matches!(it.get("rx"), Some(Value::Num(n)) if (*n - 2.0).abs() < 1e-9));
        assert!(matches!(it.get("ry"), Some(Value::Num(n)) if (*n - 30.0).abs() < 1e-9));
    }

    #[test]
    fn default_index_out_of_bounds_is_a_clear_error() {
        let mut it = Interp::new();
        let err = it.run("t = table(x = 0 to 2)\nr = t[9]").unwrap_err();
        assert!(err.msg.contains('9'), "got: {}", err.msg);
    }

    #[test]
    fn custom_string_index_via_index_by_method_looks_up_by_label() {
        let it = run(
            "base = table(x = 0 to 2)\n\
             lab = insert_column(base, \"id\", (\"p\", \"q\", \"r\"))\n\
             idx = lab.index(\"id\")\n\
             single = idx[\"q\"]\n\
             sx = single.x",
        );
        assert!(matches!(it.get("sx"), Some(Value::Num(n)) if (*n - 1.0).abs() < 1e-9));
    }

    #[test]
    fn duplicate_index_label_returns_every_matching_row_as_a_list() {
        // Confirmed with Ahmed, 2026-08-26: duplicate index values are
        // explicitly allowed (pandas-style) — a lookup on a duplicate
        // label returns every matching row, not an error, not just the
        // first. Unique-label lookup (previous test) returns a bare
        // `Value::Record` instead of a one-element list — the documented
        // dual-return shape.
        let it = run(
            "base = table(x = 0 to 3)\n\
             lab = insert_column(base, \"grp\", (\"a\", \"a\", \"b\", \"b\"))\n\
             idx = lab.index(\"grp\")\n\
             matches = idx[\"b\"]",
        );
        let Some(Value::List(rows)) = it.get("matches") else { panic!("expected a list of records") };
        assert_eq!(rows.len(), 2);
        assert!(matches!(record_field(&rows[0], "x"), Value::Num(n) if (*n - 2.0).abs() < 1e-9));
        assert!(matches!(record_field(&rows[1], "x"), Value::Num(n) if (*n - 3.0).abs() < 1e-9));
    }

    #[test]
    fn index_with_no_args_resets_back_to_the_default_index() {
        let it = run(
            "base = table(x = 0 to 2)\n\
             lab = insert_column(base, \"id\", (\"p\", \"q\", \"r\"))\n\
             idx = lab.index(\"id\")\n\
             back = idx.index()",
        );
        let Some(Value::Table(indexed)) = it.get("idx") else { panic!("expected a table") };
        assert_eq!(indexed.index_col_name(), Some("id"));
        let Some(Value::Table(reset)) = it.get("back") else { panic!("expected a table") };
        assert_eq!(reset.index_col_name(), None);
    }

    #[test]
    fn at_is_always_positional_even_with_a_custom_index_set() {
        let it = run(
            "base = table(x = 0 to 2)\n\
             lab = insert_column(base, \"grp\", (\"a\", \"a\", \"b\"))\n\
             idx = lab.index(\"grp\")\n\
             r = idx.at(0)\n\
             rx = r.x\n\
             rg = r.grp",
        );
        // position 0's `x` is 0 and `grp` is \"a\" — `.at(0)` must read the
        // FIRST row by position, never treat `0` as an index-column label
        // (the custom index here is `grp`, a string column, so `0` isn't
        // even a valid label — `.at` must not care either way).
        assert!(matches!(it.get("rx"), Some(Value::Num(n)) if n.abs() < 1e-9));
        assert!(matches!(it.get("rg"), Some(Value::Str(s)) if s == "a"));
    }

    #[test]
    fn drop_row_returns_a_new_table_and_does_not_mutate_the_original() {
        let it = run("base = table(x = 0 to 3)\ndropped = drop_row(base, 1)\nn0 = nrow(base)\nn1 = nrow(dropped)\nxv = dropped.x");
        assert!(matches!(it.get("n0"), Some(Value::Num(n)) if (*n - 4.0).abs() < 1e-9));
        assert!(matches!(it.get("n1"), Some(Value::Num(n)) if (*n - 3.0).abs() < 1e-9));
        assert_eq!(vec_of(&it, "xv"), vec![0.0, 2.0, 3.0]);
    }

    #[test]
    fn drop_row_out_of_bounds_is_a_clear_error() {
        let mut it = Interp::new();
        let err = it.run("base = table(x = 0 to 2)\nbad = drop_row(base, 99)").unwrap_err();
        assert!(err.msg.contains("99"), "got: {}", err.msg);
    }

    #[test]
    fn drop_row_accepts_a_bracketed_list_of_indices_for_a_multi_row_drop() {
        let it = run(
            "base = table(x = 0 to 4)\n\
             dropped = drop_row(base, [1, 3])\n\
             n0 = nrow(base)\n\
             n1 = nrow(dropped)\n\
             xv = dropped.x",
        );
        assert!(matches!(it.get("n0"), Some(Value::Num(n)) if (*n - 5.0).abs() < 1e-9));
        assert!(matches!(it.get("n1"), Some(Value::Num(n)) if (*n - 3.0).abs() < 1e-9));
        // rows 0, 2, 4 survive, in original order — 1 and 3 are gone.
        assert_eq!(vec_of(&it, "xv"), vec![0.0, 2.0, 4.0]);
    }

    #[test]
    fn drop_row_multi_preserves_column_order_and_types() {
        let it = run(
            "base = table(id = 0 to 3)\n\
             lab = insert_column(base, \"label\", (\"p\", \"q\", \"r\", \"s\"))\n\
             dropped = drop_row(lab, [0, 2])\n\
             idv = dropped.id\n\
             lb = dropped.label",
        );
        // survivors are original rows 1 and 3: id 1, 3 / label \"q\", \"s\" —
        // both columns still line up row-for-row and keep their own types
        // (numeric `id`, text `label`) and left-to-right order.
        assert_eq!(vec_of(&it, "idv"), vec![1.0, 3.0]);
        let Some(Value::List(labels)) = it.get("lb") else { panic!("expected a text-column list") };
        let labels: Vec<String> = labels
            .iter()
            .map(|v| match v {
                Value::Str(s) => s.clone(),
                other => panic!("expected Value::Str, got {other:?}"),
            })
            .collect();
        assert_eq!(labels, vec!["q", "s"]);
    }

