    #[test]
    fn dot_equals_and_at_operator_produce_identical_results() {
        // `t .= drop("b")` and `@t.drop("b")` are two spellings of exactly
        // the same desugar (§ `.=` and `@`, 2026-08-26) — both must produce
        // the same table from the same starting data.
        let it = run(
            "t1 = table(a = [1, 2], b = [3, 4], c = [5, 6])\n\
             t1 .= drop(\"b\")\n\
             t2 = table(a = [1, 2], b = [3, 4], c = [5, 6])\n\
             @t2.drop(\"b\")",
        );
        let Some(Value::Table(t1)) = it.get("t1") else { panic!("expected a table") };
        let Some(Value::Table(t2)) = it.get("t2") else { panic!("expected a table") };
        assert_eq!(t1.column_names(), vec!["a", "c"]);
        assert_eq!(t1.column_names(), t2.column_names());
        assert_eq!(t1.col_num("a").unwrap(), t2.col_num("a").unwrap());
        assert_eq!(t1.col_num("c").unwrap(), t2.col_num("c").unwrap());
    }

