    #[test]
    fn corrmat_ignores_text_columns_and_matches_direct_corrcoef() {
        // a/b perfectly anti-correlated; `target` is dropped first; `name`
        // is a text column that must be silently skipped (not errored on)
        // by `corrmat()`, same convention `corr_heatmap`/`describe` use.
        let mut it = Interp::new();
        let dir = std::env::temp_dir();
        let path = dir.join("qu_corrmat_test.csv");
        std::fs::write(
            &path,
            "a,b,target,name\n1,5,9,x\n2,4,9,y\n3,3,9,z\n4,2,9,w\n5,1,9,v\n",
        )
        .unwrap();
        it.run(&format!(
            "data = read_csv(\"{}\")\ncleaned = data.drop(\"target\")\nrm = cleaned.corrmat()",
            path.display().to_string().replace('\\', "\\\\")
        )).unwrap();

        let Some(Value::Table(cleaned)) = it.get("cleaned") else { panic!("expected a table") };
        // `name` (text) survives the drop — corrmat() must skip it, not error.
        assert_eq!(cleaned.column_names(), vec!["a", "b", "name"]);

        let Some(Value::Model(m)) = it.get("rm") else { panic!("expected a model") };
        assert_eq!(m.kind, "corrmat");
        let Some(Value::Mat(mat)) = m.field("matrix") else { panic!("expected a matrix field") };
        assert_eq!(mat.shape(), (2, 2));
        assert!((mat.get(0, 0).unwrap() - 1.0).abs() < 1e-9);
        assert!((mat.get(1, 1).unwrap() - 1.0).abs() < 1e-9);
        assert!((mat.get(0, 1).unwrap() + 1.0).abs() < 1e-9); // a,b perfectly anti-correlated
        assert!((mat.get(1, 0).unwrap() + 1.0).abs() < 1e-9);
        let Some(Value::List(labels)) = m.field("labels") else { panic!("expected labels") };
        let labels: Vec<String> = labels.iter().map(display_value).collect();
        assert_eq!(labels, vec!["a", "b"]); // "name" (text) and "target" (dropped) excluded

        let _ = std::fs::remove_file(path);
    }

    #[test]
    fn corrmat_plot_renders_a_heatmap_matching_corrcoef_on_the_same_data() {
        let mut it = Interp::new();
        let dir = std::env::temp_dir();
        let path = dir.join("qu_corrmat_plot_test.csv");
        std::fs::write(
            &path,
            "a,b,target\n1,5,9\n2,4,9\n3,3,9\n4,2,9\n5,1,9\n",
        )
        .unwrap();
        // The exact end-to-end chain from the spec: drop -> corrmat -> plot.
        it.run(&format!(
            "data = read_csv(\"{}\")\ndata.drop(\"target\").corrmat().plot()",
            path.display().to_string().replace('\\', "\\\\")
        )).unwrap();

        let hm = it.figure.panels[0].heatmap.as_ref().expect("plot() on a corrmat() result should push a heatmap");
        assert_eq!(hm.rows, 2);
        assert_eq!(hm.cols, 2);
        assert_eq!(hm.row_labels, vec!["a", "b"]);
        assert_eq!(hm.col_labels, vec!["a", "b"]);
        // row-major `values` (see `corrmat_heatmap`): [0]=corr(a,a), [1]=corr(a,b), ...
        assert!((hm.values[0] - 1.0).abs() < 1e-9);
        assert!((hm.values[1] + 1.0).abs() < 1e-9);
        assert!((hm.values[2] + 1.0).abs() < 1e-9);
        assert!((hm.values[3] - 1.0).abs() < 1e-9);

        // Cross-check against calling `corrcoef` directly on the same
        // (target-excluded) numeric data, confirming `corrmat()` didn't
        // reimplement the correlation math differently.
        let mut it2 = Interp::new();
        it2.run("a = [1,2,3,4,5]\nb = [5,4,3,2,1]\nX = vstack(a, b)'\nR = corrcoef(X)").unwrap();
        let Some(Value::Mat(r)) = it2.get("R") else { panic!("expected a matrix") };
        for i in 0..2 {
            for j in 0..2 {
                assert!((hm.values[i * 2 + j] - r.get(i, j).unwrap()).abs() < 1e-9);
            }
        }

        let _ = std::fs::remove_file(path);
    }

