    #[test]
    fn try_catch_recovers_from_a_raised_error_and_binds_its_message() {
        // `catch err` binds a record (spec §18.B: `message`/`line`/`stack`/
        // `type`), not a bare string — `err.message` is where "boom" lives.
        let it = run("try\n  error(\"boom\")\n  x = 1\ncatch err\n  x = 2\n  msg = err.message\nend");
        assert!(matches!(it.get("x"), Some(Value::Num(n)) if (*n - 2.0).abs() < 1e-9));
        assert!(matches!(it.get("msg"), Some(Value::Str(s)) if s == "boom"));
    }

    #[test]
    fn try_without_error_skips_the_catch_handler_entirely() {
        let it = run("try\n  x = 1\ncatch\n  x = 99\nend");
        assert!(matches!(it.get("x"), Some(Value::Num(n)) if (*n - 1.0).abs() < 1e-9));
    }

    #[test]
    fn try_catch_recovers_from_a_genuine_runtime_type_error_too() {
        // not just `error()` — any real EvalError (here: pinv on a non-matrix)
        // must be equally catchable, since there's no separate exception type.
        let it = run("try\n  y = pinv(\"not a matrix\")\ncatch err\n  caught = true\nend");
        assert!(matches!(it.get("caught"), Some(Value::Bool(true))));
    }

    /// A function's `for` variable must not touch the caller's.
    ///
    /// `var_set` writes through to a global when the name exists there,
    /// which is deliberate for an assignment and wrong for a loop variable:
    /// any function containing `for i in ...` used to overwrite the
    /// caller's `i`, and the caller's own loop then read the callee's final
    /// value on every iteration. Found by a real script -- the port of the
    /// crest-factor paper's SQNR figure, whose helper looped over the same
    /// index name as its caller and silently indexed the wrong element.
    #[test]
    fn a_functions_loop_variable_does_not_clobber_the_callers() {
        let it = run(
            "function inner()
             for i in 0 to 9
             z = i
             end for
             return 42
             end function
             seen = []
             for i in 0 to 2
             v = inner()
             seen = [seen, i]
             end for",
        );
        assert_eq!(
            it.get("seen").and_then(|v| to_vec(v).ok()),
            Some(vec![0.0, 1.0, 2.0]),
            "the caller's loop variable was overwritten by the callee's"
        );
    }

    /// The same name at top level still behaves as before: no frame, so
    /// nothing to protect, and the loop variable stays readable afterwards
    /// the way Python's does and existing scripts rely on.
    #[test]
    fn a_top_level_loop_variable_is_still_visible_after_the_loop() {
        let it = run("for i in 0 to 4
q = i * 2
end for");
        assert_eq!(it.get("i").and_then(|v| v.as_num().ok()), Some(4.0));
        assert_eq!(it.get("q").and_then(|v| v.as_num().ok()), Some(8.0));
    }

