    // ---- `signal(data)` optional Fs (defaults to 1.0 Hz) ----

    #[test]
    fn signal_without_fs_defaults_to_one_hz() {
        let it = run("a = signal([1,2,3,4])\nb = signal([1,2,3,4], 1.0)\nfa = a.Fs\nfb = b.Fs");
        assert!(matches!(it.get("fa"), Some(Value::Num(n)) if (*n - 1.0).abs() < 1e-12));
        assert_eq!(vec_of(&it, "a"), vec_of(&it, "b"));
        assert!(matches!((it.get("fa"), it.get("fb")), (Some(Value::Num(x)), Some(Value::Num(y))) if (x - y).abs() < 1e-12));
    }

