    // ---- `cast(value, tag)` ----

    #[test]
    fn cast_list_of_strings_to_num() {
        let it = run("xs = (\"1\", \"2.5\", \"-3\")\nys = cast(xs, \"num\")");
        assert_eq!(vec_of(&it, "ys"), vec![1.0, 2.5, -3.0]);
    }

    #[test]
    fn cast_list_of_strings_to_num_errors_clearly_on_bad_element() {
        let mut it = Interp::new();
        let err = it.run("xs = (\"1\", \"nope\", \"3\")\nys = cast(xs, \"num\")").unwrap_err();
        assert!(err.msg.contains("nope"), "got: {}", err.msg);
    }

    #[test]
    fn cast_vec_to_str_gives_a_list_of_formatted_number_strings() {
        let it = run("xs = [1, 2.5, -3]\nys = cast(xs, \"str\")");
        match it.get("ys") {
            Some(Value::List(items)) => {
                let strs: Vec<String> = items.iter().map(|v| match v {
                    Value::Str(s) => s.clone(),
                    other => panic!("expected a string element, got {other:?}"),
                }).collect();
                assert_eq!(strs, vec!["1", "2.5", "-3"]);
            }
            other => panic!("ys is not a list: {other:?}"),
        }
    }

    #[test]
    fn cast_num_and_str_roundtrip_the_single_value_forms() {
        let it = run("a = cast(42, \"str\")\nb = cast(\"42\", \"num\")");
        assert!(matches!(it.get("a"), Some(Value::Str(s)) if s == "42"));
        assert!(matches!(it.get("b"), Some(Value::Num(n)) if (*n - 42.0).abs() < 1e-12));
    }

    #[test]
    fn cast_to_bool_reuses_the_language_s_existing_truthiness_rule() {
        // same truthiness `if`/`and`/`or` already use: nonzero/non-empty is
        // true, zero/empty is false.
        let it = run(
            "t1 = cast(5, \"bool\")\nf1 = cast(0, \"bool\")\n\
             t2 = cast([1,2], \"bool\")\nf2 = cast([], \"bool\")\n\
             t3 = cast(\"hi\", \"bool\")\nf3 = cast(\"\", \"bool\")",
        );
        assert!(matches!(it.get("t1"), Some(Value::Bool(true))));
        assert!(matches!(it.get("f1"), Some(Value::Bool(false))));
        assert!(matches!(it.get("t2"), Some(Value::Bool(true))));
        assert!(matches!(it.get("f2"), Some(Value::Bool(false))));
        assert!(matches!(it.get("t3"), Some(Value::Bool(true))));
        assert!(matches!(it.get("f3"), Some(Value::Bool(false))));
    }

    #[test]
    fn cast_vec_signal_and_mask_conversions() {
        let it = run(
            "s = cast([1,2,3], \"signal\")\nfs = s.Fs\n\
             v = cast(signal([4,5,6], 200), \"vec\")\n\
             m = cast([0, 2, 0, -1], \"mask\")\n\
             back = cast(m, \"vec\")",
        );
        assert!(matches!(it.get("fs"), Some(Value::Num(n)) if (*n - 1.0).abs() < 1e-12));
        assert_eq!(vec_of(&it, "v"), vec![4.0, 5.0, 6.0]);
        assert!(matches!(it.get("m"), Some(Value::Mask(m)) if *m == vec![false, true, false, true]));
        assert_eq!(vec_of(&it, "back"), vec![0.0, 1.0, 0.0, 1.0]);
    }

    #[test]
    fn cast_rejects_an_unsupported_pairing_with_a_clear_error() {
        let mut it = Interp::new();
        let err = it.run("x = cast(signal([1,2,3], 10), \"worker\")").unwrap_err();
        assert!(err.msg.contains("unsupported conversion"), "got: {}", err.msg);
        assert!(err.msg.contains("signal") && err.msg.contains("worker"), "got: {}", err.msg);
    }

    #[test]
    fn cast_rejects_an_unknown_target_type_name() {
        let mut it = Interp::new();
        let err = it.run("x = cast(5, \"frobnicate\")").unwrap_err();
        assert!(err.msg.contains("unknown target type"), "got: {}", err.msg);
    }

    #[test]
    fn cast_method_chain_sugar_works_with_zero_extra_wiring() {
        // `x.cast(tag)` should Just Work via the same generic
        // `recv.method(args) == method(recv, args)` sugar every other free
        // function already gets, with no cast-specific dispatch added.
        let it = run("a = (42).cast(\"str\")\nb = \"42\".cast(\"num\")");
        assert!(matches!(it.get("a"), Some(Value::Str(s)) if s == "42"));
        assert!(matches!(it.get("b"), Some(Value::Num(n)) if (*n - 42.0).abs() < 1e-12));
    }

    // ---- `resample_to(signal, new_fs)` ----

    #[test]
    fn resample_to_upsamples_a_linear_ramp_with_hand_verified_values() {
        // A 4-sample, 1 Hz ramp [0,10,20,30] spans t = 0..3s (slope 10/s).
        // Resampled to 2 Hz it must become the 7-sample [0,5,10,15,20,25,30]
        // spanning the SAME t = 0..3s (not a 4-sample signal relabeled to
        // claim 2 Hz, which would silently shrink the duration to 1.5s).
        let it = run(
            "x = signal([0, 10, 20, 30], 1)\n\
             y = resample_to(x, 2)\n\
             fy = y.Fs",
        );
        assert!(matches!(it.get("fy"), Some(Value::Num(n)) if (*n - 2.0).abs() < 1e-12));
        let y = vec_of(&it, "y");
        let expected = vec![0.0, 5.0, 10.0, 15.0, 20.0, 25.0, 30.0];
        assert_eq!(y.len(), expected.len());
        for (got, want) in y.iter().zip(expected.iter()) {
            assert!((got - want).abs() < 1e-9, "got {y:?}, want {expected:?}");
        }
        // duration preserved: (n-1)/Fs must match before and after.
        let orig_duration = 3.0 / 1.0;
        let new_duration = (y.len() - 1) as f64 / 2.0;
        assert!((orig_duration - new_duration).abs() < 1e-9);
    }

    #[test]
    fn resample_to_downsamples_and_still_preserves_duration() {
        // 9 samples at 4 Hz span t = 0..2s; halving to 2 Hz still spans the
        // same t = 0..2s with 5 samples. The LENGTH/duration contract is
        // what this test is for and it is unchanged.
        //
        // The VALUES deliberately changed on 2026-09-19: downsampling now
        // runs an anti-alias lowpass first, so this no longer returns the
        // ramp's own values sample-for-sample. It used to assert exactly
        // [0, 5, 10, 15, 20]; the filter is causal, so the ramp comes back
        // delayed by its group delay (order/2 = 4 input samples here, the
        // order being reduced from the default 60 to 8 because a 9-sample
        // input cannot carry a 61-tap filter) and smoothed at the edges.
        // See the `resample_to` arm's own doc comment.
        let it = run(
            "x = signal([0, 2.5, 5, 7.5, 10, 12.5, 15, 17.5, 20], 4)\n\
             y = resample_to(x, 2)",
        );
        let y = vec_of(&it, "y");
        assert_eq!(y.len(), 5);
        // The delay is exact and checkable, which is the useful assertion
        // here: a linear-phase FIR passes a straight line through as a pure
        // delay once it has filled, so the last output sample (t = 2s) is
        // the ramp's value one group delay earlier -- 4 input samples at
        // 4 Hz = 1s back, i.e. the ramp at t = 1s, which is 10.0. Measured,
        // not assumed: the whole output is
        // [0, -0.0567, 0.5150, 4.9433, 10.0].
        assert!((y[0] - 0.0).abs() < 1e-9, "got {y:?}");
        assert!(
            (y[4] - 10.0).abs() < 1e-9,
            "group delay is not the documented order/2 = 4 input samples: {y:?}"
        );
        // And it is NOT the old sample-for-sample answer -- if this ever
        // starts passing, the anti-alias filter has been lost again.
        assert!(
            (y[4] - 20.0).abs() > 1e-6,
            "resample_to looks unfiltered again: {y:?}"
        );
    }

    /// The bug this whole change exists for: decimating without a lowpass
    /// folds everything above the new Nyquist back into the band, and the
    /// result looks like a perfectly good signal.
    ///
    /// The probe is built so it CAN differ both ways: the same grid change
    /// done by hand with `interp1` (which is literally what `resample_to`
    /// used to be) is asserted to produce the full-amplitude alias, so a
    /// passing test means the filter did something, not that the tone was
    /// too weak to alias in the first place.
    #[test]
    fn resample_to_lowpasses_before_decimating_instead_of_aliasing() {
        // A pure 35 Hz tone at 100 Hz. Decimated to 20 Hz (new Nyquist
        // 10 Hz) it would fold to |35 - 2*20| = 5 Hz.
        let it = run(
            "t = linspace(0, 4.99, 500)\n\
             x = signal(sin(2*pi*35*t), 100)\n\
             y = resample_to(x, 20)\n\
             tq = linspace(0, 5, 101)\n\
             unfiltered = interp1(t, sin(2*pi*35*t), tq, \"linear\")",
        );
        let rms = |v: &[f64]| (v.iter().map(|a| a * a).sum::<f64>() / v.len() as f64).sqrt();

        // Control: the old behavior. A tone that was never in the input,
        // at very nearly full amplitude.
        let alias = vec_of(&it, "unfiltered");
        assert!(
            rms(&alias[12..]) > 0.3,
            "control failed -- the unfiltered path did not alias, so this test proves nothing (rms {})",
            rms(&alias[12..])
        );

        // The fix: 35 Hz is deep in the stopband, so almost nothing
        // survives. Skip the first 12 output samples (the 30-input-sample
        // group delay is 6 output samples; 12 clears the transient).
        // Measured: 0.754 rms of alias before, 0.00026 after -- ~69 dB.
        let y = vec_of(&it, "y");
        // 499/100 s of signal at 20 Hz spans 101 output samples.
        assert_eq!(y.len(), 101);
        assert!(
            rms(&y[12..]) < 0.05,
            "35 Hz tone aliased through decimation at rms {}",
            rms(&y[12..])
        );
    }

    #[test]
    fn resample_to_upsampling_is_bit_for_bit_unchanged_by_the_anti_alias_fix() {
        // Upsampling cannot alias, so it gets no filter, no group delay and
        // exactly the values it always returned. This is the other half of
        // the behavior-change contract: only the DOWN direction moved.
        let it = run("x = signal([0, 10, 20, 30], 1)\ny = resample_to(x, 4)");
        let y = vec_of(&it, "y");
        assert_eq!(y.len(), 13);
        for (i, got) in y.iter().enumerate() {
            let want = i as f64 * 30.0 / 12.0;
            assert!((got - want).abs() < 1e-9, "got {y:?}");
        }
    }

    // ---- `upsample` / `downsample` / `resample_int` ----

    #[test]
    fn upsample_zero_stuffs_interpolates_and_keeps_amplitude() {
        // A 2 Hz tone sampled at 50 Hz, upsampled by 4 to 200 Hz. The
        // interpolation filter's gain of L is what keeps the amplitude at
        // 1.0 rather than 1/4 of it.
        let it = run(
            "t = linspace(0, 3.98, 200)\n\
             x = signal(sin(2*pi*2*t), 50)\n\
             y = upsample(x, 4)\n\
             fy = y.Fs\n\
             n = len(y)",
        );
        assert!(matches!(it.get("fy"), Some(Value::Num(n)) if (*n - 200.0).abs() < 1e-9));
        assert!(matches!(it.get("n"), Some(Value::Num(n)) if (*n - 800.0).abs() < 1e-9));
        let y = vec_of(&it, "y");
        // Past the 30-sample group delay and the run-out, the peak is the
        // input's own peak -- not L times it, and not 1/L of it.
        let peak = y[60..700].iter().fold(0.0f64, |m, v| m.max(v.abs()));
        assert!((peak - 1.0).abs() < 0.05, "amplitude drifted: peak {peak}");
    }

    #[test]
    fn upsample_by_one_is_the_identity_with_no_delay() {
        let it = run("y = upsample([1, 2, 3, 4], 1)");
        assert_eq!(vec_of(&it, "y"), vec![1.0, 2.0, 3.0, 4.0]);
    }

    #[test]
    fn downsample_rejects_the_band_that_would_alias() {
        // Same folding scenario as the `resample_to` test, through the
        // integer-factor primitive: a 35 Hz tone at 100 Hz, decimated by 5.
        let it = run(
            "t = linspace(0, 4.99, 500)\n\
             x = signal(sin(2*pi*35*t), 100)\n\
             y = downsample(x, 5)\n\
             fy = y.Fs",
        );
        assert!(matches!(it.get("fy"), Some(Value::Num(n)) if (*n - 20.0).abs() < 1e-9));
        let y = vec_of(&it, "y");
        assert_eq!(y.len(), 100); // ceil(500/5)
        let tail = &y[12..];
        let rms = (tail.iter().map(|v| v * v).sum::<f64>() / tail.len() as f64).sqrt();
        assert!(rms < 0.05, "aliased through at rms {rms}");
    }

    #[test]
    fn downsample_keeps_a_passband_tone_it_should_not_touch() {
        // The other side of the same filter: 2 Hz at 100 Hz decimated by 5
        // (new Nyquist 10 Hz) is well inside the passband and must come
        // through at full amplitude, delayed by order/2 = 30 input samples
        // = 6 output samples. Without this, "attenuates everything" would
        // pass the aliasing test above.
        let it = run(
            "t = linspace(0, 4.99, 500)\n\
             x = signal(sin(2*pi*2*t), 100)\n\
             y = downsample(x, 5)",
        );
        let y = vec_of(&it, "y");
        // Measured peak 0.955 -- the shortfall is the sampling grid, not
        // the filter: at 20 Hz a 2 Hz sine is only 10 samples per cycle, so
        // the output rarely lands exactly on a crest.
        let peak = y[10..90].iter().fold(0.0f64, |m, v| m.max(v.abs()));
        assert!((peak - 1.0).abs() < 0.08, "passband tone lost amplitude: peak {peak}");
    }

    #[test]
    fn upsample_then_downsample_round_trips_once_delay_aligned() {
        // Up by 3 then down by 3 on 200 samples. Two order-60 filters, each
        // contributing 30 samples of group delay at the 3x rate, so the
        // result is x delayed by 60/3 = 20 samples. Aligned by that known
        // delay, the round trip is accurate to a few parts in a thousand --
        // the delay is real and documented, not something the comparison
        // gets to pretend away.
        let it = run(
            "t = linspace(0, 1.99, 200)\n\
             x = sin(2*pi*2*t) + 0.5*sin(2*pi*5*t)\n\
             y = downsample(upsample(x, 3), 3)",
        );
        let x = vec_of(&it, "x");
        let y = vec_of(&it, "y");
        assert_eq!(y.len(), 200);
        const DELAY: usize = 20;
        // Compare only where both the input and the delayed output are
        // past their transients.
        let n = 200 - 2 * DELAY;
        let err: f64 = (0..n).map(|k| (y[k + DELAY] - x[k]).powi(2)).sum::<f64>() / n as f64;
        let rmse = err.sqrt();
        assert!(rmse < 0.01, "round-trip rmse {rmse} (measured 0.0023 when written)");
    }

    #[test]
    fn resample_int_matches_the_two_step_shape_with_half_the_delay() {
        // L=3, M=2 on a 100-sample, 50 Hz signal -> 150 samples at 75 Hz.
        let it = run(
            "t = linspace(0, 1.98, 100)\n\
             x = signal(sin(2*pi*3*t), 50)\n\
             y = resample_int(x, 3, 2)\n\
             fy = y.Fs\n\
             n = len(y)",
        );
        assert!(matches!(it.get("fy"), Some(Value::Num(n)) if (*n - 75.0).abs() < 1e-9));
        assert!(matches!(it.get("n"), Some(Value::Num(n)) if (*n - 150.0).abs() < 1e-9));
        let y = vec_of(&it, "y");
        // One filter, so the delay is 30 samples at the 150 Hz intermediate
        // rate = 15 output samples. Amplitude preserved past it.
        let peak = y[30..130].iter().fold(0.0f64, |m, v| m.max(v.abs()));
        assert!((peak - 1.0).abs() < 0.06, "amplitude drifted: peak {peak}");
    }

    #[test]
    fn resample_int_on_a_plain_vector_returns_a_plain_vector() {
        let it = run("y = resample_int([1, 2, 3, 4, 5, 6, 7, 8], 2, 2)");
        assert!(matches!(it.get("y"), Some(Value::Vec(_))), "got {:?}", it.get("y"));
    }

    #[test]
    fn multirate_builtins_reject_a_bad_order_or_factor() {
        let mut it = Interp::new();
        let odd = it.run("y = upsample([1,2,3,4,5,6], 2, order=61)").unwrap_err();
        assert!(odd.msg.contains("even"), "got: {}", odd.msg);

        let mut it = Interp::new();
        let zero = it.run("y = downsample([1,2,3,4,5,6], 0)").unwrap_err();
        assert!(zero.msg.contains("at least 1"), "got: {}", zero.msg);

        let mut it = Interp::new();
        let frac = it.run("y = resample_int([1,2,3,4,5,6], 2, 1.5)").unwrap_err();
        assert!(frac.msg.contains("whole number"), "got: {}", frac.msg);
    }

    #[test]
    fn resample_to_method_chain_sugar_works() {
        let it = run("x = signal([0, 10, 20, 30], 1)\ny = x.resample_to(2)\nfy = y.Fs");
        assert!(matches!(it.get("fy"), Some(Value::Num(n)) if (*n - 2.0).abs() < 1e-12));
        assert_eq!(vec_of(&it, "y"), vec![0.0, 5.0, 10.0, 15.0, 20.0, 25.0, 30.0]);
    }

    #[test]
    fn resample_to_rejects_a_non_signal_first_argument() {
        let mut it = Interp::new();
        let err = it.run("y = resample_to([1,2,3], 2)").unwrap_err();
        assert!(err.msg.contains("signal"), "got: {}", err.msg);
    }

    #[test]
    fn loglog_semilogx_semilogy_set_the_right_axes() {
        let it = run(
            "loglog(1 to 5, 1 to 5)\nnext plot\nsemilogx(1 to 5, 1 to 5)\nnext plot\nsemilogy(1 to 5, 1 to 5)",
        );
        let p = &it.figure.panels;
        assert_eq!(p[0].xscale, Scale::Log);
        assert_eq!(p[0].yscale, Scale::Log);
        assert_eq!(p[1].xscale, Scale::Log);
        assert_eq!(p[1].yscale, Scale::Linear);
        assert_eq!(p[2].xscale, Scale::Linear);
        assert_eq!(p[2].yscale, Scale::Log);
    }

    #[test]
    fn yyaxis_records_a_switch_point_at_the_current_series_count() {
        let it = run("plot(0 to 3, 0 to 3)\nyyaxis right\nplot(0 to 3, 0 to 3)\nyyaxis left\nplot(0 to 3, 0 to 3)");
        let panel = &it.figure.panels[0];
        assert_eq!(panel.series.len(), 3);
        assert!(!panel.is_right_axis(0), "series 0 (before any switch) should be left");
        assert!(panel.is_right_axis(1), "series 1 (after `yyaxis right`) should be right");
        assert!(!panel.is_right_axis(2), "series 2 (after `yyaxis left`) should be left");
    }

    #[test]
    fn yyaxis_right_series_get_an_independent_y_scale() {
        // left series spans 0..1, right series spans 0..1000 — if they
        // shared one scale, the left series would render as a flat line
        // pinned to the bottom; independent scales put both series'
        // extremes near the top of their own axis.
        let it = run(
            "plot([0, 1, 2], [0, 0.5, 1])\nyyaxis right\nplot([0, 1, 2], [0, 500, 1000])",
        );
        let ops = plotting::build_draw_ops(&it.figure, 400.0, 300.0);
        let polylines: Vec<&Vec<(f64, f64)>> = ops.iter().filter_map(|op| match op {
            plotting::DrawOp::Polyline { points, .. } => Some(points),
            _ => None,
        }).collect();
        assert_eq!(polylines.len(), 2);
        // both series' final point should land near the top of the plot
        // area (small y-pixel value) despite wildly different data ranges.
        let left_final_y = polylines[0].last().unwrap().1;
        let right_final_y = polylines[1].last().unwrap().1;
        assert!((left_final_y - right_final_y).abs() < 5.0, "left={left_final_y}, right={right_final_y}");
    }

    #[test]
    fn xxaxis_records_a_switch_point_and_gets_an_independent_x_scale() {
        let it = run("plot([0, 1, 2], [0, 1, 2])\nxxaxis top\nplot([0, 100, 200], [0, 1, 2])");
        let panel = &it.figure.panels[0];
        assert!(!panel.is_top_axis(0));
        assert!(panel.is_top_axis(1));
        let ops = plotting::build_draw_ops(&it.figure, 400.0, 300.0);
        let polylines: Vec<&Vec<(f64, f64)>> = ops.iter().filter_map(|op| match op {
            plotting::DrawOp::Polyline { points, .. } => Some(points),
            _ => None,
        }).collect();
        assert_eq!(polylines.len(), 2);
        // both series' final point should land near the right edge of the
        // plot area despite wildly different x ranges (0..2 vs 0..200).
        let left_final_x = polylines[0].last().unwrap().0;
        let top_final_x = polylines[1].last().unwrap().0;
        assert!((left_final_x - top_final_x).abs() < 5.0, "bottom={left_final_x}, top={top_final_x}");
    }

    #[test]
    fn axis_origin_draws_spines_crossing_at_data_zero_not_a_box() {
        // x spans -5..5 (0 is exactly centered), y spans -4..21 (0 is not
        // centered) -- the vertical spine should land at the horizontal
        // midpoint of the panel, and there must be no framing box rect.
        let it = run("plot([-5, 0, 5], [21, -4, 21])\naxis origin");
        let ops = plotting::build_draw_ops(&it.figure, 400.0, 300.0);
        assert!(
            !ops.iter().any(|op| matches!(op, plotting::DrawOp::Rect { stroke: Some(_), .. })),
            "axis origin must not draw a framing box"
        );
        let spine_lines: Vec<(f64, f64, f64, f64)> = ops
            .iter()
            .filter_map(|op| match op {
                // Spine width is derived from the type scale now rather
                // than a hardcoded 1.2, so match the colour instead. Axis
                // tick marks share that colour, so length separates them:
                // a spine runs the length of the panel, a tick is a few
                // pixels. 20 sits far from both.
                plotting::DrawOp::Line { x1, y1, x2, y2, color, .. }
                    if color == plotting::resolve_theme("default").spine_color
                        && (x2 - x1).hypot(y2 - y1) > 20.0 =>
                {
                    Some((*x1, *y1, *x2, *y2))
                }
                _ => None,
            })
            .collect();
        assert_eq!(spine_lines.len(), 2, "expected exactly one horizontal and one vertical spine, got {spine_lines:?}");
        let vertical = spine_lines.iter().find(|&&(x1, _, x2, _)| (x1 - x2).abs() < 1e-9).expect("expected a vertical spine");
        // 0 is the midpoint of [-5, 5], so the vertical spine's x must be
        // the panel's horizontal midpoint.
        let (left, right) = layout_bounds(&it, 400.0, 300.0);
        assert!((vertical.0 - (left + right) / 2.0).abs() < 1.0, "vx={}, left={left}, right={right}", vertical.0);
    }

    #[test]
    fn axis_edge_is_the_default_and_draws_a_box() {
        let it = run("plot([-5, 0, 5], [21, -4, 21])");
        let ops = plotting::build_draw_ops(&it.figure, 400.0, 300.0);
        // A framing box is four LINES now -- `DrawOp::Rect` carries no
        // stroke width, so a rect frame could not follow the theme.
        let frame_lines = ops
            .iter()
            .filter(|op| matches!(op, plotting::DrawOp::Line { color, .. } if color == plotting::resolve_theme("default").spine_color))
            .count();
        assert!(frame_lines >= 4, "default `axis edge` must draw a framing box, got {frame_lines} spine lines");
    }

    /// Test-only helper: the panel's left/right pixel bounds, derived the
    /// same way `build_draw_ops` does (margins are private to `plotting`,
    /// so this recomputes them from a gridline's known full-width span
    /// instead of duplicating the margin constants).
    fn layout_bounds(it: &Interp, width: f64, height: f64) -> (f64, f64) {
        let ops = plotting::build_draw_ops(&it.figure, width, height);
        ops.iter()
            .filter_map(|op| match op {
                plotting::DrawOp::Line { x1, y1, x2, y2, .. } if y1 == y2 => Some((*x1, *x2)),
                _ => None,
            })
            .max_by(|a, b| (a.1 - a.0).abs().total_cmp(&(b.1 - b.0).abs()))
            .expect("expected at least one horizontal line spanning the panel")
    }

