    #[test]
    fn gridlines_are_drawn_in_both_directions_by_default() {
        let it = run("plot([0,1,2],[0,1,2])");
        let ops = plotting::build_draw_ops(&it.figure, 400.0, 300.0);
        let (mut horiz, mut vert) = (0, 0);
        for op in &ops {
            if let plotting::DrawOp::Line { x1, y1, x2, y2, .. } = op {
                if (y1 - y2).abs() < 1e-9 && (x1 - x2).abs() > 1e-9 { horiz += 1; }
                if (x1 - x2).abs() < 1e-9 && (y1 - y2).abs() > 1e-9 { vert += 1; }
            }
        }
        assert!(horiz > 0, "expected horizontal gridlines");
        assert!(vert > 0, "expected vertical gridlines");
    }

