        let img = image::Image::new(2, 1, vec![255, 0, 0, 0, 255, 0]).unwrap();
        it.env.insert("img".to_string(), Value::Image(Arc::new(img)));
        it.run("g = grayscale(img)").unwrap();
        let Some(Value::Image(g)) = it.get("g") else { panic!("expected an image") };
