    #[test]
    fn blur_sharpen_edge_detect_and_imfilter_builtins_run_and_change_pixels() {
        let mut it = Interp::new();
        let mut img = image::Image::filled(5, 5, (0, 0, 0));
        img.set_pixel(2, 2, (255, 255, 255));
        it.env.insert("img".to_string(), Value::Image(Arc::new(img)));

        it.run("b = blur(img)").unwrap();
        let Some(Value::Image(b)) = it.get("b") else { panic!("expected an image") };
        let b = b.clone();
        let expected = (255.0 / 9.0_f64).round() as u8;
        assert_eq!(b.get_pixel(2, 2), (expected, expected, expected));
        assert_eq!(b.get_pixel(0, 0), (0, 0, 0));

        it.run("s = sharpen(img)").unwrap();
        assert!(matches!(it.get("s"), Some(Value::Image(_))));

        it.run("e = edge_detect(img)").unwrap();
        assert!(matches!(it.get("e"), Some(Value::Image(_))));

        // imfilter with an explicit 3x3 box-blur kernel must match `blur`
        // exactly — it's the same underlying convolution, just user-supplied.
        it.run("k = [1/9,1/9,1/9; 1/9,1/9,1/9; 1/9,1/9,1/9]\nf = imfilter(img, k)").unwrap();
        let Some(Value::Image(f)) = it.get("f") else { panic!("expected an image") };
        assert_eq!(**f, *b);
    }

    // ---- § thresholding (2026-08-24): threshold/multithreshold/
    // otsu_threshold/multi_otsu/kapur_threshold across Vec/Signal/Image ----

    #[test]
    fn threshold_on_a_vector_matches_the_ge_comparison_operator() {
        let it = run("x = [1, 5, 3, 8, 2]\nm = threshold(x, 4)\nc = x >= 4");
        assert!(matches!(it.get("m"), Some(Value::Mask(_))));
        let Some(Value::Mask(m)) = it.get("m") else { unreachable!() };
        let Some(Value::Mask(c)) = it.get("c") else { unreachable!() };
        assert_eq!(m, c);
        assert_eq!(*m, vec![false, true, false, true, false]);
    }

