    #[test]
    fn otsu_threshold_on_color_image_matches_otsu_threshold_on_its_grayscale_conversion() {
        // Regression test for image_luma_samples' fast path: an image that's
        // already grayscale (R=G=B per pixel, as `grayscale(img)` produces)
        // must read its luma straight from a channel instead of re-running
        // `to_grayscale`'s BT.601 math a second time. Since the BT.601
        // weights sum to exactly 1.0, that shortcut is only valid if it
        // produces bit-identical results to the general per-channel BT.601
        // path used for non-gray pixels -- this proves it does: computing
        // otsu_threshold directly on a genuinely multi-channel color image
        // (exercises the general path) must equal computing it on that same
        // image after an explicit `grayscale()` call (exercises the R=G=B
        // shortcut path), for every pixel across a spread of channel values.
        let mut it = Interp::new();
        let mut pixels = Vec::new();
        for i in 0..64u32 {
            // Deliberately non-gray per-channel values (r != g != b) so the
            // luma computation actually depends on the BT.601 weights, not
            // just a single channel.
            let r = (i * 4) as u8;
            let g = (255 - i * 3) as u8;
            let b = ((i * 7) % 256) as u8;
            pixels.push(r);
            pixels.push(g);
            pixels.push(b);
        }
        let img = image::Image::new(8, 8, pixels).unwrap();
        it.env.insert("img".to_string(), Value::Image(Arc::new(img)));
        it.run("t_color = otsu_threshold(img)\ngray = grayscale(img)\nt_gray = otsu_threshold(gray)").unwrap();
        let t_color = num(&it, "t_color");
        let t_gray = num(&it, "t_gray");
        assert_eq!(
            t_color, t_gray,
            "otsu_threshold on a color image ({t_color}) must exactly match otsu_threshold on its grayscale() conversion ({t_gray})"
        );
    }

