    #[test]
    fn progress_draws_a_bar_that_reaches_100_percent_on_the_last_call() {
        // The first and last frame always draw regardless of the 100ms
        // throttle (see progress()'s own comment) -- a short, fast loop
        // like this one would otherwise draw nothing at all and the test
        // would pass for the wrong reason (an empty `it.out`).
        let it = run("for i = 0 to 4\n  progress(i, 5)\nend for");
        assert!(it.out.contains("0%"), "first frame should draw 0%%: {}", it.out);
        assert!(it.out.contains("100%"), "last frame should draw 100%%: {}", it.out);
        assert!(it.out.contains("(5/5)"), "last frame should show the final count: {}", it.out);
        // Exactly one trailing newline (after the LAST frame only) -- every
        // other frame overwrites via `\r`, so the bar does not scroll the
        // terminal once per iteration.
        assert_eq!(it.out.matches('\n').count(), 1, "got: {:?}", it.out);
    }

    #[test]
    fn progress_rejects_the_one_to_n_off_by_one() {
        // `for i = 1 to n` is the OTHER common Qu range idiom, and passing
        // its `i` straight through is the mistake this error exists to
        // catch: i == n is one past the last valid 0-based index.
        let mut it = Interp::new();
        let err = it.run("progress(5, 5)").unwrap_err();
        assert!(err.msg.contains("0-based"), "got: {}", err.msg);
        assert!(err.msg.contains("1 to n"), "should name the actual mistake: {}", err.msg);
    }

    #[test]
    fn progress_rejects_a_nonpositive_total() {
        let mut it = Interp::new();
        let err = it.run("progress(0, 0)").unwrap_err();
        assert!(err.msg.contains("positive"), "got: {}", err.msg);
    }

    #[test]
    fn progress_resets_its_clock_on_a_second_loop_in_the_same_script() {
        // Two loops back to back: the second loop's i==0 call must not
        // inherit the first loop's elapsed time, or its ETA/rate would be
        // computed against the wrong start.
        let it = run(
            "for i = 0 to 2\n  progress(i, 3)\nend for\n\
             for i = 0 to 2\n  progress(i, 3)\nend for",
        );
        // Two runs to completion means two "100%" frames, not one.
        assert_eq!(it.out.matches("100%").count(), 2, "got: {}", it.out);
    }

    #[test]
    fn every_and_after_interleave_by_scheduled_virtual_time() {
        // every 100ms fires at 100,200,300,400,500ms (count -> 1..5, total
        // 15); after 250ms fires once, between the 200 and 300ms firings, so
        // it sees count=2 — the real assertion: firings interleave by
        // scheduled time, not "run `every` to completion, then `after`."
        // Uses `ms` unit literals throughout (exercising that `every 500 ms`
        // and a bare-seconds `run_for` compose via the same unit system
        // `apply_unit` already gives every other builtin).
        let it = run(
            "count = 0\ntotal = 0\n\
             every 100 ms do\n  count = count + 1\n  total = total + count\nend\n\
             after 250 ms do\n  snapshot = count\nend\n\
             fired = run_for(500 ms)",
        );
        assert!(matches!(it.get("fired"), Some(Value::Num(n)) if (*n - 6.0).abs() < 1e-9));
        assert!(matches!(it.get("count"), Some(Value::Num(n)) if (*n - 5.0).abs() < 1e-9));
        assert!(matches!(it.get("total"), Some(Value::Num(n)) if (*n - 15.0).abs() < 1e-9));
        assert!(matches!(it.get("snapshot"), Some(Value::Num(n)) if (*n - 2.0).abs() < 1e-9));
    }

    #[test]
    fn at_behaves_as_a_one_shot_alias_of_after() {
        let it = run("hits = 0\nat 50 ms do\n    hits = hits + 1\nend\nrun_for(200 ms)");
        assert!(matches!(it.get("hits"), Some(Value::Num(n)) if (*n - 1.0).abs() < 1e-9));
    }

