    #[test]
    fn workers_get_independent_rng_streams_not_a_duplicated_one() {
        // the exact bug class this design is meant to rule out: a naive
        // shared/cloned RNG would give every worker (and the main script)
        // the identical "random" sequence.
        let it = run(
            "draw(n) := rand(n)\n\
             seed(42)\n\
             main = rand(3)\n\
             w1 = spawn(\"draw\", 3)\n\
             w2 = spawn(\"draw\", 3)\n\
             r1 = join(w1)\n\
             r2 = join(w2)",
        );
        let as_vec = |v: Option<&Value>| match v {
            Some(Value::Vec(xs)) => xs.clone(),
            other => panic!("expected a vector, got {other:?}"),
        };
        let (main, r1, r2) = (as_vec(it.get("main")), as_vec(it.get("r1")), as_vec(it.get("r2")));
        assert_ne!(main, r1, "worker 1 duplicated the main thread's RNG stream");
        assert_ne!(main, r2, "worker 2 duplicated the main thread's RNG stream");
        assert_ne!(r1, r2, "the two workers duplicated each other's RNG stream");
    }

    #[test]
    fn spawn_does_not_leak_worker_side_effects_back_into_the_caller() {
        // the isolation guarantee: a worker's env is a snapshot, not a
        // reference — mutating what looks like the same variable name
        // inside the spawned function must not touch the caller's copy.
        let it = run(
            "counter = 0\n\
             function bump()\n  counter = counter + 100\nend function\n\
             w = spawn(\"bump\")\n\
             _r = join(w)",
        );
        assert!(matches!(it.get("counter"), Some(Value::Num(n)) if (*n - 0.0).abs() < 1e-9));
    }

