    /// The real end-to-end check the task asked for: a genuine client and
    /// server, the server running in a `spawn`'d worker thread (exactly
    /// the pattern `tcp_listen`'s own doc comment recommends for running a
    /// server without blocking the caller), talking over a real loopback
    /// TCP connection — not a mock, not two calls into the same in-process
    /// buffer. `tcp_listen(0)` asks the OS for an ephemeral free port
    /// (avoids any fixed-port collision between parallel `cargo test`
    /// threads); `tcp_port(l)` reads back whichever port it actually
    /// picked so the client can connect to it.
    #[test]
    fn tcp_client_server_round_trip_via_spawn() {
        let it = run(
            "function server(listener)\n\
             \x20   c = tcp_accept(listener)\n\
             \x20   msg = tcp_recv(c)\n\
             \x20   tcp_send(c, msg + \"-pong\")\n\
             \x20   tcp_close(c)\n\
             \x20   return msg\n\
             end function\n\
             listener = tcp_listen(0)\n\
             port = tcp_port(listener)\n\
             w = spawn(\"server\", listener)\n\
             conn = tcp_connect(\"127.0.0.1\", port)\n\
             tcp_send(conn, \"ping\")\n\
             reply = tcp_recv(conn)\n\
             server_saw = join(w)\n\
             tcp_close(conn)",
        );
        assert!(matches!(it.get("reply"), Some(Value::Str(s)) if s == "ping-pong"));
        assert!(matches!(it.get("server_saw"), Some(Value::Str(s)) if s == "ping"));
    }

    #[test]
    fn tcp_recv_returns_nothing_at_eof() {
        // when the peer closes its write side, a blocking recv on the
        // other end must see a clean 0-byte read (EOF), not hang or error
        // — `Value::Nothing`, the same "absent" marker `read_line` uses.
        let it = run(
            "function server(listener)\n\
             \x20   c = tcp_accept(listener)\n\
             \x20   tcp_close(c)\n\
             end function\n\
             listener = tcp_listen(0)\n\
             port = tcp_port(listener)\n\
             w = spawn(\"server\", listener)\n\
             conn = tcp_connect(\"127.0.0.1\", port)\n\
             _done = join(w)\n\
             r = tcp_recv(conn)",
        );
        assert!(matches!(it.get("r"), Some(Value::Nothing)));
    }

    #[test]
    fn mutex_add_across_parallel_for_loses_no_updates() {
        // the whole point of `mutex_add`: 100 concurrent increments on a
        // genuinely shared cell must total exactly 100, not less (a naive
        // unprotected `mutex_set(m, mutex_get(m) + 1)` would race and lose
        // updates under real concurrency).
        let it = run("counter = mutex(0)\nparallel for i in 1 to 100\n  mutex_add(counter, 1)\nend parallel\ntotal = mutex_get(counter)");
        assert!(matches!(it.get("total"), Some(Value::Num(n)) if (*n - 100.0).abs() < 1e-9));
    }

    #[test]
    fn mutex_update_applies_a_named_function_atomically() {
        let it = run(
            "bump(n) := n + 10\nm = mutex(1)\nresult = mutex_update(m, \"bump\")\nfinal = mutex_get(m)",
        );
        assert!(matches!(it.get("result"), Some(Value::Num(n)) if (*n - 11.0).abs() < 1e-9));
        assert!(matches!(it.get("final"), Some(Value::Num(n)) if (*n - 11.0).abs() < 1e-9));
    }

    #[test]
    fn a_mutex_referenced_but_untouched_inside_parallel_for_is_not_a_conflict() {
        // reading a shared handle (without reassigning the *variable* that
        // holds it) must not trip the "unsafe reassignment" merge check —
        // this is the exact bug class the `value_unchanged` generic check
        // exists to close (first caught with a `Worker` handle carried
        // unchanged through a nested `spawn` + `parallel for`).
        let it = run(
            "m = mutex(0)\nresults = zeros(5)\nparallel for i in 0 to 4\n  mutex_add(m, 1)\n  results[i] = i\nend parallel\ntotal = mutex_get(m)",
        );
        assert!(matches!(it.get("total"), Some(Value::Num(n)) if (*n - 5.0).abs() < 1e-9));
        match it.get("results") {
            Some(Value::Vec(xs)) => assert_eq!(xs.as_ref(), &vec![0.0, 1.0, 2.0, 3.0, 4.0]),
            other => panic!("expected a vector, got {other:?}"),
        }
    }

    #[test]
    fn a_pre_existing_list_the_loop_never_touches_is_not_a_conflict() {
        // `value_unchanged` had no arm for `Value::List` (nor most of the
        // other `Value` kinds added after it was first written), so it fell
        // through to `_ => false` and made every untouched `List` in scope
        // look "reassigned" to the merge check below, even though the body
        // never references it at all — a spurious error on any script with
        // a `List` variable in scope before an unrelated `parallel for`.
        let it = run(
            "somelist = [\"a\", \"b\"]\ncounter = mutex(0)\nparallel for i in 1 to 100\n  mutex_add(counter, 1)\nend parallel\ntotal = mutex_get(counter)",
        );
        assert!(matches!(it.get("total"), Some(Value::Num(n)) if (*n - 100.0).abs() < 1e-9));
        match it.get("somelist") {
            Some(Value::List(items)) => {
                assert_eq!(items.len(), 2);
            }
            other => panic!("expected the list to survive unchanged, got {other:?}"),
        }
    }

    #[test]
    fn two_independent_mutexes_do_not_share_state() {
        let it = run("a = mutex(1)\nb = mutex(1)\nmutex_add(a, 100)\nva = mutex_get(a)\nvb = mutex_get(b)");
        assert!(matches!(it.get("va"), Some(Value::Num(n)) if (*n - 101.0).abs() < 1e-9));
        assert!(matches!(it.get("vb"), Some(Value::Num(n)) if (*n - 1.0).abs() < 1e-9));
    }

