    // ---- impedance spectroscopy: rLKK ----

    // A minimal Randles-circuit generator (Rs + Rct/(1+j*omega*Rct*Cdl)),
    // written directly in Qu source rather than a Rust helper so it doubles
    // as a runnable-doc-style fixture; `j` is a complex unit built from the
    // `1i` imaginary literal since there's no bare `complex(re, im)`
    // constructor.
    const RANDLES_QU: &str = "\
        j = 0 + 1i\n\
        randles(freqs, Rs, Rct, Cdl) := Rs + Rct ./ (1 + j .* (2*pi*freqs) .* Rct .* Cdl)\n";

    #[test]
    fn rlkk_reconstruct_recovers_clean_randles_data_under_light_regularization() {
        let it = run(&format!(
            "{RANDLES_QU}\
             freqs = logspace(-1, 4, 30)\n\
             Z = randles(freqs, 0.2, 0.01, 100e-6)\n\
             fit = rlkk_reconstruct(Z, freqs, lambda=1e-6)\n\
             err = max(abs(fit.z - Z))",
        ));
        assert!(num(&it, "err") < 1e-4, "err = {}", num(&it, "err"));
    }

    #[test]
    fn rlkk_validate_passes_clean_data_and_flags_a_corrupted_point() {
        let it = run(&format!(
            "{RANDLES_QU}\
             freqs = logspace(0, 3, 40)\n\
             Z = randles(freqs, 0.2, 0.01, 100e-6)\n\
             clean = rlkk_validate(Z, freqs, lambda=1e-4, threshold=2.0)\n\
             mask = ones(40)\n\
             mask[20] = 1.5\n\
             Z2 = Z .* mask\n\
             corrupted = rlkk_validate(Z2, freqs, lambda=1e-4, threshold=2.0)\n\
             clean_valid = clean.valid\n\
             clean_residual = clean.max_residual\n\
             corrupted_valid = corrupted.valid\n\
             corrupted_residual = corrupted.max_residual",
        ));
        assert!(matches!(it.get("clean_valid"), Some(Value::Bool(true))));
        assert!(matches!(it.get("corrupted_valid"), Some(Value::Bool(false))));
        assert!(
            num(&it, "corrupted_residual") > num(&it, "clean_residual") + 10.0,
            "a 50% single-point corruption must dominate the residual budget"
        );
    }

    #[test]
    fn rlkk_extrapolate_matches_randles_impedance_beyond_the_measured_band() {
        let it = run(&format!(
            "{RANDLES_QU}\
             freqs = logspace(0, 3, 40)\n\
             Z = randles(freqs, 0.2, 0.01, 100e-6)\n\
             target = logspace(-1, 4, 60)\n\
             Z_extrap = rlkk_extrapolate(Z, freqs, target, lambda=1e-6)\n\
             Z_true = randles(target, 0.2, 0.01, 100e-6)\n\
             rel_err = mean(abs(Z_extrap - Z_true) ./ abs(Z_true))",
        ));
        assert!(num(&it, "rel_err") < 0.01, "rel_err = {}", num(&it, "rel_err"));
    }

    #[test]
    fn rlkk_reconstruct_rejects_mismatched_z_and_freqs_lengths() {
        let mut it = Interp::new();
        let err = it.run("Z = [1+0i, 2+0i]\nfreqs = [1, 2, 3]\nfit = rlkk_reconstruct(Z, freqs)").unwrap_err();
        assert!(err.msg.contains("rlkk_reconstruct"), "got: {}", err.msg);
    }

    #[test]
    fn nyquist_plots_re_z_against_negative_im_z() {
        let it = run("Z = [3+4i, 1-2i]\nnyquist(Z)");
        let panel = &it.figure.panels[0];
        assert_eq!(panel.series[0].x, vec![3.0, 1.0]);
        assert_eq!(panel.series[0].y, vec![-4.0, 2.0]);
    }

    #[test]
    fn bode_magnitude_and_phase_compute_db_and_degrees_on_a_log_x_axis() {
        let it = run(
            "Z = [1+0i, 0+1i]\n\
             freqs = [1, 10]\n\
             panel(2, 1, 1)\n\
             bode_magnitude(Z, freqs)\n\
             panel(2, 1, 2)\n\
             bode_phase(Z, freqs)",
        );
        let mag_panel = &it.figure.panels[0];
        assert!((mag_panel.series[0].y[0] - 0.0).abs() < 1e-9); // 20*log10(1) = 0
        assert!(matches!(mag_panel.xscale, Scale::Log));

        let phase_panel = &it.figure.panels[1];
        assert!((phase_panel.series[0].y[1] - 90.0).abs() < 1e-9); // arg(0+1i) = 90deg
    }

    // ---- fft on real input: the real-optimized fast path (§ 2026-09-10) ----
    //
    // `fft(x)` on real `x` used to zero-pad an imaginary part onto every
    // sample and run a full complex-to-complex transform. `mirror_half_
    // spectrum` reconstructs the exact same full-length spectrum from
    // `rfft_real`'s half, roughly halving real compute -- verified here
    // against the untouched full-complex path directly, not assumed from
    // the symmetry argument, across even, odd and single-sample lengths.

    #[test]
    fn mirror_half_spectrum_matches_the_full_complex_transform() {
        for n in [1usize, 2, 3, 4, 5, 8, 9, 100, 101] {
            let real: Vec<f64> = (0..n).map(|i| (i as f64 * 1.37).sin() + i as f64 * 0.1).collect();
            let half = numeric::rfft_real(&real).unwrap();
            let got = mirror_half_spectrum(&half, n);

            let padded: Vec<Complex64> = real.iter().map(|&v| Complex64::real(v)).collect();
            let want = numeric::fft_complex(&padded).unwrap();

            assert_eq!(got.len(), want.len(), "n={n}");
            for (i, (g, w)) in got.iter().zip(want.iter()).enumerate() {
                assert!(
                    (g.re - w.re).abs() < 1e-9 && (g.im - w.im).abs() < 1e-9,
                    "n={n}, bin {i}: got {g:?}, want {w:?}"
                );
            }
        }
    }

    #[test]
    fn fft_on_real_input_is_unchanged_end_to_end() {
        // The path a caller actually exercises: `fft(x)` on a real vector,
        // with and without the length-override argument, matched against
        // `dft` (the untouched, deliberately-naive reference transform
        // below) rather than against fft_complex directly, so this checks
        // the same public contract `dft_matches_the_fast_fft` checks.
        let it = run(
            "x = [0.5, 1.2, -0.3, 2.1, 0.7, -1.1, 0.3, 1.8, 0.9]\n\
             err = max(abs(fft(x) - dft(x)))\n\
             y = [0.5, 1.2, -0.3, 2.1, 0.7]\n\
             padded = max(abs(fft(y, 8) - dft([y, 0, 0, 0])))",
        );
        assert!(num(&it, "err") < 1e-9, "err = {}", num(&it, "err"));
        assert!(num(&it, "padded") < 1e-9, "padded = {}", num(&it, "padded"));
    }

