    #[test]
    fn xcorr_autocorrelation_peaks_at_zero_lag_with_the_signal_energy() {
        let it = run("x = [1, 2, -1, 3, 0.5]\nr = xcorr(x)\nenergy = sum(x .^ 2)");
        let r = vec_of(&it, "r");
        let zero_lag = r.len() / 2;
        let peak_index = r.iter().enumerate().max_by(|(_, a), (_, b)| a.total_cmp(b)).unwrap().0;
        assert_eq!(peak_index, zero_lag);
        assert!((r[zero_lag] - num(&it, "energy")).abs() < 1e-9);
    }

