    // `findpeaks` — MATLAB-style `[peaks, locations] = findpeaks(x, ...)`,
    // returned as a `Value::Model` (kind "findpeaks") since Qu has no
    // multi-return assignment. See the builtin's own doc comment.

    #[test]
    fn findpeaks_returns_a_model_with_peaks_and_locations() {
        let it = run("y = [0, 1, 0, 3, 0, 1, 0]\nr = findpeaks(y)\np = r.peaks\nloc = r.locations");
        assert_eq!(vec_of(&it, "p"), vec![1.0, 3.0, 1.0]);
        // 0-indexed, matching Qu's convention everywhere else (argmin/
        // argmax etc.) -- deliberately NOT MATLAB's 1-indexing.
        assert_eq!(vec_of(&it, "loc"), vec![1.0, 3.0, 5.0]);
    }

    #[test]
    fn findpeaks_finds_synthetic_gaussian_bumps_at_known_locations() {
        // Two Gaussian bumps with exactly-known integer centers/heights --
        // a discrete Gaussian is monotonic away from its center, so the
        // local maximum lands exactly on the center sample, no tolerance
        // needed for the locations themselves.
        let it = run(
            "n = 0 to 99\n\
             x = 5 * exp(-((n - 20) ^ 2) / (2 * 3 ^ 2)) + 3 * exp(-((n - 60) ^ 2) / (2 * 3 ^ 2))\n\
             r = findpeaks(x)\n\
             loc = r.locations\n\
             pk = r.peaks",
        );
        assert_eq!(vec_of(&it, "loc"), vec![20.0, 60.0]);
        let pk = vec_of(&it, "pk");
        assert!((pk[0] - 5.0).abs() < 1e-9, "pk0 = {}", pk[0]);
        assert!((pk[1] - 3.0).abs() < 1e-9, "pk1 = {}", pk[1]);
    }

    #[test]
    fn findpeaks_min_peak_height_filters_smaller_peaks() {
        let it = run("y = [0, 1, 0, 3, 0, 1, 0]\nr = findpeaks(y, min_peak_height=2)\np = r.peaks\nloc = r.locations");
        assert_eq!(vec_of(&it, "p"), vec![3.0]);
        assert_eq!(vec_of(&it, "loc"), vec![3.0]);
    }

    #[test]
    fn findpeaks_min_peak_distance_merges_close_peaks_keeping_the_tallest() {
        let it = run(
            "y = [0, 1, 0, 1.5, 2, 0.5, 0, 0, 0]\n\
             r = findpeaks(y, min_peak_distance=4)\n\
             p = r.peaks\n\
             loc = r.locations",
        );
        assert_eq!(vec_of(&it, "p"), vec![2.0]);
        assert_eq!(vec_of(&it, "loc"), vec![4.0]);
    }

    #[test]
    fn findpeaks_locations_index_back_into_the_original_signal() {
        // Confirms the user's actual script pattern
        // (`f[r.locations]`) -- fancy-indexing a Vec by a Vec of
        // indices -- already works in Qu.
        let it = run("y = [0, 1, 0, 3, 0, 1, 0]\nr = findpeaks(y)\nback = y[r.locations]");
        assert_eq!(vec_of(&it, "back"), vec![1.0, 3.0, 1.0]);
    }

    #[test]
    fn db_conversions_round_trip() {
        let it = run(
            "a = mag2db(2)\n\
             b = db2mag(a)\n\
             c = pow2db(2)\n\
             d = db2pow(c)",
        );
        assert!((num(&it, "a") - 6.0206).abs() < 1e-3);
        assert!((num(&it, "b") - 2.0).abs() < 1e-9);
        assert!((num(&it, "c") - 3.0103).abs() < 1e-3);
        assert!((num(&it, "d") - 2.0).abs() < 1e-9);
    }

    #[test]
    fn mag2db_and_pow2db_differ_by_the_expected_factor_of_two() {
        // 20*log10(x) == 2 * 10*log10(x) for the same x -- the actual
        // reason these are two named functions, not one ambiguous `db()`.
        let it = run("x = 5\na = mag2db(x)\nb = pow2db(x)");
        assert!((num(&it, "a") - 2.0 * num(&it, "b")).abs() < 1e-9);
    }

    #[test]
    fn db_and_db_power_aliases_round_trip_and_match_known_values() {
        // db2mag(mag2db(x)) == x, for several x, including x=1 (0 dB) and
        // the well-known x=10 (20 dB) / x=2 (~6.0206 dB) landmarks -- and
        // `db`/`db_power` are exact aliases of `mag2db`/`pow2db`, so the
        // same identities hold through them too.
        for x in [1.0, 2.0, 10.0, 0.5, 3.7] {
            let it = run(&format!("x = {x}\na = db(x)\nb = db2mag(a)\nc = db_power(x)\nd = db2pow(c)"));
            assert!((num(&it, "b") - x).abs() < 1e-9, "db2mag(db({x})) round trip failed: {}", num(&it, "b"));
            assert!((num(&it, "d") - x).abs() < 1e-9, "db2pow(db_power({x})) round trip failed: {}", num(&it, "d"));
            assert!(
                (num(&it, "a") - 20.0 * x.log10()).abs() < 1e-9,
                "db({x}) should equal mag2db({x})"
            );
            assert!(
                (num(&it, "c") - 10.0 * x.log10()).abs() < 1e-9,
                "db_power({x}) should equal pow2db({x})"
            );
        }
        let it = run("a = db(1)\nb = db_power(1)");
        assert!(num(&it, "a").abs() < 1e-12, "db(1) should be 0 dB, got {}", num(&it, "a"));
        assert!(num(&it, "b").abs() < 1e-12, "db_power(1) should be 0 dB, got {}", num(&it, "b"));
        let it = run("a = db(10)\nb = db(2)");
        assert!((num(&it, "a") - 20.0).abs() < 1e-9, "db(10) should be 20 dB, got {}", num(&it, "a"));
        assert!((num(&it, "b") - 6.0206).abs() < 1e-3, "db(2) should be ~6.0206 dB, got {}", num(&it, "b"));
    }

