    // ---- corr/energy/tkeo/emd/vmd ----

    #[test]
    fn corr_matches_a_hand_computed_value() {
        let it = run("x = [1, 2, 3, 4, 5]\ny = [2, 1, 4, 3, 5]\nr = corr(x, y)");
        assert!((num(&it, "r") - 0.8).abs() < 1e-9);
    }

    #[test]
    fn corr_of_a_signal_with_itself_is_one() {
        let it = run("x = [1, 4, 2, 8, 5]\nr = corr(x, x)");
        assert!((num(&it, "r") - 1.0).abs() < 1e-9);
    }

    #[test]
    fn corrcoef_matches_hand_computed_correlations() {
        // Three columns, 5 samples each: b = 2*a (perfectly correlated),
        // c handpicked so corr(a, c) is neither +-1 nor 0 -- a small matrix
        // whose off-diagonal entries can be checked against `corr` itself
        // (already verified above) rather than only against each other.
        let it = run(
            "X = [1, 2, 5; 2, 4, 3; 3, 6, 6; 4, 8, 2; 5, 10, 9]\n\
             R = corrcoef(X)\n\
             r_ab = corr(X[:,0], X[:,1])\n\
             r_ac = corr(X[:,0], X[:,2])\n\
             r_bc = corr(X[:,1], X[:,2])",
        );
        let r_ab = num(&it, "r_ab");
        let r_ac = num(&it, "r_ac");
        let r_bc = num(&it, "r_bc");
        match it.get("R") {
            Some(Value::Mat(m)) => {
                assert_eq!(m.shape(), (3, 3));
                // diagonal is self-correlation == 1
                for i in 0..3 {
                    assert!((m.get(i, i).unwrap() - 1.0).abs() < 1e-9);
                }
                // symmetric
                for i in 0..3 {
                    for j in 0..3 {
                        assert!((m.get(i, j).unwrap() - m.get(j, i).unwrap()).abs() < 1e-12);
                    }
                }
                // b = 2*a exactly, so corr(a,b) must be 1
                assert!((m.get(0, 1).unwrap() - 1.0).abs() < 1e-9);
                // off-diagonal entries match the pairwise `corr` builtin
                assert!((m.get(0, 1).unwrap() - r_ab).abs() < 1e-9);
                assert!((m.get(0, 2).unwrap() - r_ac).abs() < 1e-9);
                assert!((m.get(1, 2).unwrap() - r_bc).abs() < 1e-9);
            }
            other => panic!("expected R to be a Mat, got {other:?}"),
        }
    }

    #[test]
    fn corrcoef_of_anticorrelated_columns_is_minus_one() {
        // a = 0..9 ascending, b = 9..0 descending -- same pair `corr_heatmap`'s
        // own diagonal/off-diagonal test above uses, here through `corrcoef`.
        // `vstack(a, b)` stacks the two as rows (2x10); transposing gives the
        // 10x2 samples-by-features matrix `corrcoef` expects.
        let it = run(
            "a = 0 to 9\n\
             b = 9 to 0 step -1\n\
             X = vstack(a, b)'\n\
             R = corrcoef(X)",
        );
        match it.get("R") {
            Some(Value::Mat(m)) => {
                assert!((m.get(0, 0).unwrap() - 1.0).abs() < 1e-9);
                assert!((m.get(1, 1).unwrap() - 1.0).abs() < 1e-9);
                assert!((m.get(0, 1).unwrap() + 1.0).abs() < 1e-9);
                assert!((m.get(1, 0).unwrap() + 1.0).abs() < 1e-9);
            }
            other => panic!("expected R to be a Mat, got {other:?}"),
        }
    }

    #[test]
    fn corrcoef_rejects_fewer_than_two_rows() {
        // `reshape(..., 1, 3)` forces a genuine (1,3) `Mat` (a bare `[1,2,3]`
        // literal would instead stay a column-oriented `Value::Vec`) -- one
        // sample, three "features". `corrcoef` needs at least 2 samples per
        // feature to define a correlation, so this must error rather than
        // silently divide by a zero-length centered column.
        let mut it = Interp::new();
        let err = it.run("X = reshape([1, 2, 3], 1, 3)\nR = corrcoef(X)");
        assert!(err.is_err(), "corrcoef on a single sample row should error");
    }

