    #[test]
    fn ste_matches_a_hand_computed_frame_and_frame_count() {
        // win=4, hop=2 over 8 samples -> 3 frames; frame 0 of a constant
        // [1,1,1,1] Hann-windowed ([0, 0.5, 1, 0.5]) then squared and
        // summed is 1.5 -- verified independently in Python (numpy)
        // before writing this assertion, matching the qu-core-level test
        // for the same function.
        let it = run("e = ste([1, 1, 1, 1, 1, 1, 1, 1], 4, 2)");
        let e = vec_of(&it, "e");
        assert_eq!(e.len(), 3);
        assert!((e[0] - 1.5).abs() < 1e-9, "e[0] = {}", e[0]);
    }

    #[test]
    fn spectral_entropy_is_lower_for_a_tone_than_for_noise() {
        // Reuses the same qu-core-level contrast (a pure tone concentrates
        // energy in one bin; noise spreads it across all bins) as an
        // end-to-end check through the builtin, not just the underlying
        // qu_core function directly.
        let it = run(
            "n = 2000\n\
             idx = 0 to n-1\n\
             tone = sin(2*pi*50/1000 .* idx)\n\
             noise = randn(n, seed=1)\n\
             h_tone = mean(spectral_entropy(tone, 256, 128))\n\
             h_noise = mean(spectral_entropy(noise, 256, 128))",
        );
        let h_tone = num(&it, "h_tone");
        let h_noise = num(&it, "h_noise");
        assert!(h_tone < 0.3, "h_tone = {h_tone} should be low");
        assert!(h_noise > 0.7, "h_noise = {h_noise} should be high");
    }

