    #[test]
    fn vmd_separates_two_tones_and_reconstructs_the_signal() {
        let it = run(
            "n = 512\n\
             fs = 512\n\
             idx = 0 to n-1\n\
             sig = sin(2*pi*5.*idx./fs) + sin(2*pi*60.*idx./fs)\n\
             v = vmd(sig, 2)\n\
             freqs_hz = sort(v.center_freqs .* fs)\n\
             recon = sum(v.modes, axis=0)\n\
             err = max(abs(recon - sig))",
        );
        let freqs = vec_of(&it, "freqs_hz");
        assert!((freqs[0] - 5.0).abs() < 1.0, "freqs = {freqs:?}");
        assert!((freqs[1] - 60.0).abs() < 1.0, "freqs = {freqs:?}");
        assert!(num(&it, "err") < 0.05, "err = {}", num(&it, "err"));
    }

    #[test]
    fn vmd_mode_count_matches_k() {
        let it = run("idx = 0 to 63\nx = sin(2*pi*0.1.*idx)\nv = vmd(x, 3)");
        let Some(Value::Model(m)) = it.get("v") else { panic!("expected a model") };
        let Some(Value::Mat(modes)) = m.field("modes") else { panic!("expected a matrix") };
        assert_eq!(modes.rows(), 3);
    }

    // ---- butter/sosfilt/filtfilt/filter_init/filter_next ----

    #[test]
    fn butter_lowpass_passes_a_low_tone_and_rejects_a_high_one() {
        let it = run(
            "fs = 1000\n\
             lp = butter(4, \"low\", 100, fs)\n\
             idx = 0 to 499\n\
             low_tone = sin(2*pi*10.*idx./fs)\n\
             high_tone = sin(2*pi*300.*idx./fs)\n\
             low_out = sosfilt(lp, low_tone)\n\
             high_out = sosfilt(lp, high_tone)\n\
             rms_low = rms(low_out[200:499])\n\
             rms_high = rms(high_out[200:499])",
        );
        assert!(num(&it, "rms_low") > 0.6, "rms_low = {}", num(&it, "rms_low"));
        assert!(num(&it, "rms_high") < 0.1, "rms_high = {}", num(&it, "rms_high"));
    }

    #[test]
    fn butter_notch_removes_a_narrow_band_while_preserving_others() {
        let it = run(
            "fs = 1000\n\
             notch = butter(2, \"notch\", [45, 55], fs)\n\
             idx = 0 to 499\n\
             mains = sin(2*pi*50.*idx./fs)\n\
             clean = sin(2*pi*10.*idx./fs)\n\
             noisy = mains + clean\n\
             denoised = sosfilt(notch, noisy)\n\
             residual = rms(denoised[200:499] - filtfilt(notch, clean)[200:499])\n\
             mains_rms = rms(mains[200:499])",
        );
        // the mains tone should be reduced by more than an order of
        // magnitude relative to its own original amplitude.
        assert!(num(&it, "residual") < num(&it, "mains_rms") / 5.0);
    }

    #[test]
    fn filtfilt_has_no_net_phase_shift() {
        let it = run(
            "fs = 1000\n\
             lp = butter(4, \"low\", 100, fs)\n\
             idx = 0 to 999\n\
             x = sin(2*pi*20.*idx./fs)\n\
             y = filtfilt(lp, x)\n\
             mid = x[500]\n\
             mid_y = y[500]",
        );
        assert!((num(&it, "mid") - num(&it, "mid_y")).abs() < 0.05);
    }

    #[test]
    fn streaming_filter_next_matches_batch_sosfilt() {
        let it = run(
            "fs = 1000\n\
             lp = butter(3, \"low\", 80, fs)\n\
             idx = 0 to 199\n\
             x = sin(2*pi*30.*idx./fs) + 0.3*sin(2*pi*300.*idx./fs)\n\
             batch = sosfilt(lp, x)\n\
             state = filter_init(lp)\n\
             for i = 0 to length(x) - 1\n\
             \x20   state = filter_next(state, x[i])\n\
             end for\n\
             last_streamed = state.y\n\
             last_batch = batch[length(batch) - 1]",
        );
        assert!((num(&it, "last_streamed") - num(&it, "last_batch")).abs() < 1e-9);
    }

    #[test]
    fn sosfilt_and_filtfilt_of_a_signal_preserve_its_fs() {
        // filtering never changes sample count or sample rate — same
        // "still the same time domain" convention `diff`/`cumsum` already
        // follow (Â§41.2). `sosfilt`/`filtfilt` used to always return a
        // plain `Vec` regardless of the input type, silently dropping `Fs`
        // whenever the input was a `Signal` (e.g. straight from `sine`/
        // `multisine`/`signal(...)`) — `y.Fs` on the result errored with
        // "no field `Fs` on vector" instead of reporting the true rate.
        // Verified two independent ways: the `.Fs` field is now correct,
        // and the filtered *values* are bit-identical to running the exact
        // same filter over the plain-`Vec` (`array(x)`) version of the same
        // data — this fix changes only the wrapper type, never the math.
        let it = run(
            "fs = 100\n\
             x = sine(5, fs, 50)\n\
             xa = array(x)\n\
             filt = fir1(4, 0.2)\n\
             y1 = sosfilt(filt, x)\n\
             y2 = sosfilt(filt, xa)\n\
             sos_fs = y1.Fs\n\
             sos_diff = sum(abs(y1 - y2))\n\
             yz1 = filtfilt(filt, x)\n\
             yz2 = filtfilt(filt, xa)\n\
             filtfilt_fs = yz1.Fs\n\
             filtfilt_diff = sum(abs(yz1 - yz2))",
        );
        assert_eq!(num(&it, "sos_fs"), 100.0);
        assert_eq!(num(&it, "sos_diff"), 0.0);
        assert_eq!(num(&it, "filtfilt_fs"), 100.0);
        assert_eq!(num(&it, "filtfilt_diff"), 0.0);
    }

    #[test]
    fn sosfilt_of_a_plain_vector_still_returns_a_plain_vector() {
        // the fix above must not force everything through `Signal` — a
        // plain-`Vec` input (no sample-rate metadata to begin with) keeps
        // returning a plain `Vec`, matching every pre-existing sosfilt/
        // filtfilt test in this file (all of which pass a range-generated
        // plain vector, never a `Signal`).
        let it = run(
            "fs = 1000\n\
             lp = butter(3, \"low\", 80, fs)\n\
             idx = 0 to 49\n\
             x = sin(2*pi*30.*idx./fs)\n\
             y = sosfilt(lp, x)\n\
             ylen = length(y)",
        );
        assert_eq!(num(&it, "ylen"), 50.0);
    }

