    #[test]
    fn firls_weights_kwarg_upweights_the_stopband_reducing_its_own_error() {
        let it = run(
            "lp_equal = firls(30, [0, 0.3, 0.4, 1.0], [1, 1, 0, 0])\n\
             lp_weighted = firls(30, [0, 0.3, 0.4, 1.0], [1, 1, 0, 0], weights=[1, 20])\n\
             h_equal = lp_equal.freqz(513)\n\
             h_weighted = lp_weighted.freqz(513)",
        );
        let (Some(Value::CVec(he)), Some(Value::CVec(hw))) = (it.get("h_equal"), it.get("h_weighted")) else { panic!("expected complex vectors") };
        let stop_worst = |h: &[qu_core::Complex64]| -> f64 {
            h.iter().enumerate().filter(|(k, _)| *k as f64 / 512.0 >= 0.45).map(|(_, hk)| hk.magnitude()).fold(0.0, f64::max)
        };
        assert!(stop_worst(hw) < stop_worst(he), "upweighting the stopband should reduce its worst-case error");
    }

