    #[test]
    fn pzplot_renders_poles_zeros_and_a_unit_circle_with_a_stability_titled_panel() {
        let it = run("lp = butter(4, \"low\", 100, 1000)\nlp.pzplot()");
        assert_eq!(it.figure.panels.len(), 1);
        let panel = &it.figure.panels[0];
        assert_eq!(panel.series.len(), 3, "expected unit circle, zeros, and poles series");
        let title = panel.title.as_deref().unwrap();
        assert!(title.contains("stable"));
        assert!(!title.contains("UNSTABLE"));
        assert_eq!(panel.xlabel.as_deref(), Some("Real part"));
        assert_eq!(panel.ylabel.as_deref(), Some("Imaginary part"));
        let poles_series = panel.series.iter().find(|s| s.label.as_deref() == Some("poles")).expect("poles series");
        assert_eq!(poles_series.marker, "x");
        assert_eq!(poles_series.x.len(), 4);
        let zeros_series = panel.series.iter().find(|s| s.label.as_deref() == Some("zeros")).expect("zeros series");
        assert_eq!(zeros_series.marker, "o");
        let circle_series = panel.series.iter().find(|s| s.label.as_deref() == Some("unit circle")).expect("circle series");
        assert_eq!(circle_series.x.len(), 201);
    }

