    #[test]
    fn curve_fit_calls_a_vectorizable_model_once_per_jacobian_column_not_once_per_point() {
        // The fix for curve_fit's O(N x (P+1)) interpreted-call blowup:
        // an elementwise model (ordinary arithmetic over a vector `x`,
        // exactly like `damped_sine`/`double_exp` in
        // `benchmarks/advanced_validation/curve_kalman`) should now be
        // called once per residual/Jacobian-column evaluation, with the
        // WHOLE `xdata` vector passed at once -- not once per data point.
        // `counter` (mutated inside `model`, a plain global-scope
        // variable) counts real interpreter dispatches of `model`
        // directly; if the old per-point loop were still in place, this
        // would scale with N (20 vs 500 would differ by >>10x). Under the
        // fix it depends only on the number of LM iterations x (P+1),
        // which is essentially unchanged between the two data sizes.
        let script = |n: i64| {
            format!(
                "counter = 0\n\
                 function model(x, p)\n\
                     counter = counter + 1\n\
                     return p[0] * exp(-p[1] * x)\n\
                 end function\n\
                 idx = 0 to {}\n\
                 xdata = idx .* (4.0 / {})\n\
                 ydata = 5 * exp(-0.5 .* xdata)\n\
                 fit = curve_fit(\"model\", xdata, ydata, [1, 1])\n\
                 a = fit.params[0]\n\
                 b = fit.params[1]\n\
                 calls = counter",
                n - 1,
                n
            )
        };
        let small = run(&script(20));
        let large = run(&script(500));
        assert!((num(&small, "a") - 5.0).abs() < 1e-4);
        assert!((num(&small, "b") - 0.5).abs() < 1e-4);
        assert!((num(&large, "a") - 5.0).abs() < 1e-4);
        assert!((num(&large, "b") - 0.5).abs() < 1e-4);
        let calls_small = num(&small, "calls");
        let calls_large = num(&large, "calls");
        // Same model, same shape of problem, 25x the data points: a
        // per-point calling convention would inflate `calls_large` by
        // roughly that same 25x. A per-Jacobian-column convention keeps
        // them close (LM's iteration count can still vary a little
        // between runs, so allow generous slack, not exact equality).
        assert!(calls_small < 100.0, "calls_small={calls_small}");
        assert!(calls_large < 100.0, "calls_large={calls_large}");
    }

    #[test]
    fn curve_fit_falls_back_to_per_point_calls_for_a_model_that_rejects_a_vector_x() {
        // Not every conceivable model is elementwise-safe over a vector
        // `x` (e.g. one with a branch keyed on `len(x)` rather than on
        // `x`'s own value, which is a contrived but legal way to make a
        // model behave differently for a batched call than a per-point
        // one). The vectorized fast path must detect this (wrong-length
        // result) and permanently fall back to the original one-call-
        // per-point convention for the rest of the fit -- correctness
        // preserved, at the pre-existing (slower) call volume.
        let it = run(
            "counter = 0\n\
             function model(x, p)\n\
                 global counter\n\
                 counter = counter + 1\n\
                 if len(x) > 1\n\
                     return p[0]\n\
                 end if\n\
                 return p[0] * exp(-p[1] * x)\n\
             end function\n\
             idx = 0 to 19\n\
             xdata = idx .* 0.2\n\
             ydata = 5 * exp(-0.5 .* xdata)\n\
             fit = curve_fit(\"model\", xdata, ydata, [1, 1])\n\
             a = fit.params[0]\n\
             b = fit.params[1]\n\
             cost = fit.cost\n\
             calls = counter",
        );
        assert!((num(&it, "a") - 5.0).abs() < 1e-4);
        assert!((num(&it, "b") - 0.5).abs() < 1e-4);
        assert!(num(&it, "cost") < 1e-8);
        // One failed vectorized probe, then per-point calls (a multiple
        // of N=20 data points) for every residual/Jacobian evaluation
        // after that -- proof the fallback actually engaged rather than
        // silently producing a wrong (but coincidentally passing) fit.
        let calls = num(&it, "calls");
        assert!(calls > 200.0, "expected many per-point fallback calls, got {calls}");
        assert_eq!((calls as i64 - 1) % 20, 0, "expected 1 failed probe + a multiple of 20 per-point calls, got {calls}");
    }

    #[test]
    fn minimize_finds_the_minimum_of_a_quadratic_bowl() {
        let it = run("bowl(p) := (p[0]-3)^2 + (p[1]+2)^2\nm = minimize(\"bowl\", [0, 0])");
        let Some(Value::Model(m)) = it.get("m") else { panic!("expected a model") };
        let Some(Value::Vec(p)) = m.field("params") else { panic!("expected a vector") };
        assert!((p[0] - 3.0).abs() < 1e-3);
        assert!((p[1] - (-2.0)).abs() < 1e-3);
        assert!(matches!(m.field("value"), Some(Value::Num(v)) if *v < 1e-6));
    }

    #[test]
    fn minimize_accepts_an_analytical_gradient_and_reaches_the_same_minimum() {
        // Same bowl as above, but with `grad=` given explicitly -- should
        // still land on the true minimum (and no numerical gradient is ever
        // computed, since the analytical one is always available here).
        let it = run(
            "bowl(p) := (p[0]-3)^2 + (p[1]+2)^2\n\
             bowl_grad(p) := [2*(p[0]-3), 2*(p[1]+2)]\n\
             m = minimize(\"bowl\", [0, 0], grad=\"bowl_grad\")",
        );
        let Some(Value::Model(m)) = it.get("m") else { panic!("expected a model") };
        let Some(Value::Vec(p)) = m.field("params") else { panic!("expected a vector") };
        assert!((p[0] - 3.0).abs() < 1e-3);
        assert!((p[1] - (-2.0)).abs() < 1e-3);
    }

