    // ---- collections: `Value::List`/`Value::Record` via the existing
    // tuple/record syntax, generic collection utilities, string utilities
    // (2026-08-24) ----

    #[test]
    fn tuple_literal_builds_a_heterogeneous_list_indexable_by_position() {
        let it = run("t = (1, \"hello\", [1, 2, 3])\na = t[0]\nb = t[1]\nc = t[2]");
        assert!(matches!(it.get("a"), Some(Value::Num(n)) if *n == 1.0));
        assert!(matches!(it.get("b"), Some(Value::Str(s)) if s == "hello"));
        assert_eq!(vec_of(&it, "c"), vec![1.0, 2.0, 3.0]);
    }

    #[test]
    fn single_parenthesized_expr_is_not_a_list_but_a_trailing_comma_makes_one() {
        // `(5)` is just the number 5 (no comma, so `qu-syntax`'s `"("`
        // primary-expression parsing returns the inner expr directly, not
        // an `Expr::Tuple`) — a genuine 1-element list needs `(5,)`,
        // exactly like Python.
        let it = run("x = (5)\nt = (5,)\nn = length(t)\nfirst = t[0]");
        assert!(matches!(it.get("x"), Some(Value::Num(n)) if *n == 5.0));
        assert!(matches!(it.get("n"), Some(Value::Num(n)) if *n == 1.0));
        assert!(matches!(it.get("first"), Some(Value::Num(n)) if *n == 5.0));
    }

