    #[test]
    fn nested_list_and_record_save_load_round_trip() {
        let path = save_load_path("qu_save_list_record_nested.json");
        let mut it = Interp::new();
        it.run(&format!(
            "t = (1, \"hello\", [1, 2, 3], (2, 3))\nr = {{a = 1, b = \"x\", c = (1, 2), d = {{e = 5}}}}\nsave_all(\"{}\")",
            qu_path(&path)
        ))
        .unwrap();

        let mut it2 = Interp::new();
        it2.run(&format!("load(\"{}\")", qu_path(&path))).unwrap();

        let Some(Value::List(t)) = it2.get("t") else { panic!("expected a list") };
        assert!(matches!(t[0], Value::Num(n) if n == 1.0));
        assert!(matches!(&t[1], Value::Str(s) if s == "hello"));
        assert!(matches!(&t[2], Value::Vec(xs) if xs.as_ref().clone() == vec![1.0, 2.0, 3.0]));
        let Value::List(nested) = &t[3] else { panic!("expected a nested list") };
        assert!(matches!(nested[0], Value::Num(n) if n == 2.0));
        assert!(matches!(nested[1], Value::Num(n) if n == 3.0));

        let Some(Value::Record(r)) = it2.get("r") else { panic!("expected a record") };
        // field order must survive the round trip (a JSON object alone
        // would silently alphabetize it — this is exactly why `value_to_
        // json`/`json_to_value` store the field order in its own array).
        let names: Vec<&str> = r.iter().map(|(k, _)| k.as_str()).collect();
        assert_eq!(names, vec!["a", "b", "c", "d"]);
        assert!(matches!(r[0].1, Value::Num(n) if n == 1.0));
        let Value::Record(d) = &r[3].1 else { panic!("expected a nested record") };
        assert_eq!(d[0].0, "e");
        assert!(matches!(d[0].1, Value::Num(n) if n == 5.0));

        let _ = std::fs::remove_file(path);
    }

    #[test]
    fn empty_list_is_falsy_and_displays_as_empty_parens() {
        // There's no bare empty-list literal (`()` isn't valid Qu syntax —
        // the tuple grammar always parses at least one inner expression
        // first); `remove` on a 1-element list is a simple way to produce
        // a genuinely empty one to exercise `truthy`/`display_value`'s own
        // empty-collection handling.
        let it = run("t = remove((5,), 0)\nok = t ? 1 : 0\nprint(t)");
        assert!(matches!(it.get("ok"), Some(Value::Num(n)) if *n == 0.0));
        assert_eq!(it.out.trim(), "()");
    }

