    #[test]
    fn dict_construction_and_get_set_keys_values_round_trip() {
        let it = run(
            "d0 = dict((\"a\", \"b\", \"c\"), (1, 2, 3))\n\
             va = get(d0, \"a\")\n\
             vb = get(d0, \"b\")\n\
             vmiss = get(d0, \"nope\")\n\
             d1 = set(d0, \"b\", 99)\n\
             vb_original_after_set = get(d0, \"b\")\n\
             vb_in_new_dict = get(d1, \"b\")\n\
             ks = keys(d0)\n\
             vs = values(d0)",
        );
        assert!(matches!(it.get("va"), Some(Value::Num(n)) if *n == 1.0));
        assert!(matches!(it.get("vb"), Some(Value::Num(n)) if *n == 2.0));
        // missing key -> `Nothing`, same "absent" convention `indexof` uses,
        // not a thrown error.
        assert!(matches!(it.get("vmiss"), Some(Value::Nothing)));
        // `set` must NOT mutate the original dict.
        assert!(matches!(it.get("vb_original_after_set"), Some(Value::Num(n)) if *n == 2.0));
        assert!(matches!(it.get("vb_in_new_dict"), Some(Value::Num(n)) if *n == 99.0));
        match it.get("ks") {
            Some(Value::List(items)) => {
                let got: Vec<String> = items
                    .iter()
                    .map(|v| match v {
                        Value::Str(s) => s.clone(),
                        other => panic!("expected a Str key, got {other:?}"),
                    })
                    .collect();
                assert_eq!(got, vec!["a".to_string(), "b".to_string(), "c".to_string()]);
            }
            other => panic!("expected a List, got {other:?}"),
        }
        match it.get("vs") {
            Some(Value::List(items)) => {
                let got: Vec<f64> = items.iter().map(|v| v.as_num().unwrap()).collect();
                assert_eq!(got, vec![1.0, 2.0, 3.0]);
            }
            other => panic!("expected a List, got {other:?}"),
        }
    }

