    // ---- § file/directory I/O extensions + type casts (2026-08-26,
    // `fs_ops.rs`): seek/tell/rewind/eof, generic read_int/write_int,
    // read_bin/write_bin, cd/pwd/mkdir/file_exists/dir_exists/make_file/
    // tmp_file/list_dir, to_int/to_float/to_bool ----

    #[test]
    fn fsops_file_seek_tell_rewind_and_whence_variants_round_trip() {
        let path = file_test_path("qu_fs_seek_test.bin");
        let _ = std::fs::remove_file(&path);
        let lit = qu_path_literal(&path);
        let it = run(&format!(
            "f = fopen(\"{lit}\", \"wb\")\n\
             write(f, \"0123456789\")\n\
             close(f)\n\
             g = fopen(\"{lit}\", \"rb\")\n\
             t0 = tell(g)\n\
             a = read_chars(g, 3)\n\
             t1 = tell(g)\n\
             seek(g, 5)\n\
             b = read_chars(g, 2)\n\
             seek(g, -3, whence=\"current\")\n\
             c = read_chars(g, 2)\n\
             seek(g, -2, whence=\"end\")\n\
             d = read_chars(g, 2)\n\
             e1 = eof(g)\n\
             rewind(g)\n\
             t2 = tell(g)\n\
             full = read_chars(g, 10)\n\
             close(g)"
        ));
        assert!(matches!(it.get("t0"), Some(Value::Num(n)) if *n == 0.0));
        assert!(matches!(it.get("a"), Some(Value::Str(s)) if s == "012"));
        assert!(matches!(it.get("t1"), Some(Value::Num(n)) if *n == 3.0));
        assert!(matches!(it.get("b"), Some(Value::Str(s)) if s == "56"));
        assert!(matches!(it.get("c"), Some(Value::Str(s)) if s == "45"));
        assert!(matches!(it.get("d"), Some(Value::Str(s)) if s == "89"));
        assert!(matches!(it.get("e1"), Some(Value::Bool(true))), "expected eof() true at exact EOF, got {:?}", it.get("e1"));
        assert!(matches!(it.get("t2"), Some(Value::Num(n)) if *n == 0.0));
        assert!(matches!(it.get("full"), Some(Value::Str(s)) if s == "0123456789"));
        let _ = std::fs::remove_file(&path);
    }

