    #[test]
    fn fsops_tmp_file_creates_a_real_empty_file_with_a_unique_path_each_call() {
        // `a == b` isn't used to check uniqueness here: this interpreter's
        // `==` doesn't support two `Str` operands at all today (falls
        // through to a numeric coercion and errors, `"expected a number,
        // found string"` — checked directly, a separate pre-existing gap,
        // not something this pass touches) — so the two paths are compared
        // in Rust below instead.
        let it = run("a = tmp_file()\nb = tmp_file()\na_exists = file_exists(a)\nb_exists = file_exists(b)");
        let (a, b) = match (it.get("a"), it.get("b")) {
            (Some(Value::Str(a)), Some(Value::Str(b))) => (a.clone(), b.clone()),
            other => panic!("expected tmp_file() to return path strings, got {:?}", other),
        };
        assert!(matches!(it.get("a_exists"), Some(Value::Bool(true))));
        assert!(matches!(it.get("b_exists"), Some(Value::Bool(true))));
        assert_ne!(a, b, "two tmp_file() calls must not collide");
        assert_eq!(std::fs::read(&a).unwrap().len(), 0, "tmp_file() must create an EMPTY file");
        let _ = std::fs::remove_file(&a);
        let _ = std::fs::remove_file(&b);
    }

    // ===== § OS surface (2026-09-09): list_files / exec / shell =====

    /// Builds a small tree under the temp directory and returns its root:
    ///
    /// ```text
    /// <root>/a.html          "hello needle"
    /// <root>/b.html          "hello"
    /// <root>/c.txt           "needle"
    /// <root>/sub/d.html      "" (empty)
    /// <root>/sub/deep/e.html "x"
    /// ```
    fn os_test_tree(name: &str) -> std::path::PathBuf {
        let root = file_test_path(name);
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(root.join("sub").join("deep")).unwrap();
        std::fs::write(root.join("a.html"), "hello needle").unwrap();
        std::fs::write(root.join("b.html"), "hello").unwrap();
        std::fs::write(root.join("c.txt"), "needle").unwrap();
        std::fs::write(root.join("sub").join("d.html"), "").unwrap();
        std::fs::write(root.join("sub").join("deep").join("e.html"), "x").unwrap();
        root
    }

    /// The `List` of strings a `list_files` call produced, as bare file
    /// names, sorted — the paths themselves carry a temp directory that
    /// differs per machine, and every assertion here is about WHICH files
    /// came back, not where they live.
    fn names_of(it: &Interp, var: &str) -> Vec<String> {
        let Some(Value::List(items)) = it.get(var) else {
            panic!("expected `{var}` to be a List, got {:?}", it.get(var));
        };
        let mut out: Vec<String> = items
            .iter()
            .map(|v| match v {
                Value::Str(s) => std::path::Path::new(s.as_str())
                    .file_name()
                    .map(|n| n.to_string_lossy().into_owned())
                    .unwrap_or_else(|| s.to_string()),
                other => panic!("expected a path string, got {other:?}"),
            })
            .collect();
        out.sort();
        out
    }

    #[test]
    fn list_files_reads_one_argument_as_a_pattern_or_a_directory() {
        let root = os_test_tree("qu_os_listfiles_oneargtest");
        let lit = qu_path_literal(&root);
        let it = run(&format!(
            "pat = list_files(\"{lit}/*.html\")\n\
             dir_only = list_files(\"{lit}\")\n\
             two = list_files(\"{lit}\", \"*.html\")"
        ));
        // A wildcard means it is a pattern; no wildcard means it is a
        // directory. Neither spelling needs a keyword to say which.
        assert_eq!(names_of(&it, "pat"), vec!["a.html", "b.html"]);
        assert_eq!(names_of(&it, "dir_only"), vec!["a.html", "b.html", "c.txt"]);
        assert_eq!(names_of(&it, "two"), vec!["a.html", "b.html"]);
        let _ = std::fs::remove_dir_all(&root);
    }

    #[test]
    fn list_files_star_stays_in_one_segment_and_doublestar_walks_the_tree() {
        let root = os_test_tree("qu_os_listfiles_walktest");
        let lit = qu_path_literal(&root);
        let it = run(&format!(
            "flat = list_files(\"{lit}/*.html\")\n\
             deep = list_files(\"{lit}/**/*.html\")\n\
             rec = list_files(\"{lit}\", \"*.html\", recursive = true)\n\
             tail = list_files(\"{lit}/**\")"
        ));
        // The whole reason `**` is spelled differently: a single `*` must
        // not reach into `sub/`, or the common case is wrong.
        assert_eq!(names_of(&it, "flat"), vec!["a.html", "b.html"]);
        // `**` matches ZERO segments as well as many, so the top-level
        // files come back alongside the nested ones.
        assert_eq!(
            names_of(&it, "deep"),
            vec!["a.html", "b.html", "d.html", "e.html"]
        );
        // `recursive = true` is exactly the `**` spelling.
        assert_eq!(names_of(&it, "rec"), names_of(&it, "deep"));
        // A trailing `**` is the whole subtree -- files only, so `sub` and
        // `sub/deep` are walked but never reported.
        assert_eq!(
            names_of(&it, "tail"),
            vec!["a.html", "b.html", "c.txt", "d.html", "e.html"]
        );
        let _ = std::fs::remove_dir_all(&root);
    }

    #[test]
    fn list_files_returns_files_only_never_directories() {
        let root = os_test_tree("qu_os_listfiles_filesonlytest");
        let lit = qu_path_literal(&root);
        let it = run(&format!(
            "everything = list_files(\"{lit}/*\")\n\
             entries = list_dir(\"{lit}\")"
        ));
        // `sub` matches the pattern by name and is still not an answer:
        // that is the whole difference from `list_dir`, which reports it.
        assert_eq!(names_of(&it, "everything"), vec!["a.html", "b.html", "c.txt"]);
        let Some(Value::List(entries)) = it.get("entries") else {
            panic!("list_dir must return a List");
        };
        assert_eq!(entries.len(), 4, "list_dir reports `sub` too");
        let _ = std::fs::remove_dir_all(&root);
    }

    #[test]
    fn list_files_filters_by_contents_and_by_size() {
        let root = os_test_tree("qu_os_listfiles_filtertest");
        let lit = qu_path_literal(&root);
        let it = run(&format!(
            "needle = list_files(\"{lit}/**\", contains = \"needle\")\n\
             empty = list_files(\"{lit}/**\", size = \"0\")\n\
             nonempty = list_files(\"{lit}/**\", size = \">0\")\n\
             small = list_files(\"{lit}/**\", size = \"<1KB\")\n\
             huge = list_files(\"{lit}/**\", size = \">2MB\")\n\
             both = list_files(\"{lit}/**\", contains = \"needle\", size = \"<6\")"
        ));
        assert_eq!(names_of(&it, "needle"), vec!["a.html", "c.txt"]);
        assert_eq!(names_of(&it, "empty"), vec!["d.html"]);
        assert_eq!(
            names_of(&it, "nonempty"),
            vec!["a.html", "b.html", "c.txt", "e.html"]
        );
        assert_eq!(names_of(&it, "small").len(), 5);
        assert!(names_of(&it, "huge").is_empty());
        // Both filters apply, not either: only `c.txt` ("needle", 6 bytes)
        // is under 6 bytes AND contains it... it is exactly 6, so neither.
        assert!(names_of(&it, "both").is_empty());
        let _ = std::fs::remove_dir_all(&root);
    }

    #[test]
    fn list_files_size_units_are_1024_based_and_a_bad_unit_errors() {
        let root = file_test_path("qu_os_listfiles_unitstest");
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(&root).unwrap();
        // 1500 bytes: over 1KB decimal, UNDER 1KB if KB means 1024.
        std::fs::write(root.join("mid.bin"), vec![0u8; 1500]).unwrap();
        let lit = qu_path_literal(&root);
        let it = run(&format!(
            "under = list_files(\"{lit}/*\", size = \"<2KB\")\n\
             over = list_files(\"{lit}/*\", size = \">1KB\")\n\
             kib = list_files(\"{lit}/*\", size = \">1KiB\")"
        ));
        assert_eq!(names_of(&it, "under"), vec!["mid.bin"]);
        assert_eq!(names_of(&it, "over"), vec!["mid.bin"]);
        // `KiB` is an explicit spelling of the same 1024, not a different
        // number.
        assert_eq!(names_of(&it, "kib"), vec!["mid.bin"]);

        // A unit this does not know is an error, never a silent "assume
        // bytes" -- that would answer a mistyped query as if it were right.
        let mut bad = Interp::new();
        let err = bad
            .run(&format!("x = list_files(\"{lit}/*\", size = \">2Qb\")"))
            .unwrap_err();
        assert!(err.msg.contains("not a unit"), "got: {}", err.msg);
        let _ = std::fs::remove_dir_all(&root);
    }

    #[test]
    fn list_files_rejects_a_pattern_given_twice() {
        let root = os_test_tree("qu_os_listfiles_ambigtest");
        let lit = qu_path_literal(&root);
        let mut it = Interp::new();
        let err = it
            .run(&format!("x = list_files(\"{lit}\", \"*.html\", filter = \"*.txt\")"))
            .unwrap_err();
        // Two honest readings, so it picks neither.
        assert!(err.msg.contains("pass one or the other"), "got: {}", err.msg);
        let _ = std::fs::remove_dir_all(&root);
    }

