    #[test]
    fn exec_runs_a_program_and_captures_what_it_printed() {
        // `cmd /C echo` on Windows, `echo` on anything else -- the point is
        // a program every machine running these tests already has.
        let src = if cfg!(windows) {
            "r = exec(\"cmd\", (\"/C\", \"echo hello\"))"
        } else {
            "r = exec(\"echo\", (\"hello\",))"
        };
        let it = run(src);
        let Some(Value::Record(rec)) = it.get("r") else {
            panic!("exec must return a Record, got {:?}", it.get("r"));
        };
        let field = |k: &str| rec.iter().find(|(n, _)| n == k).map(|(_, v)| v.clone());
        assert!(
            matches!(field("stdout"), Some(Value::Str(s)) if s.contains("hello")),
            "stdout was {:?}",
            field("stdout")
        );
        assert!(matches!(field("success"), Some(Value::Bool(true))));
        assert!(matches!(field("exit_code"), Some(Value::Num(n)) if n == 0.0));
        // The same four fields `python_exec`/`js_exec`/`matlab_exec`
        // already hand back, so a reader learns one shape.
        assert!(field("stderr").is_some());
    }

    #[test]
    fn exec_reports_a_failing_program_rather_than_raising() {
        let src = if cfg!(windows) {
            "r = exec(\"cmd\", (\"/C\", \"exit 3\"))"
        } else {
            "r = exec(\"sh\", (\"-c\", \"exit 3\"))"
        };
        let it = run(src);
        let Some(Value::Record(rec)) = it.get("r") else {
            panic!("exec must return a Record");
        };
        let field = |k: &str| rec.iter().find(|(n, _)| n == k).map(|(_, v)| v.clone());
        // A non-zero exit is the ANSWER to plenty of questions
        // (`git diff --quiet`), so it is data here, not an exception.
        assert!(matches!(field("success"), Some(Value::Bool(false))));
        assert!(matches!(field("exit_code"), Some(Value::Num(n)) if n == 3.0));
    }

    #[test]
    fn exec_errors_when_the_program_does_not_exist() {
        let mut it = Interp::new();
        let err = it
            .run("r = exec(\"qu_definitely_not_a_program_xyz\")")
            .unwrap_err();
        // Failing to START is a different thing from running and failing,
        // and only this one is a Qu error.
        assert!(err.msg.contains("could not start"), "got: {}", err.msg);
    }

    #[test]
    fn exec_shell_keyword_runs_a_command_line_and_cwd_does_not_move_the_caller() {
        let root = os_test_tree("qu_os_exec_cwdtest");
        let lit = qu_path_literal(&root);
        let src = if cfg!(windows) {
            format!("r = exec(\"cd\", shell = true, cwd = \"{lit}\")\nhere = cur_dir()")
        } else {
            format!("r = exec(\"pwd\", shell = true, cwd = \"{lit}\")\nhere = cur_dir()")
        };
        let it = run(&src);
        let Some(Value::Record(rec)) = it.get("r") else {
            panic!("exec must return a Record");
        };
        let out = match rec.iter().find(|(n, _)| n == "stdout") {
            Some((_, Value::Str(s))) => s.clone(),
            other => panic!("no stdout: {other:?}"),
        };
        assert!(
            out.trim().ends_with(
                root.file_name().unwrap().to_string_lossy().as_ref()
            ),
            "the command should have run in cwd=, got {out:?}"
        );
        // `cwd=` is not `cd`: the caller's own directory is untouched.
        let here = match it.get("here") {
            Some(Value::Str(s)) => s.clone(),
            other => panic!("cur_dir gave {other:?}"),
        };
        assert_ne!(here.trim(), out.trim());
        let _ = std::fs::remove_dir_all(&root);
    }

    #[test]
    fn exec_writes_stdin_and_closes_it_so_the_program_does_not_hang() {
        let src = if cfg!(windows) {
            "r = exec(\"findstr needle\", shell = true, stdin = \"hay\\nneedle\\nhay\\n\")"
        } else {
            "r = exec(\"grep needle\", shell = true, stdin = \"hay\\nneedle\\nhay\\n\")"
        };
        let it = run(src);
        let Some(Value::Record(rec)) = it.get("r") else {
            panic!("exec must return a Record");
        };
        // The real assertion is that this test TERMINATES: a program
        // reading to EOF would hang forever if the pipe were left open.
        let out = match rec.iter().find(|(n, _)| n == "stdout") {
            Some((_, Value::Str(s))) => s.clone(),
            other => panic!("no stdout: {other:?}"),
        };
        assert!(out.contains("needle"), "got {out:?}");
    }

    #[test]
    fn shell_returns_a_process_id_and_rejects_a_style_it_does_not_know() {
        let cmd = if cfg!(windows) { "cmd /c exit" } else { "true" };
        let it = run(&format!("p = shell(\"{cmd}\", \"hidden\")"));
        assert!(
            matches!(it.get("p"), Some(Value::Num(n)) if *n > 0.0),
            "shell must return a process id, got {:?}",
            it.get("p")
        );
        let mut bad = Interp::new();
        let err = bad
            .run(&format!("p = shell(\"{cmd}\", \"sideways\")"))
            .unwrap_err();
        assert!(err.msg.contains("not a window style"), "got: {}", err.msg);
    }

    #[test]
    fn exec_and_shell_are_refused_in_a_sandbox() {
        // Spawning a process is the most capability-bearing thing a script
        // can do; `--sandbox` would be a lie if either got through.
        for src in ["r = exec(\"cmd\")", "r = shell(\"cmd /c exit\")"] {
            let mut it = Interp::new();
            it.set_sandboxed(true);
            let err = it.run(src).unwrap_err();
            assert!(
                err.msg.contains("disabled in sandboxed execution"),
                "got: {}",
                err.msg
            );
        }
        // The guest-language runners are the same category and were simply
        // missed when the deny-list was first written.
        for src in ["r = js_exec(\"1\")", "r = matlab_exec(\"1\")"] {
            let mut it = Interp::new();
            it.set_sandboxed(true);
            let err = it.run(src).unwrap_err();
            assert!(
                err.msg.contains("disabled in sandboxed execution"),
                "got: {}",
                err.msg
            );
        }
        // Reads stay allowed: a sandboxed script can still find its input.
        let mut ok = Interp::new();
        ok.set_sandboxed(true);
        ok.run("x = list_files(\"*.nothing_matches_this\")").unwrap();
    }

    #[test]
    fn fsops_make_file_creates_when_missing_and_truncates_when_present() {
        let path = file_test_path("qu_fs_make_file_test.txt");
        let _ = std::fs::remove_file(&path);
        std::fs::write(&path, "old content").unwrap();
        let lit = qu_path_literal(&path);
        let _ = run(&format!("make_file(\"{lit}\")"));
        let contents = std::fs::read(&path).unwrap();
        assert!(contents.is_empty(), "make_file must truncate an existing file to empty, matching fopen(path, \"w\")");
        let _ = std::fs::remove_file(&path);
    }

    #[test]
    fn fsops_to_int_rounds_numbers_and_parses_valid_numeric_strings() {
        let it = run(
            "a = to_int(3.2)\nb = to_int(3.7)\nc = to_int(-3.5)\nd = to_int(\"42\")\ne = to_int(\"  7.6  \")"
        );
        assert!(matches!(it.get("a"), Some(Value::Num(n)) if *n == 3.0));
        assert!(matches!(it.get("b"), Some(Value::Num(n)) if *n == 4.0));
        // Ties away from zero — the exact same primitive (`f64::round`) the
        // pre-existing `round` builtin already uses, so the two agree by
        // construction.
        assert!(matches!(it.get("c"), Some(Value::Num(n)) if *n == -4.0));
        assert!(matches!(it.get("d"), Some(Value::Num(n)) if *n == 42.0));
        assert!(matches!(it.get("e"), Some(Value::Num(n)) if *n == 8.0));
    }

