        assert!(matches!(it.get("mid"), Some(Value::Vec(v)) if **v == vec![100.0, 101.0, 102.0, 103.0]));
        assert!(matches!(it.get("tail"), Some(Value::Vec(v)) if **v == vec![252.0, 253.0, 254.0, 255.0]));
