    // --------------------------------- Sequential 3-tier API (2026-08-26):
    // `input(...)`/`dense(...)`/`compile(...)` (Tier 2), `quick_mlp(...)`
    // (Tier 1), and `sequential_fit`'s real Adam branch (the "allow SGD,
    // adam etc." ask, replacing the old hardcoded-SGD-only update). See
    // each builtin arm's own doc comment (`"input"`/`"dense"`/`"compile"`/
    // `"quick_mlp"` in `call_builtin`, and `sequential_fit`'s own comment)
    // for the full design; these tests check the actual runtime behavior
    // documented there.

    #[test]
    fn pipeline_chaining_infers_each_stage_input_dim_from_the_previous_stage() {
        // `input(3) |> dense(5, activation="relu") |> dense(2)` must infer
        // the SECOND dense stage's `in_dim` (5) from the first stage's
        // `out_dim`, never from the caller writing it out by hand — this
        // is the entire point of the pipeline shape-tracking Record
        // (`input`/`dense`'s own doc comments). Also exercises the
        // `eval_pipe` bugfix this task made (this file's own doc comment
        // on `eval_pipe`): `activation="relu"` must actually reach `dense`
        // as a keyword, not get silently flattened into a positional arg.
        let it = run(
            "p = input(3) |> dense(5, activation=\"relu\") |> dense(2)\n\
             out_dim = p.out_dim\n\
             n_layers = length(p.layers)\n\
             l0_in = p.layers[0].in_dim\n\
             l0_out = p.layers[0].out_dim\n\
             l0_act = p.layers[0].activation\n\
             l1_in = p.layers[1].in_dim\n\
             l1_out = p.layers[1].out_dim\n\
             l1_act = p.layers[1].activation",
        );
        assert!(matches!(it.get("out_dim"), Some(Value::Num(n)) if *n == 2.0));
        assert!(matches!(it.get("n_layers"), Some(Value::Num(n)) if *n == 2.0));
        assert!(matches!(it.get("l0_in"), Some(Value::Num(n)) if *n == 3.0));
        assert!(matches!(it.get("l0_out"), Some(Value::Num(n)) if *n == 5.0));
        assert!(matches!(it.get("l0_act"), Some(Value::Str(s)) if s.as_str() == "relu"));
        // Second stage's `in_dim` (5) was NEVER written in the script —
        // it's inferred purely from the first stage's `out_dim`.
        assert!(matches!(it.get("l1_in"), Some(Value::Num(n)) if *n == 5.0));
        assert!(matches!(it.get("l1_out"), Some(Value::Num(n)) if *n == 2.0));
        // `activation=` defaults to `"none"` when not given, matching
        // `dense_layer`'s own default.
        assert!(matches!(it.get("l1_act"), Some(Value::Str(s)) if s.as_str() == "none"));
    }

    #[test]
    fn compile_turns_a_pipeline_into_a_real_working_sequential_model() {
        // `compile(...)` must produce an actually-usable `kind="sequential"`
        // model: `.predict(X)` should run, and the output shape must match
        // the pipeline's own final `out_dim`, not some other stale shape.
        let it = run(
            "net = input(3) |> dense(5, activation=\"relu\") |> dense(2) |> compile(loss=\"mse\")\n\
             x = [1.0, 2.0, 3.0] as matrix(1, 3)\n\
             pred = net.predict(x)\n\
             pred_rows = rows(pred)\n\
             pred_cols = cols(pred)\n\
             loss_kind = net.loss",
        );
        assert!(matches!(it.get("pred_rows"), Some(Value::Num(n)) if *n == 1.0));
        assert!(matches!(it.get("pred_cols"), Some(Value::Num(n)) if *n == 2.0));
        assert!(matches!(it.get("loss_kind"), Some(Value::Str(s)) if s.as_str() == "mse"));
        // `compile(...)` without an explicit `optimizer=` defaults to
        // `adam(...)`, matching `quick_mlp`'s own "Adam by default" choice
        // — see `"compile"`'s own doc comment. Checked in Rust (`model_of`)
        // since `ModelHandle.kind` isn't itself a script-visible field.
        let net = model_of(&it, "net");
        match net.field("optimizer") {
            Some(Value::Model(opt)) => assert_eq!(opt.kind, "adam"),
            other => panic!("expected net.optimizer to be a Model, got {other:?}"),
        }
    }

    #[test]
    fn sgd_and_adam_zero_arg_recipes_carry_only_hyperparameters() {
        // `sgd(lr=...)`/`adam(lr=...)` called with NO positional params
        // tensor — the "spec-only recipe" carve-out `optimizer=` needs
        // (see `"sgd"`/`"adam"`'s own doc comments) — must still return a
        // `Model` carrying just the hyperparameters, and must NOT break
        // the pre-existing 1-tensor call form those builtins already had.
        let it = run(
            "spec = adam(lr=0.05, beta1=0.8)\n\
             spec_lr = spec.lr\n\
             spec_beta1 = spec.beta1\n\
             p = param([1.0, 2.0])\n\
             bound = sgd(p, 0.02)\n\
             bound_lr = bound.lr",
        );
        assert!(matches!(it.get("spec_lr"), Some(Value::Num(n)) if (*n - 0.05).abs() < 1e-12));
        assert!(matches!(it.get("spec_beta1"), Some(Value::Num(n)) if (*n - 0.8).abs() < 1e-12));
        assert!(matches!(it.get("bound_lr"), Some(Value::Num(n)) if (*n - 0.02).abs() < 1e-12));
    }

    #[test]
    fn sequential_fit_one_adam_epoch_matches_hand_computed_bias_corrected_update() {
        // Isolates "does `sequential_fit`'s Adam branch apply the correct
        // textbook update formula" from "did autodiff compute the right
        // gradient" (already covered elsewhere) by computing the REAL
        // gradient independently — via the exact same `sequential_forward`
        // + `sequential_loss` + `eval_grad` path `sequential_fit` itself
        // uses — then hand-applying Adam's bias-corrected update formula
        // to that real gradient, and checking `fit(..., epochs=1,
        // optimizer=adam(...))` lands on EXACTLY that number (not just
        // "loss went down").
        let mut it = Interp::new();
        let w0 = 0.7_f64;
        let b0 = -0.2_f64;
        let lr = 0.05;
        let (beta1, beta2, eps) = (0.9, 0.999, 1e-8);
        let x = mat_value(Matrix::from_col_major(1, 1, vec![2.0]));
        let y = mat_value(Matrix::from_col_major(1, 1, vec![0.5]));

        let make_layer = || Value::Record(Arc::new(vec![
            ("kind".to_string(), Value::Str("dense".to_string())),
            ("in_dim".to_string(), Value::Num(1.0)),
            ("out_dim".to_string(), Value::Num(1.0)),
            ("activation".to_string(), Value::Str("none".to_string())),
        ]));
        let make_params = || Value::Record(Arc::new(vec![
            ("w".to_string(), mat_value(Matrix::from_col_major(1, 1, vec![w0]))),
            ("b".to_string(), Value::Vec(Arc::new(vec![b0]))),
        ]));

        // Real gradient at (w0, b0), independent of `fit` itself.
        let layers = vec![make_layer()];
        let params_list = vec![make_params()];
        let mut leaves: Vec<(usize, &'static str, Value)> = Vec::new();
        let pred = sequential_forward(&mut it, &layers, &params_list, x.clone(), true, &mut leaves).unwrap();
        let loss = sequential_loss(&mut it, "mse", pred, y.clone()).unwrap();
        let leaf_tensors: Vec<Value> = leaves.iter().map(|(_, _, t)| t.clone()).collect();
        let grads = it.eval_grad(loss, Value::List(Arc::new(leaf_tensors))).unwrap();
        let Value::List(grads) = grads else { panic!("expected grad() to return a list") };
        let g_w = to_vec(&grads[0]).unwrap()[0];
        let g_b = to_vec(&grads[1]).unwrap()[0];

        // Hand-computed single Adam step (t=1): m/v start at zero, so
        // m1 = (1-beta1)*g, v1 = (1-beta2)*g^2, and the bias-correction
        // denominators are exactly (1-beta1)/(1-beta2) at t=1.
        let expected = |p0: f64, g: f64| {
            let m1 = (1.0 - beta1) * g;
            let v1 = (1.0 - beta2) * g * g;
            let mc = m1 / (1.0 - beta1);
            let vc = v1 / (1.0 - beta2);
            p0 - lr * mc / (vc.sqrt() + eps)
        };
        let expected_w = expected(w0, g_w);
        let expected_b = expected(b0, g_b);

        // The real thing: `fit(..., epochs=1, optimizer=adam(lr=...))`,
        // starting from the SAME (w0, b0).
        let model = Value::Model(Arc::new(ModelHandle::new(
            "sequential",
            vec![
                ("layers".to_string(), Value::List(Arc::new(vec![make_layer()]))),
                ("params".to_string(), Value::List(Arc::new(vec![make_params()]))),
            ],
        )));
        let opt = it.call_builtin("adam", Vec::new(), None, vec![("lr".to_string(), Value::Num(lr))]).unwrap();
        let fitted = it.call_builtin(
            "fit",
            vec![model, x, y],
            None,
            vec![
                ("epochs".to_string(), Value::Num(1.0)),
                ("loss".to_string(), Value::Str("mse".to_string())),
                ("optimizer".to_string(), opt),
            ],
        ).unwrap();
        let Value::Model(fm) = fitted else { panic!("fit must return a Model") };
        let Some(Value::List(pl)) = fm.field("params") else { panic!("fitted model missing params") };
        let Value::Record(p0rec) = &pl[0] else { panic!("expected a params record") };
        let actual_w = to_vec(&p0rec.iter().find(|(k, _)| k == "w").unwrap().1).unwrap()[0];
        let actual_b = to_vec(&p0rec.iter().find(|(k, _)| k == "b").unwrap().1).unwrap()[0];

        assert!((actual_w - expected_w).abs() < 1e-9, "w: expected {expected_w}, got {actual_w}");
        assert!((actual_b - expected_b).abs() < 1e-9, "b: expected {expected_b}, got {actual_b}");
    }

