    // ---- job queue / worker pool (§47.3, 2026-08-26) ----

    #[test]
    fn queue_push_run_on_anonymous_pool_runs_every_job_and_returns_a_list() {
        let it = run(
            "double(n) := n * 2\n\
             jobs = queue()\n\
             jobs.push(\"double\", 1)\n\
             jobs.push(\"double\", 2)\n\
             jobs.push(\"double\", 3)\n\
             results = run jobs on pool(2)",
        );
        match it.get("results") {
            Some(Value::List(items)) => {
                let got: Vec<f64> = items
                    .iter()
                    .map(|v| v.as_num().unwrap_or(f64::NAN))
                    .collect();
                assert_eq!(got, vec![2.0, 4.0, 6.0]);
            }
            other => panic!("expected a list of results, got {other:?}"),
        }
    }

    #[test]
    fn run_on_an_empty_queue_returns_an_empty_list() {
        let it = run("jobs = queue()\nresults = run jobs on pool(2)");
        match it.get("results") {
            Some(Value::List(items)) => assert!(items.is_empty()),
            other => panic!("expected an empty list, got {other:?}"),
        }
    }

    #[test]
    fn run_returns_job_results_in_submission_order_not_completion_order() {
        // job "slow" (submitted FIRST) does real, deliberate CPU work; job
        // "fast" (submitted LAST) does none. With a real 2-worker pool,
        // "fast" finishes in wall-clock time well before "slow" — but
        // `run`'s result must still be [1, 2] (submission order), never
        // [2, 1] (completion order). This is a magnitude-of-work check,
        // not a wall-clock timing check, so it can't flake on a slow CI
        // box the way a millisecond-threshold assertion could.
        let it = run(
            "function slow(tag)\n\
                 total = 0\n\
                 for i = 1 to 300000\n\
                     total = total + i\n\
                 end for\n\
                 return tag\n\
             end function\n\
             fast(tag) := tag\n\
             jobs = queue()\n\
             jobs.push(\"slow\", 1)\n\
             jobs.push(\"fast\", 2)\n\
             results = run jobs on pool(2)",
        );
        match it.get("results") {
            Some(Value::List(items)) => {
                assert_eq!(items.len(), 2);
                assert!(matches!(items[0], Value::Num(n) if n == 1.0), "got {:?}", items[0]);
                assert!(matches!(items[1], Value::Num(n) if n == 2.0), "got {:?}", items[1]);
            }
            other => panic!("expected a list of results, got {other:?}"),
        }
    }

    #[test]
    fn named_pool_cpu_worker_count_is_respected_not_serialized_to_one() {
        // A controlled (non-wall-clock) concurrency check: every job
        // atomically bumps a shared `[running, peak]` mutex on entry and
        // decrements it on exit (via `mutex_update`, which holds the
        // mutex's own lock for the whole read-modify-write, so this is
        // race-free regardless of scheduling). With `cpu = 1`, at most one
        // job can ever be "running" at once, so `peak` is DETERMINISTICALLY
        // exactly 1 — no timing luck involved. With `cpu = 4` and 8 jobs
        // each doing enough real work to make thread-dispatch overhead
        // negligible by comparison, at least two jobs overlap and `peak`
        // reaches above 1 — proof the pool actually respects `cpu = N`
        // rather than silently running everything on one worker.
        let script = |cpu: u32| {
            format!(
                "function bump_enter(state)\n\
                     r = state[0] + 1\n\
                     p = state[1]\n\
                     if r > p then\n\
                         p = r\n\
                     end if\n\
                     return [r, p]\n\
                 end function\n\
                 function bump_exit(state)\n\
                     return [state[0] - 1, state[1]]\n\
                 end function\n\
                 function track(tag)\n\
                     _e = mutex_update(state, \"bump_enter\")\n\
                     total = 0\n\
                     for i = 1 to 150000\n\
                         total = total + i\n\
                     end for\n\
                     _x = mutex_update(state, \"bump_exit\")\n\
                     return tag\n\
                 end function\n\
                 state = mutex([0, 0])\n\
                 jobs = queue()\n\
                 jobs.push(\"track\", 1)\n\
                 jobs.push(\"track\", 2)\n\
                 jobs.push(\"track\", 3)\n\
                 jobs.push(\"track\", 4)\n\
                 jobs.push(\"track\", 5)\n\
                 jobs.push(\"track\", 6)\n\
                 jobs.push(\"track\", 7)\n\
                 jobs.push(\"track\", 8)\n\
                 pool p with cpu = {cpu}\n\
                 end pool\n\
                 results = run jobs on p\n\
                 peak = mutex_get(state)[1]"
            )
        };
        let it1 = run(&script(1));
        assert!(
            matches!(it1.get("peak"), Some(Value::Num(n)) if *n == 1.0),
            "cpu=1 pool should never let more than one job run at once, got {:?}",
            it1.get("peak")
        );

        // cpu = 4 used to run 8 busywork jobs and assert only that peak
        // rose above 1. That is timing luck, not a measurement: under a
        // saturated full-suite run the jobs can serialise, peak reads 1,
        // and the test fails while the pool did nothing wrong. It failed
        // exactly that way on 2026-09-09 (green 5/5 in isolation, red
        // under suite load) -- the same defect, in the same shape, as its
        // sibling `run_on_any_spreads_load_across_two_registered_pools_
        // not_piling_onto_one`, whose own comment used to concede the
        // dependency on "enough real work".
        //
        // A rendezvous of exactly 4 jobs on 4 workers replaces the luck
        // with a proof: every job holds until all four have entered, so
        // peak is DETERMINISTICALLY 4 when the pool really provides four
        // workers, and caps below 4 when it serialises -- and the bounded
        // guard inside `rendezvous` means a pool that cannot deliver
        // fails with a clear number instead of hanging. Stronger than the
        // old assertion, which 2 overlapping jobs out of 8 would satisfy.
        let it4 = run(&format!(
            "{}\
             jobs = queue()\n\
             jobs.push(\"rendezvous\", 1)\n\
             jobs.push(\"rendezvous\", 2)\n\
             jobs.push(\"rendezvous\", 3)\n\
             jobs.push(\"rendezvous\", 4)\n\
             pool p with cpu = 4\n\
             end pool\n\
             results = run jobs on p\n\
             peak = mutex_get(state)[1]",
            rendezvous_fns(4)
        ));
        assert!(
            matches!(it4.get("peak"), Some(Value::Num(n)) if *n == 4.0),
            "a cpu=4 pool must run all four rendezvousing jobs at once (peak=4); got {:?} — \
             the worker count doesn't look respected",
            it4.get("peak")
        );
    }

