    // ---- distributed job dispatch: `pool ... remote=(...)` + `listen_pool`
    // (§ distributed job dispatch, 2026-08-31) ----
    //
    // Real TCP loopback throughout (a background thread runs the actual
    // `remote_pool::serve_on_listener` accept loop; `run jobs on pool`
    // dispatches over real sockets to it) — genuine functional coverage of
    // the wire protocol, not a mock. Still one physical machine (there is
    // no second one available in this environment), so this is NOT a true
    // multi-machine test; the report for this feature is explicit about
    // that distinction. A real two-process `qu.exe` run (a separate
    // `listen_pool` script process + a separate client script process) is
    // exercised manually for this feature's own verification, alongside
    // these in-process tests.
    //
    // The listener side is deliberately given a DIFFERENT definition of
    // the shared function name than the caller's own local definition
    // (`mark(n) := n + 1000` remotely vs `mark(n) := n` locally) — since
    // each side runs on its own share-nothing `Interp` snapshot (see
    // `remote_pool`'s own "Isolation model" doc comment), this makes which
    // definition a job's result reflects a direct, unambiguous proof of
    // WHERE it actually ran, not just that the numbers came out right.

    /// Spawns a real listener on an OS-assigned loopback port (so no two
    /// test runs can collide on a fixed port) and returns its address.
    fn spawn_test_listener(script: &str, allow: &[&str]) -> String {
        let mut it = Interp::new();
        it.run(script).unwrap_or_else(|e| panic!("listener script failed: {e}"));
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let addr = format!("127.0.0.1:{}", listener.local_addr().unwrap().port());
        let allow: Vec<String> = allow.iter().map(|s| s.to_string()).collect();
        std::thread::spawn(move || {
            let _ = remote_pool::serve_on_listener(&mut it, listener, allow);
        });
        addr
    }

    #[test]
    fn active_never_exceeds_cpu_while_a_remote_pool_drains_local_jobs() {
        // Pins what `active` MEANS: occupied slots, never queued work.
        //
        // The remote dispatch path used to add the whole local batch size
        // to `active` in one go, so a cpu=1 pool given several local jobs
        // reported active = <batch size>. Nothing crashed -- `free()` is
        // a saturating subtraction -- but `run_jobs_auto` reads `free()`
        // to place work, so that pool looked permanently full to a
        // concurrent `run jobs on any` for as long as it took to drain.
        //
        // Observing this needs the LIVE handle while jobs are in flight,
        // which is why the pool is created in its own `run` first: the
        // pool outlives that call in the same `Interp`, so the sampler
        // below is watching the very handle the second `run` dispatches
        // onto.
        let addr = spawn_test_listener("slow(n) := n", &["slow"]);
        let mut it = Interp::new();
        it.run(&format!(
            "slow(n) := n\n\
             pool p with cpu = 1, remote = (\"{addr}\")\n\
             end pool"
        ))
        .expect("pool definition should succeed");
        let handle = match it.get("p") {
            Some(Value::Pool(h)) => h.clone(),
            other => panic!("expected `p` to be a pool, got {other:?}"),
        };
        let cpu = 1;

        let stop = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
        let peak = std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let sampler = {
            let (handle, stop, peak) = (handle.clone(), stop.clone(), peak.clone());
            std::thread::spawn(move || {
                while !stop.load(std::sync::atomic::Ordering::SeqCst) {
                    let seen = handle.active_count();
                    peak.fetch_max(seen, std::sync::atomic::Ordering::SeqCst);
                    std::thread::yield_now();
                }
            })
        };

        // Enough jobs that several land on the local lane, and each slow
        // enough that the sampler above is certain to see the counter
        // while it is up rather than only at rest.
        it.run(
            "function slow(n)\n\
                 total = 0\n\
                 for i = 1 to 400000\n\
                     total = total + i\n\
                 end for\n\
                 return n\n\
             end function\n\
             jobs = queue()\n\
             for k = 1 to 8\n\
                 jobs.push(\"slow\", k)\n\
             end for\n\
             results = run jobs on p",
        )
        .expect("dispatch should succeed");
        stop.store(true, std::sync::atomic::Ordering::SeqCst);
        sampler.join().unwrap();

        let observed = peak.load(std::sync::atomic::Ordering::SeqCst);
        assert!(
            observed <= cpu,
            "`active` must count OCCUPIED SLOTS, so it can never exceed cpu ({cpu}); saw \
             {observed}, which means the batch was counted as queued work again"
        );
        assert_eq!(
            handle.active_count(),
            0,
            "every slot must be released once the run finishes"
        );
    }

    #[test]
    fn on_cpu_stays_local_and_on_remote_crosses_the_network() {
        // The taxonomy's two exclusions, proved by WHERE each job ran
        // rather than by inspecting the scheduler. Same trick as the
        // other remote tests: the listener defines mark(n) = n + 1000
        // while the caller defines mark(n) = n, and each side runs on its
        // own share-nothing snapshot -- so 1001 can only have come from
        // the listener and 1 can only have come from here.
        //
        // One pool owns BOTH kinds of lane, so the tag is the only thing
        // deciding, and a scheduler that ignored it would be caught in
        // whichever direction it erred.
        let addr = spawn_test_listener("mark(n) := n + 1000", &["mark"]);
        let pool = format!(
            "mark(n) := n\n\
             pool p with cpu = 1, remote = (\"{addr}\")\n\
             end pool\n\
             jobs = queue()\n"
        );

        // on="remote": must take the network, even though local workers
        // are sitting right there unused.
        let it = run(&format!(
            "{pool}\
             jobs.push(\"mark\", 1, on=\"remote\")\n\
             jobs.push(\"mark\", 2, on=\"remote\")\n\
             results = run jobs on any"
        ));
        match it.get("results") {
            Some(Value::List(items)) => {
                let got: Vec<f64> = items.iter().map(|v| v.as_num().unwrap()).collect();
                assert_eq!(
                    got,
                    vec![1001.0, 1002.0],
                    "on=remote must run on the LISTENER, not the local workers -- got {got:?}"
                );
            }
            other => panic!("expected a list of results, got {other:?}"),
        }

        // on="cpu": must stay local, even though a remote lane is
        // configured and idle. This is the behaviour that CHANGED with
        // the taxonomy -- before it, a cpu-tagged job could cross the
        // network.
        let it = run(&format!(
            "{pool}\
             jobs.push(\"mark\", 1, on=\"cpu\")\n\
             jobs.push(\"mark\", 2, on=\"cpu\")\n\
             results = run jobs on any"
        ));
        match it.get("results") {
            Some(Value::List(items)) => {
                let got: Vec<f64> = items.iter().map(|v| v.as_num().unwrap()).collect();
                assert_eq!(
                    got,
                    vec![1.0, 2.0],
                    "on=cpu means LOCAL cpu -- these must NOT have crossed the network, \
                     but got {got:?} (1001-style values mean they ran on the listener)"
                );
            }
            other => panic!("expected a list of results, got {other:?}"),
        }
    }

    #[test]
    fn run_on_any_actually_dispatches_to_a_remote_worker() {
        // The point of the lane refactor, stated as a test: `on any` used
        // to schedule over POOLS and execute only through a pool's local
        // rayon pool, so a configured remote worker was unreachable from
        // this path no matter how many were declared. It now schedules
        // over LANES, and a remote address is a lane.
        //
        // Proof of WHERE the job ran, not just that a number came back:
        // the listener defines `mark(n) := n + 1000` while the caller
        // defines `mark(n) := n`. Each side runs on its own share-nothing
        // snapshot, so a result of 1001 can only have come from the
        // listener's definition. The pool has cpu = 0, so there is no
        // local lane to fall back to.
        let addr = spawn_test_listener("mark(n) := n + 1000", &["mark"]);
        let it = run(&format!(
            "mark(n) := n\n\
             pool p with cpu = 0, remote = (\"{addr}\")\n\
             end pool\n\
             jobs = queue()\n\
             jobs.push(\"mark\", 1)\n\
             jobs.push(\"mark\", 2)\n\
             results = run jobs on any"
        ));
        match it.get("results") {
            Some(Value::List(items)) => {
                let got: Vec<f64> = items.iter().map(|v| v.as_num().unwrap()).collect();
                assert_eq!(
                    got,
                    vec![1001.0, 1002.0],
                    "`on any` must have run both jobs on the REMOTE listener's own \
                     mark(n)=n+1000, in submission order -- got {got:?}"
                );
            }
            other => panic!("expected a list of results, got {other:?}"),
        }
    }

    #[test]
    fn pool_with_only_remote_workers_runs_every_job_on_the_listener() {
        // Verification point (a): a pool with ONLY `remote` workers (no
        // local `cpu` at all) correctly executes and returns results from
        // the remote listener.
        let addr = spawn_test_listener("mark(n) := n + 1000", &["mark"]);
        let it = run(&format!(
            "mark(n) := n\n\
             pool p with remote = (\"{addr}\")\n\
             end pool\n\
             jobs = queue()\n\
             jobs.push(\"mark\", 1)\n\
             jobs.push(\"mark\", 2)\n\
             results = run jobs on p"
        ));
        match it.get("results") {
            Some(Value::List(items)) => {
                let got: Vec<f64> = items.iter().map(|v| v.as_num().unwrap()).collect();
                assert_eq!(
                    got,
                    vec![1001.0, 1002.0],
                    "both jobs should have run on the REMOTE listener's own mark(n)=n+1000, \
                     not the caller's local mark(n)=n"
                );
            }
            other => panic!("expected a list of results, got {other:?}"),
        }
    }

    #[test]
    fn pool_with_cpu_and_remote_distributes_across_both_and_merges_in_order() {
        // Verification point (b): a pool with BOTH `cpu` and `remote`
        // workers distributes across both and merges results correctly,
        // in submission order.
        let addr = spawn_test_listener("mark(n) := n + 1000", &["mark"]);
        let it = run(&format!(
            "mark(n) := n\n\
             pool p with cpu = 1, remote = (\"{addr}\")\n\
             end pool\n\
             jobs = queue()\n\
             jobs.push(\"mark\", 1)\n\
             jobs.push(\"mark\", 2)\n\
             jobs.push(\"mark\", 3)\n\
             jobs.push(\"mark\", 4)\n\
             results = run jobs on p"
        ));
        match it.get("results") {
            Some(Value::List(items)) => {
                let got: Vec<f64> = items.iter().map(|v| v.as_num().unwrap()).collect();
                // Round-robin across 2 lanes (1 local-cpu lane + 1 remote
                // lane): job indices 0,2 -> local (mark(n)=n), indices
                // 1,3 -> remote (mark(n)=n+1000) — proves both lanes were
                // actually used, not just that the local pool ran
                // everything, AND that results merge back in submission
                // order regardless of which lane produced them.
                assert_eq!(got, vec![1.0, 1002.0, 3.0, 1004.0], "got {got:?}");
            }
            other => panic!("expected a list of results, got {other:?}"),
        }
    }

    #[test]
    fn run_on_pool_rejects_a_non_allowlisted_remote_function_cleanly() {
        // Verification point (c): the security allowlist actually rejects
        // a non-allowlisted function name — cleanly (a normal job-level
        // `run` error, never a crash, never a silent bypass that executes
        // it anyway).
        let addr = spawn_test_listener("mark(n) := n + 1000", &["mark"]);
        let mut it = Interp::new();
        let err = it
            .run(&format!(
                "other(n) := n\n\
                 pool p with remote = (\"{addr}\")\n\
                 end pool\n\
                 jobs = queue()\n\
                 jobs.push(\"other\", 1)\n\
                 results = run jobs on p"
            ))
            .unwrap_err();
        assert!(err.msg.contains("other"), "got: {}", err.msg);
        assert!(
            err.msg.to_lowercase().contains("allowlist") || err.msg.to_lowercase().contains("rejected"),
            "got: {}",
            err.msg
        );
    }

    #[test]
    fn run_on_pool_with_unreachable_remote_worker_fails_fast_not_forever() {
        // Verification point (d): an unreachable/dead remote worker is
        // handled — as a normal job-level `run` error, matching how a
        // single local job's failure already propagates (first error in
        // submission order, rest of the batch still attempted) — within a
        // real, bounded connection timeout, never hanging forever.
        let probe = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let dead_port = probe.local_addr().unwrap().port();
        drop(probe); // nothing is listening at this address anymore

        let mut it = Interp::new();
        let start = std::time::Instant::now();
        let err = it
            .run(&format!(
                "mark(n) := n\n\
                 pool p with remote = (\"127.0.0.1:{dead_port}\")\n\
                 end pool\n\
                 jobs = queue()\n\
                 jobs.push(\"mark\", 1)\n\
                 results = run jobs on p"
            ))
            .unwrap_err();
        let elapsed = start.elapsed();
        assert!(elapsed < std::time::Duration::from_secs(10), "took too long: {elapsed:?}");
        assert!(err.msg.contains("unreachable"), "got: {}", err.msg);
    }

    #[test]
    fn pool_remote_alone_with_no_cpu_key_parses_and_defaults_cpu_to_zero() {
        // `pool p with remote = (...)` (no `cpu = ` key at all) must parse
        // — `qu-syntax`'s `pool_stmt` defaults `cpu` to 0 in exactly this
        // shape (see `Stmt::Pool`'s own doc comment on the `remote` field).
        let addr = spawn_test_listener("mark(n) := n + 1000", &["mark"]);
        let it = run(&format!(
            "mark(n) := n\n\
             pool p with remote = (\"{addr}\")\n\
             end pool\n\
             jobs = queue()\n\
             jobs.push(\"mark\", 5)\n\
             results = run jobs on p"
        ));
        match it.get("results") {
            Some(Value::List(items)) => {
                assert!(matches!(items[0], Value::Num(n) if n == 1005.0), "got {:?}", items[0]);
            }
            other => panic!("expected a list of results, got {other:?}"),
        }
    }

    #[test]
    fn pool_cpu_zero_or_absurdly_large_is_a_clear_error() {
        let mut it = Interp::new();
        let err = it.run("pool p with cpu = 0\nend pool").unwrap_err();
        assert!(err.msg.contains("cpu"), "got: {}", err.msg);

        let mut it2 = Interp::new();
        let err2 = it2.run("pool p with cpu = 999999\nend pool").unwrap_err();
        assert!(err2.msg.contains("cpu"), "got: {}", err2.msg);
    }

    #[test]
    fn run_jobs_do_not_see_each_others_mutations() {
        // Same isolation guarantee `spawn`/`parallel for` already give: a
        // job's env is a SNAPSHOT, not a live reference — mutating what
        // looks like the same variable name inside one job must not leak
        // into the caller's own copy, nor into a sibling job's view.
        let it = run(
            "counter = 0\n\
             function bump()\n\
                 counter = counter + 100\n\
                 return counter\n\
             end function\n\
             jobs = queue()\n\
             jobs.push(\"bump\")\n\
             jobs.push(\"bump\")\n\
             results = run jobs on pool(2)\n\
             final_counter = counter",
        );
        assert!(matches!(it.get("final_counter"), Some(Value::Num(n)) if *n == 0.0));
        match it.get("results") {
            Some(Value::List(items)) => {
                assert_eq!(items.len(), 2);
                // each job saw counter == 0 from ITS OWN snapshot, never a
                // sibling's write — both must independently land on 100,
                // never 100 then 200.
                for (i, v) in items.iter().enumerate() {
                    assert!(matches!(v, Value::Num(n) if *n == 100.0), "job {i}: got {v:?}");
                }
            }
            other => panic!("expected a list of results, got {other:?}"),
        }
    }

    // ---- multi-pool load-aware auto-routing (§47.3 Phase A2, 2026-08-26) ----

    /// Shared helper for the auto-routing tests below: a `rendezvous(tag)`
    /// function that turns "did these jobs genuinely overlap?" into a
    /// DETERMINISTIC question instead of a timing race. Each job atomically
    /// bumps a shared `[entered, peak]` mutex on entry (the same race-free
    /// technique as `named_pool_cpu_worker_count_is_respected_not_
    /// serialized_to_one` above), then spins until it sees all `n` jobs
    /// have entered before releasing — so the overlap is forced by
    /// construction rather than hoped for from a chunk of busywork lining
    /// up, which is exactly the kind of thing a fully loaded machine
    /// running the whole suite will happily un-line-up. When the capacity
    /// genuinely isn't there the barrier simply never completes: the
    /// bounded `guard` trips, the jobs unwind, and `peak` lands below `n`
    /// with a clear assertion failure rather than a hang.
    fn rendezvous_fns(n: usize) -> String {
        format!(
            "function bump_enter(state)\n\
                 r = state[0] + 1\n\
                 p = state[1]\n\
                 if r > p then\n\
                     p = r\n\
                 end if\n\
                 return [r, p]\n\
             end function\n\
             function bump_exit(state)\n\
                 return [state[0] - 1, state[1]]\n\
             end function\n\
             function rendezvous(tag)\n\
                 _e = mutex_update(state, \"bump_enter\")\n\
                 guard = 0\n\
                 while mutex_get(state)[0] < {n} and guard < 8000000\n\
                     guard = guard + 1\n\
                 end while\n\
                 _x = mutex_update(state, \"bump_exit\")\n\
                 return tag\n\
             end function\n\
             state = mutex([0, 0])\n"
        )
    }

    #[test]
    fn run_on_any_spreads_load_across_two_registered_pools_not_piling_onto_one() {
        // Two pools, cpu = 1 EACH, so neither pool ALONE can ever have two
        // jobs in flight: `peak == 2` is reachable only if `on any` put the
        // two jobs on two DIFFERENT pools. The rendezvous barrier is what
        // makes that a statement about the ROUTING and not about the
        // machine's mood — job 1 refuses to finish until job 2 has also
        // started, so correct routing reaches peak=2 no matter how
        // contended the CPU is. (Measuring the peak around a fixed chunk of
        // busywork instead was flaky under full-suite load: if job 1 got
        // all the way through before job 2 was scheduled, the peak read 1
        // even though the scheduler had done the right thing.) A bug that
        // piles both jobs onto one pool leaves the second queued behind the
        // first, the barrier can then never complete, and `peak` caps at 1
        // — deterministically, in either direction.
        let script = format!(
            "{}\
             pool p1 with cpu = 1\n\
             end pool\n\
             pool p2 with cpu = 1\n\
             end pool\n\
             jobs = queue()\n\
             jobs.push(\"rendezvous\", 1, on=\"any\")\n\
             jobs.push(\"rendezvous\", 2, on=\"any\")\n\
             results = run jobs on any\n\
             peak = mutex_get(state)[1]",
            rendezvous_fns(2)
        );
        let it = run(&script);
        assert!(
            matches!(it.get("peak"), Some(Value::Num(n)) if *n == 2.0),
            "expected `on any` to spread the two jobs across the two single-worker pools \
             (they rendezvous, so peak=2 whenever the routing is right), got {:?}",
            it.get("peak")
        );
        // Both jobs still have to come back, in submission order.
        match it.get("results") {
            Some(Value::List(items)) => {
                assert_eq!(items.len(), 2);
                assert!(matches!(items[0], Value::Num(n) if n == 1.0), "got {:?}", items[0]);
                assert!(matches!(items[1], Value::Num(n) if n == 2.0), "got {:?}", items[1]);
            }
            other => panic!("expected a list of results, got {other:?}"),
        }
    }

    #[test]
    fn run_on_any_uses_the_combined_capacity_of_unequally_sized_pools() {
        // `small` (cpu=1) + `big` (cpu=3): a real, deterministic RENDEZVOUS
        // barrier, not a "do enough busywork that timing probably lines
        // up" hope — every job bumps the shared "currently entered"
        // counter, then spins reading it back until it sees all 4 jobs
        // have entered (`state[0] == 4`) before letting go. Since `big`
        // alone only has 3 workers, that rendezvous can PROVABLY only
        // complete if `small`'s one slot is used too — a routing bug that
        // never reaches into the smaller pool would leave the 4th job
        // permanently unable to start, and every already-entered job
        // would spin until the bounded guard trips and the test fails
        // with a clear "never reached 4" message, instead of hanging.
        let script = format!(
            "{}\
             pool small with cpu = 1\n\
             end pool\n\
             pool big with cpu = 3\n\
             end pool\n\
             jobs = queue()\n\
             jobs.push(\"rendezvous\", 1, on=\"any\")\n\
             jobs.push(\"rendezvous\", 2, on=\"any\")\n\
             jobs.push(\"rendezvous\", 3, on=\"any\")\n\
             jobs.push(\"rendezvous\", 4, on=\"any\")\n\
             results = run jobs on any\n\
             peak = mutex_get(state)[1]",
            rendezvous_fns(4)
        );
        let it = run(&script);
        assert!(
            matches!(it.get("peak"), Some(Value::Num(n)) if *n == 4.0),
            "expected all 4 jobs to rendezvous (needs the smaller pool's capacity too, since \
             the bigger pool alone only has 3 workers), got {:?}",
            it.get("peak")
        );
    }

