    #[test]
    fn explicit_named_pool_run_is_unaffected_by_the_registry_existing() {
        // Registering a pool (which now also inserts it into `Interp::
        // pool_registry`) must not change the behavior of `run jobs on
        // <thatSamePool>` — the explicit path still ignores the registry
        // entirely and just uses the one pool it was handed.
        let it = run(
            "double(n) := n * 2\n\
             pool p with cpu = 2\n\
             end pool\n\
             jobs = queue()\n\
             jobs.push(\"double\", 5)\n\
             results = run jobs on p",
        );
        match it.get("results") {
            Some(Value::List(items)) => {
                assert_eq!(items.len(), 1);
                assert!(matches!(items[0], Value::Num(n) if n == 10.0), "got {:?}", items[0]);
            }
            other => panic!("expected a list of results, got {other:?}"),
        }
    }

    #[test]
    fn a_variable_literally_named_any_still_works_as_an_explicit_pool() {
        // The `on any` auto-routing sentinel only activates when `any` is
        // an UNBOUND identifier at that point in the script — a script
        // that happens to bind its own pool to a variable named `any`
        // must still be able to `run jobs on any` and get that exact
        // pool, not auto-routing.
        let it = run(
            "double(n) := n * 2\n\
             any = pool(2)\n\
             jobs = queue()\n\
             jobs.push(\"double\", 3)\n\
             results = run jobs on any",
        );
        match it.get("results") {
            Some(Value::List(items)) => {
                assert_eq!(items.len(), 1);
                assert!(matches!(items[0], Value::Num(n) if n == 6.0), "got {:?}", items[0]);
            }
            other => panic!("expected a list of results, got {other:?}"),
        }
    }

    // `save_model`/`load_model` (feature `h5-models`, see `h5_model.rs`'s
    // own module doc comment) — real round-trip tests, not just "the file
    // got written": weight-value equality (bit-for-bit, since f64 through
    // an uncompressed HDF5 dataset is lossless), `.predict()`-output
    // equality after a real `.fit()`, and the missing/malformed-file error
    // paths. `#[cfg(not(feature = "h5-models"))]` gets the same clear-error
    // coverage `gpu_matmul_gives_a_clear_error_without_the_gpu_feature`
    // above already has for `gpu`.
    #[test]
    #[cfg(not(feature = "h5-models"))]
    fn save_model_gives_a_clear_error_without_the_h5_models_feature() {
        let mut it = Interp::new();
        let err = it.run("save_model(1, \"x.h5\")").unwrap_err();
        assert!(err.msg.contains("--features h5-models"), "got: {}", err.msg);
    }

    #[test]
    #[cfg(feature = "h5-models")]
    fn save_model_load_model_round_trip_preserves_weight_values() {
        let it = run(
            "spec = dense_layer(3, 5, activation=\"relu\") |> dense_layer(5, 2, activation=\"none\")\n\
             net = sequential(spec, seed=11)",
        );
        let Some(Value::Model(net)) = it.get("net") else { panic!("expected a model") };
        let path = std::env::temp_dir().join("qu_h5_model_weights_test.h5");
        h5_model::save_model(&net, &path.to_string_lossy()).unwrap_or_else(|e| panic!("save_model: {e}"));
        let loaded = h5_model::load_model(&path.to_string_lossy()).unwrap_or_else(|e| panic!("load_model: {e}"));
        let _ = std::fs::remove_file(&path);

        assert_eq!(loaded.kind, "sequential");
        let Some(Value::List(orig_params)) = net.field("params") else { panic!("expected params") };
        let Some(Value::List(new_params)) = loaded.field("params") else { panic!("expected params") };
        assert_eq!(orig_params.len(), new_params.len());
        for (a, b) in orig_params.iter().zip(new_params.iter()) {
            match (a, b) {
                (Value::Record(af), Value::Record(bf)) => {
                    let aw = af.iter().find(|(k, _)| k == "w").map(|(_, v)| v.clone());
                    let bw = bf.iter().find(|(k, _)| k == "w").map(|(_, v)| v.clone());
                    match (aw, bw) {
                        (Some(Value::Mat(aw)), Some(Value::Mat(bw))) => {
                            assert_eq!(aw.shape(), bw.shape());
                            assert_eq!(aw.as_slice(), bw.as_slice(), "dense weight mismatch after round trip");
                        }
                        (None, None) => {} // dropout layer, no weights
                        other => panic!("weight-field shape mismatch: {other:?}"),
                    }
                    let ab = af.iter().find(|(k, _)| k == "b").map(|(_, v)| v.clone());
                    let bb = bf.iter().find(|(k, _)| k == "b").map(|(_, v)| v.clone());
                    match (ab, bb) {
                        (Some(Value::Vec(ab)), Some(Value::Vec(bb))) => {
                            assert_eq!(ab.as_slice(), bb.as_slice(), "bias mismatch after round trip");
                        }
                        (None, None) => {}
                        other => panic!("bias-field shape mismatch: {other:?}"),
                    }
                }
                other => panic!("expected two per-layer param records: {other:?}"),
            }
        }
    }

    #[test]
    #[cfg(feature = "h5-models")]
    fn save_model_load_model_round_trip_preserves_predict_output() {
        let it = run(
            "spec = dense_layer(4, 6, activation=\"relu\") |> dense_layer(6, 2, activation=\"none\")\n\
             net = sequential(spec, seed=3)\n\
             X = [1,2,3,4; 5,6,7,8; 0,1,0,1; 2,2,2,2]\n\
             Y = [1,0; 0,1; 1,1; 0,0]\n\
             trained = net.fit(X, Y, epochs=5, lr=0.01, loss=\"mse\")\n\
             pred_before = trained.predict(X)",
        );
        let Some(Value::Mat(pred_before)) = it.get("pred_before") else { panic!("expected a matrix") };
        let Some(Value::Model(trained)) = it.get("trained") else { panic!("expected a model") };
        let path = std::env::temp_dir().join("qu_h5_model_predict_test.h5");
        h5_model::save_model(&trained, &path.to_string_lossy()).unwrap_or_else(|e| panic!("save_model: {e}"));

        let mut it2 = Interp::new();
        let escaped = path.display().to_string().replace('\\', "\\\\");
        it2.run(&format!(
            "net2 = load_model(\"{escaped}\")\n\
             X = [1,2,3,4; 5,6,7,8; 0,1,0,1; 2,2,2,2]\n\
             pred_after = net2.predict(X)"
        ))
        .unwrap_or_else(|e| panic!("load_model round trip: {e}"));
        let _ = std::fs::remove_file(&path);
        let Some(Value::Mat(pred_after)) = it2.get("pred_after") else { panic!("expected a matrix") };

        assert_eq!(pred_before.shape(), pred_after.shape());
        let max_diff = pred_before
            .as_slice()
            .iter()
            .zip(pred_after.as_slice())
            .map(|(a, b)| (a - b).abs())
            .fold(0.0_f64, f64::max);
        assert!(max_diff < 1e-12, "predict output changed after save_model/load_model round trip: max_diff={max_diff}");
    }

